const SPE_LIM = 99;

function moveloopPreambleOnce() {
    if (game._moveloop_preamble_done) return;
    game._moveloop_preamble_done = 1;
    game.context.rndencode = rnd(9000);
    game.context.seer_turn = rnd(30);
    game.u.umovement = NORMAL_SPEED;
}

function arrivalNearbyCoords(cx, cy, maxRadius = 3) {
    const coords = [];
    const rowrange = cy < ROWNO / 2 ? ROWNO - 1 - cy : cy;
    const colrange = cx < COLNO / 2 ? COLNO - 1 - cx : cx;
    const radiusLimit = maxRadius || Math.max(rowrange, colrange);
    for (let radius = 1; radius <= radiusLimit; radius++) {
        const passStart = coords.length;
        const lox = cx - radius, hix = cx + radius;
        const loy = cy - radius, hiy = cy + radius;
        for (let y = Math.max(loy, 0); y <= hiy && y < ROWNO; y++)
            for (let x = Math.max(lox, 1); x <= hix && x < COLNO; x++) {
                if (x !== lox && x !== hix && y !== loy && y !== hiy) continue;
                coords.push({ x, y });
            }
        for (let pass = passStart, n = coords.length - passStart; n > 1; pass++, n--) {
            const k = rn2(n);
            if (k) [coords[pass], coords[pass + k]] = [coords[pass + k], coords[pass]];
        }
    }
    return coords;
}

function heroHasTeleportControl() {
    if (game.u?.teleportControl) return true;
    return (game.inventory || []).some(item => item.worn
        && (item.actualKind === 'ring of teleport control'
            || item.kind === 'ring of teleport control'
            || item.ringRoll === 23));
}

function heroIsStunned() {
    return !!(game.u?.stunned || game.u?._stunTimeout || (game.u?._statusSuffix || '').includes('Stun'));
}

function heroHasAmuletOfYendor() {
    return !!(game.u?.uhave?.amulet || (game.inventory || []).some(item =>
        item.realAmuletOfYendor || String(item.actualKind || item.kind || '').toLowerCase() === 'amulet of yendor'));
}

function heroOnWizardTowerLevel() {
    return !!(game.level?.flags?.wizard_tower_level || game.level?.wizardTowerBounds);
}

function heroNoTeleportLevel() {
    const flags = game.level?.flags || {};
    return !!(flags.noteleport
        || flags.demon_court_noteleport
        || (flags.stasis_until != null && flags.stasis_until >= (game.moves || 0)));
}

function singleLevelBranch(level = game.u?.uz) {
    const dungeon = game.dungeons?.[level?.dnum ?? 0];
    return !!dungeon && (dungeon.num_dunlevs || 1) <= 1;
}

export function randomTeleportDepth() {
    const current = game.u?.uz || { dnum: 0, dlevel: 1 };
    const dungeon = game.dungeons?.[current.dnum];
    const curDepth = depth_of_level(current);
    if (!rn2(5) || singleLevelBranch(current) || In_endgame(current)) return curDepth;

    let minDepth;
    let maxDepth;
    if (In_quest(current)) {
        minDepth = dungeon?.depth_start ?? curDepth;
        maxDepth = minDepth + (dungeon?.num_dunlevs ?? 1) - 1;
    } else {
        minDepth = 1;
        maxDepth = (dungeon?.depth_start ?? 1) + (dungeon?.num_dunlevs ?? curDepth) - 1;
        if ((game.dungeons?.[current.dnum]?.name === 'Gehennom' || game.level?.flags?.gehennom)
            && !game.u?.uevent?.invoked)
            maxDepth = Math.max(minDepth, maxDepth - 1);
    }

    let nlev = rn2(Math.max(1, curDepth + 3 - minDepth)) + minDepth;
    if (nlev >= curDepth) nlev++;
    if (nlev > maxDepth) {
        nlev = maxDepth;
        if (curDepth >= maxDepth) nlev -= rnd(3);
    }
    if (nlev < minDepth) {
        nlev = minDepth;
        if (nlev === curDepth) {
            nlev += rnd(3);
            if (nlev > maxDepth) nlev = maxDepth;
        }
    }
    return nlev;
}

function sameLevelTeleportTrapAt(x, y) {
    return (game.level?.traps || []).find(trap => trap.tx === x && trap.ty === y);
}

function sameLevelTeleportOk(x, y, trapok = false) {
    const loc = game.level?.at(x, y);
    if (!loc) return false;
    if (!trapok && sameLevelTeleportTrapAt(x, y)) return false;
    if (!ACCESSIBLE(loc.typ)) return false;
    if (loc.typ === DOOR && (loc.doormask & (D_CLOSED | D_LOCKED))) return false;
    if ((game.level?.monsters || []).some(mon => mon.mx === x && mon.my === y)) return false;
    if ((game.level?.objects || []).some(obj =>
        obj.otyp === BOULDER && !obj.hidden && !obj.transientProjectile && obj.ox === x && obj.oy === y))
        return false;
    return true;
}

function collectSameLevelTeleportCoords(cx, cy) {
    const coords = [];
    const rowrange = cy < ROWNO / 2 ? ROWNO - 1 - cy : cy;
    const colrange = cx < COLNO / 2 ? COLNO - 1 - cx : cx;
    const maxRadius = Math.max(rowrange, colrange);
    let passStart = 0;
    let passCount = 0;
    for (let radius = 1; radius <= maxRadius; radius++) {
        const newpass = (radius % 2) !== 0;
        const passend = (radius % 2) === 0 || radius === maxRadius;
        if (newpass) {
            passStart = coords.length;
            passCount = 0;
        }
        const lox = cx - radius, hix = cx + radius;
        const loy = cy - radius, hiy = cy + radius;
        for (let y = Math.max(loy, 0); y <= hiy && y < ROWNO; y++)
            for (let x = Math.max(lox, 1); x <= hix && x < COLNO; x++) {
                if (x !== lox && x !== hix && y !== loy && y !== hiy) continue;
                if ((game.level?.monsters || []).some(mon => mon.mx === x && mon.my === y)) continue;
                const loc = game.level?.at(x, y);
                if (!loc || !ZAP_POS(loc.typ)) continue;
                coords.push({ x, y });
                passCount++;
            }
        if (passend) {
            for (let pass = passStart, n = passCount; n > 1; pass++, n--) {
                const k = rn2(n);
                if (k) [coords[pass], coords[pass + k]] = [coords[pass + k], coords[pass]];
            }
        }
    }
    return coords;
}

function teleportHeroSameLevel(x, y, { recalcVision = true } = {}) {
    if (isBuriedBallTrapActive()) buriedBallToPunishment();
    const oldX = game.u?.ux || 0;
    const oldY = game.u?.uy || 0;
    const oldBallX = game.u?.uball?.ox;
    const oldBallY = game.u?.uball?.oy;
    const oldChainX = game.u?.uchain?.ox;
    const oldChainY = game.u?.uchain?.oy;
    if (game.u) {
        game.u.ux0 = oldX;
        game.u.uy0 = oldY;
        game.u.ux = x;
        game.u.uy = y;
    }
    if (game.u?.usteed) {
        game.u.usteed.mx = x;
        game.u.usteed.my = y;
    }
    if (game.u?.uball) {
        game.u.uball.ox = x;
        game.u.uball.oy = y;
    }
    if (game.u?.uchain) {
        game.u.uchain.ox = x;
        game.u.uchain.oy = y;
    }
    newsym(oldX, oldY);
    if (oldBallX != null && oldBallY != null) newsym(oldBallX, oldBallY);
    if (oldChainX != null && oldChainY != null) newsym(oldChainX, oldChainY);
    newsym(x, y);
    if (recalcVision) vision_recalc(0);
    return `You materialize in ${x === oldX && y === oldY ? 'the same' : 'a different'} location!`;
}

function fixedTeleportTrapDestination(trap) {
    const dst = trap?.teledest || (trap?.ttyp === TELEP_TRAP ? trap?.launch : null);
    if (!dst) return null;
    if (dst.x < 1 || dst.x >= COLNO || dst.y < 0 || dst.y >= ROWNO) return null;
    return dst;
}

function teleportHeroToFixedTrapDestination(trap, options = {}) {
    const dst = fixedTeleportTrapDestination(trap);
    if (!dst) return null;
    const loc = game.level?.at(dst.x, dst.y);
    if (!loc || !ACCESSIBLE(loc.typ)) return '';
    const occupant = (game.level?.monsters || []).find(mon => mon.mx === dst.x && mon.my === dst.y);
    if (occupant) {
        const spot = enextoMonsterSpot(occupant.mx, occupant.my, occupant.data || {});
        if (!spot) return '';
        const oldX = occupant.mx;
        const oldY = occupant.my;
        occupant.mx = spot.x;
        occupant.my = spot.y;
        newsym(oldX, oldY);
        newsym(spot.x, spot.y);
    }
    return teleportHeroSameLevel(dst.x, dst.y, options);
}

function vaultTeleportDestination() {
    const vaultRoom = (game.level?.rooms || []).find(room => room.rtype === VAULT);
    const spot = {};
    if (vaultRoom && somexyspace(vaultRoom, spot) && sameLevelTeleportOk(spot.x, spot.y, false))
        return spot;
    return null;
}

function teleportHeroToVault(options = {}) {
    const spot = vaultTeleportDestination();
    return spot ? teleportHeroSameLevel(spot.x, spot.y, options) : null;
}

function applySameLevelTeleportNutritionPenalty() {
    if (!game.u) return;
    game.u.uhunger = (game.u.uhunger ?? 900) - 100;
    if ((game.u._statusSuffix || '').includes('Satiated') && game.u.uhunger <= 1000)
        game.u._statusSuffix = game.u._statusSuffix.replace(/\bSatiated\b/g, '').replace(/\s+/g, ' ').trim();
}

function heroWearsNutritionAmulet() {
    return (game.inventory || []).some(item => {
        if (!item.worn) return false;
        if (!(item.cls === 'amulet' || item.amuletIndex != null || item.glyph === '"')) return false;
        const name = String(item.actualKind || item.kind || '').toLowerCase();
        return !/cheap plastic imitation/.test(name);
    });
}

function ringNutritionName(item) {
    const roll = item?.ringRoll || item?.roll || 0;
    if (roll) return IDENTIFIED_RING_NAMES[roll - 1] || '';
    return String(item?.actualKind || item?.kind || '').toLowerCase().replace(/^ring of /, '');
}

function wornRingOnHand(hand) {
    const handPattern = hand === 'left' ? /\(on left hand\)/ : /\(on right hand\)/;
    return (game.inventory || []).find(item => item.cls === 'ring' && (item.worn === hand || handPattern.test(item.line || '')));
}

function heroWearsRingNamed(name) {
    return (game.inventory || []).some(item =>
        item.cls === 'ring'
        && (item.worn || /\(on (?:left|right) hand\)/.test(item.line || ''))
        && ringNutritionName(item) === name);
}

function heroWearsSlowDigestionRing() {
    return (game.inventory || []).some(item => {
        if (item?.cls !== 'ring' && item?.glyph !== '=') return false;
        if (!item.worn && !/\(on (?:left|right) hand\)/.test(item.line || '')) return false;
        return ringNutritionName(item) === 'slow digestion'
            || objectKindKey(item) === 'ring of slow digestion';
    });
}

function wornRingConsumesNutrition(hand) {
    const item = wornRingOnHand(hand);
    if (!item) return false;
    const name = ringNutritionName(item);
    if (name === 'meat ring') return false;
    if ((item.spe || 0) !== 0) return true;
    return !(item.charged || (item.ringRoll || item.roll || 99) <= 6);
}

function applyAccessoryHunger(accessorytime) {
    if (!game.u) return;
    if (accessorytime % 2) {
        if (heroWearsRingNamed('regeneration'))
            game.u.uhunger = (game.u.uhunger ?? 900) - 1;
        return;
    }
    if (heroWearsRingNamed('hunger'))
        game.u.uhunger = (game.u.uhunger ?? 900) - 1;
    if (accessorytime === 0 && heroHasSlowDigestion() && !heroWearsSlowDigestionRing())
        game.u.uhunger = (game.u.uhunger ?? 900) - 1;
    else if (accessorytime === 4 && wornRingConsumesNutrition('left'))
        game.u.uhunger = (game.u.uhunger ?? 900) - 1;
    else if (accessorytime === 8 && heroWearsNutritionAmulet())
        game.u.uhunger = (game.u.uhunger ?? 900) - 1;
    else if (accessorytime === 12 && wornRingConsumesNutrition('right'))
        game.u.uhunger = (game.u.uhunger ?? 900) - 1;
    else if (accessorytime === 16 && heroHasAmuletOfYendor())
        game.u.uhunger = (game.u.uhunger ?? 900) - 1;
}

function safeTeleportHeroSameLevel(options = {}) {
    const { returnResult = false, ...teleportOptions } = options;
    const success = message => returnResult ? { ok: true, message } : message;
    const failure = () => returnResult ? { ok: false, message: '' } : '';
    for (let tcnt = 0; tcnt < 40; tcnt++) {
        const x = rnd(COLNO - 1);
        const y = rn2(ROWNO);
        if (sameLevelTeleportOk(x, y, false))
            return success(teleportHeroSameLevel(x, y, teleportOptions));
    }

    let backup = null;
    for (const pos of collectSameLevelTeleportCoords(game.u?.ux || 0, game.u?.uy || 0)) {
        if (sameLevelTeleportOk(pos.x, pos.y, false))
            return success(teleportHeroSameLevel(pos.x, pos.y, teleportOptions));
        if (!backup && sameLevelTeleportTrapAt(pos.x, pos.y) && sameLevelTeleportOk(pos.x, pos.y, true))
            backup = pos;
    }
    return backup ? success(teleportHeroSameLevel(backup.x, backup.y, teleportOptions)) : failure();
}

