function levelTeleportMenuPage3Lines() {
    const hasKnox = hasPlacedKnoxBranch();
    const endgameLetters = hasKnox ? ['L', 'M', 'N', 'O'] : ['K', 'L', 'M', 'N'];
    const tutorialLetters = hasKnox ? ['Q', 'R'] : ['P', 'Q'];
    const specialDepth = name => wizWhereDepth(specialLevel(name));
    return LEVEL_TELEPORT_MENU_PAGE3_LINES.map(([row, col, text, attr]) => {
        if (row >= 0 && row <= 3) {
            const names = ['water', 'fire', 'air', 'earth'];
            const name = names[row];
            return [row, col, `${endgameLetters[row]} -   ${name}: ${specialDepth(name)}`, attr];
        }
        if (row === 6) return [row, col, `${tutorialLetters[0]} -   tut-1: ${specialDepth('tut-1')}`, attr];
        if (row === 7) return [row, col, `${tutorialLetters[1]} -   tut-2: ${specialDepth('tut-2')}`, attr];
        return [row, col, text, attr];
    });
}

function wizWhereDepth(level) {
    if (!level) return 0;
    if (level.dnum === 7) return level.dlevel - 6;
    if (level.dnum === 8) return level.dlevel;
    return (game.dungeons?.[level.dnum]?.depth_start ?? 1) + level.dlevel - 1;
}

function wizWhereRange(dnum) {
    const dungeon = game.dungeons?.[dnum];
    if (dnum === 7) return '-5 to 0';
    if (dnum === 8) return '1 to 2';
    return `${dungeon?.depth_start ?? 1} to ${(dungeon?.depth_start ?? 1) + (dungeon?.num_dunlevs ?? 1) - 1}`;
}

function wizWhereBranchLabel(branch) {
    const dungeonName = game.dungeons?.[branch.end2.dnum]?.name || 'Dungeon';
    if (branch.type === 'portal') return `Portal to ${dungeonName}`;
    if (branch.type === 'stair') return `Stair to ${dungeonName}`;
    if (branch.end1_up) return `One way stair to ${dungeonName}`;
    return `Connection to ${dungeonName}`;
}

function wizWhereLines() {
    const lines = [];
    const roleCode = ROLE_ABBREVIATIONS[game.urole?.name?.m || game._startup_role || 'Wizard'] || 'Wiz';
    const addHeader = (dnum, text = '') => {
        const dungeon = game.dungeons?.[dnum];
        if (!dungeon) return;
        lines.push(text || `${dungeon.name}: levels ${wizWhereRange(dnum)}`);
    };
    const addEntries = dnum => {
        const entries = [];
        for (const branch of game.branches || [])
            if (branch.end1?.dnum === dnum)
            entries.push({ depth: wizWhereDepth(branch.end1), text: `${wizWhereBranchLabel(branch)}: ${wizWhereDepth(branch.end1)}` });
        for (const level of game.specialLevels || []) {
            if (level.dnum !== dnum) continue;
            const label = level.name === 'x-strt' ? `${roleCode}-strt`
                : level.name === 'x-loca' ? `${roleCode}-loca`
                : level.name === 'x-goal' ? `${roleCode}-goal`
                : level.name;
            const suffix = level.name === 'castle' ? ` (tune ${game.castleTune || ''})` : '';
            entries.push({ depth: wizWhereDepth(level), text: `${label}: ${wizWhereDepth(level)}${suffix}` });
        }
        entries
            .sort((a, b) => a.depth - b.depth)
            .forEach(entry => lines.push(`  ${entry.text}`));
    };

    addHeader(0);
    addEntries(0);
    addHeader(1);
    addEntries(1);
    addHeader(2);
    addEntries(2);
    addHeader(3);
    addEntries(3);
    addHeader(4, `Sokoban: levels ${wizWhereRange(4)}, entrance from below`);
    addEntries(4);
    addHeader(5, `Fort Ludios: level ${wizWhereDepth({ dnum: 5, dlevel: 1 })}`);
    addEntries(5);
    addHeader(6, `Vlad's Tower: levels ${wizWhereRange(6)}, entrance from below`);
    addEntries(6);
    addHeader(7, `The Elemental Planes: levels ${wizWhereRange(7)}, entrance on -1`);
    addEntries(7);
    addHeader(8);
    addEntries(8);
    return lines;
}

function showWizWherePage(page) {
    const lines = game._wiz_where_lines || wizWhereLines();
    game._wiz_where_lines = lines;
    game._wiz_where_page = page;
    const start = page * 23;
    const body = lines.slice(start, start + 23);
    const rows = body.map((line, row) => [row, 0, line]);
    rows.push([body.length, 1, '--More--']);
    setOverlay(rows, 24, true);
    game._command_mode = 'wizWhereMore';
}

function spellMenuLines(prompt = 'Choose which spell to cast', includeSort = false) {
    const roleName = game.urole?.name?.m || game._startup_role || '';
    const spellbooks = game._known_spells || [];
    const wornArmor = (game.inventory || [])
        .filter(inv => inv.worn && inv.cls === 'armor')
        .map(inv => String(inv.actualKind || inv.kind || inventoryItemName(inv)).toLowerCase())
        .map(name => name.replace(/^(?:an?|the) /, '')
            .replace(/^(?:uncursed|blessed|cursed) /, '')
            .replace(/^[+-]\d+ /, '')
            .replace(/^pair of /, ''))
        .map(name => ARMOR_APPEARANCE_KINDS[name] || name);
    const hasRobe = wornArmor.includes('robe');
    const hasShield = wornArmor.some(name => name.includes('shield'));
    const heavyShield = wornArmor.some(name => name.includes('shield')
        && (OBJECT_WEIGHTS[name] ?? 0) > OBJECT_WEIGHTS['small shield']);
    const hasMetalSuit = wornArmor.some(name => METALLIC_BODY_ARMOR.has(name));
    const hasMetalHelm = wornArmor.some(name => METALLIC_HELMS.has(name));
    const hasMetalGloves = wornArmor.some(name => METALLIC_GLOVES.has(name));
    const hasMetalBoots = wornArmor.some(name => METALLIC_BOOTS.has(name));
    const hasQuarterstaff = (game.inventory || []).some(inv => inv.wielded && String(inv.kind || '').toLowerCase() === 'quarterstaff');
    const showTurns = !!game.flags?.debug;
    const left = showTurns ? 13 : 20;
    const rows = [
        [0, left, prompt, 1],
        [2, left, '    Name', 1],
        [2, left + 26, 'Level Category', 1],
        [2, left + 45, `Fail Retention${showTurns ? '  turns' : ''}`, 1],
    ];
    game._spell_menu_spells = [];
    let row = 3;
    for (const item of spellbooks) {
        const name = item.name || item.spellName || item.spell?.name || String(item.kind || '').replace(/^spellbook of /, '') || 'spell';
        const level = item.level || item.spell?.level || (name === 'extra healing' || name === 'stone to flesh' || name === 'remove curse' ? 3 : name === 'slow monster' || name === 'create monster' ? 2 : 1);
        const skillName = item.skill || item.spell?.skill || SPELL_CATEGORIES[name] || 'cleric';
        const category = skillName === 'cleric' ? 'clerical' : skillName;
        const skillLevel = ROLE_INITIAL_SPELL_SKILLS[roleName]?.[skillName] || P_UNSKILLED;
        let fail = level > 2 ? '76%' : '0%';
        let successChance = level > 2 ? 24 : 100;
        const stats = ROLE_SPELL_STATS[roleName];
        if (stats) {
            let splcaster = stats.base;
            const paladinBonus = roleName === 'Knight' && skillName === 'cleric';
            if (hasMetalSuit && !paladinBonus) splcaster += hasRobe ? Math.trunc(stats.armor / 2) : stats.armor;
            else if (hasRobe) splcaster -= stats.armor;
            if (hasShield) splcaster += stats.shield;
            if (hasQuarterstaff) splcaster -= 3;
            if (!paladinBonus) {
                if (hasMetalHelm) splcaster += 4;
                if (hasMetalGloves) splcaster += 6;
                if (hasMetalBoots) splcaster += 2;
            }
            if (name === stats.special) splcaster += stats.specialBonus;
            if (HEALING_SPELLS.has(name)) splcaster += stats.healing;
            if (splcaster > 20) splcaster = 20;

            const statused = game.u?.acurr?.a?.[stats.statIndex] || 10;
            const spellSkill = Math.max(skillLevel, 1) - 1;
            const difficulty = (level - 1) * 4 - ((spellSkill * 6) + Math.trunc((game.u?.ulevel || 1) / 3) + 1);
            let chance = Math.trunc(11 * statused / 2);
            if (difficulty > 0) chance -= Math.trunc(Math.sqrt(900 * difficulty + 2000));
            else chance += Math.min(20, Math.trunc(15 * -difficulty / level));
            chance = Math.max(0, Math.min(120, chance));
            if (heavyShield) chance = Math.trunc(chance / (name === stats.special ? 2 : 4));
            chance = Math.trunc(chance * (20 - splcaster) / 15) - splcaster;
            chance = Math.max(0, Math.min(100, chance));
            successChance = chance;
            fail = `${100 - chance}%`;
        }
        const accuracy = skillLevel >= 4 ? 2 : skillLevel === 3 ? 5 : skillLevel === 2 ? 10 : 25;
        const learnedTurn = item.learnedTurn ?? 1;
        const turnsLeft = Math.max(0, 20000 - Math.max(0, (game.moves || 1) - learnedTurn));
        const percent = turnsLeft >= 20000 ? 100 : Math.trunc((turnsLeft - 1) / 200) + 1;
        const high = turnsLeft >= 20000 ? 100 : accuracy * (Math.trunc((percent - 1) / accuracy) + 1);
        const retention = turnsLeft >= 20000 ? '100%' : `${high - accuracy + 1}%-${high}%`;
        const letter = String.fromCharCode('a'.charCodeAt(0) + game._spell_menu_spells.length);
        game._spell_menu_spells.push({ letter, name, level, category: skillName, successChance });
        const failGap = fail.length > 3 ? '' : ' ';
        rows.push([row++, left, `${letter} - ${name.padEnd(20, ' ')}  ${String(level).padStart(2, ' ')}   ${category.padEnd(13, ' ')}${failGap}${fail.padStart(3, ' ')} ${retention.padStart(9, ' ')}${showTurns ? ` ${String(turnsLeft).padStart(6, ' ')}` : ''}`]);
    }
    if (includeSort && spellbooks.length > 1) rows.push([row++, left, '+ - [sort spells]']);
    rows.push([row, left, '(end)']);
    // C ref: wintty.c tty_display_nhwindow() NHW_MENU — the menu window is
    // placed at offx = max(10, cols - maxcol - 1) (= left - 1 here) with a
    // one-cell margin before the first text column, and its whole rectangle
    // (offx..78 on every menu row) is cleared, erasing the map beneath.
    const windowClears = [];
    for (let r = 0; r <= row; r++) windowClears.push([r, left - 1, ' '.repeat(79 - (left - 1))]);
    return [...windowClears, ...rows];
}

function currentSkillLines() {
    const rows = [[0, 0, ' '], [0, 1, 'Current skills:', 1], [2, 0, ' '], [2, 1, 'Fighting Skills', 1]];
    const role = game.urole?.name?.m || game._startup_role || '';
    if (role === 'Samurai') {
        return [
            ...rows,
            [3, 0, `   ${'martial arts'.padEnd(18, ' ')}[Basic]`],
            [4, 0, `   ${'two weapon combat'.padEnd(18, ' ')}[Unskilled]`],
            [5, 0, `   ${'riding'.padEnd(18, ' ')}[Unskilled]`],
            [6, 0, ' '], [6, 1, 'Weapon Skills', 1],
            [7, 0, `   ${'dagger'.padEnd(18, ' ')}[Unskilled]`],
            [8, 0, `   ${'knife'.padEnd(18, ' ')}[Unskilled]`],
            [9, 0, `   ${'short sword'.padEnd(18, ' ')}[Basic]`],
            [10, 0, `   ${'broadsword'.padEnd(18, ' ')}[Unskilled]`],
            [11, 0, `   ${'long sword'.padEnd(18, ' ')}[Basic]`],
            [12, 0, `   ${'two-handed sword'.padEnd(18, ' ')}[Unskilled]`],
            [13, 0, `   ${'saber'.padEnd(18, ' ')}[Unskilled]`],
            [14, 0, `   ${'flail'.padEnd(18, ' ')}[Unskilled]`],
            [15, 0, `   ${'quarterstaff'.padEnd(18, ' ')}[Unskilled]`],
            [16, 0, `   ${'polearms'.padEnd(18, ' ')}[Unskilled]`],
            [17, 0, `   ${'spear'.padEnd(18, ' ')}[Unskilled]`],
            [18, 0, `   ${'lance'.padEnd(18, ' ')}[Unskilled]`],
            [19, 0, `   ${'bow'.padEnd(18, ' ')}[Basic]`],
            [20, 0, `   ${'shuriken'.padEnd(18, ' ')}[Unskilled]`],
            [21, 0, ' '], [21, 1, 'Spellcasting Skills', 1],
            [22, 0, `   ${'attack spells'.padEnd(18, ' ')}[Unskilled]`],
            [23, 0, ' (1 of 2)'],
        ];
    }
    if (role === 'Priest') {
        return [
            ...rows,
            [3, 0, `   ${'bare handed combat'.padEnd(19, ' ')}[Unskilled]`],
            [4, 1, 'Weapon Skills', 1],
            [5, 0, `   ${'club'.padEnd(19, ' ')}[Unskilled]`],
            [6, 0, `   ${'mace'.padEnd(19, ' ')}[Basic]`],
            [7, 0, `   ${'morning star'.padEnd(19, ' ')}[Unskilled]`],
            [8, 0, `   ${'flail'.padEnd(19, ' ')}[Unskilled]`],
            [9, 0, `   ${'hammer'.padEnd(19, ' ')}[Unskilled]`],
            [10, 0, `   ${'quarterstaff'.padEnd(19, ' ')}[Unskilled]`],
            [11, 0, `   ${'polearms'.padEnd(19, ' ')}[Unskilled]`],
            [12, 0, `   ${'spear'.padEnd(19, ' ')}[Unskilled]`],
            [13, 0, `   ${'trident'.padEnd(19, ' ')}[Unskilled]`],
            [14, 0, `   ${'lance'.padEnd(19, ' ')}[Unskilled]`],
            [15, 0, `   ${'bow'.padEnd(19, ' ')}[Unskilled]`],
            [16, 0, `   ${'sling'.padEnd(19, ' ')}[Unskilled]`],
            [17, 0, `   ${'crossbow'.padEnd(19, ' ')}[Unskilled]`],
            [18, 0, `   ${'dart'.padEnd(19, ' ')}[Unskilled]`],
            [19, 0, `   ${'shuriken'.padEnd(19, ' ')}[Unskilled]`],
            [20, 0, `   ${'boomerang'.padEnd(19, ' ')}[Unskilled]`],
            [21, 0, `   ${'unicorn horn'.padEnd(19, ' ')}[Unskilled]`],
            [22, 1, 'Spellcasting Skills', 1],
            [23, 0, ' (1 of 2)'],
        ];
    }
    rows.push([3, 0, `   bare handed combat [${role === 'Monk' ? 'Basic' : 'Unskilled'}]`]);
    rows.push([4, 0, `   two weapon combat  [${game._twoweapon ? 'Basic' : 'Unskilled'}]`]);
    rows.push([5, 0, `   riding             [${game.u?.usteed ? 'Basic' : 'Unskilled'}]`]);
    rows.push([6, 0, ' '], [6, 1, 'Weapon Skills', 1]);
    const weaponSkills = new Set();
    for (const item of game.inventory || []) {
        const name = inventoryItemName(item).toLowerCase();
        if (item.cls !== 'weapon' && !/staff|sword|dagger|bow|sling|dart|spear|mace|axe|lance|shuriken|club/.test(name)) continue;
        const skill = name.includes('staff') ? 'quarterstaff'
            : name.includes('short sword') || name.includes('wakizashi') ? 'short sword'
            : name.includes('long sword') || name.includes('katana') ? 'long sword'
            : name.includes('bow') || name.includes('yumi') ? 'bow'
            : name.includes('sling') ? 'sling'
            : name.includes('dart') ? 'dart'
            : name.includes('spear') ? 'spear'
            : name.includes('mace') ? 'mace'
            : name.includes('axe') ? 'axe'
            : name.includes('lance') ? 'lance'
            : name.includes('shuriken') ? 'shuriken'
            : name.includes('club') ? 'club'
            : name.includes('dagger') ? 'dagger'
            : 'weapon';
        weaponSkills.add(skill);
    }
    let row = 7;
    for (const skill of [...weaponSkills].sort()) rows.push([row++, 0, `   ${skill.padEnd(19, ' ')}[Basic]`]);
    if (row === 7) rows.push([row++, 0, '   weapon             [Unskilled]']);
    rows.push([row++, 0, ' '], [row++, 1, 'Spellcasting Skills', 1]);
    const spellbooks = game._known_spells || [];
    const spellSkills = new Set(spellbooks.map(item => item.skill || item.spell?.skill || item.section || 'cleric'));
    if (!spellSkills.size) spellSkills.add('spellcasting');
    for (const skill of [...spellSkills].sort()) {
        const skillName = String(skill);
        const label = skillName.endsWith('spells') ? skillName : `${skillName} spells`;
        rows.push([row++, 0, `   ${label.padEnd(19, ' ')}[Unskilled]`]);
    }
    rows.push([23, 0, '(end)']);
    return rows.slice(0, 24);
}

function attributesDungeonLocation(uz) {
    if (In_endgame(uz)) {
        if (sameLevel(uz, specialLevel('astral'))) return 'the endgame, on the Astral Plane';
        const elemental = [
            ['water', 'Water'],
            ['fire', 'Fire'],
            ['air', 'Air'],
            ['earth', 'Earth'],
        ].find(([name]) => sameLevel(uz, specialLevel(name)));
        if (elemental) return `the endgame, on the Elemental Plane of ${elemental[1]}`;
        return 'the endgame';
    }
    const currentDungeon = game.dungeons?.[uz.dnum];
    const dungeonName = currentDungeon?.name === 'The Dungeons of Doom'
        ? 'the Dungeons of Doom'
        : currentDungeon?.name === 'The Quest'
            ? 'the Quest'
            : currentDungeon?.name || 'the Dungeons of Doom';
    const dungeonLevel = currentDungeon?.name === 'The Quest' ? uz.dlevel : depth_of_level(uz);
    return `${dungeonName}, on level ${dungeonLevel}`;
}

function genericAttributesPage1() {
    const stats = game.u?.acurr?.a || [];
    const peaks = game.u?.amax?.a || stats;
    const attrLimits = ATTR_LIMITS_BY_RACE[game._startup_race] || {};
    const strength = attrLimits[0] ? `${strengthString(stats[0])} (current; limit:${attrLimits[0]})`
        : stats[0] !== peaks[0] ? `${strengthString(stats[0])} (current; ${stats[0] > peaks[0] ? 'base' : 'peak'}:${strengthString(peaks[0])})`
            : strengthString(stats[0]);
    const dexterity = attrLimits[3] ? `${stats[3]} (current; limit:${attrLimits[3]})`
        : stats[3] !== peaks[3] ? `${stats[3]} (current; base:${peaks[3]})` : stats[3];
    const rawName = game.plname || 'Hero';
    const name = rawName[0].toUpperCase() + rawName.slice(1);
    const role = game.urole?.name?.[game.flags?.female ? 'f' : 'm'] || game.urole?.name?.m || game._startup_role || 'Adventurer';
    const rank = game.urole?.rank?.[game.flags?.female ? 'f' : 'm'] || game.urole?.rank?.m || role;
    const race = game.urace?.adj || game._startup_race || 'human';
    const roleBase = game.urole?.name?.m || game._startup_role || role;
    const genderPrefix = (!game.urole?.name?.f && roleBase !== 'Valkyrie')
        ? `${game.flags?.female ? 'female' : 'male'} `
        : '';
    const alignType = game.u?.ualign?.type ?? 0;
    const align = alignType > 0 ? 'lawful' : alignType < 0 ? 'chaotic' : 'neutral';
    const alignIndex = alignType > 0 ? 0 : alignType < 0 ? 2 : 1;
    const alignNames = ['lawful', 'neutral', 'chaotic'];
    const pantheonRole = roleBase === 'Priest' ? game._pantheon_role || 'Barbarian' : roleBase;
    const gods = GODS_BY_ROLE[pantheonRole] || ['Marduk', 'Marduk', 'Marduk'];
    const opposedGods = gods
        .map((god, idx) => ({ god, idx }))
        .filter(({ idx }) => idx !== alignIndex)
        .map(({ god, idx }) => `${god} (${alignNames[idx]})`)
        .join(' and ');
    const uz = game.u?.uz || { dnum: 0, dlevel: 1 };
    const dungeon = attributesDungeonLocation(uz);
    const hp = game.u?.uhp ?? game.u?.uhpmax ?? 1;
    const hpmax = game.u?.uhpmax ?? hp;
    const energy = game.u?.uen ?? game.u?.uenmax ?? 0;
    const energymax = game.u?.uenmax ?? energy;
    const energyLine = energy === energymax
        ? energymax === 2 ? '  You have both energy points (spell power).' : `  You have all ${energymax} energy points (spell power).`
        : `  You have ${energy} out of ${energymax} energy points (spell power).`;
    const gold = game._goldCount || 0;
    const displayTurns = game.moves || 1;
    const turnLine = displayTurns === 1
        ? '  You have just started your adventure.'
        : `  You entered the dungeon ${displayTurns} turns ago.`;
    const rows = [
        [0, 0, ` ${name} the ${role}'s attributes:`],
        [2, 0, ' Background:'],
        [3, 0, role === rank
            ? `  You are a ${role}, level ${game.u?.ulevel || 1} ${genderPrefix}${race}.`
            : `  You are ${/^[aeiou]/i.test(rank) ? 'an' : 'a'} ${rank}, a level ${game.u?.ulevel || 1} ${genderPrefix}${race} ${role}.`],
        [4, 0, `  You are ${align}, on a mission for ${gods[alignIndex]}`],
        [5, 0, `  who is opposed by ${opposedGods}.`],
        [6, 0, `  You are ${game.u?.uhandedness || 'right'}-handed.`],
        [7, 0, `  You are in ${dungeon}.`],
        [8, 0, turnLine],
    ];
    let row = 9;
    if (game.flags?.moonphase === 4) rows.push([row++, 0, '  There is a full moon in effect.']);
    if (game.flags?.moonphase === 0) rows.push([row++, 0, '  There is a new moon in effect.']);
    if (game.flags?.friday13) rows.push([row++, 0, '  Bad things can happen on Friday the 13th.']);
    const exp = game.u?.uexp || 0;
    const level = game.u?.ulevel || 1;
    const nextLevelExp = level < 10 ? 10 * (2 ** level)
        : level < 20 ? 10000 * (2 ** (level - 10))
            : 10000000 * (level - 19);
    const expLine = game.flags?.debug
        ? `  You have ${exp} experience point${exp === 1 ? '' : 's'}, ${nextLevelExp - exp}${exp > 0 ? ' more' : ''} needed ${level < 18 ? 'to attain' : 'for'} level ${level + 1}.`
        : `  You have ${exp} experience point${exp === 1 ? '' : 's'}.`;
    rows.push(
        [row++, 0, expLine],
        [row++, 0, ''],
        [row++, 0, ' Basics:'],
        [row++, 0, hp === hpmax ? `  You have all ${hpmax} hit points.` : `  You have ${hp} out of ${hpmax} hit points.`],
        [row++, 0, energyLine],
        [row++, 0, `  Your armor class is ${game.u?.uac ?? 10}.`],
        [row++, 0, gold ? `  Your wallet contains ${gold} zorkmid${gold === 1 ? '' : 's'}.` : '  Your wallet is empty.'],
        [row++, 0, game.flags?.pickup ? `  Autopickup is on for '${game.flags.pickup_types || 'all'}' plus thrown.` : '  Autopickup is off.'],
        [row++, 0, ''],
        [row++, 0, ' Characteristics:'],
        [row++, 0, `  Your strength is ${strength}.`],
        [row++, 0, `  Your dexterity is ${dexterity}.`],
        [row++, 0, `  Your constitution is ${stats[4]}.`],
        [row++, 0, `  Your intelligence is ${stats[1]}${attrLimits[1] ? ` (current; limit:${attrLimits[1]})` : ''}.`],
    );
    game._attributes_page2_prefix = rows.filter(([line]) => line >= 23).map(([, col, text]) => [col, text]);
    const page2Rows = buildGenericAttributesPage2Rows();
    const totalPages = page2Rows.some(([line]) => line >= 23) ? 3 : 2;
    return [...rows.filter(([line]) => line < 23), [23, 0, ` (1 of ${totalPages})`]];
}

function enlightenmentPiousness(record) {
    if (record >= 20) return 'piously aligned';
    if (record > 13) return 'devoutly aligned';
    if (record > 8) return 'fervently aligned';
    if (record > 3) return 'stridently aligned';
    if (record === 3) return 'aligned';
    if (record > 0) return 'haltingly aligned';
    if (record === 0) return 'nominally aligned';
    if (record >= -3) return 'strayed';
    if (record >= -8) return 'sinned';
    return 'transgressed';
}

function enlightenmentWeaponName(weapon, roleName) {
    let name = weapon?.actualKind || weapon?.kind || weapon?.name
        || (typeof weapon?.otyp === 'string' ? weapon.otyp : '');
    name = String(name || '').toLowerCase().replace(/\s+named\s+.*$/, '');
    if (roleName === 'Samurai') {
        if (name === 'katana') name = 'long sword';
        else if (name === 'wakizashi') name = 'short sword';
    }
    if (name === 'battle-axe') name = 'axe';
    if (name === 'dwarvish mattock') name = 'mattock';
    if (/war hammer|mjollnir/.test(name)) name = 'hammer';
    if (name === 'silver saber' || name === 'scimitar') name = 'saber';
    if (name === 'scalpel') name = 'knife';
    return name ? name.replace(/^(?:elven|orcish|dwarvish) /, '') : '';
}

function enlightenmentWeaponSkillLine(weaponName, roleName) {
    if (weaponName === 'hammer' && roleName === 'Wizard')
        return `  You have no skill with ${weaponName}.`;
    if (weaponName === 'saber' && roleName === 'Archeologist')
        return `  You are unskilled in ${weaponName}.`;
    return `  You have basic skill with ${weaponName}.`;
}

function enlightenmentSourceForSearching(roleName) {
    return roleName === 'Archeologist' || roleName === 'Ranger'
        ? 'innately' : 'because of your experience';
}

function enlightenmentSourceForStealth(roleName) {
    return roleName === 'Rogue' ? 'innately' : 'because of your experience';
}

function enlightenmentSourceForSpeed(roleName) {
    return roleName === 'Monk' || roleName === 'Samurai'
        ? 'innately' : 'because of your experience';
}

function wornReflectionSource() {
    return (game.inventory || []).find(item => {
        if (!isActiveInventoryExtrinsicItem(item)) return false;
        const kind = armorKind(item);
        return isSilverDragonArmorKind(kind) || kind === 'shield of reflection'
            || item.amuletIndex === 7 || kind === 'amulet of reflection';
    });
}

function simpleEquipmentName(item) {
    if (!item) return '';
    if (item.cls === 'armor') return armorKind(item) || pickupObjectName(item);
    return item.actualKind || item.kind || pickupObjectName(item);
}

function buildGenericAttributesPage2Rows() {
    const stats = game.u?.acurr?.a || [];
    const peaks = game.u?.amax?.a || stats;
    const attrLimits = ATTR_LIMITS_BY_RACE[game._startup_race] || {};
    const wisdom = attrLimits[2] ? `${stats[2]} (current; limit:${attrLimits[2]})`
        : stats[2] !== peaks[2] ? `${stats[2]} (current; peak:${peaks[2]})` : stats[2];
    const charisma = attrLimits[5] ? `${stats[5]} (current; limit:${attrLimits[5]})` : stats[5];
    const roleName = game.urole?.name?.m || game._startup_role || '';
    const wieldedItem = (game.inventory || []).find(item =>
        item.wielded || item.line?.includes('(wielded)') || item.line?.includes('weapon in'))
        || (game.inventory || []).find(item => item.line?.includes('weapon;'));
    const weapon = wieldedItem && (wieldedItem.cls === 'weapon' || wieldedItem.otyp === WEAPON_CLASS || wieldedItem.glyph === ')')
        ? wieldedItem : null;
    const nonWeaponWielded = wieldedItem && !weapon ? wieldedItem : null;
    const weaponName = enlightenmentWeaponName(weapon, roleName);
    const weaponArticle = weaponName && /^[aeiou]/i.test(weaponName) ? 'an' : 'a';
    let carriedWeight = Math.trunc(((game._goldCount || 0) + 50) / 100);
    for (const item of game.inventory || []) {
        if (isGoldObject(item)) continue;
        let kind = String(item.actualKind || item.kind || item.spellName || item.spell?.name || '').toLowerCase();
        kind = ARMOR_APPEARANCE_KINDS[kind] || kind;
        const cls = item.cls || (item.otyp === RING_CLASS ? 'ring'
            : item.otyp === SCROLL_CLASS ? 'scroll'
                : item.otyp === POTION_CLASS ? 'potion'
                    : item.otyp === WAND_CLASS ? 'wand'
                        : item.otyp === GEM_CLASS ? 'gem' : '');
        const quan = item.quan || 1;
        const weightKind = /war hammer|mjollnir/.test(kind) ? 'war hammer' : kind;
        const unitWeight = OBJECT_WEIGHTS[weightKind] ?? CLASS_WEIGHTS[cls] ?? item.owt ?? 0;
        carriedWeight += unitWeight * quan;
    }
    const normalCapacity = Math.min(1000, 25 * ((stats[0] ?? 10) + (stats[4] ?? 10)) + 50);
    const capacity = Is_airlevel(game.u?.uz) || game.u?.levitating ? 1000 : normalCapacity;
    const burden = game.u?._debug_burden_override ?? (carriedWeight - capacity);
    const encumbrance = burden <= 0 ? 0 : Math.min(Math.trunc(burden * 2 / capacity) + 1, OVERLOADED);
    const statusSuffix = game.u?._statusSuffix || '';
    const hunger = statusSuffix.includes('Satiated') ? 'satiated'
        : statusSuffix.includes('Hungry') ? 'hungry'
            : statusSuffix.includes('Weak') ? 'weak from severe hunger'
                : statusSuffix.includes('Faint') ? 'fainting due to starvation'
                    : 'not hungry';
    const debugHunger = game.u?.uhunger ?? 900;
    const hungerLine = hunger === 'not hungry'
        ? game.flags?.debug ? `  You aren't hungry <${debugHunger}>.` : "  You aren't hungry."
        : game.flags?.debug ? `  You are ${hunger} <${debugHunger}>.` : `  You are ${hunger}.`;
    const encumbranceNames = ['', 'burdened', 'stressed', 'strained', 'overtaxed', 'overloaded'];
    const encumbranceAdverbs = ['', 'slightly', 'moderately', 'very', 'extremely', 'not possible'];
    const rows = [];
    let row = 0;
    for (const [col, text] of game._attributes_page2_prefix || []) rows.push([row++, col, text]);
    rows.push(
        [row++, 0, `  Your wisdom is ${wisdom}.`],
        [row++, 0, `  Your charisma is ${charisma}.`],
        [row++, 0, ''],
        [row++, 0, ' Status:'],
    );
    if (statusSuffix.includes('Deaf')) rows.push([row++, 0, '  You are deaf.']);
    if (statusSuffix.includes('Hallu')) rows.push([row++, 0, '  You are hallucinating.']);
    if (game.u?.uball || isBuriedBallTrapActive()) rows.push([row++, 0, '  You are chained to a heavy iron ball.']);
    if (game.u?._woundedLegTurns) {
        const side = game.u._woundedLegSide === 'left' ? 'left '
            : game.u._woundedLegSide === 'right' ? 'right ' : '';
        rows.push([row++, 0, `  You have a wounded ${side}leg.`]);
    }
    rows.push([row++, 0, hungerLine]);
    if (encumbrance > 0) {
        const slowed = encumbrance < OVERLOADED ? ' slowed' : '';
        const debugWeight = game.flags?.debug ? ` <${burden}>` : '';
        rows.push([row++, 0, `  You are ${encumbranceNames[encumbrance]}${debugWeight}; movement is ${encumbranceAdverbs[encumbrance]}${slowed}.`]);
    } else {
        rows.push([row++, 0, game.flags?.debug ? `  You are unencumbered <${burden}>.` : '  You are unencumbered.']);
    }
    if (game._twoweapon) {
        const primary = (game.inventory || []).find(item => item.wielded || item.line?.includes('right hand') || item.cls === 'weapon');
        const secondary = (game.inventory || []).find(item => item !== primary && (item.alternate || item.line?.includes('left hand')));
        const primarySkill = enlightenmentWeaponName(primary, roleName) || 'weapon';
        const secondarySkill = enlightenmentWeaponName(secondary, roleName) || 'weapon';
        rows.push(
            [row++, 0, '  You are wielding two weapons at once.'],
            [row++, 0, `  Your skill in ${primarySkill} is limited by being unskilled with two weapons.`],
            [row++, 0, `  Your skill in ${secondarySkill} is also limited by being unskilled with two weapons`],
        );
    } else {
        const emptyHanded = roleName === 'Monk' ? '  You are empty handed.' : '  You are bare handed.';
        const bareSkill = roleName === 'Monk' ? '  You have basic skill with martial arts.' : '  You are unskilled in bare handed combat.';
        if (nonWeaponWielded) {
            const wieldedName = nonWeaponWielded.cls === 'spellbook'
                ? 'spellbook'
                : simpleEquipmentName(nonWeaponWielded) || pickupObjectName(nonWeaponWielded);
            const wieldedArticle = /^[aeiou]/i.test(wieldedName) ? 'an' : 'a';
            rows.push([row++, 0, `  You are wielding ${wieldedArticle} ${wieldedName}.`]);
        } else {
            rows.push(
                [row++, 0, weaponName ? `  You are wielding ${weaponArticle} ${weaponName}.` : emptyHanded],
                [row++, 0, weaponName ? enlightenmentWeaponSkillLine(weaponName, roleName) : bareSkill],
            );
        }
    }
    const wornArmor = (game.inventory || []).some(item => item.cls === 'armor' && item.worn);
    if (!wornArmor) rows.push([row++, 0, "  You aren't wearing any armor."]);
    const magicNegation = (game.inventory || []).reduce((best, item) => {
        if (!(item.cls === 'armor' && item.worn)) return best;
        const name = String(item.actualKind || item.kind || inventoryItemName(item)).toLowerCase();
        return Math.max(best, ARMOR_MAGIC_NEGATION[name] || 0);
    }, 0);
    row++;
    if (game.flags?.debug) {
        const alignRecord = game.u?.ualign?.record ?? 0;
        const piousness = enlightenmentPiousness(alignRecord);
        const alignmentLine = alignRecord < 0 ? `  You have ${piousness}.` : `  You are ${piousness}.`;
        rows.push(
            [row++, 0, ' Attributes:'],
            [row++, 0, alignmentLine],
            [row++, 0, `  Your alignment is ${alignRecord}.`],
        );
        const magicResistanceSource = activeAntimagicSource();
        if (polyselfFormHasAntimagic())
            rows.push([row++, 0, '  You are magic-protected from your creature form.']);
        else if (magicResistanceSource)
            rows.push([row++, 0, `  You are magic-protected because of your ${pickupObjectName(magicResistanceSource)}.`]);
        if ((game.inventory || []).some(item => item.wielded && item.artifact === 'Grayswandir'))
            rows.push([row++, 0, '  You resist hallucinations because of Grayswandir.']);
        if (game.u?.fireResistance)
            rows.push([row++, 0, '  You are fire resistant because of your experience.']);
        const blueDragonArmor = (game.inventory || []).find(item =>
            isWornInventoryItem(item) && isBlueDragonArmorKind(String(item.kind || item.actualKind || '').toLowerCase()));
        if (blueDragonArmor) {
            rows.push([row++, 0, `  You are shock resistant because of your ${simpleEquipmentName(blueDragonArmor)}.`]);
            rows.push([row++, 0, `  Your items are protected from electric shocks by your ${blueDragonArmor.dragonArmorKind === 'mail' ? 'dragon mail' : 'dragon scales'}.`]);
        }
        if (game.u?.poisonResistance) {
            const poisonSource = roleName === 'Barbarian' || roleName === 'Healer' || game._startup_race === 'orc'
                ? 'innately' : 'because of your experience';
            rows.push([row++, 0, `  You are poison resistant ${poisonSource}.`]);
        }
        const telepathyAmulet = (game.inventory || []).find(item =>
            isWornInventoryItem(item) && item.cls === 'amulet'
            && (item.amuletIndex === 0 || /amulet of (?:esp|telepathy)/i.test(String(item.kind || item.actualKind || ''))));
        if (telepathyAmulet) {
            const appearance = telepathyAmulet.appearance || game._object_descriptions?.amulets?.[telepathyAmulet.amuletIndex];
            rows.push([row++, 0, `  You are telepathic because of your ${appearance ? `${appearance} amulet` : simpleEquipmentName(telepathyAmulet)}.`]);
        }
        if (game.u?.warning) rows.push([row++, 0, '  You are warned because of your experience.']);
        const displacementSource = (game.inventory || []).find(item =>
            isWornInventoryItem(item)
            && String(item.kind || item.actualKind || inventoryItemName(item)).toLowerCase() === 'cloak of displacement');
        if (game._has_displacement || displacementSource)
            rows.push([row++, 0, `  You are displaced because of your ${simpleEquipmentName(displacementSource) || 'cloak of displacement'}.`]);
        if (game.u?.searching)
            rows.push([row++, 0, `  You have automatic searching ${enlightenmentSourceForSearching(roleName)}.`]);
        if (game.u?.stealth)
            rows.push([row++, 0, `  You are stealthy ${enlightenmentSourceForStealth(roleName)}.`]);
        if (game.u?.teleportControl) rows.push([row++, 0, '  You have teleport control because of your experience.']);
        const teleportControlRing = (game.inventory || []).find(item =>
            item.worn && (item.actualKind === 'ring of teleport control' || item.ringRoll === 23));
        if (teleportControlRing) rows.push([row++, 0, `  You have teleport control because of your ${pickupObjectName(teleportControlRing)}.`]);
        if (heroHasSlowDigestion()) rows.push([row++, 0, '  You have slower digestion.']);
        if (magicNegation > 0) rows.push([row++, 0, '  You are warded.']);
        if (roleName === 'Knight' || game.u?.jumping) rows.push([row++, 0, '  You can jump intrinsically.']);
        if (game.u?.fast || game.u?.veryfast) {
            const speedBoots = (game.inventory || []).find(item =>
                isWornInventoryItem(item) && String(item.kind || item.actualKind || '').toLowerCase() === 'speed boots');
            const speedSource = speedBoots ? 'because of your speed boots'
                : game.u?._blueDragonFast ? 'because of worn equipment' : enlightenmentSourceForSpeed(roleName);
            rows.push([row++, 0, `  You are ${game.u?.veryfast ? 'very fast' : 'fast'} ${speedSource}.`]);
        }
        const reflectionSource = wornReflectionSource();
        if (game.u?.reflecting || reflectionSource)
            rows.push([row++, 0, `  You have reflection because of your ${simpleEquipmentName(reflectionSource) || 'worn equipment'}.`]);
        if ((game.inventory || []).some(item => item.worn && item.amuletIndex === 1))
            rows.push([row++, 0, '  Your life will be saved.']);
        const luck = (game.u?.uluck || 0) + (game.u?.moreluck || 0);
        rows.push([row++, 0, luck < 0 ? `  You are unlucky (${luck}).` : luck > 0 ? `  You are lucky (${luck}).` : '  Your luck is zero.']);
        rows.push([row++, 0, `  You can't safely pray (${game.u?.ublesscnt ?? 0}).`]);
        if (game._survived_death_count > 0)
            rows.push([row++, 0, `  You have been killed ${deathCountAdverb(game._survived_death_count)}.`]);
        row++;
    } else if (game.flags?.explore) {
        rows.push(
            [row++, 0, ' Attributes:'],
            [row++, 0, '  You are nominally aligned.'],
        );
        if (heroHasSlowDigestion()) rows.push([row++, 0, '  You have slower digestion.']);
        if (magicNegation > 0) rows.push([row++, 0, '  You are warded.']);
        rows.push([row++, 0, "  You can't safely pray."]);
        row++;
    }
    rows.push([row++, 0, ' Miscellaneous:']);
    if (game.flags?.debug) {
        rows.push(
            [row++, 0, '  You are running in debug mode.'],
            [row++, 0, "  You haven't encountered any bones levels."],
            [row++, 0, '  Total elapsed playing time is none.'],
        );
    }
    else if (game.flags?.explore) {
        rows.push(
            [row++, 0, '  You are running in explore mode.'],
            [row++, 0, "  You haven't encountered any bones levels."],
            [row++, 0, '  Total elapsed playing time is none.'],
        );
    } else rows.push([row++, 0, '  Total elapsed playing time is none.']);
    return rows;
}

function genericAttributesPage2() {
    const rows = buildGenericAttributesPage2Rows();
    const page2 = rows.filter(([line]) => line < 23);
    const page3 = rows.filter(([line]) => line >= 23).map(([, col, text], index) => [index, col, text]);
    if (page3.length) {
        page3.push([page3.length, 0, ' (3 of 3)']);
        game._attributes_page_3 = page3;
    } else {
        game._attributes_page_3 = null;
    }
    const page2FooterRow = page3.length
        ? 23
        : Math.max(...page2.map(([line]) => line), -1) + 1;
    page2.push([page2FooterRow, 0, page3.length ? ' (2 of 3)' : ' (2 of 2)']);
    return page2;
}

function heroFarlookDescription() {
    const form = polyselfForm();
    const chained = game.u?.uball || isBuriedBallTrapActive() ? ', chained to a heavy iron ball' : '';
    if (form) {
        const called = game.plname ? ` called ${game.plname}` : '';
        return `${form.name}${called}${chained}`;
    }
    const raceAdj = game.urace?.adj || game._startup_race || 'human';
    const race = { orcish: 'orc', elven: 'elf', gnomish: 'gnome', dwarven: 'dwarf' }[raceAdj] || raceAdj;
    const role = game.urole?.name?.[game.flags?.female ? 'f' : 'm'] || game.urole?.name?.m || game._startup_role || 'Adventurer';
    const called = game.plname ? ` called ${game.plname}` : '';
    return `${String(race).toLowerCase()} ${String(role).toLowerCase()}${called}${chained}`;
}

function farlookMonsterDescription(mon) {
    const data = mon.data || {};
    let name = data.name || 'monster';
    if (mon.givenName && name === 'ghost') name = `${mon.givenName}'s ghost`;
    else if (mon.givenName) name = mon.givenName;
    else if (mon.isshk && mon.shknam) name = mon.shknam;
    else if (mon.pet || mon.mpeaceful) name = `${mon.pet ? 'tame' : 'peaceful'} ${name}`;
    const details = [];
    if (mon.msleeping) details.push('asleep');
    if (mon.mundetected) details.push('hidden');
    if (mon.appearObj != null || mon.appearGlyph) details.push('mimicking something');
    return details.length ? `${name}, ${details.join(', ')}` : name;
}

