function buriedMerchandiseDebtMessage(x, y, ignoredObject = null) {
    const shkp = shopkeeperForCostlySpot(x, y);
    if (!shopkeeperInHisShop(shkp) || game._monster_moving) return '';
    let loss = 0;
    const seen = new Set();
    const source = { ox: x, oy: y };
    const peaceful = shkp.mpeaceful !== 0;
    for (const obj of game.level?.objects || []) {
        if (!obj || obj === ignoredObject || obj.transientProjectile) continue;
        if (obj.ox !== x || obj.oy !== y) continue;
        const charges = lostShopMerchandiseChargesForObject(source, obj, shkp, seen);
        for (const [chargedShkp, value] of charges)
            loss += chargeShopkeeperForLostMerchandise(chargedShkp, value, { peaceful });
        if (!shopBillableGold(obj))
            obj.no_charge = true;
    }
    if (!loss) return '';
    return `You owe ${shopkeeperDisplayName(shkp)} ${loss} ${shopCurrency(loss)} for burying merchandise.`;
}

function clearHeroSlimeFromMoltenLava() {
    if (game.u?._statusSuffix?.includes('Slimed')) {
        game.u._statusSuffix = game.u._statusSuffix.replace(/ Slimed/g, '');
        game.u.slimed = false;
    }
}

function heroNextToSquare(x, y) {
    if (game.u?.ux == null || game.u?.uy == null) return false;
    return distmin(game.u.ux, game.u.uy, x, y) <= 1;
}

function applyBoulderLavaSplashToHero(messages) {
    if (!game.u) return false;
    messages.push(`You are hit by molten lava${game.u.fireResistance ? '.' : '!'}`);
    clearHeroSlimeFromMoltenLava();
    const damage = d(game.u.fireResistance ? 1 : 3, 6);
    game.u.uhp = Math.max(0, (game.u.uhp || 1) - damage);
    if ((game.u.uhp || 0) <= 0) {
        game._death_cause = 'killed by molten lava';
        messages.push('You die...');
    }
    return true;
}

function boulderFillMonsterAt(x, y) {
    return (game.level?.monsters || []).find(mon =>
        mon.mx === x && mon.my === y && !mon.dead && (mon.mhp == null || mon.mhp > 0));
}

function boulderFillMonsterInAir(mon) {
    const data = mon?.data || {};
    return !!(mon?.inAir || mon?.flyer || mon?.floater
        || data.inAir || data.flyer || data.floater
        || ((mon?.mundetected || mon?.uundetected) && (data.clinger || data.ceilingHider)
            && !Is_airlevel(game.u?.uz)));
}

function maybeCreateBoulderFillCorpse(mon) {
    const data = mon?.data || {};
    const corpseData = data.corpse || data;
    if (!monsterLeavesCorpseLikeDrop(corpseData)) return;
    if (!monsterCorpseDropSucceeds(mon, data)) return;
    createMonsterCorpseOrGlob(mon, corpseData);
}

function killBoulderFillMonster(x, y) {
    const mon = boulderFillMonsterAt(x, y);
    if (!mon || boulderFillMonsterInAir(mon)) return false;
    dropMonsterInventory(mon);
    maybeCreateBoulderFillCorpse(mon);
    recordVanquished(mon, false);
    const loc = game.level?.at(x, y);
    if (loc?.map_invisible) {
        loc.map_invisible = false;
        loc.remembered_glyph = null;
    }
    game.level.monsters = (game.level?.monsters || []).filter(other => other !== mon);
    mon.mhp = 0;
    mon.movement = 0;
    mon.dead = true;
    newsym(x, y);
    return true;
}

const BOULDER_FILL_FLOOR_TRAPS = new Set([
    SQKY_BOARD, BEAR_TRAP, LANDMINE, FIRE_TRAP,
    PIT, SPIKED_PIT, HOLE, TRAPDOOR,
    TELEP_TRAP, LEVEL_TELEP, WEB, MAGIC_TRAP, ANTI_MAGIC,
]);

function boulderFillTrapAt(x, y) {
    return (game.level?.traps || []).find(trap => trap.tx === x && trap.ty === y) || null;
}

function deleteBoulderFillFloorTrap(trap, x, y) {
    if (!trap || !BOULDER_FILL_FLOOR_TRAPS.has(trap.ttyp) || !game.level?.traps) return false;
    if (game.u?.ux === x && game.u?.uy === y) {
        if (game.u.utraptype !== TT_BURIEDBALL) {
            game.u.utrap = 0;
            game.u.utraptype = null;
        }
    } else {
        const mon = (game.level?.monsters || []).find(candidate => candidate.mx === x && candidate.my === y);
        if (mon) mon.mtrapped = 0;
    }
    game.level.traps = game.level.traps.filter(candidate => candidate !== trap);
    return true;
}

function earthBoulderPitTrapAt(x, y) {
    const trap = boulderFillTrapAt(x, y);
    return trap && (trap.ttyp === PIT || trap.ttyp === SPIKED_PIT || trap.ttyp === HOLE || trap.ttyp === TRAPDOOR)
        ? trap
        : null;
}

function earthBoulderPitMessage(trap) {
    if (trap?.ttyp === TRAPDOOR) return `${trap.tseen ? '' : 'triggers and '}plugs a trap door`;
    if (trap?.ttyp === HOLE) return 'plugs a hole';
    return 'fills a pit';
}

function applyEarthBoulderPitOccupantEffects(trap, x, y, messages, verb = 'fall') {
    const mon = (game.level?.monsters || []).find(candidate =>
        candidate.mx === x && candidate.my === y && !candidate.dead && (candidate.mhp == null || candidate.mhp > 0));
    const heroHere = game.u?.ux === x && game.u?.uy === y;
    const monsterTrapped = mon && mon.mtrapped;
    const heroTrapped = heroHere && game.u?.utrap;
    if (!monsterTrapped && !heroTrapped) return { skipPlugMessage: false };
    if (verb && (earthVisibleSquare(x, y) || heroHere))
        messages.push(`${game.u?.blind ? 'A' : 'The'} boulder ${verb}s into the pit${monsterTrapped ? '' : ' with you'}.`);
    if (monsterTrapped) {
        if (earthTargetIsSolid(mon) && !earthTargetThrowsRocks(mon)) {
            mon.mhp = (mon.mhp || 1) - earthObjectDamage({ otyp: BOULDER, quan: 1 }, mon);
            if ((mon.mhp || 0) <= 0) {
                dropMonsterInventory(mon, messages);
                game.level.monsters = (game.level?.monsters || []).filter(other => other !== mon);
                mon.mhp = 0;
                mon.dead = true;
                const heroCaused = !game._monster_moving;
                recordVanquished(mon, heroCaused);
                if (earthVisibleSquare(x, y)) {
                    messages.push(heroCaused
                        ? `You kill the ${mon.data?.name || mon.name || 'monster'}!`
                        : `${fireScrollMonsterName(mon)} is killed!`);
                }
            }
        }
        mon.mtrapped = 0;
    } else if (heroTrapped) {
        const heroTarget = { ...game.u, data: polyselfForm() || {} };
        const solidHero = earthTargetIsSolid(heroTarget) && !earthTargetThrowsRocks(heroTarget);
        if (solidHero && game.u) {
            game.u.uhp = Math.max(0, (game.u.uhp || 1) - rnd(15));
            if ((game.u.uhp || 0) <= 0) {
                game._death_cause = 'squished under a boulder';
                messages.push('You die...');
            }
            return { skipPlugMessage: true };
        } else if (game.u?.utraptype !== TT_BURIEDBALL) {
            game.u.utrap = 0;
            game.u.utraptype = null;
        }
    }
    return { skipPlugMessage: false };
}

function earthBoulderPitHoleEffects(obj, x, y, messages, verb = 'fall', {
    usedUpShopBillOnDestroy = false,
} = {}) {
    if (obj?.otyp !== BOULDER) return false;
    const trap = earthBoulderPitTrapAt(x, y);
    if (!trap) return false;
    const heroHere = game.u?.ux === x && game.u?.uy === y;
    const { skipPlugMessage } = applyEarthBoulderPitOccupantEffects(trap, x, y, messages, verb);
    if (verb && !skipPlugMessage && game.u?.blind && heroHere) {
        messages.push('You hear a CRASH! beneath you.');
    } else if (verb && !skipPlugMessage && earthVisibleSquare(x, y)) {
        messages.push(`The boulder ${earthBoulderPitMessage(trap)}.`);
    } else if (verb && !skipPlugMessage && !heroIsDeaf()) {
        messages.push(`You hear a boulder ${verb}.`);
    }
    const buriedDebt = buriedMerchandiseDebtMessage(x, y, obj);
    deleteBoulderFillFloorTrap(trap, x, y);
    if (game.u?.ux === x && game.u?.uy === y && game.u.utraptype !== TT_BURIEDBALL) {
        game.u.utrap = 0;
        game.u.utraptype = null;
    }
    messages.push(...buryObjectsAt(x, y, { ignore: obj }));
    if (buriedDebt) messages.push(buriedDebt);
    if (usedUpShopBillOnDestroy) markObjectShopBillUsedUp(obj);
    newsym(x, y);
    return true;
}

function earthFloorLiquidType(loc) {
    if (!loc) return null;
    if (loc.typ === DRAWBRIDGE_UP) return earthLiquidUnderDrawbridge(loc);
    return loc.typ;
}

function floorEffectsObjectWeight(obj) {
    if (obj?.owt != null) return obj.owt;
    if (obj?.weight != null) return obj.weight;
    if (obj?.otyp === ROCK || objectKindKey(obj) === 'rock') return 10;
    return 10 * Math.max(1, obj?.quan || 1);
}

function maybeDroppedObjectPoolFeedback(obj, x, y, messages) {
    if (!game.u || game.u.ux !== x || game.u.uy !== y || heroIsDeaf()) return;
    const floating = !!(game.u.levitation || game.u.Levitation || game.u.flying || game.u.Flying);
    if (!game.u.blind && !floating) return;
    if (!(game.u.underwater || game.u.uunderwater)) {
        if (floorEffectsObjectWeight(obj) > 9) messages.push('Splash!');
        else if (floating) messages.push('Plop!');
    }
    newsym(x, y);
}

function droppedObjectWaterFloorEffects(obj, x, y, messages, {
    usedUpShopBillOnDestroy = false,
} = {}) {
    let destroyed = false;
    maybeDroppedObjectPoolFeedback(obj, x, y, messages);
    waterDamageFloorItem(obj, messages, floorObjectVisible(x, y), { count: 0 }, {
        removeObject: () => { destroyed = true; },
        usedUpShopBillOnDestroy,
    });
    return destroyed;
}

function droppedObjectLavaFloorEffects(obj, x, y, messages, {
    usedUpShopBillOnDestroy = false,
} = {}) {
    let destroyed = false;
    const visible = floorObjectVisible(x, y);
    const acidContext = { count: 0 };
    const processed = new Set();
    const processSpill = item => {
        if (processed.has(item)) return false;
        processed.add(item);
        if (!(game.level?.objects || []).includes(item)) return false;
        return liquidFlowFloorEffectsItem(item, x, y, messages, visible, acidContext, [], processSpill, {
            usedUpShopBillOnDestroy,
        });
    };
    lavaDamageFloorEffectItem(obj, messages, visible, {
        removeObject: () => { destroyed = true; },
        processSpill,
        usedUpShopBillOnDestroy,
        x,
        y,
    });
    return destroyed;
}

function droppedObjectHotGroundFloorEffects(obj, x, y, messages, {
    usedUpShopBillOnDestroy = false,
} = {}) {
    let destroyed = false;
    hotGroundPotionFloorEffect(obj, x, y, messages, floorObjectVisible(x, y), {
        removeObject: () => { destroyed = true; },
        usedUpShopBillOnDestroy,
    });
    return destroyed;
}

function floorEffectsTeeteringPit(trap, x, y) {
    return !!(trap && (trap.ttyp === PIT || trap.ttyp === SPIKED_PIT) && trap.tseen
        && game.u?.ux === x && game.u?.uy === y
        && !(game.u?.utrap && isPitTrapType(game.u?.utraptype)));
}

function floorEffectsEscapedShaft(trap, x, y) {
    return !!(trap && (trap.ttyp === HOLE || trap.ttyp === TRAPDOOR) && trap.tseen
        && game.u?.ux === x && game.u?.uy === y);
}

function floorEffectsObjectVerb(obj, singular, plural) {
    return (obj?.quan || 1) > 1 ? plural : singular;
}

function droppedObjectPitHoleFloorEffects(obj, x, y, messages) {
    const trap = boulderFillTrapAt(x, y);
    if (floorEffectsTeeteringPit(trap, x, y)) {
        if (game.u?.blind && !heroIsDeaf()) {
            messages.push(`You hear ${floorObjectTheName(obj)} tumble downwards.`);
        } else {
            const whose = trap.madeby_u ? 'your' : 'the';
            messages.push(`${floorObjectSubject(obj)} ${floorEffectsObjectVerb(obj, 'tumbles', 'tumble')} into ${whose} pit.`);
        }
        return { handled: true, consumed: false };
    }
    if (!floorEffectsEscapedShaft(trap, x, y)) return { handled: false, consumed: false };
    if (obj === game.u?.uball || obj === game.u?.uchain) return { handled: true, consumed: false };
    if (!canFallThroughLevel(game.u?.uz)) return { handled: true, consumed: false };
    if (rn2(3)) return { handled: true, consumed: false };
    const target = sitFallTargetLevel(trap);
    if (!target) return { handled: true, consumed: false };
    if (floorObjectVisible(x, y)) {
        const gate = trap.ttyp === TRAPDOOR ? 'through the trap door' : 'through the hole';
        messages.push(`${floorObjectSubject(obj)} ${floorEffectsObjectVerb(obj, 'falls', 'fall')} ${gate}.`);
    }
    const debt = shipObjectShopDebt(obj, x, y);
    if (debt.message) messages.push(debt.message);
    const breakKind = impactDropObjectBreaks(obj);
    if (breakKind) {
        messages.push(`You hear a muffled ${shipObjectMuffledBreakResult(breakKind)}.`);
        newsym(x, y);
        return { handled: true, consumed: true };
    }
    queueImpactDroppedObjects(target, [obj]);
    newsym(x, y);
    return { handled: true, consumed: true };
}

function globTypeForObject(obj) {
    if (!obj) return null;
    if (GLOB_TYPE_BY_OTYP.has(obj.otyp)) return GLOB_TYPE_BY_OTYP.get(obj.otyp);
    let name = String(obj.globName || obj.actualKind || obj.kind || '').toLowerCase();
    name = name.replace(/^partly eaten\s+/, '').replace(/^(?:small|medium|large|very large)\s+/, '');
    const match = name.match(/^glob of (.+)$/);
    return GLOB_TYPES.get(match?.[1] || name) || null;
}

function isGlobbyObject(obj) {
    return !!(obj?.globby || globTypeForObject(obj));
}

function globsCanMeld(target, obj) {
    const targetType = globTypeForObject(target);
    const objType = globTypeForObject(obj);
    if (!targetType || !objType || targetType.otyp !== objType.otyp) return false;
    if (target === obj || target?.nomerge || obj?.nomerge) return false;
    if (!!target.cursed !== !!obj.cursed || !!target.blessed !== !!obj.blessed) return false;
    if (target.how_lost === 'LOST_EXPLODING' || obj.how_lost === 'LOST_EXPLODING') return false;
    if (target.how_lost && target.how_lost !== 'LOST_NONE' && target.how_lost !== obj.how_lost) return false;
    return true;
}

function floorGlobMeldCandidateAt(obj, x, y) {
    return (game.level?.objects || []).find(candidate =>
        candidate !== obj && !candidate.buried && !candidate.transientProjectile
        && candidate.ox === x && candidate.oy === y
        && globsCanMeld(candidate, obj)) || null;
}

function floorGlobMeldTarget(obj, x, y) {
    const here = floorGlobMeldCandidateAt(obj, x, y);
    if (here) return here;

    const dx = rn2(2) ? -1 : 1;
    const dy = rn2(2) ? -1 : 1;
    const ex = x - dx;
    const ey = y - dy;
    for (let fx = ex; Math.abs(fx - ex) < 3; fx += dx) {
        for (let fy = ey; Math.abs(fy - ey) < 3; fy += dy) {
            if (fx < 0 || fx >= COLNO || fy < 0 || fy >= ROWNO || (fx === x && fy === y)) continue;
            const target = floorGlobMeldCandidateAt(obj, fx, fy);
            if (target) return target;
        }
    }
    return null;
}

function globMeldWeight(obj) {
    return Math.max(1, obj?.oeaten || obj?.owt || 20);
}

function globMeldRemainingTurns(obj) {
    const turn = obj?.globShrinkTurn;
    if (typeof turn !== 'number') return 25;
    return Math.max(1, turn - (game.moves || 0));
}

function syncGlobObjectFields(obj) {
    const globType = globTypeForObject(obj);
    if (!globType) return;
    Object.assign(obj, {
        otyp: globType.otyp,
        cls: 'food',
        glyph: '%',
        color: globType.color,
        _display_color: globType.color,
        kind: globType.name,
        actualKind: globType.name,
        singular: globType.name,
        globName: globType.name,
        globby: true,
        quan: 1,
        known: obj.known ?? true,
        dknown: obj.dknown ?? true,
    });
}

function unpaidBillPrice(obj) {
    const price = Number(obj?.unpaidPrice || 0);
    return Number.isFinite(price) ? Math.max(0, price) : 0;
}

function syncUnpaidBillLine(obj) {
    const price = unpaidBillPrice(obj);
    if (!obj?.line || !price) return;
    const suffix = ` (unpaid, ${price} zorkmid${price === 1 ? '' : 's'})`;
    if (/ \(unpaid, \d+ zorkmids?\)/.test(obj.line))
        obj.line = obj.line.replace(/ \(unpaid, \d+ zorkmids?\)/, suffix);
    else obj.line = `${obj.line}${suffix}`;
}

function combineAbsorbedGlobBill(absorber, absorbed) {
    const total = unpaidBillPrice(absorber) + unpaidBillPrice(absorbed);
    if (!total) return;
    absorber.unpaid = true;
    absorber.unpaidPrice = total;
    syncUnpaidBillLine(absorber);
}

function absorbGlobObject(absorber, absorbed) {
    const w1 = globMeldWeight(absorber);
    const w2 = globMeldWeight(absorbed);
    const moves = game.moves || 0;
    const age1 = typeof absorber.age === 'number' ? absorber.age : moves;
    const age2 = typeof absorbed.age === 'number' ? absorbed.age : moves;

    if (!!absorber.bknown !== !!absorbed.bknown) absorber.bknown = false;
    if (!!absorber.rknown !== !!absorbed.rknown) absorber.rknown = false;
    if (!!absorber.greased !== !!absorbed.greased) absorber.greased = false;
    if (absorber.orotten || absorbed.orotten) absorber.orotten = true;
    combineAbsorbedGlobBill(absorber, absorbed);

    absorber.age = moves - Math.trunc((((moves - age1) * w1) + ((moves - age2) * w2)) / (w1 + w2));
    absorber.owt = Math.max(1, absorber.owt || w1) + w2;
    if (absorber.oeaten || absorbed.oeaten) absorber.oeaten = w1 + w2;
    absorber.globShrinkTurn = moves + Math.trunc((globMeldRemainingTurns(absorber) + globMeldRemainingTurns(absorbed) + 1) / 2);
    syncGlobObjectFields(absorber);
    if (game.level?.objects?.includes(absorbed))
        game.level.objects = game.level.objects.filter(candidate => candidate !== absorbed);
}

function globPluralName(obj) {
    const globType = globTypeForObject(obj);
    return globType ? `${globType.name.replace(/^glob\b/, 'globs')}` : 'globs';
}

function droppedObjectGlobMeldFloorEffects(obj, x, y, messages) {
    if (!isGlobbyObject(obj)) return false;
    const target = floorGlobMeldTarget(obj, x, y);
    if (!target) return false;

    pushGlobMeldMessage(obj, target, x, y, messages);
    absorbGlobObject(target, obj);
    newsym(x, y);
    newsym(target.ox, target.oy);
    return true;
}

function pushGlobMeldMessage(obj, target, x, y, messages) {
    if (!messages) return;
    const visible = !game.u?.blind && (cansee(x, y) || cansee(target.ox, target.oy));
    if (visible) {
        if (heroIsHallucinating()) {
            messages.push('You see parts of the floor melting!');
        } else {
            const adjacent = (x !== game.u?.ux || y !== game.u?.uy)
                && (target.ox !== game.u?.ux || target.oy !== game.u?.uy);
            messages.push(`The ${adjacent ? 'adjacent ' : ''}${globPluralName(obj)} coalesce.`);
        }
    } else if (!heroIsDeaf()) {
        messages.push('You hear a faint sloshing sound.');
    }
}

function globShrinkDelay() {
    return 25 + rn2(5) - 2;
}

function startGlobShrinkTimeout(obj, when = 0) {
    if (!isGlobbyObject(obj)) return;
    const delay = when > 0 ? when : globShrinkDelay();
    obj.globShrinkTurn = Math.max(game.moves || 0, 1) + delay;
}

function globContents(obj) {
    const contents = Array.isArray(obj?.contents) ? obj.contents : [];
    const cobj = Array.isArray(obj?.cobj) ? obj.cobj : [];
    if (contents.length && cobj.length) {
        const seen = new Set();
        const merged = [];
        for (const item of [...contents, ...cobj]) {
            const key = item?.id != null ? `id:${item.id}` : item;
            if (seen.has(key)) continue;
            seen.add(key);
            merged.push(item);
        }
        return merged;
    }
    if (contents.length) return contents;
    if (cobj.length) return cobj;
    if (Array.isArray(obj?.contents)) return obj.contents;
    if (Array.isArray(obj?.cobj)) return obj.cobj;
    return [];
}

function normalizeContainedObjectParents(container, seen = new Set()) {
    if (!container || seen.has(container)) return;
    seen.add(container);
    for (const child of globContents(container)) {
        child.contained = true;
        child.container = container;
        normalizeContainedObjectParents(child, seen);
    }
}

function collectGlobShrinkEntriesFromList(list, source, entries, {
    parent = null,
    root = null,
    ancestors = [],
    owner = null,
} = {}) {
    for (const obj of list || []) {
        const top = root || obj;
        if (isGlobbyObject(obj)) entries.push({
            obj,
            parent,
            root: top,
            ancestors: [...ancestors],
            source,
            owner,
        });
        const contents = globContents(obj);
        if (contents.length) {
            collectGlobShrinkEntriesFromList(contents, source, entries, {
                parent: obj,
                root: top,
                ancestors: [...ancestors, obj],
                owner,
            });
        }
    }
}

function collectGlobShrinkEntries(g = game) {
    const entries = [];
    collectGlobShrinkEntriesFromList(g.inventory || [], 'inventory', entries);
    collectGlobShrinkEntriesFromList(g.level?.objects || [], 'floor', entries);
    for (const mon of g.level?.monsters || [])
        collectGlobShrinkEntriesFromList(mon.minvent || [], 'minvent', entries, { owner: mon });
    return entries;
}

function collectCorpseTimerEntriesFromList(list, source, entries, {
    parent = null,
    root = null,
    ancestors = [],
    owner = null,
    seen = new Set(),
} = {}) {
    for (const obj of list || []) {
        if (!obj || seen.has(obj)) continue;
        seen.add(obj);
        const top = root || obj;
        const actualSource = source === 'floor' && top?.buried ? 'buried' : source;
        if (isCorpseItem(obj)) entries.push({
            obj,
            parent,
            root: top,
            ancestors: [...ancestors],
            source: actualSource,
            owner,
        });
        const contents = globContents(obj);
        if (contents.length) {
            collectCorpseTimerEntriesFromList(contents, source, entries, {
                parent: obj,
                root: top,
                ancestors: [...ancestors, obj],
                owner,
                seen,
            });
        }
    }
}

function collectCorpseTimerEntries(g = game) {
    const entries = [];
    const seen = new Set();
    collectCorpseTimerEntriesFromList(g.inventory || [], 'inventory', entries, { seen });
    collectCorpseTimerEntriesFromList(g.level?.objects || [], 'floor', entries, { seen });
    collectCorpseTimerEntriesFromList(g.level?.buriedobjlist || [], 'buried', entries, { seen });
    for (const mon of g.level?.monsters || [])
        collectCorpseTimerEntriesFromList(mon.minvent || [], 'minvent', entries, { owner: mon, seen });
    return entries;
}

const CORPSE_TIMER_ACTION_RANK = { revive: 0, zombify: 1, rot: 2 };

function corpseTimerDue(entry, moves = game.moves || 0) {
    const obj = entry?.obj;
    const timers = [
        ['rot', obj?.rotAwayTurn],
        ['revive', obj?.reviveTurn],
        ['zombify', obj?.zombifyTurn],
    ].filter(([, turn]) => typeof turn === 'number' && turn <= moves);
    if (!timers.length) return null;
    timers.sort((a, b) => a[1] - b[1] || CORPSE_TIMER_ACTION_RANK[a[0]] - CORPSE_TIMER_ACTION_RANK[b[0]]);
    return { action: timers[0][0], turn: timers[0][1] };
}

function corpseInIceBox(entry) {
    return !!(entry?.obj?.inIceBox || entry?.ancestors?.some(isIceBoxObject));
}

function corpseTimerObjectName(obj) {
    return pickupObjectName({ ...(obj || {}), line: '', quan: 1 });
}

function corpseTimerRotMessage(entry) {
    const obj = entry.obj;
    const name = corpseTimerObjectName(obj);
    if (entry.source === 'inventory' && !entry.parent) return `Your ${name} rots away.`;
    if (entry.source === 'inventory' && entry.parent) {
        const container = articlelessObjectName(entry.root || entry.parent);
        return `You smell something rotten in your ${container}.`;
    }
    if (entry.source === 'floor' && !entry.parent && floorObjectVisible(obj.ox, obj.oy))
        return `The ${name} rots away.`;
    return '';
}

function refreshCorpseTimerContainerWeights(entry) {
    if (!entry?.parent) return;
    refreshGlobEntryContainerWeights(entry);
    if (entry.root) refreshTipContainerWeight(entry.root);
}

function removeCorpseTimerObject(entry) {
    const obj = entry.obj;
    rememberUsedUpShopBill(obj);
    if (entry.parent) {
        removeContainedObject(entry.parent, obj);
        refreshCorpseTimerContainerWeights(entry);
        return;
    }
    if (entry.source === 'inventory') {
        game.inventory = (game.inventory || []).filter(item => item !== obj);
        game._pet_food_scan_inventory = game.inventory;
        return;
    }
    if (entry.source === 'floor') {
        removeFloorObject(obj);
        if (typeof obj.ox === 'number' && typeof obj.oy === 'number') newsym(obj.ox, obj.oy);
        return;
    }
    if (entry.source === 'buried') {
        if (game.level?.buriedobjlist)
            game.level.buriedobjlist = game.level.buriedobjlist.filter(item => item !== obj);
        if (game.level?.objects)
            game.level.objects = game.level.objects.filter(item => item !== obj);
        if (typeof obj.ox === 'number' && typeof obj.oy === 'number') newsym(obj.ox, obj.oy);
        return;
    }
    if (entry.source === 'minvent' && entry.owner)
        entry.owner.minvent = (entry.owner.minvent || []).filter(item => item !== obj);
}

function rotCorpseTimerEntry(entry, { silent = false } = {}) {
    const messages = [];
    if (!silent) {
        const message = corpseTimerRotMessage(entry);
        if (message) messages.push(message);
    }
    removeCorpseTimerObject(entry);
    return messages;
}

function scheduleCorpseFallbackRot(obj) {
    clearCorpseTimeout(obj);
    const moves = game.moves || 0;
    const age = obj?.age ?? moves;
    const delay = Math.max(1, d(5, 50) - Math.max(0, moves - age));
    obj.rotAwayTurn = moves + delay;
}

function corpseTimerMonsterData(obj) {
    const saved = savedCorpstatMonsterTraits(obj);
    if (saved?.data && typeof saved.data === 'object' && saved.data.name) return saved.data;
    if (typeof saved?.data === 'string') {
        const savedName = saved.data.toLowerCase();
        const savedData = monsterByRndName(savedName) || RANDOM_MONSTER_BY_NAME.get(savedName);
        if (savedData) return savedData;
    }
    if (obj?.corpsenm?.name) return obj.corpsenm;
    const name = corpseName(obj);
    return name ? monsterByRndName(name) || RANDOM_MONSTER_BY_NAME.get(name) || null : null;
}

function isRiderCorpseTimerObject(obj) {
    const name = corpseName(obj);
    return !!(obj?.corpsenm?.rider || name === 'death' || name === 'pestilence' || name === 'famine');
}

function applyCorpseGenderToRevivedMonster(mon, obj) {
    const gender = (obj?.spe || 0) & CORPSTAT_GENDER;
    if (gender === CORPSTAT_MALE) mon.female = false;
    else if (gender === CORPSTAT_FEMALE) mon.female = true;
}

function corpseTimerLocation(entry) {
    if (entry.source === 'inventory') {
        return { x: game.u?.ux || 0, y: game.u?.uy || 0, carried: true };
    }
    if (entry.source === 'minvent' && entry.owner) {
        return { x: entry.owner.mx || 0, y: entry.owner.my || 0, carried: true };
    }
    const root = entry.root || entry.obj;
    if (typeof root?.ox === 'number' && typeof root?.oy === 'number')
        return { x: root.ox, y: root.oy, carried: false };
    if (typeof entry.obj?.ox === 'number' && typeof entry.obj?.oy === 'number')
        return { x: entry.obj.ox, y: entry.obj.oy, carried: false };
    return { x: game.u?.ux || 0, y: game.u?.uy || 0, carried: true };
}

function corpseRevivalSpot(entry, data) {
    const loc = corpseTimerLocation(entry);
    if (loc.carried || entry.parent) return enextoMonsterSpot(loc.x, loc.y, data) || null;
    return { x: loc.x, y: loc.y };
}

function corpseRevivalMessages(entry, mon, data) {
    const messages = [];
    if (entry.source === 'inventory') {
        if (entry.parent) messages.push(`Something writhes out of your ${articlelessObjectName(entry.root || entry.parent)}!`);
        else messages.push('You feel squirming in your backpack!');
    } else if (entry.source === 'minvent') {
        if (!game.u?.blind && couldsee(mon.mx, mon.my))
            messages.push(`Something writhes out of the ${entry.owner?.data?.name || 'monster'}'s pack!`);
    } else if (entry.source === 'floor' && !entry.parent && floorObjectVisible(mon.mx, mon.my)) {
        messages.push(`${sentenceCase(monsterIndefiniteName(data?.name || 'monster'))} rises from the dead!`);
    }
    return messages;
}

function handleCorpseRevivalFailure(entry, { zombified = false } = {}) {
    if (zombified) return rotCorpseTimerEntry(entry, { silent: true });
    const obj = entry.obj;
    if (isRiderCorpseTimerObject(obj) && rn2(99)) {
        clearCorpseTimeout(obj);
        obj.reviveTurn = (game.moves || 0) + riderRevivalDelay(obj, true);
    } else {
        scheduleCorpseFallbackRot(obj);
    }
    return [];
}

async function reviveCorpseTimerEntry(entry, data = corpseTimerMonsterData(entry.obj), options = {}) {
    const obj = entry.obj;
    const savedTraits = savedCorpstatMonsterTraits(obj);
    clearCorpseTimeout(obj);
    if (!data?.name || obj.norevive || isMonsterGenocidedName(data.name))
        return handleCorpseRevivalFailure(entry, options);
    const spot = corpseRevivalSpot(entry, data);
    if (!spot) return handleCorpseRevivalFailure(entry, options);
    const flags = NO_MINVENT | MM_NOMSG | MM_NOCOUNTBIRTH | MM_NOWAIT
        | (savedTraits ? MM_NOTAIL : 0);
    const mon = await makemon(data, spot.x, spot.y, flags);
    if (!mon) return handleCorpseRevivalFailure(entry, options);

    if (savedTraits) applySavedCorpstatMonsterTraits(mon, savedTraits, data);
    mon.mrevived = 1;
    mon.mundetected = 0;
    mon.m_ap_type = 0;
    mon.appearObj = null;
    mon.appearGlyph = null;
    mon.appearColor = null;
    if (!savedTraits) applyCorpseGenderToRevivedMonster(mon, obj);
    removeCorpseTimerObject(entry);
    newsym(mon.mx, mon.my);
    return corpseRevivalMessages(entry, mon, data);
}

async function zombifyCorpseTimerEntry(entry) {
    const obj = entry.obj;
    const zombieName = zombieFormNameForCorpse(obj);
    const data = zombieName ? monsterByRndName(zombieName) || RANDOM_MONSTER_BY_NAME.get(zombieName) : null;
    clearCorpseTimeout(obj);
    if (!data?.name || isMonsterGenocidedName(data.name))
        return rotCorpseTimerEntry(entry, { silent: true });
    clearSavedCorpstatMonsterTraits(obj);
    obj.corpsenm = data;
    obj.zombifying = false;
    Object.assign(obj, object_display(obj));
    return reviveCorpseTimerEntry(entry, data, { zombified: true });
}

async function processCorpseTimerEntry(entry) {
    if (!isCorpseItem(entry.obj)) return [];
    if (corpseInIceBox(entry)) {
        clearCorpseTimeout(entry.obj);
        return [];
    }
    const due = corpseTimerDue(entry);
    if (!due) return [];
    if (due.action === 'rot') return rotCorpseTimerEntry(entry);
    if (due.action === 'zombify') return zombifyCorpseTimerEntry(entry);
    return reviveCorpseTimerEntry(entry);
}

export async function processCorpseTimers(g = game) {
    const moves = g.moves || 0;
    const due = collectCorpseTimerEntries(g)
        .map(entry => ({ entry, due: corpseTimerDue(entry, moves) }))
        .filter(item => item.due)
        .sort((a, b) => a.due.turn - b.due.turn
            || CORPSE_TIMER_ACTION_RANK[a.due.action] - CORPSE_TIMER_ACTION_RANK[b.due.action]
            || ((a.entry.obj.id || a.entry.obj.oid || 0) - (b.entry.obj.id || b.entry.obj.oid || 0)));
    const messages = [];
    for (const { entry } of due)
        messages.push(...await processCorpseTimerEntry(entry));
    return messages;
}

function globInIceBox(entry) {
    return !!(entry.obj?.inIceBox || entry.ancestors.some(isIceBoxObject));
}

function globIceState(entry) {
    if (entry.source !== 'floor') return 'none';
    const root = entry.root || entry.obj;
    const x = root?.ox;
    const y = root?.oy;
    if (typeof x !== 'number' || typeof y !== 'number') return 'none';
    const loc = game.level?.at?.(x, y);
    if (loc?.typ !== ICE) return 'none';
    return root.buried ? 'buried' : 'onice';
}

function removeShrunkGlob(entry) {
    const obj = entry.obj;
    rememberUsedUpShopBill(obj);
    if (entry.parent) {
        removeContainedObject(entry.parent, obj);
        refreshGlobEntryContainerWeights(entry);
        return;
    }
    if (entry.source === 'inventory') {
        game.inventory = (game.inventory || []).filter(item => item !== obj);
        return;
    }
    if (entry.source === 'floor') {
        game.level.objects = (game.level?.objects || []).filter(item => item !== obj);
        if (typeof obj.ox === 'number' && typeof obj.oy === 'number') newsym(obj.ox, obj.oy);
        return;
    }
    if (entry.source === 'minvent' && entry.owner)
        entry.owner.minvent = (entry.owner.minvent || []).filter(item => item !== obj);
}

function outerInventoryContainer(entry) {
    if (entry.source !== 'inventory' || !entry.parent) return null;
    return entry.root || entry.parent;
}

function usedUpShopBillName(obj) {
    let name = String(obj?.line || '')
        .replace(/^[a-zA-Z$] - /, '')
        .replace(/ \(unpaid, \d+ zorkmids?\)/, '');
    if (name) return name;
    const baseName = pickupObjectName({ ...(obj || {}), quan: 1 });
    return `${/^[aeiou]/i.test(baseName) ? 'an' : 'a'} ${baseName}`;
}

function rememberUsedUpShopBill(obj) {
    const { shkp, entry: billEntry } = shopkeeperOwningBillEntry(obj);
    const price = shopBillEntryTotal(billEntry);
    if (!shkp || !billEntry || !(price > 0)) return;
    const name = usedUpShopBillName(obj);
    billEntry.useup = true;
    clearObjectShopBillState(obj);
    billEntry.name = name;
    billEntry.shopkeeperId = shopkeeperIdentity(shkp);
    if (usedUpShopBillTrackerForId(billEntry.bo_id, shkp)) return;
    game._usedUpShopBills ??= [];
    game._usedUpShopBills.push({
        name,
        price,
        bo_id: billEntry.bo_id,
        shopkeeperId: shopkeeperIdentity(shkp),
    });
}

function objectWeightKind(obj) {
    const kind = String(obj?.actualKind || obj?.kind || obj?.spellName || obj?.spell?.name || '').toLowerCase();
    if (/war hammer|mjollnir/.test(kind)) return 'war hammer';
    if (!kind && isBoulderObject(obj)) return 'boulder';
    if (!kind && obj?.otyp === LARGE_BOX) return 'large box';
    if (!kind && obj?.otyp === CHEST) return 'chest';
    if (!kind && obj?.otyp === ICE_BOX) return 'ice box';
    if (!kind && obj?.otyp === SACK) return 'sack';
    if (!kind && obj?.otyp === OILSKIN_SACK) return 'oilskin sack';
    if (!kind && obj?.otyp === BAG_OF_HOLDING) return 'bag of holding';
    if (!kind && obj?.otyp === BAG_OF_TRICKS) return 'bag of tricks';
    return kind;
}

function objectWeightClass(obj) {
    return obj?.cls || (obj?.otyp === RING_CLASS ? 'ring'
        : obj?.otyp === SCROLL_CLASS || obj?.otyp === SCR_SCARE_MONSTER ? 'scroll'
            : obj?.otyp === POTION_CLASS ? 'potion'
                : obj?.otyp === WAND_CLASS ? 'wand'
                    : obj?.otyp === GEM_CLASS ? 'gem'
                        : obj?.otyp === FOOD_CLASS ? 'food'
                            : obj?.otyp === AMULET_CLASS ? 'amulet' : '');
}

function containerBaseWeight(obj) {
    const kind = objectWeightKind(obj);
    if (obj?.otyp === LARGE_BOX || kind === 'large box') return 350;
    if (obj?.otyp === CHEST || kind === 'chest') return 600;
    if (obj?.otyp === ICE_BOX || kind === 'ice box') return 900;
    if (obj?.otyp === SACK || obj?.otyp === OILSKIN_SACK
        || obj?.otyp === BAG_OF_HOLDING || obj?.otyp === BAG_OF_TRICKS
        || kind === 'sack' || kind === 'oilskin sack'
        || kind === 'bag of holding' || kind === 'bag of tricks')
        return 15;
    return null;
}

function isGlobWeightContainerObject(obj) {
    const kind = objectWeightKind(obj);
    return obj?.otyp === LARGE_BOX || obj?.otyp === CHEST || obj?.otyp === ICE_BOX
        || obj?.otyp === SACK || obj?.otyp === OILSKIN_SACK
        || obj?.otyp === BAG_OF_HOLDING || obj?.otyp === BAG_OF_TRICKS
        || kind === 'large box' || kind === 'chest' || kind === 'ice box'
        || kind === 'sack' || kind === 'oilskin sack'
        || kind === 'bag of holding' || kind === 'bag of tricks';
}

const WISHED_OBJECT_WEIGHT_OVERRIDES = new Map([
    ['bell', 30],
    ['bell of opening', 10],
    ['book of the dead', 20],
    ['heavy iron ball', WT_IRON_BALL_BASE],
    ['horn of plenty', 18],
    ['tooled horn', 18],
]);

function globObjectWeight(obj) {
    if (isGlobbyObject(obj)) return Math.max(0, obj.owt ?? 20);
    if (obj?.otyp === GOLD_PIECE || obj?.cls === 'coin' || obj?.glyph === '$')
        return Math.max(1, Math.trunc(((obj.quan || 1) + 50) / 100));
    const contents = globContents(obj);
    if (contents.length || isGlobWeightContainerObject(obj)) {
        let contentsWeight = contents.reduce((sum, item) => sum + globObjectWeight(item), 0);
        if (isBagOfHoldingObject(obj)) {
            contentsWeight = obj.cursed ? contentsWeight * 2
                : obj.blessed ? Math.trunc((contentsWeight + 3) / 4)
                    : Math.trunc((contentsWeight + 1) / 2);
        }
        const baseKind = objectWeightKind(obj);
        const base = containerBaseWeight(obj) ?? OBJECT_WEIGHTS[baseKind] ?? CLASS_WEIGHTS[objectWeightClass(obj)] ?? 0;
        return Math.max(0, base + contentsWeight);
    }
    const kind = objectWeightKind(obj);
    const cls = objectWeightClass(obj);
    const unitWeight = OBJECT_WEIGHTS[kind] ?? CLASS_WEIGHTS[cls] ?? obj?.owt ?? 0;
    return Math.max(0, unitWeight * (obj?.quan || 1));
}

function wishedObjectFinalWeight(obj) {
    if (!obj) return 0;
    if (isCandelabrumOfInvocationItem(obj)) {
        const candleWeight = OBJECT_WEIGHTS['tallow candle'] ?? 2;
        return 200 + Math.max(0, Math.trunc(Number(obj.spe || 0))) * candleWeight;
    }
    const kind = objectKindKey(obj);
    const metadata = wishObjectMetadataForItem(obj);
    if (metadata?.unitWeight != null) return Math.max(0, metadata.unitWeight * (obj.quan || 1));
    const override = WISHED_OBJECT_WEIGHT_OVERRIDES.get(kind);
    if (override != null) return Math.max(0, override * (obj.quan || 1));
    return globObjectWeight(obj);
}

function heroCarriedWeight() {
    let weight = Math.max(0, Math.trunc(((game._goldCount || 0) + 50) / 100));
    for (const item of game.inventory || []) {
        if (isGoldObject(item)) continue;
        weight += globObjectWeight(item);
    }
    return weight;
}

function heroCarryCapacity() {
    const stats = game.u?.acurr?.a || [];
    const normalCapacity = Math.min(1000, 25 * ((stats[0] ?? 10) + (stats[4] ?? 10)) + 50);
    return Is_airlevel(game.u?.uz) || game.u?.levitating ? 1000 : normalCapacity;
}

const PICKUP_BURDEN_LEVELS = {
    unencumbered: 0,
    burdened: 1,
    stressed: 2,
    strained: 3,
    overtaxed: 4,
    overloaded: 5,
};

function heroEncumbranceForWeight(weight) {
    const capacity = heroCarryCapacity();
    const burden = Math.trunc(Number(weight || 0)) - capacity;
    if (burden <= 0) return 0;
    if (capacity <= 1) return OVERLOADED;
    return Math.min(Math.trunc(burden * 2 / capacity) + 1, OVERLOADED);
}

function pickupBurdenLimit() {
    const value = String(game.flags?.pickup_burden || 'stressed').toLowerCase();
    return PICKUP_BURDEN_LEVELS[value] ?? PICKUP_BURDEN_LEVELS.stressed;
}

function containerTakeoutBurdenPrefix(encumbrance) {
    if (encumbrance >= 4) return 'You have extreme difficulty';
    if (encumbrance >= 3) return 'You have much trouble';
    if (encumbrance >= 2) return 'You have trouble';
    return 'You have a little trouble';
}

function containerTakeoutObjectView(obj, count) {
    const quantity = Math.max(1, Math.trunc(Number(count || obj?.quan || 1)));
    return quantity === Math.max(1, Math.trunc(Number(obj?.quan || 1)))
        ? obj
        : { ...obj, quan: quantity };
}

function containerTakeoutWeightIncrease(obj, count, goldCount = game._goldCount || 0) {
    const quantity = Math.max(1, Math.trunc(Number(count || obj?.quan || 1)));
    if (shopBillableGold(obj)) {
        const oldGoldWeight = Math.max(0, Math.trunc((Math.max(0, Math.trunc(Number(goldCount || 0))) + 50) / 100));
        const newGoldWeight = Math.max(0, Math.trunc((Math.max(0, Math.trunc(Number(goldCount || 0))) + quantity + 50) / 100));
        return newGoldWeight - oldGoldWeight;
    }
    return globObjectWeight(containerTakeoutObjectView(obj, quantity));
}

function containerTakeoutLiftableCount(container, obj, currentWeight, goldCount = game._goldCount || 0) {
    const count = Math.max(1, Math.trunc(Number(obj?.quan || 1)));
    if ((game.inventory || []).includes(container)) return count;
    const maxWeight = heroCarryCapacity() * 3;
    if (currentWeight + containerTakeoutWeightIncrease(obj, count, goldCount) <= maxWeight)
        return count;
    if (count <= 1 || obj?.otyp === LOADSTONE || objectKindKey(obj) === 'loadstone' || globContents(obj).length)
        return 0;

    let low = 0;
    let high = count;
    while (low < high) {
        const mid = Math.ceil((low + high) / 2);
        if (currentWeight + containerTakeoutWeightIncrease(obj, mid, goldCount) <= maxWeight)
            low = mid;
        else high = mid - 1;
    }
    return low;
}

function floorPickupObjectKey(obj) {
    if (!obj) return null;
    return obj.id ?? obj.o_id
        ?? `${obj.ox},${obj.oy},${obj.otyp},${obj.kind || obj.actualKind || ''}`;
}

function splitFloorPickupObjectForLift(obj, count) {
    const quantity = Math.max(1, Math.trunc(Number(obj?.quan || 1)));
    const takeCount = Math.max(1, Math.min(quantity, Math.trunc(Number(count || quantity))));
    if (isLoadstoneObject(obj)) return obj;
    if (!obj || takeCount >= quantity) return obj;
    const lifted = { ...obj, id: next_ident(), quan: takeCount };
    delete lifted.o_id;
    delete lifted._shopBillObjectId;
    delete lifted.letter;
    delete lifted.line;
    obj.quan = quantity - takeCount;
    return lifted;
}

function isLoadstoneObject(obj) {
    return !!obj && (obj.otyp === LOADSTONE || objectKindKey(obj) === 'loadstone');
}

function isBoulderObject(obj) {
    return !!obj && (obj.otyp === BOULDER || objectKindKey(obj) === 'boulder');
}

function normalizeBoulderObject(obj) {
    if (!isBoulderObject(obj)) return obj;
    obj.otyp = BOULDER;
    obj.cls = 'rock';
    obj.glyph = '`';
    obj.kind ||= 'boulder';
    obj.actualKind ||= 'boulder';
    obj.quan = Math.max(1, Math.trunc(Number(obj.quan || 1)));
    obj.owt = 6000 * obj.quan;
    return obj;
}

const ROCK_THROWING_FORM_NAMES = new Set([
    'giant', 'stone giant', 'hill giant', 'fire giant', 'frost giant',
    'storm giant', 'titan', 'cyclops', 'lord surtur',
]);

function heroThrowsRocks() {
    const form = game.u?._polyself_form || game.u?._polyself_base || {};
    const name = String(form.name || '').toLowerCase();
    return !!(form.throwsRocks || form.rockThrower || ROCK_THROWING_FORM_NAMES.has(name));
}

function carriedBoulderObject() {
    return (game.inventory || []).find(item => isBoulderObject(item));
}

function carriedLoadstoneObject() {
    return (game.inventory || []).find(item => isLoadstoneObject(item));
}

function noSlotSpecialPickupMessage(obj) {
    const name = pickupObjectName(obj);
    return `You are carrying too much stuff to pick up ${(obj?.quan || 1) === 1 ? 'another' : 'more'} ${name}.`;
}

function boulderSokobanPickupMessage(obj) {
    return `You cannot get your hand around this ${pickupObjectName({ ...obj, quan: 1 })}.`;
}

function boulderTooHeavyPickupMessage(obj) {
    const quantity = Math.max(1, Math.trunc(Number(obj?.quan || 1)));
    const phrase = pickupObjectPhrase(obj);
    const hereVerb = quantity === 1 ? 'is' : 'are';
    if ((game.inventory || []).length || (game._goldCount || 0))
        return `There ${hereVerb} ${phrase} here, but you cannot lift any more.`;
    return `There ${hereVerb} ${phrase} here, but ${quantity === 1 ? 'it' : 'even one'} is too heavy for you to lift.`;
}

function boulderContainerTooHeavyPickupMessage(container, obj) {
    const quantity = Math.max(1, Math.trunc(Number(obj?.quan || 1)));
    const phrase = pickupObjectPhrase(obj);
    const verb = quantity === 1 ? 'is' : 'are';
    if ((game.inventory || []).length || (game._goldCount || 0))
        return `There ${verb} ${phrase} in ${containerObjectPhrase(container)}, but you cannot carry any more.`;
    return `There ${verb} ${phrase} in ${containerObjectPhrase(container)}, but ${quantity === 1 ? 'it' : 'even one'} is too heavy for you to carry.`;
}

function curseLoadstoneLeavingInventory(obj) {
    if (!isLoadstoneObject(obj)) return;
    obj.cursed = true;
    obj.blessed = false;
}

function cursedLoadstoneLetGoMessage(obj, word = 'drop') {
    if (obj) obj.bknown = true;
    const plural = Math.max(1, Math.trunc(Number(obj?.quan || 1))) > 1;
    return `For some reason, you cannot ${word} ${plural ? 'any of ' : ''}the stone${plural ? 's' : ''}!`;
}

function isScareMonsterScrollObject(obj) {
    if (!obj) return false;
    if (obj.otyp === SCR_SCARE_MONSTER || obj.scrollIndex === 3) return true;
    const raw = String(obj.actualKind || obj.kind || '').toLowerCase()
        .replace(/^scroll(?::| of | labeled )/, '');
    return raw === 'scare monster';
}

function normalizeScareMonsterScrollObject(obj) {
    if (!isScareMonsterScrollObject(obj)) return obj;
    obj.cls = 'scroll';
    obj.glyph = '?';
    obj.scrollIndex = 3;
    obj.actualKind ||= 'scroll of scare monster';
    return obj;
}

function scareMonsterScrollDustMessage(obj) {
    const plural = Math.max(1, Math.trunc(Number(obj?.quan || 1))) > 1;
    return `The scroll${plural ? 's' : ''} ${plural ? 'turn' : 'turns'} to dust as you pick ${plural ? 'them' : 'it'} up.`;
}

function floorUsedUpShopBillMessage(obj, price) {
    if (!obj || !(price > 0)) return '';
    const units = Math.max(1, Math.trunc(Number(shopPricingUnits(obj) || 1)));
    const unitPrice = units > 1 ? Math.max(1, Math.trunc(price / units)) : Math.trunc(price);
    const subject = units > 1
        ? pickupObjectPhrase(obj)
        : pickupObjectName({ ...(obj || {}), quan: 1 });
    return `The ${subject} will cost you ${unitPrice} ${shopCurrency(unitPrice)}${units > 1 ? ' each' : ''}.`;
}

function useUpFloorObjectWithShopBill(obj) {
    if (!obj) return '';
    const x = obj.ox ?? game.u?.ux;
    const y = obj.oy ?? game.u?.uy;
    const shkp = x == null || y == null ? null : shopkeeperForCostlySpot(x, y);
    let billMessage = '';
    if (shopkeeperInHisShop(shkp)) {
        const price = shopItemPrice(obj, x, y);
        if (price > 0) {
            addObjectToShopBill(shkp, obj, price, { useup: true });
            markObjectShopBillUsedUp(obj, shkp);
            billMessage = floorUsedUpShopBillMessage(obj, price);
        }
    }
    game.level.objects = (game.level?.objects || []).filter(item => item !== obj);
    if (x != null && y != null) newsym(x, y);
    return billMessage;
}

function finalizeScareMonsterDust(preflight) {
    const dustObj = preflight?.scareDustObj || preflight;
    return useUpFloorObjectWithShopBill(dustObj);
}

function observeFloorPickupObject(obj) {
    if (!obj || game.u?.blind || heroIsHallucinating()) return;
    obj.dknown = true;
    recordObservedObjectDiscovery(obj);
}

function scheduleScareMonsterDustTryCall(preflight, pending = {}) {
    const dustObj = preflight?.scareDustObj;
    if (!dustObj || !preflight?.scareDustTryCall) return false;
    prepareScrollTryCall(dustObj, 3, pending.moveCost ?? 1);
    game._scroll_trycall_pending = {
        kind: 'scareDust',
        preflight,
        moveCost: pending.moveCost ?? 1,
        pickupListState: pending.pickupListState || null,
    };
    game._command_mode = 'callScrollAfterMore';
    return true;
}

async function finishPendingScrollTryCall(defaultMoveCost = 1) {
    const pending = game._scroll_trycall_pending;
    game._scroll_trycall_pending = null;
    if (!pending) return false;
    let followupMessage = '';
    if (pending.kind === 'scareDust') followupMessage = finalizeScareMonsterDust(pending.preflight);
    if (pending.pickupListState) {
        if (followupMessage) pending.pickupListState.messages.push(followupMessage);
        pending.pickupListState.index = (pending.pickupListState.index || 0) + 1;
        await continuePickupListProcessing(pending.pickupListState);
        return true;
    }
    game.context.move = pending.moveCost ?? defaultMoveCost;
    if (followupMessage) await setMessage(followupMessage);
    return true;
}

function artifactPowerSourceName(obj) {
    const name = String(obj?.artifact || pickupObjectName(obj) || 'the artifact');
    return name.replace(/^The\b/, 'the');
}

function containerTakeoutArtifactTouch(obj) {
    const def = artifactDefinitionForName(obj?.artifact);
    if (!def) return { ok: true, skip: false, messages: [] };
    const status = artifactTouchStatus(def);
    const messages = [];
    const blast = ((status.badClass || status.badAlign) && status.selfWilled)
        || (status.badAlign && !rn2(4));
    if (blast) {
        messages.push(`You are blasted by ${artifactPowerSourceName(obj)}'s power!`);
        const damage = d(heroHasAntimagic() ? 2 : 4, status.selfWilled ? 10 : 4);
        if (game.u) game.u.uhp = Math.max(0, (game.u.uhp || 0) - damage);
        exerciseAttribute(A_WIS, false);
        if ((game.u?.uhp || 0) <= 0) {
            game._death_cause = `touching ${def.name}`;
            messages.push('You die...');
            return { ok: false, fatal: true, message: messages.join('  '), messages };
        }
    }
    if (status.badClass && status.badAlign && status.selfWilled) {
        messages.push(`${obj.artifact || pickupObjectName(obj)} evades your grasp!`);
        return { ok: true, skip: true, messages };
    }
    return { ok: true, skip: false, messages };
}

function isPetrifyingCorpseObject(obj) {
    if (!(obj?.otyp === CORPSE || obj?.otyp === 'corpse')) return false;
    const name = corpseMonsterName(obj).toLowerCase();
    return name === 'cockatrice' || name === 'chickatrice' || !!obj?.corpsenm?.touchPetrifies;
}

function isRiderCorpseObject(obj) {
    if (!(obj?.otyp === CORPSE || obj?.otyp === 'corpse')) return false;
    const name = corpseMonsterName(obj).toLowerCase();
    return name === 'death' || name === 'famine' || name === 'pestilence';
}

function containerTakeoutFatalCorpseMessage(obj) {
    if (!isPetrifyingCorpseObject(obj) || wornGlovesItem() || game.u?.stoneResistance)
        return '';
    if (heroPolyselfResistsStoning()) return '';
    const polyselfMessage = maybeTurnPolyselfIntoStoneGolem();
    if (polyselfMessage) return '';
    const name = corpseMonsterName(obj).toLowerCase() || 'cockatrice';
    if (game.u) game.u.uhp = 0;
    game._death_cause = `petrified by a ${name} corpse`;
    return `Touching ${pickupObjectPhrase({ ...obj, quan: 1 })} is a fatal mistake.`;
}

function containerTakeoutPreliftCheck(obj) {
    const artifactTouch = containerTakeoutArtifactTouch(obj);
    if (!artifactTouch.ok || artifactTouch.skip) return artifactTouch;
    const fatalMessage = containerTakeoutFatalCorpseMessage(obj);
    if (fatalMessage) return { ok: false, fatal: true, message: fatalMessage };
    return { ok: true, skip: false, messages: artifactTouch.messages || [] };
}

function floorPickupPreflightMessage(preflight) {
    const parts = [...(preflight?.messages || [])];
    const message = preflight?.message || '';
    if (message && message !== parts.join('  ')) parts.push(message);
    return parts.join('  ') || 'You cannot pick that up.';
}

function floorPickupBurdenPromptMessage(preflight) {
    return [...(preflight?.messages || []), preflight?.prompt || 'Continue? [ynq] (q)'].join('  ');
}

function floorPickupAcceptedPreflight(preflight) {
    return { ...(preflight || {}), messages: [], prompt: null };
}

async function floorPickupRiderCorpseRevival(obj) {
    if (!isCorpseItem(obj) || !isRiderCorpseTimerObject(obj)) return null;
    const messages = ['At your touch, the corpse suddenly moves...'];
    messages.push(...await reviveCorpseTimerEntry({ obj, source: 'floor' }));
    exerciseAttribute(A_WIS, false);
    return { ok: false, riderRevival: true, messages };
}

function findFloorPickupInventoryMergeTargetForPreflight(source, sourcePrice = null) {
    if (!pickupObjectCanInventoryMerge(source)) return null;
    const x = source?.ox ?? game.u?.ux;
    const y = source?.oy ?? game.u?.uy;
    const shkp = x == null || y == null ? null : shopkeeperForCostlySpot(x, y);
    const price = sourcePrice != null ? Number(sourcePrice) : shopItemPrice(source, x, y);
    const sourceWillBeUnpaid = Number.isFinite(price) && price > 0 && shopkeeperInHisShop(shkp);
    if (sourceWillBeUnpaid) return null;
    const billing = { shkp, price, sourceWillBeUnpaid };
    for (const target of game.inventory || []) {
        if (!pickedObjectInventoryMergeCompatible(target, source, sourceWillBeUnpaid, shkp)) continue;
        if (!containerTakeoutBillMergeCompatible(source, target, billing)) continue;
        return target;
    }
    return null;
}

function findFloorPickupFoodMergeTargetForPreflight(source, sourcePrice = null) {
    if (!isSimpleMergeableFoodObject(source)) return null;
    return findFloorPickupInventoryMergeTargetForPreflight(source, sourcePrice);
}

async function floorPickupPreflight(obj, { shopPrice = null, prompt = true, scareSpecial = true } = {}) {
    const promptKey = floorPickupObjectKey(obj);
    const cached = game._skip_floor_pickup_preflight_once;
    if (cached && cached.objectId === promptKey) {
        game._skip_floor_pickup_preflight_once = null;
        return { ...(cached.preflight || {}), prompt: null };
    }
    if (cached) game._skip_floor_pickup_preflight_once = null;

    observeFloorPickupObject(obj);
    const prelift = containerTakeoutPreliftCheck(obj);
    if (!prelift.ok || prelift.skip) return prelift;
    const riderRevival = await floorPickupRiderCorpseRevival(obj);
    if (riderRevival) return riderRevival;

    const currentWeight = heroCarriedWeight();
    const gold = Math.max(0, Math.trunc(Number(game._goldCount || 0)));
    const messages = [...(prelift.messages || [])];
    const originalCount = Math.max(1, Math.trunc(Number(obj?.quan || 1)));
    if (isBoulderObject(obj)) {
        normalizeBoulderObject(obj);
        if (game.level?.flags?.sokoban_rules) {
            return {
                ok: false,
                move: true,
                message: boulderSokobanPickupMessage(obj),
                messages,
            };
        }
        if (heroThrowsRocks()) {
            const x = obj?.ox ?? game.u?.ux;
            const y = obj?.oy ?? game.u?.uy;
            const price = shopPrice != null ? shopPrice : shopItemPrice(obj, x, y);
            const mergeTarget = findFloorPickupInventoryMergeTargetForPreflight(obj, price);
            const hasSlot = !!simulatedNextInventoryLetters(1);
            if (!hasSlot && carriedBoulderObject() && !mergeTarget) {
                return {
                    ok: false,
                    move: true,
                    message: noSlotSpecialPickupMessage(obj),
                    messages,
                };
            }
            return {
                ok: true,
                skip: false,
                messages,
                takeCount: originalCount,
                liftView: obj,
                prompt: null,
                inventoryLetter: !hasSlot && !mergeTarget ? '#' : null,
            };
        }
    }
    if (isLoadstoneObject(obj)) {
        const x = obj?.ox ?? game.u?.ux;
        const y = obj?.oy ?? game.u?.uy;
        const price = shopPrice != null ? shopPrice : shopItemPrice(obj, x, y);
        const mergeTarget = findFloorPickupInventoryMergeTargetForPreflight(obj, price);
        const hasSlot = !!simulatedNextInventoryLetters(1);
        if (!hasSlot && carriedLoadstoneObject() && !mergeTarget) {
            return {
                ok: false,
                message: noSlotSpecialPickupMessage(obj),
                messages,
            };
        }
        return {
            ok: true,
            skip: false,
            messages,
            takeCount: originalCount,
            liftView: obj,
            prompt: null,
            inventoryLetter: !hasSlot && !mergeTarget ? '#' : null,
        };
    }
    const takeCount = containerTakeoutLiftableCount(null, obj, currentWeight, gold);
    if (takeCount < 1) {
        return {
            ok: false,
            move: isBoulderObject(obj) ? true : undefined,
            message: isBoulderObject(obj)
                ? boulderTooHeavyPickupMessage(obj)
                : `There is ${pickupObjectPhrase(obj)} here, but you cannot carry any more.`,
            messages,
        };
    }
    if (takeCount < originalCount)
        messages.push(`You can only lift ${takeCount === 1 ? 'one' : 'some'} of the ${pickupObjectPhrase(obj)} lying here.`);

    let scareResetSpeOnDecline = false;
    let scareRemainderState = null;
    if (scareSpecial && isScareMonsterScrollObject(obj)) {
        normalizeScareMonsterScrollObject(obj);
        const oldState = {
            blessed: !!obj.blessed,
            cursed: !!obj.cursed,
            spe: obj.spe || 0,
        };
        if (obj.blessed) {
            obj.blessed = false;
            scareRemainderState = oldState;
        } else if (!obj.cursed && !(obj.spe || 0)) {
            obj.spe = 1;
            scareResetSpeOnDecline = true;
            scareRemainderState = oldState;
        } else {
            const dustObj = splitFloorPickupObjectForLift(obj, takeCount);
            normalizeScareMonsterScrollObject(dustObj);
            return {
                ok: false,
                scareDust: true,
                scareDustObj: dustObj,
                scareDustTryCall: shouldTryCallScroll('scare monster', dustObj, 3),
                move: true,
                message: scareMonsterScrollDustMessage(dustObj),
                messages,
            };
        }
    }

    const view = containerTakeoutObjectView(obj, takeCount);
    const x = obj?.ox ?? game.u?.ux;
    const y = obj?.oy ?? game.u?.uy;
    const price = shopPrice != null && takeCount === originalCount ? shopPrice : shopItemPrice(view, x, y);
    const mergeTarget = findFloorPickupFoodMergeTargetForPreflight(view, price)
        || findFloorPickupInventoryMergeTargetForPreflight(view, price);
    if (!shopBillableGold(view) && !mergeTarget && !simulatedNextInventoryLetters(1)) {
        if (scareResetSpeOnDecline) obj.spe = 0;
        return {
            ok: false,
            message: 'Your knapsack cannot accommodate any more items.',
            messages,
        };
    }

    let burdenPrompt = null;
    if (prompt) {
        const burdenLimit = Math.max(heroEncumbranceForWeight(currentWeight), pickupBurdenLimit());
        const nextWeight = currentWeight + containerTakeoutWeightIncrease(obj, takeCount, gold);
        const nextEncumbrance = heroEncumbranceForWeight(nextWeight);
        if (nextEncumbrance > burdenLimit)
            burdenPrompt = `${containerTakeoutBurdenPrefix(nextEncumbrance)} lifting ${pickupObjectPhrase(view)}.  Continue? [ynq] (q)`;
    }

    return {
        ok: true,
        skip: false,
        messages,
        takeCount,
        liftView: view,
        prompt: burdenPrompt,
        scareResetSpeOnDecline,
        scareRemainderState,
    };
}

function containerTakeoutPreflight(container, entries) {
    let currentWeight = heroCarriedWeight();
    let gold = Math.max(0, Math.trunc(Number(game._goldCount || 0)));
    const initialEncumbrance = heroEncumbranceForWeight(currentWeight);
    const burdenLimit = Math.max(initialEncumbrance, pickupBurdenLimit());
    let burdenPrompt = null;
    const messages = [];
    const planned = [];

    for (const entry of entries || []) {
        const obj = entry?.item || entry;
        if (!obj) continue;
        const prelift = containerTakeoutPreliftCheck(obj);
        if (!prelift.ok) return prelift;
        if (prelift.messages?.length) messages.push(...prelift.messages);
        if (prelift.skip) {
            continue;
        }
        const originalCount = Math.max(1, Math.trunc(Number(obj.quan || 1)));
        if (isBoulderObject(obj)) {
            normalizeBoulderObject(obj);
            if (game.level?.flags?.sokoban_rules) {
                return {
                    ok: false,
                    message: boulderSokobanPickupMessage(obj),
                    messages,
                };
            }
            if (heroThrowsRocks()) {
                const view = containerTakeoutObjectView(obj, originalCount);
                const mergeTarget = findContainerTakeoutInventoryMergeTarget(container, view);
                const hasSlot = !!simulatedNextInventoryLetters(1);
                const plannedBoulder = planned.some(item => isBoulderObject(item?.liftView || item?.item));
                if (!hasSlot && (carriedBoulderObject() || plannedBoulder) && !mergeTarget) {
                    return {
                        ok: false,
                        message: noSlotSpecialPickupMessage(obj),
                        messages,
                    };
                }
                const increase = containerTakeoutWeightIncrease(obj, originalCount, gold);
                currentWeight += increase;
                planned.push({
                    ...entry,
                    item: obj,
                    takeCount: originalCount,
                    liftView: view,
                    inventoryLetter: !hasSlot && !mergeTarget ? '#' : null,
                });
                continue;
            }
        }
        if (isLoadstoneObject(obj)) {
            const view = containerTakeoutObjectView(obj, originalCount);
            const mergeTarget = findContainerTakeoutInventoryMergeTarget(container, view);
            const hasSlot = !!simulatedNextInventoryLetters(1);
            if (!hasSlot && carriedLoadstoneObject() && !mergeTarget) {
                return {
                    ok: false,
                    message: noSlotSpecialPickupMessage(obj),
                    messages,
                };
            }
            const increase = containerTakeoutWeightIncrease(obj, originalCount, gold);
            currentWeight += increase;
            planned.push({
                ...entry,
                item: obj,
                takeCount: originalCount,
                liftView: view,
                inventoryLetter: !hasSlot && !mergeTarget ? '#' : null,
            });
            continue;
        }
        const takeCount = containerTakeoutLiftableCount(container, obj, currentWeight, gold);
        if (takeCount < 1) {
            return {
                ok: false,
                message: isBoulderObject(obj)
                    ? boulderContainerTooHeavyPickupMessage(container, obj)
                    : `There is ${pickupObjectPhrase(obj)} in ${containerObjectPhrase(container)}, but you cannot carry any more.`,
            };
        }
        if (takeCount < originalCount) {
            messages.push(`You can only carry ${takeCount === 1 ? 'one' : 'some'} of the ${pickupObjectPhrase(obj)} in ${containerObjectPhrase(container)}.`);
        }
        const view = containerTakeoutObjectView(obj, takeCount);
        const increase = containerTakeoutWeightIncrease(obj, takeCount, gold);
        const nextWeight = currentWeight + increase;
        const nextEncumbrance = heroEncumbranceForWeight(nextWeight);
        if (!burdenPrompt && nextEncumbrance > burdenLimit) {
            burdenPrompt = `${containerTakeoutBurdenPrefix(nextEncumbrance)} removing ${pickupObjectPhrase(view)}.  Continue? [ynq] (q)`;
        }
        currentWeight = nextWeight;
        if (shopBillableGold(obj)) gold += takeCount;
        planned.push({ ...entry, item: obj, takeCount, liftView: view });
    }

    const newSlotCount = planned
        .filter(entry => !entry.inventoryLetter && !shopBillableGold(entry.liftView) && !findContainerTakeoutInventoryMergeTarget(container, entry.liftView))
        .length;
    if (newSlotCount && !simulatedNextInventoryLetters(newSlotCount)) {
        return {
            ok: false,
            message: 'Your knapsack cannot accommodate any more items.',
        };
    }
    return { ok: true, message: '', entries: planned, messages, prompt: burdenPrompt };
}

function globEntryTopContainer(entry) {
    if (!entry?.parent) return null;
    const chain = entry.ancestors?.length ? entry.ancestors : [entry.parent];
    return chain[0] || entry.parent;
}

function refreshGlobEntryContainerWeights(entry, oldTopWeight = null) {
    if (!entry?.parent) return { top: null, oldTopWeight: 0, newTopWeight: 0 };
    const chain = entry.ancestors?.length ? entry.ancestors : [entry.parent];
    const top = globEntryTopContainer(entry);
    oldTopWeight ??= globObjectWeight(top);
    for (let i = chain.length - 1; i >= 0; i--) {
        const container = chain[i];
        if (container) container.owt = globObjectWeight(container);
    }
    return { top, oldTopWeight, newTopWeight: top?.owt ?? globObjectWeight(top) };
}

function globFloorVisible(entry) {
    const obj = entry.obj;
    return entry.source === 'floor' && !entry.parent
        && typeof obj.ox === 'number' && typeof obj.oy === 'number'
        && !game.u?.blind && couldsee(obj.ox, obj.oy);
}

function globShrinkName(obj) {
    return globObjectName(obj).replace(/^the /i, '');
}

function catchUpGlobShrink(entry, iceState) {
    const obj = entry.obj;
    const moves = game.moves || 0;
    const expired = obj.globShrinkTurn || moves;
    let delta = Math.trunc((moves - expired + 24) / 25);
    const nextDelay = 25 - (delta % 25);
    if (iceState === 'onice') delta = Math.trunc((delta + 2) / 3);
    if (delta >= Math.max(0, obj.owt ?? 20)) {
        obj.owt = 0;
        removeShrunkGlob(entry);
        return [];
    }
    obj.owt = Math.max(0, (obj.owt ?? 20) - Math.max(1, delta));
    refreshGlobEntryContainerWeights(entry);
    startGlobShrinkTimeout(obj, nextDelay);
    return [];
}

function processGlobShrinkEntry(entry) {
    const obj = entry.obj;
    if (!isGlobbyObject(obj) || typeof obj.globShrinkTurn !== 'number') return [];
    if (globInIceBox(entry)) {
        delete obj.globShrinkTurn;
        return [];
    }
    const iceState = globIceState(entry);
    if (obj.globShrinkTurn < (game.moves || 0) && iceState !== 'buried')
        return catchUpGlobShrink(entry, iceState);
    if (game._eating_floor_object === obj || iceState === 'buried'
        || (iceState === 'onice' && (game.moves || 0) % 3 === 1)) {
        startGlobShrinkTimeout(obj);
        return [];
    }

    const oldWeight = Math.max(0, obj.owt ?? 20);
    const thresholdMessage = oldWeight > 0 && oldWeight % 10 === 0;
    const name = globShrinkName(obj);
    const topContainer = outerInventoryContainer(entry);
    const oldTopContainerWeight = topContainer ? globObjectWeight(topContainer) : null;
    obj.owt = Math.max(0, oldWeight - 1);
    if ((obj.oeaten || 0) > 1) obj.oeaten -= 1;
    const containerWeights = refreshGlobEntryContainerWeights(entry, oldTopContainerWeight);

    const messages = [];
    const gone = !obj.owt;
    if (entry.source === 'inventory' && !entry.parent && (thresholdMessage || gone))
        messages.push(`Your ${name} ${gone ? 'dissolves completely' : 'shrinks'}.`);
    if (topContainer && (thresholdMessage || gone)) {
        const topName = pickupObjectName(topContainer);
        const verb = containerWeights.newTopWeight !== containerWeights.oldTopWeight ? 'becomes' : 'seems';
        messages.push(`Your ${topName} ${verb}${gone ? '' : ' slightly'} lighter.`);
    }

    if (gone) {
        const visibleFloor = globFloorVisible(entry);
        removeShrunkGlob(entry);
        if (visibleFloor) messages.push(`A ${name} fades away.`);
    } else {
        startGlobShrinkTimeout(obj);
    }
    return messages;
}

export function processGlobShrinkTimers(g = game) {
    const moves = g.moves || 0;
    const due = collectGlobShrinkEntries(g)
        .filter(entry => typeof entry.obj?.globShrinkTurn === 'number'
            && entry.obj.globShrinkTurn <= moves)
        .sort((a, b) => (a.obj.globShrinkTurn - b.obj.globShrinkTurn)
            || ((a.obj.id || a.obj.oid || 0) - (b.obj.id || b.obj.oid || 0)));
    const messages = [];
    for (const entry of due) messages.push(...processGlobShrinkEntry(entry));
    return messages;
}

function collectReturnedLevelGlobShrinkEntries(g = game) {
    const entries = [];
    collectGlobShrinkEntriesFromList(g.level?.objects || [], 'floor', entries);
    for (const mon of g.level?.monsters || [])
        collectGlobShrinkEntriesFromList(mon.minvent || [], 'minvent', entries, { owner: mon });
    return entries;
}

export function catchUpReturnedLevelGlobShrinkTimers(g = game) {
    const moves = g.moves || 0;
    const stale = collectReturnedLevelGlobShrinkEntries(g)
        .filter(entry => typeof entry.obj?.globShrinkTurn === 'number'
            && entry.obj.globShrinkTurn < moves)
        .sort((a, b) => (a.obj.globShrinkTurn - b.obj.globShrinkTurn)
            || ((a.obj.id || a.obj.oid || 0) - (b.obj.id || b.obj.oid || 0)));
    for (const entry of stale) {
        const obj = entry.obj;
        if (!isGlobbyObject(obj) || typeof obj.globShrinkTurn !== 'number') continue;
        if (globInIceBox(entry)) {
            delete obj.globShrinkTurn;
            continue;
        }
        const iceState = globIceState(entry);
        if (iceState === 'buried') continue;
        catchUpGlobShrink(entry, iceState);
    }
}

function floorObjectClass(obj) {
    if (obj?.cls) return obj.cls;
    if (obj?.otyp === GOLD_PIECE || obj?.glyph === '$') return 'coin';
    return '';
}

function droppedObjectAltarFloorEffects(obj, x, y, messages) {
    const loc = game.level?.at(x, y);
    if (!game._monster_moving || loc?.typ !== ALTAR || !floorObjectVisible(x, y)) return false;
    const coin = floorObjectClass(obj) === 'coin';
    if (coin) {
        obj.blessed = false;
        obj.cursed = false;
    }
    if (obj.blessed || obj.cursed) {
        const color = obj.blessed ? 'amber' : 'black';
        messages.push(`There is an ${color} flash as ${floorObjectArticleName(obj)} ${floorObjectVerb(obj, 'hits', 'hit')} the altar.`);
        if (!heroIsHallucinating()) obj.bknown = true;
    } else {
        messages.push(`${floorObjectSubject(obj)} ${floorObjectVerb(obj, 'lands', 'land')} on the altar.`);
        if (!coin) obj.bknown = true;
    }
    return true;
}

export function earthFloorEffects(obj, x, y, messages, verb = 'fall', {
    usedUpShopBillOnDestroy = false,
} = {}) {
    const loc = game.level?.at(x, y);
    if (!loc || !obj) return false;
    if (obj?.otyp === BOULDER && earthBoulderHitsLiquid(loc)) {
        const lava = earthLiquidIsLava(loc);
        const chance = rn2(10);
        const body = earthWaterBodyName(loc);
        const trap = boulderFillTrapAt(x, y);
        const fillsUp = earthBoulderFillsLiquid(loc, lava, chance);
        let buriedDebt = '';
        if (fillsUp) {
            fillBoulderLiquidTerrain(loc);
            killBoulderFillMonster(x, y);
            deleteBoulderFillFloorTrap(trap, x, y);
            buriedDebt = buriedMerchandiseDebtMessage(x, y, obj);
            messages.push(...buryObjectsAt(x, y, { ignore: obj }));
            if (buriedDebt) messages.push(buriedDebt);
        }
        if (!game.u?.uinwater) {
            if (earthVisibleSquare(x, y)) {
                messages.push(`There is a large splash as the boulder ${fillsUp ? 'fills' : 'falls into'} the ${body}.`);
            } else if (!heroIsDeaf()) {
                messages.push(`You hear a${lava ? ' sizzling' : ''} splash.`);
            }
        }
        if (fillsUp && game.u?.uinwater && game.u?.ux === x && game.u?.uy === y) {
            game.u.uinwater = 0;
            game.u.underwater = false;
            game.u.uunderwater = false;
            game.u.uundetected = 0;
            vision_recalc(1);
            messages.push('You find yourself on dry land again!');
        } else if (lava && heroNextToSquare(x, y)) {
            applyBoulderLavaSplashToHero(messages);
        } else if (!fillsUp && earthVisibleSquare(x, y)) {
            messages.push('It sinks without a trace!');
        }
        if (usedUpShopBillOnDestroy) markObjectShopBillUsedUp(obj);
        newsym(x, y);
        return true;
    }
    if (obj?.otyp === BOULDER)
        return earthBoulderPitHoleEffects(obj, x, y, messages, verb, { usedUpShopBillOnDestroy });

    const liquidType = earthFloorLiquidType(loc);
    if (liquidType === LAVAPOOL || liquidType === LAVAWALL)
        return droppedObjectLavaFloorEffects(obj, x, y, messages, { usedUpShopBillOnDestroy });
    if (IS_POOL(liquidType))
        return droppedObjectWaterFloorEffects(obj, x, y, messages, { usedUpShopBillOnDestroy });
    const pitHole = droppedObjectPitHoleFloorEffects(obj, x, y, messages);
    if (pitHole.handled) return pitHole.consumed;
    if (droppedObjectGlobMeldFloorEffects(obj, x, y, messages)) return true;
    if (droppedObjectAltarFloorEffects(obj, x, y, messages)) return false;
    return droppedObjectHotGroundFloorEffects(obj, x, y, messages, { usedUpShopBillOnDestroy });
}

function dropMonsterInventory(mon, messages = null, { verb = 'fall' } = {}) {
    const floorMessages = Array.isArray(messages) ? messages : [];
    return dropMonsterInventoryRaw(mon, {
        verb,
        floorEffects: (obj, x, y, floorVerb) => earthFloorEffects(obj, x, y, floorMessages, floorVerb),
    });
}

function monstoneObjectEscapesStatue(obj) {
    if (!obj) return false;
    if (obj.otyp === BOULDER || objectKindKey(obj) === 'boulder') return true;
    const kind = objectKindKey(obj);
    const actual = String(obj.actualKind || '').toLowerCase();
    return obj.realAmuletOfYendor || actual === 'amulet of yendor' || kind === 'amulet of yendor'
        || isBookOfTheDeadItem(obj) || isBellOfOpeningItem(obj) || isCandelabrumOfInvocationItem(obj);
}

function monsterStoneCorpstatFlags(mon) {
    const data = mon?.data || {};
    let flags = 0;
    if (mon?.female) flags |= CORPSTAT_FEMALE;
    else if (!data.neuter) flags |= CORPSTAT_MALE;
    if (data.unique || data.nemesis || data.rider) flags |= CORPSTAT_HISTORIC;
    return flags;
}

function placeMonstoneEscapedObject(obj, x, y, messages) {
    Object.assign(obj, { ox: x, oy: y });
    obj.hidden = false;
    obj.buried = false;
    obj.transientProjectile = false;
    obj.contained = false;
    delete obj.line;
    if (earthFloorEffects(obj, x, y, messages, 'fall')) return;
    game.level.objects.push(obj);
    newsym(x, y);
}

function makeStoneMonsterRock(x, y) {
    const rock = mksobj(ROCK, true, false);
    Object.assign(rock, object_display(rock), { ox: x, oy: y, quan: 1 });
    const stacked = stackMonsterThrownObject(rock);
    if (stacked === rock) game.level.objects.push(rock);
    return stacked;
}

export function stoneMonster(mon, messages = null, { awardExperience = false } = {}) {
    if (!mon || !game.level) return null;
    const x = mon.mx;
    const y = mon.my;
    if (x == null || y == null) return null;
    game.level.objects ??= [];
    const floorMessages = Array.isArray(messages) ? messages : [];
    const data = mon.data || {};
    mon.mhp = 0;
    mon.mtrapped = 0;

    const oldInventory = [...(mon.minvent || [])];
    const statueContents = [];
    mon.minvent = [];
    if (mon.missile && !oldInventory.includes(mon.missile)) oldInventory.push(mon.missile);
    mon.missile = null;
    mon.mw = null;

    for (const obj of oldInventory) {
        if (monstoneObjectEscapesStatue(obj)) {
            placeMonstoneEscapedObject(obj, x, y, floorMessages);
            continue;
        }
        if (obj.lamplit || obj.burning) {
            obj.lamplit = false;
            obj.burning = false;
            delete obj._burnTimer;
            delete obj.litRadius;
        }
        obj.contained = false;
        obj.worn = false;
        obj.owornmask = 0;
        statueContents.push(obj);
    }

    const tiny = !!(data.verysmall || data.tiny || data.msize === 'tiny' || data.size === 'tiny');
    const makeStatue = !tiny || !rn2(2 + ((data.genoFreq ?? 1) > 2 ? 1 : 0));
    let remains;
    if (makeStatue) {
        remains = mkcorpstat(STATUE, mon, data, x, y, monsterStoneCorpstatFlags(mon));
        remains.kind = 'statue';
        remains.contents = [];
        for (const obj of statueContents) add_to_container(remains, obj);
        remains.owt = (remains.owt || 0)
            + remains.contents.reduce((sum, obj) => sum + (obj.owt || obj.weight || 0) * Math.max(1, obj.quan || 1), 0);
        Object.assign(remains, object_display(remains));
    } else {
        for (const obj of statueContents) placeMonstoneEscapedObject(obj, x, y, floorMessages);
        remains = makeStoneMonsterRock(x, y);
    }

    recordVanquished(mon, awardExperience);
    game.level.monsters = (game.level.monsters || []).filter(other => other !== mon);
    mon.dead = true;
    mon.movement = 0;
    newsym(x, y);
    return remains;
}

function objectStackType(obj) {
    if (!obj) return undefined;
    if (obj.otyp != null && obj.otyp !== obj.cls) return obj.otyp;
    return obj.actualKind ?? obj.kind ?? obj.otyp ?? obj.cls;
}

function objectStackColor(obj) {
    if (!obj) return undefined;
    if (shopBillableGold(obj)) return CLR_YELLOW;
    if (obj.color != null) return obj.color;
    if (obj.cls === 'weapon') return obj.kind === 'quarterstaff' ? CLR_BROWN : CLR_CYAN;
    if (obj.cls === 'scroll' || obj.cls === 'spellbook') return CLR_WHITE;
    return NO_COLOR;
}

function stackMonsterNameKey(obj) {
    return String(obj?.corpsenm?.name || '').toLowerCase();
}

function corpseIsReviverForMerge(obj) {
    if (!isCorpseItem(obj)) return false;
    const name = stackMonsterNameKey(obj);
    const glyph = obj?.corpsenm?.glyph || obj?.corpsenm?.mlet;
    return !!(obj?.corpsenm?.rider || glyph === 'T' || name.includes('troll')
        || name === 'death' || name === 'pestilence' || name === 'famine');
}

function sameStackCorpseEggTinFields(existing, obj) {
    const existingSpecial = isCorpseItem(existing) || isEggItem(existing) || isTinObject(existing);
    const objSpecial = isCorpseItem(obj) || isEggItem(obj) || isTinObject(obj);
    if (!existingSpecial && !objSpecial) return true;
    if (existingSpecial !== objSpecial) return false;
    if (stackMonsterNameKey(existing) !== stackMonsterNameKey(obj)) return false;
    if ((isEggItem(existing) || isEggItem(obj)) && (eggHasHatchTimer(existing) || eggHasHatchTimer(obj)))
        return false;
    if (corpseIsReviverForMerge(existing) || corpseIsReviverForMerge(obj)) return false;
    return true;
}

function sameMonsterThrownStackObject(existing, obj) {
    if (!existing || !obj || existing === obj) return false;
    if (existing.hidden || existing.buried || existing.transientProjectile) return false;
    if (existing.ox !== obj.ox || existing.oy !== obj.oy) return false;
    if (!!existing.unpaid !== !!obj.unpaid || !!existing.no_charge !== !!obj.no_charge) return false;
    if (existing.unpaid && !sameShopBillUnitPrice(existing, obj)) return false;
    const erosionMatters = wishedDamageProfile(existing).erosionMatters || wishedDamageProfile(obj).erosionMatters;
    const compareProofKnown = !!(game.u?.blind || game.u?.hallucinating || /\bHallu\b/.test(game.u?._statusSuffix || ''));
    return objectStackType(existing) === objectStackType(obj)
        && existing.cls === obj.cls
        && existing.kind === obj.kind
        && existing.actualKind === obj.actualKind
        && sameStackCorpseEggTinFields(existing, obj)
        && existing.glyph === obj.glyph
        && objectStackColor(existing) === objectStackColor(obj)
        && (existing.spe || 0) === (obj.spe || 0)
        && stackedObjectInstanceNamesMergeCompatible(existing, obj)
        && !!existing.blessed === !!obj.blessed
        && !!existing.cursed === !!obj.cursed
        && !!existing.opoisoned === !!obj.opoisoned
        && (existing.oeroded || 0) === (obj.oeroded || 0)
        && (existing.oeroded2 || 0) === (obj.oeroded2 || 0)
        && !!existing.greased === !!obj.greased
        && (!erosionMatters || (!!existing.oerodeproof === !!obj.oerodeproof
            && !!existing.rustproof === !!obj.rustproof
            && (!compareProofKnown || !!existing.rknown === !!obj.rknown)))
        && existing.gemDescription === obj.gemDescription
        && existing.scrollIndex === obj.scrollIndex
        && existing.potionIndex === obj.potionIndex
        && existing.spellbookIndex === obj.spellbookIndex;
}

function stackMonsterThrownObject(obj) {
    const stack = (game.level?.objects || []).find(existing => sameMonsterThrownStackObject(existing, obj));
    if (!stack) return obj;
    mergeStackedShopBillEntries(stack, obj);
    copyStackedObjectInstanceNameForMerge(stack, obj);
    stack.quan = (stack.quan || 1) + (obj.quan || 1);
    return stack;
}

function sameDroppedFloorStackObject(dropped, existing) {
    if (!sameMonsterThrownStackObject(existing, dropped)) return false;
    if (dropped.nomerge || existing.nomerge) return false;
    if (dropped.artifact || existing.artifact) return false;
    if (globContents(dropped).length || globContents(existing).length) return false;
    return true;
}

function stackDroppedFloorObject(obj) {
    if (!game.level || !Array.isArray(game.level.objects) || !obj) return obj;
    const objects = game.level.objects;
    if (!objects.includes(obj)) return obj;
    const stack = objects.find(existing => existing !== obj && sameDroppedFloorStackObject(obj, existing));
    if (!stack) return obj;
    mergeStackedShopBillEntries(obj, stack);
    copyStackedObjectInstanceNameForMerge(obj, stack);
    obj.quan = (obj.quan || 1) + (stack.quan || 1);
    stack.quan = 0;
    game.level.objects = objects.filter(existing => existing !== stack);
    newsym(obj.ox, obj.oy);
    return obj;
}

function placeStackableFloorObject(obj) {
    game.level.objects ??= [];
    const stacked = stackMonsterThrownObject(obj);
    if (stacked === obj) game.level.objects.push(obj);
    return stacked;
}

function monsterThrownFloorEffects(obj, x, y, messages, verb) {
    const previousMonsterMoving = game._monster_moving;
    game._monster_moving = 1;
    try {
        return earthFloorEffects(obj, x, y, messages, verb);
    } finally {
        if (previousMonsterMoving === undefined) delete game._monster_moving;
        else game._monster_moving = previousMonsterMoving;
    }
}

export function dropMonsterObject(mon, obj, messages = null, {
    verb = 'fall',
    monsterMoving = true,
} = {}) {
    if (!mon || !obj || !game.level) return { consumed: false, object: null, messages: [] };
    game.level.objects ??= [];
    const floorMessages = Array.isArray(messages) ? messages : [];
    if (Array.isArray(mon.minvent))
        mon.minvent = mon.minvent.filter(item => item !== obj);
    if (mon.missile === obj) mon.missile = null;
    if (mon.mw === obj) mon.mw = null;

    obj.ox = mon.mx;
    obj.oy = mon.my;
    obj.hidden = false;
    obj.buried = false;
    obj.transientProjectile = false;
    delete obj.line;

    const previousMonsterMoving = game._monster_moving;
    if (monsterMoving) game._monster_moving = 1;
    let consumed = false;
    try {
        consumed = earthFloorEffects(obj, obj.ox, obj.oy, floorMessages, verb);
    } finally {
        if (monsterMoving) {
            if (previousMonsterMoving === undefined) delete game._monster_moving;
            else game._monster_moving = previousMonsterMoving;
        }
    }
    if (consumed) {
        newsym(obj.ox, obj.oy);
        return { consumed: true, object: null, messages: floorMessages };
    }
    const stacked = stackMonsterThrownObject(obj);
    if (stacked === obj) game.level.objects.push(obj);
    newsym(obj.ox, obj.oy);
    return { consumed: false, object: stacked, messages: floorMessages };
}

function monsterThrownMulchCandidate(obj) {
    if (!obj) return false;
    const kind = objectKindKey(obj) || pickupObjectName({ ...obj, quan: 1 }).toLowerCase();
    if (/\bboomerang\b/.test(kind)) return false;
    if (obj.oc_magic || obj.magic || obj.magicStone) return false;
    if (/\b(?:luckstone|loadstone|touchstone)\b/.test(kind)) return false;
    if ([LUCKSTONE, LOADSTONE, TOUCHSTONE].includes(obj.otyp)) return false;
    if (obj.otyp === GEM_CLASS || obj.cls === 'gem' || obj.glyph === '*') return true;
    return obj.otyp === DART
        || /\b(?:arrow|arrows|ya|bolt|bolts|dart|darts|shuriken|throwing star|throwing stars|rock|rocks|flint)\b/.test(kind);
}

function monsterThrownHardGemMulchCandidate(obj) {
    if (!obj) return false;
    const kind = objectKindKey(obj) || pickupObjectName({ ...obj, quan: 1 }).toLowerCase();
    return kind === 'flint' || obj.otyp === FLINT || (!!obj.gemTough && (obj.cls === 'gem' || obj.glyph === '*'));
}

function shouldMulchMonsterThrownMissile(obj) {
    if (!monsterThrownMulchCandidate(obj)) return false;
    const erosion = Math.max(0, Math.trunc(Number(obj.oeroded || 0)), Math.trunc(Number(obj.oeroded2 || 0)));
    const chance = 3 + erosion - Math.trunc(Number(obj.spe || 0));
    let broken = chance > 1 ? !!rn2(chance) : !rn2(4);
    if (obj.blessed && !rn2(3)) broken = false;
    if (monsterThrownHardGemMulchCandidate(obj) && !rn2(2)) broken = false;
    return broken;
}

const MONSTER_PASSIVE_OBJECT_ATTACK_FALLBACKS = new Map([
    ['acid blob', 'acid'],
    ['spotted jelly', 'acid'],
    ['ochre jelly', 'acid'],
    ['green mold', 'acid'],
    ['fire elemental', 'fire'],
    ['fire vortex', 'fire'],
    ['red mold', 'fire'],
    ['rust monster', 'rust'],
    ['black pudding', 'corr'],
    ['disenchanter', 'ench'],
]);

function normalizedPassiveObjectAttackType(type) {
    const key = String(type || '').toLowerCase();
    if (key === 'ad_fire' || key === 'fire') return 'fire';
    if (key === 'ad_acid' || key === 'acid') return 'acid';
    if (key === 'ad_rust' || key === 'rust') return 'rust';
    if (key === 'ad_corr' || key === 'corr' || key === 'corrode') return 'corr';
    if (key === 'ad_ench' || key === 'ench' || key === 'disenchant') return 'ench';
    return '';
}

function passiveAttackEntriesForMonster(mon) {
    const attacks = [];
    if (!mon) return attacks;
    if (mon.attack) attacks.push(mon.attack);
    if (Array.isArray(mon.attacks)) attacks.push(...mon.attacks);
    if (mon.data?.attack) attacks.push(mon.data.attack);
    if (Array.isArray(mon.data?.attacks)) attacks.push(...mon.data.attacks);
    return attacks.filter(attack => {
        const aatyp = String(attack?.aatyp || attack?.type || '').toLowerCase();
        return aatyp === 'none' || aatyp === 'at_none' || aatyp === 'passive';
    });
}

function passiveObjectAttackForMonster(mon) {
    if (!mon) return '';
    for (const attack of passiveAttackEntriesForMonster(mon)) {
        const adtyp = normalizedPassiveObjectAttackType(attack?.adtyp || attack?.damageType);
        if (adtyp) return adtyp;
    }
    return MONSTER_PASSIVE_OBJECT_ATTACK_FALLBACKS.get(String(mon.data?.name || mon.name || '').toLowerCase()) || '';
}

function passiveStoningAttackForMonster(mon) {
    if (!mon) return false;
    for (const attack of passiveAttackEntriesForMonster(mon)) {
        const key = String(attack?.adtyp || attack?.damageType || '').toLowerCase();
        if (key === 'ad_ston' || key === 'ston' || key === 'stone' || key === 'stoning')
            return true;
    }
    const name = String(mon.data?.name || mon.name || '').toLowerCase();
    return name === 'cockatrice' || name === 'chickatrice' || !!(mon.touchPetrifies || mon.data?.touchPetrifies);
}

function monsterAtSquareForPassiveObject(x, y) {
    const mon = (game.level?.monsters || []).find(candidate =>
        candidate && candidate.mx === x && candidate.my === y && !candidate.dead
        && (candidate.mhp == null || candidate.mhp > 0));
    if (mon) return mon;
    if (game.u && game.u.ux === x && game.u.uy === y)
        return { ...game.u, data: polyselfForm() || game.u.data || {} };
    return null;
}

function liveMonsterThrownPassiveTarget(target, x, y) {
    if (!target) return null;
    if (game.u && target.ux === game.u.ux && target.uy === game.u.uy && x === game.u.ux && y === game.u.uy)
        return target;
    if (target.dead || (target.mhp != null && target.mhp <= 0)) return null;
    if (target.mx != null && target.my != null && (target.mx !== x || target.my !== y)) return null;
    return target;
}

function erodeMonsterThrownPassiveObject(obj, type, messages) {
    const profile = wishedDamageProfile(obj);
    const erosion = type === 'rust'
        ? { field: 'oeroded', word: 'rusty', action: 'rust', bythe: 'oxidation' }
        : type === 'corr' || type === 'acid'
            ? { field: 'oeroded2', word: 'corroded', action: 'corrode', bythe: 'corrosion' }
            : type === 'fire'
                ? { field: 'oeroded', word: 'burnt', action: 'smoulder', bythe: 'heat' }
                : null;
    if (!erosion) return { handled: false, damaged: false };
    if ((type === 'rust' || type === 'corr' || type === 'acid') && obj.greased) {
        if (!rn2(2)) obj.greased = false;
        return { handled: true, damaged: false, greased: true };
    }
    if (!profile.erosionMatters || (erosion.field === 'oeroded' ? profile.primaryWord : profile.secondaryWord) !== erosion.word)
        return { handled: !!erosion, damaged: false };
    if (obj.oerodeproof || (type === 'rust' && obj.rustproof)) {
        const name = floorObjectBaseName(obj);
        if (!obj.rknown && game.flags?.verbose !== false && floorObjectVisible(obj.ox, obj.oy)
            && Array.isArray(messages))
            messages.push(`Somehow, the ${name} ${rustTrapNameVerb(name, 'is', 'are')} not affected by the ${erosion.bythe}.`);
        obj.rknown = true;
        return { handled: true, damaged: false };
    }
    if (obj.blessed && !rnl(4)) return { handled: true, damaged: false };
    const current = Math.min(3, obj[erosion.field] || 0);
    if (current >= 3) return { handled: true, damaged: false };
    const name = floorObjectBaseName(obj);
    obj[erosion.field] = current + 1;
    if (floorObjectVisible(obj.ox, obj.oy)) {
        const adverb = obj[erosion.field] === 3 ? ' completely' : current ? ' further' : '';
        messages.push(`The ${name} ${rustTrapNameVerb(name, `${erosion.action}s`, erosion.action)}${adverb}!`);
    }
    return { handled: true, damaged: true };
}

function applyMonsterThrownPassiveObject(landing, target, ohit, messages) {
    if (!landing || !target || !ohit) return { handled: false, damaged: false };
    const type = passiveObjectAttackForMonster(target);
    if (!type) return { handled: false, damaged: false, type };
    if (type === 'ench') {
        if (target.mcan) return { handled: true, damaged: false, type };
        const drain = drainItem(landing, { byYou: true, messages });
        return { handled: true, damaged: drain.drained, type, ...drain };
    }
    if ((type === 'rust' || type === 'corr') && target.mcan)
        return { handled: true, damaged: false, type };
    if (type === 'fire') {
        if (rn2(6) || target.mcan || String(target.data?.name || target.name || '').toLowerCase() === 'steam vortex')
            return { handled: true, damaged: false, type };
    } else if (type === 'acid' && rn2(6)) {
        return { handled: true, damaged: false, type };
    }
    return { ...erodeMonsterThrownPassiveObject(landing, type, messages), type };
}

export function landMonsterThrownObject(missile, x, y, {
    glyph = missile?.glyph || ')',
    color = missile?.color ?? CLR_CYAN,
    petFetchable = true,
    messages = null,
    verb = 'fall',
    quan = 1,
    ohit = false,
    passiveTarget = null,
    contactBreaks = null,
} = {}) {
    if (!missile || !game.level) return { consumed: false, object: null, messages: [] };
    game.level.objects ??= [];
    const floorMessages = Array.isArray(messages) ? messages : [];
    const breaksOnContact = contactBreaks ?? (isCreamPieObject(missile) || isVenomObject(missile) || (!!ohit && isEggItem(missile)));
    const mulched = !breaksOnContact && !!ohit && shouldMulchMonsterThrownMissile(missile);
    const dropThrow = {
        broken: breaksOnContact || mulched,
        ohit: !!ohit,
        mulched,
    };
    if (dropThrow.broken) {
        if (mulched) rn2(100);
        newsym(x, y);
        return {
            consumed: true,
            object: null,
            messages: floorMessages,
            shipObject: projectileShipObjectResult(),
            floorEffects: { consumed: false },
            dropThrow,
        };
    }
    const passiveObjectTarget = liveMonsterThrownPassiveTarget(passiveTarget, x, y)
        || monsterAtSquareForPassiveObject(x, y);
    const landing = {
        ...missile,
        ox: x,
        oy: y,
        quan: Math.max(1, quan || 1),
        glyph,
        color,
        petFetchable,
        hidden: false,
        buried: false,
        transientProjectile: false,
    };
    delete landing.line;
    const shipObject = landing.otyp === BOULDER
        ? projectileShipObjectResult()
        : maybeShipRemoteProjectileObject(landing, x, y, floorMessages);
    if (shipObject.handled) {
        return {
            consumed: true,
            object: null,
            messages: floorMessages,
            shipObject,
            floorEffects: { consumed: false },
            dropThrow,
        };
    }
    const consumed = monsterThrownFloorEffects(landing, x, y, floorMessages, verb);
    if (consumed) {
        newsym(x, y);
        return {
            consumed: true,
            object: null,
            messages: floorMessages,
            shipObject,
            floorEffects: { consumed: true },
            dropThrow,
        };
    }
    const passiveObj = applyMonsterThrownPassiveObject(landing, passiveObjectTarget, !!ohit, floorMessages);
    const stacked = stackMonsterThrownObject(landing);
    if (stacked === landing) game.level.objects.push(landing);
    newsym(x, y);
    return {
        consumed: false,
        object: stacked,
        messages: floorMessages,
        shipObject,
        floorEffects: { consumed: false },
        dropThrow,
        passiveObj,
    };
}

function promoteLethalProjectileAfterMore() {
    if (!game._lethal_arrow_after_topline_more) return false;
    const lethalArrow = game._lethal_arrow_after_topline_more;
    game._deferred_lethal_attack_after_more = lethalArrow;
    game._lethal_arrow_after_topline_more = null;
    game._death_cause = lethalArrow.deathCause || game._death_cause || 'killed by an arrow';
    return true;
}

function continueLethalAttackAfterLifeSaving(attack) {
    const continuation = attack?.lifeSavingContinuation || {};
    const messages = [];
    if (continuation.exerciseStrength) exerciseAttribute(A_STR, false);
    if (continuation.poison) {
        const poisonResult = applyHeroPoisonedProjectileAfterMore(continuation.poison, {
            appendMessages: false,
        });
        messages.push(...(poisonResult.messages || []));
    }
    const thrown = continuation.monsterThrow;
    if (thrown?.missile) {
        const floorMessages = [];
        landMonsterThrownObject(thrown.missile, thrown.x ?? game.u?.ux ?? 0, thrown.y ?? game.u?.uy ?? 0, {
            glyph: thrown.glyph || thrown.missile.glyph || ')',
            color: thrown.color ?? thrown.missile.color ?? CLR_CYAN,
            messages: floorMessages,
            ohit: !!thrown.ohit,
            passiveTarget: thrown.passiveTarget || null,
        });
        messages.push(...floorMessages);
    }
    return messages;
}

// C done_object_cleanup() salvages gt.thrownobj for bones without drop_throw().
function deathCleanupThrownObjectLandingSpot() {
    const ux = game.u?.ux || 0;
    const uy = game.u?.uy || 0;
    let x = ux + (game.u?.dx || 0);
    let y = uy + (game.u?.dy || 0);
    const loc = game.level?.at?.(x, y);
    if (!isok(x, y) || !loc || !ACCESSIBLE(loc.typ)) {
        x = ux;
        y = uy;
    }
    return { x, y };
}

function placeDeathCleanupThrownObject(attack) {
    const missile = attack?.deathCleanupThrownObject;
    if (!missile || !game.level) return null;
    game.level.objects ??= [];
    const sameProjectile = obj => obj?.transientProjectile
        && (missile.id != null ? obj.id === missile.id : obj === missile);
    const projectile = game.level.objects.find(sameProjectile) || missile;
    const oldX = projectile.ox;
    const oldY = projectile.oy;
    const projectileColor = projectile.color;
    game.level.objects = game.level.objects
        .filter(obj => obj === projectile || !sameProjectile(obj));
    if (!game.level.objects.includes(projectile)) game.level.objects.push(projectile);

    const { x, y } = deathCleanupThrownObjectLandingSpot();
    Object.assign(projectile, missile, {
        ox: x,
        oy: y,
        quan: Math.max(1, attack.deathCleanupQuan || missile.quan || 1),
        glyph: attack.deathCleanupGlyph || missile.glyph || ')',
        color: attack.deathCleanupColor ?? projectileColor ?? missile.color ?? CLR_CYAN,
        hidden: false,
        buried: false,
        transientProjectile: false,
        _deathCleanupThrownObject: true,
    });
    delete projectile.line;
    delete projectile.nobj;
    delete projectile.nexthere;

    const stacked = stackDroppedFloorObject(projectile);
    if (oldX != null && oldY != null) newsym(oldX, oldY);
    newsym(x, y);
    if (!(game.level.objects || []).some(obj => obj.transientProjectile))
        game._clear_transient_projectiles_after_more = 0;
    return stacked;
}

function appendToplineAfterMoreMessages(messages) {
    let queued = false;
    for (const msg of messages || []) {
        if (!msg) continue;
        if (!game._topline_after_more) {
            game._topline_after_more = msg;
            continue;
        }
        const width = game.nhDisplay?.cols || 80;
        if (game._topline_after_more.length + msg.length + 3 < width - 8) {
            game._topline_after_more = `${game._topline_after_more}  ${msg}`;
        } else {
            game._queued_messages_after_more ??= [];
            game._queued_messages_after_more.push({ text: msg, more: true });
            queued = true;
        }
    }
    return queued;
}

function clearLifeSavedDeathState() {
    game._death_cause = '';
    game._death_bones_body = '';
    game._death_current_move = 0;
    game._death_status_hp_before_zero = null;
    game._death_taker = '';
    game._death_moves = 0;
}

function applyHeroPoisonedProjectileAfterMore(effect, options = {}) {
    const reason = String(effect?.reason || 'poisoned arrow');
    const messages = [];
    const appendMessages = options.appendMessages !== false;
    const finishMessages = () => appendMessages
        ? appendToplineAfterMoreMessages(messages)
        : messages.length > 0;
    if (!/poison/i.test(reason)) {
        const plural = /s$/i.test(reason);
        messages.push(`${/^[A-Z]/.test(reason) ? '' : 'The '}${reason} ${plural ? 'were' : 'was'} poisoned!`);
    }
    if (heroHasPoisonResistance()) {
        messages.push("The poison doesn't seem to affect you.");
        return { dead: false, more: finishMessages(), messages };
    }

    const fatal = effect?.fatal != null && Number.isFinite(Number(effect.fatal))
        ? Number(effect.fatal) : 10;
    const roll = fatal ? rn2(fatal + 20) : 1;
    let dead = false;
    if (roll === 0) {
        const loss = 6 + d(4, 6);
        if ((game.u?.uhp || 0) <= loss) {
            if (game.u) game.u.uhp = -1;
            messages.push('The poison was deadly...');
            dead = true;
        } else {
            if (game.u) {
                game.u.uhpmax = Math.max(3, (game.u.uhpmax || game.u.uhp || 1) - Math.trunc(loss / 2));
                game.u.uhp = Math.max(0, (game.u.uhp || 0) - loss);
                if (game.u.acurr?.a) {
                    game.u.acurr.a[A_CON] = Math.max(3, (game.u.acurr.a[A_CON] ?? 10) - 1);
                    game.u.acurr.a[A_STR] = Math.max(3, (game.u.acurr.a[A_STR] ?? 10) - 3);
                }
            }
            messages.push('You feel very sick!');
            messages.push('You feel weaker!');
            dead = (game.u?.uhp || 0) < 1;
        }
    } else if (roll > 5) {
        const loss = rnd(6);
        if (game.u) game.u.uhp = Math.max(0, (game.u.uhp || 0) - loss);
        dead = (game.u?.uhp || 0) < 1;
    } else {
        if (game.u?.acurr?.a) game.u.acurr.a[A_STR] = Math.max(3, (game.u.acurr.a[A_STR] ?? 10) - 1);
        messages.push('You feel weaker!');
    }
    const more = finishMessages();
    if (dead) {
        game._death_cause = `poisoned by ${String(effect?.killer || reason)}`;
        game._queued_message_after_more ||= 'You die...';
    }
    return { dead, more: more || dead, messages };
}

function earthTargetIsSolid(target) {
    const data = target?.data || target || {};
    return !(target?.passWalls || target?.noncorporeal || target?.unsolid
        || data.passWalls || data.noncorporeal || data.unsolid
        || data.amorphous || data.name === 'fog cloud');
}

function earthTargetThrowsRocks(target) {
    const data = target?.data || target || {};
    return !!(target?.throwsRocks || data.throwsRocks);
}

function earthObjectDamage(obj, target) {
    const quan = obj?.quan || 1;
    const base = obj?.otyp === BOULDER ? rnd(20) : rnd(3);
    const data = target?.data || target || {};
    if (data.thickSkinned || data.scaled || data.name === 'shade') return 0;
    return base * quan;
}

function wornEarthHelmet() {
    return (game.inventory || []).find(item =>
        item.cls === 'armor' && (item.worn || item.line?.includes('being worn')) && armorSlot(item) === 'helm');
}

function monsterEarthHelmet(mon) {
    return (mon?.minvent || []).find(item =>
        item.cls === 'armor' && (item.worn || item.owornmask || item.line?.includes('being worn')) && armorSlot(item) === 'helm');
}

function hardEarthHelmet(item) {
    const name = armorKind(item);
    return armorSlot(item) === 'helm' && !/\b(?:elven leather helm|leather hat|fedora|cornuthaum|dunce cap)\b/.test(name);
}

function dropEarthObjectOnHero(confused, helmetProtects, messages) {
    if (game.u?.uswallow) return dropEarthObjectOnMonster(game.u.ux, game.u.uy, confused, messages);
    const obj = makeEarthDropObject(confused);
    const solidHero = earthTargetIsSolid({ ...game.u, data: polyselfForm() || {} });
    let damage = 0;
    if (solidHero) {
        messages.push(`You are hit by ${earthDropObjectPhrase(obj)}!`);
        damage = earthObjectDamage(obj, { data: polyselfForm() || {} });
        const helmet = wornEarthHelmet();
        if (helmet && helmetProtects) {
            if (hardEarthHelmet(helmet)) {
                messages.push('Fortunately, you are wearing a hard helmet.');
                if (damage > 2) damage = 2;
            } else {
                messages.push(`Your ${pickupObjectName(helmet)} does not protect you.`);
            }
        }
    }
    if (!earthFloorEffects(obj, game.u?.ux || 0, game.u?.uy || 0, messages))
        earthPlaceObject(obj, game.u?.ux || 0, game.u?.uy || 0);
    if (damage && game.u && (game.u.uhp || 0) > 0) {
        game.u.uhp = Math.max(0, (game.u.uhp || 0) - damage);
        if ((game.u.uhp || 0) <= 0) {
            game._death_cause = 'killed by a scroll of earth';
            messages.push('You die...');
        }
    }
    return true;
}

function dropEarthObjectOnMonster(x, y, confused, messages) {
    const obj = makeEarthDropObject(confused);
    const mon = (game.level?.monsters || []).find(mtmp => mtmp.mx === x && mtmp.my === y && !mtmp.dead);
    const visible = mon && earthVisibleSquare(x, y);
    if (mon && earthTargetIsSolid(mon)) {
        const name = fireScrollMonsterName(mon);
        if (visible) messages.push(`${name} is hit by ${earthDropObjectPhrase(obj)}!`);
        let damage = earthObjectDamage(obj, mon);
        const helmet = monsterEarthHelmet(mon);
        if (helmet) {
            if (hardEarthHelmet(helmet)) {
                if (visible) messages.push(`Fortunately, ${name.replace(/^The /, 'the ')} is wearing a hard helmet.`);
                else if (!heroIsDeaf()) messages.push('You hear a clanging sound.');
                if (damage > 2) damage = 2;
            } else if (visible) {
                messages.push(`${name}'s ${pickupObjectName(helmet)} does not protect it.`);
            }
        }
        mon.mhp = (mon.mhp || 1) - damage;
        if ((mon.mhp || 0) <= 0) {
            dropMonsterInventory(mon, messages);
            game.level.monsters = (game.level?.monsters || []).filter(other => other !== mon);
            recordVanquished(mon, true);
            newsym(x, y);
            if (visible) messages.push(`You kill the ${mon.data?.name || mon.name || 'monster'}!`);
        } else {
            mon.msleeping = 0;
            mon.mpeaceful = false;
        }
    }
    if (!earthFloorEffects(obj, x, y, messages)) earthPlaceObject(obj, x, y);
    return true;
}

function earthDropEligibleSquare(x, y) {
    if (x == null || y == null || x < 1 || x >= COLNO || y < 0 || y >= ROWNO) return false;
    const loc = game.level?.at(x, y);
    if (!loc) return false;
    if (loc.typ === DOOR && (loc.doormask & (D_CLOSED | D_LOCKED))) return false;
    return !IS_OBSTRUCTED(loc.typ) && !IS_AIR(loc.typ);
}

function earthScrollEffect(item) {
    const messages = [];
    let known = false;
    let changedVision = false;
    if (earthScrollHasEffect()) {
        messages.push(earthCeilingMessage(item));
        known = true;
        applySokobanGuilt();
        let nboulders = 0;
        const ux = game.u?.ux || 0;
        const uy = game.u?.uy || 0;
        if (!item?.cursed) {
            for (let x = ux - 1; x <= ux + 1; x++) {
                for (let y = uy - 1; y <= uy + 1; y++) {
                    if (x === ux && y === uy) continue;
                    if (!earthDropEligibleSquare(x, y)) continue;
                    if (dropEarthObjectOnMonster(x, y, heroIsConfused(), messages)) {
                        nboulders++;
                        changedVision = true;
                    }
                }
            }
        }
        if (!item?.blessed) {
            if (dropEarthObjectOnHero(heroIsConfused(), !item?.cursed, messages)) changedVision = true;
        } else if (!nboulders) {
            messages.push('But nothing else happens.');
        }
    }
    if (changedVision) {
        vision_reset();
        vision_recalc(0);
    }
    return { messages, known, more: messages.length > 1 || (game.u?.uhp || 1) <= 0 };
}

function armorKind(item) {
    return String(item?.actualKind || item?.kind || pickupObjectName(item)).toLowerCase();
}

function armorMessageName(item) {
    return pickupObjectName(item).replace(/^pair of /, '');
}

function armorNameIsPlural(name) {
    return /\b(?:boots|shoes|gloves|gauntlets|scales)\b/i.test(name) && !/\bmail\b/i.test(name);
}

function armorVerb(item, singular, plural) {
    return armorNameIsPlural(armorMessageName(item)) ? plural : singular;
}

function armorSubject(item) {
    return `Your ${armorMessageName(item)}`;
}

function armorSlot(item) {
    const name = armorKind(item);
    if (/\b(?:cloak|robe|wrapping|mantelet|pall|cape|cope|cloth|smock|apron)\b/.test(name)) return 'cloak';
    if (/\b(?:mail|armor|jacket|coat|dragon scales?)\b/.test(name)) return 'body';
    if (/\bshirt\b/.test(name)) return 'shirt';
    if (/\b(?:helm|helmet|hat|fedora|cornuthaum|cap|pot)\b/.test(name)) return 'helm';
    if (/\b(?:gloves|gauntlets)\b/.test(name)) return 'gloves';
    if (/\b(?:boots|shoes)\b/.test(name)) return 'boots';
    if (/\bshield\b/.test(name)) return 'shield';
    return '';
}

function isWornArmorItem(item) {
    return (item?.cls === 'armor' || item?.glyph === '[' || item?.otyp === ARMOR_CLASS)
        && (item.worn || item.owornmask || item.line?.includes('being worn'));
}

function wornArmorItemsBySlotOrder(slots) {
    const wornArmor = (game.inventory || []).filter(isWornArmorItem);
    const used = new Set();
    const ordered = [];
    for (const slot of slots) {
        const item = wornArmor.find(candidate => !used.has(candidate) && armorSlot(candidate) === slot);
        if (item) {
            used.add(item);
            ordered.push(item);
        }
    }
    return ordered;
}

function countWornArmor() {
    return (game.inventory || []).filter(isWornArmorItem).length;
}

function someArmorTarget() {
    const wornArmor = (game.inventory || []).filter(isWornArmorItem);
    let target = wornArmor.find(item => armorSlot(item) === 'cloak')
        || wornArmor.find(item => armorSlot(item) === 'body')
        || wornArmor.find(item => armorSlot(item) === 'shirt')
        || null;
    for (const slot of ['helm', 'gloves', 'boots', 'shield']) {
        const item = wornArmor.find(candidate => armorSlot(candidate) === slot);
        if (item && (!target || !rn2(4))) target = item;
    }
    return target;
}

function someEnchantArmorTarget() {
    const wornArmor = (game.inventory || []).filter(item =>
        item.cls === 'armor' && (item.worn || item.line?.includes('being worn')));
    let target = wornArmor.find(item => armorSlot(item) === 'cloak')
        || wornArmor.find(item => armorSlot(item) === 'body')
        || wornArmor.find(item => armorSlot(item) === 'shirt')
        || null;
    for (const slot of ['helm', 'gloves', 'boots', 'shield']) {
        const item = wornArmor.find(candidate => armorSlot(candidate) === slot);
        if (item && (!target || !rn2(4))) target = item;
    }
    return target;
}

function wornArmorAcValue(item) {
    const base = ARMOR_AC_BONUS[armorKind(item)] ?? 0;
    return base + (item.spe ?? 0) - Math.min(item.oeroded || 0, base);
}

function wornArmorAcValueGreatestErosion(item) {
    const base = ARMOR_AC_BONUS[armorKind(item)] ?? 0;
    return base + (item.spe ?? 0) - Math.min(Math.max(item.oeroded || 0, item.oeroded2 || 0), base);
}

function updateArmorLine(item) {
    item.line = normalInventoryLine({ ...item, line: '' });
}

function updateReflectionFromInventory() {
    if (!game.u) return;
    game.u.reflecting = (game.inventory || []).some(item => {
        if (!isActiveInventoryExtrinsicItem(item)) return false;
        const kind = armorKind(item);
        return isSilverDragonArmorKind(kind) || kind === 'shield of reflection'
            || item.amuletIndex === 7 || kind === 'amulet of reflection';
    });
}

function updateWornArmorAcAfterChange(armor, oldAc) {
    if (game.u && isWornArmorItem(armor)) game.u.uac = (game.u.uac ?? 10) + oldAc - wornArmorAcValueGreatestErosion(armor);
    updateArmorLine(armor);
}

function destroyWornArmorItem(armor, messages = null) {
    const oldAc = wornArmorAcValueGreatestErosion(armor);
    const wasWorn = isWornArmorItem(armor);
    const kind = armorKind(armor);
    if (game.u && wasWorn) game.u.uac = (game.u.uac ?? 10) + oldAc;
    if (wasWorn) {
        armor.worn = false;
        armor.owornmask = 0;
        armor.line = normalInventoryLine({ ...armor, line: '' });
    }
    if ((kind === 'speed boots' || isBlueDragonArmorKind(kind)) && game.u)
        syncHeroSpeedState();
    if (armorSlot(armor) === 'gloves')
        addPolyselfGlovesOffSideEffects(armor);
    else
        updateGauntletsOfPowerStrength(kind, false);
    if (armorSlot(armor) === 'boots' && Array.isArray(messages))
        addBootsOffSideEffects(armor, messages);
    if ((game.inventory || []).includes(armor))
        useUpInventoryItem(armor, armor.quan || 1);
    updateReflectionFromInventory();
}

function armorGlowMessage(armor, color) {
    const subject = armorSubject(armor);
    if (game.u?.blind)
        return `${subject} ${armorVerb(armor, 'vibrates', 'vibrate')} for a moment.`;
    return `${subject} ${armorVerb(armor, 'glows', 'glow')} ${color} for a moment.`;
}

function destroyArmorErosionType(armor) {
    const profile = wishedDamageProfile(armor);
    if (!profile.erosionMatters || !profile.damageable) return null;
    if (profile.primaryWord === 'burnt') return { field: 'oeroded', action: 'smoulder' };
    if (profile.primaryWord === 'rusty') return { field: 'oeroded', action: 'rust' };
    if (profile.primaryWord === 'cracked') return { field: 'oeroded', action: 'crack', shatters: true };
    if (profile.secondaryWord === 'rotted') return { field: 'oeroded2', action: 'rot' };
    if (profile.secondaryWord === 'corroded') return { field: 'oeroded2', action: 'corrode' };
    return null;
}

function erosionVerb(armor, action) {
    const plural = {
        smoulder: 'smoulder',
        rust: 'rust',
        rot: 'rot',
        corrode: 'corrode',
        crack: 'crack',
    }[action] || action;
    const singular = {
        smoulder: 'smoulders',
        rust: 'rusts',
        rot: 'rots',
        corrode: 'corrodes',
        crack: 'cracks',
    }[action] || `${action}s`;
    return armorVerb(armor, singular, plural);
}

function erosionAlterationVerb(action) {
    return {
        smoulder: 'burn',
        rust: 'rust',
        rot: 'rot',
        corrode: 'tarnish',
        crack: 'crack',
    }[action] || action;
}

function erodeDestroyArmor(armor, messages) {
    const erosion = destroyArmorErosionType(armor);
    if (!erosion || armor.oerodeproof) return false;
    if (armor.blessed && !rnl(4)) return false;

    const current = Math.min(3, armor[erosion.field] || 0);
    const name = armorMessageName(armor);
    if (current < 3) {
        const adverb = current + 1 === 3 ? ' completely' : current ? ' further' : '';
        messages.push(`Your ${name} ${erosionVerb(armor, erosion.action)}${adverb}!`);
        const payment = costlyAlterationPaymentMessage(armor, erosionAlterationVerb(erosion.action));
        if (payment) messages.push(payment);
        const oldAc = wornArmorAcValueGreatestErosion(armor);
        armor[erosion.field] = current + 1;
        updateWornArmorAcAfterChange(armor, oldAc);
        return true;
    }

    messages.push(erosion.shatters
        ? `Your ${name} shatters!`
        : `Your ${name} ${erosionVerb(armor, erosion.action)} away!`);
    const payment = costlyAlterationPaymentMessage(armor, erosionAlterationVerb(erosion.action));
    if (payment) messages.push(payment);
    destroyWornArmorItem(armor, messages);
    return 'destroyed';
}

function destroyArm(messages) {
    const armors = wornArmorItemsBySlotOrder(['body', 'cloak', 'helm', 'shield', 'gloves', 'boots', 'shirt']);
    if (!armors.length) return false;

    const hits = rn2(4) + 1;
    let result = false;
    for (let i = 0; i < hits; i++) {
        const armor = armors[rn2(armors.length)];
        if (!armor || !(game.inventory || []).includes(armor)) continue;
        const erosion = erodeDestroyArmor(armor, messages);
        if (erosion) result = true;
        if (erosion === 'destroyed') break;
    }
    return result;
}

function legacyDestroyArm(messages) {
    const wornArmor = (game.inventory || []).filter(item =>
        item.cls === 'armor' && (item.worn || item.line?.includes('being worn')));
    if (!wornArmor.length) return { changed: false, uacDelta: 0 };
    const hits = rn2(4) + 1;
    let result = false;
    let uacDelta = 0;
    for (let i = 0; i < hits; i++) {
        const armor = wornArmor[rn2(wornArmor.length)];
        if (!armor || !(game.inventory || []).includes(armor)) continue;
        const armorBase = ARMOR_AC_BONUS[String(armor.kind || '').toLowerCase()] ?? 0;
        if (!armorBase || (armor.oeroded || 0) >= armorBase) continue;
        const oldAc = wornArmorAcValue(armor);
        armor.oeroded = (armor.oeroded || 0) + 1;
        armor.bknown = true;
        uacDelta += oldAc - wornArmorAcValue(armor);
        updateArmorLine(armor);
        const name = pickupObjectName(armor);
        messages.push(armor.oeroded === 1
            ? `Your ${name} smoulders!`
            : `Your ${name} smoulders further!`);
        result = true;
    }
    return { changed: result, uacDelta };
}

function armorSimpleSlotName(armor) {
    const name = armorMessageName(armor);
    const kind = armorKind(armor);
    switch (armorSlot(armor)) {
    case 'cloak':
        if (kind.includes('robe')) return 'robe';
        if (kind.includes('apron')) return 'apron';
        if (kind.includes('smock')) return 'smock';
        if (kind.includes('wrapping')) return 'wrapping';
        return 'cloak';
    case 'body':
        return name;
    case 'shirt':
        return 'shirt';
    case 'helm':
        return /\b(?:hat|fedora|cornuthaum|cap)\b/.test(kind) ? 'hat' : 'helm';
    case 'gloves':
        return 'gloves';
    case 'boots':
        return 'boots';
    case 'shield':
        return 'shield';
    default:
        return name;
    }
}

function disintegrateArmorMessage(armor) {
    const simple = armorSimpleSlotName(armor);
    switch (armorSlot(armor)) {
    case 'cloak':
        return `Your ${simple} crumbles and turns to dust!`;
    case 'body':
        return `Your ${simple} ${armorNameIsPlural(simple) ? 'turn' : 'turns'} to dust and ${armorNameIsPlural(simple) ? 'fall' : 'falls'} to the floor!`;
    case 'shirt':
        return `Your ${simple} crumbles into tiny threads and falls apart!`;
    case 'helm':
        return `Your ${simple} turns to dust and is blown away!`;
    case 'gloves':
        return `Your ${simple} vanish!`;
    case 'boots':
        return `Your ${simple} disintegrate!`;
    case 'shield':
        return `Your ${simple} crumbles away!`;
    default:
        return `Your ${simple} turns to dust!`;
    }
}

function armorResistsDisintegration(armor) {
    if (armor.invocation || armor.riderCorpse) return true;
    const chance = rn2(100);
    return chance < (armor.artifact || armor.oartifact ? 90 : 0);
}

function maybeDisintegrateArmor(armor, target, state, key = 'resisted') {
    if (!armor || (target && target !== armor)) return null;
    const resisted = armorResistsDisintegration(armor);
    state[key] = resisted;
    return resisted ? null : armor;
}

function disintegrateArm(target, messages) {
    const bySlot = Object.fromEntries(wornArmorItemsBySlotOrder([
        'cloak', 'body', 'shirt', 'helm', 'gloves', 'boots', 'shield',
    ]).map(armor => [armorSlot(armor), armor]));
    const state = {};
    let armor = maybeDisintegrateArmor(bySlot.cloak, target, state, 'resistedCloak');
    if (!armor && !state.resistedCloak)
        armor = maybeDisintegrateArmor(bySlot.body, target, state, 'resistedSuit');
    if (!armor && !state.resistedCloak && !state.resistedSuit)
        armor = maybeDisintegrateArmor(bySlot.shirt, target, state);
    if (!armor) armor = maybeDisintegrateArmor(bySlot.helm, target, state);
    if (!armor) armor = maybeDisintegrateArmor(bySlot.gloves, target, state);
    if (!armor) armor = maybeDisintegrateArmor(bySlot.boots, target, state);
    if (!armor) armor = maybeDisintegrateArmor(bySlot.shield, target, state);
    if (!armor) return false;

    if (armor.lamplit || armor.burning) {
        armor.lamplit = false;
        armor.burning = false;
        delete armor._burnTimer;
        delete armor.litRadius;
    }
    messages.push(disintegrateArmorMessage(armor));
    destroyWornArmorItem(armor, messages);
    return true;
}

function disintegrateCursedArmor(messages) {
    const armors = wornArmorItemsBySlotOrder(['body', 'cloak', 'helm', 'shield', 'gloves', 'boots', 'shirt'])
        .filter(armor => armor.cursed);
    if (!armors.length) return false;
    return disintegrateArm(armors[rn2(armors.length)], messages);
}

function destroyArmorPromptLetters() {
    return inventoryLetters(isWornArmorItem) || '*';
}

function destroyArmorPromptText() {
    return `What do you want to destroy? [${getobjPromptLetters(destroyArmorPromptLetters())} or ?*]`;
}

function destroyArmorConfusedEffect(scroll, target, messages) {
    if (!target) {
        messages.push('Your bones itch.');
        exerciseAttribute(A_STR, false);
        exerciseAttribute(A_CON, false);
        return { learned: false, more: messages.length > 1 };
    }
    const oldErodeproof = !!target.oerodeproof;
    const newErodeproof = !!scroll.cursed;
    target.oerodeproof = false;
    messages.push(armorGlowMessage(target, 'purple'));
    finishConfusedProofMutation(target, oldErodeproof, newErodeproof, messages);
    updateArmorLine(target);
    return { learned: false, more: messages.length > 1 };
}

function destroyArmorCursedCursedEffect(target, messages) {
    messages.push(`${armorSubject(target)} ${armorVerb(target, 'vibrates', 'vibrate')}.`);
    if ((target.spe ?? 0) >= -6) {
        const oldAc = wornArmorAcValueGreatestErosion(target);
        target.spe = (target.spe ?? 0) - 1;
        updateWornArmorAcAfterChange(target, oldAc);
    } else {
        updateArmorLine(target);
    }
    addHeroStun(rn1(10, 10));
    return { learned: false, more: messages.length > 1 };
}

function destroyArmorScrollEffect(scroll, messages) {
    const target = someArmorTarget();
    if (heroIsConfused()) return destroyArmorConfusedEffect(scroll, target, messages);

    if (scroll.cursed) {
        if (target?.cursed) return destroyArmorCursedCursedEffect(target, messages);
        return { learned: disintegrateArm(target, messages), more: messages.length > 1 };
    }

    if (target && scroll.blessed && countWornArmor() > 1)
        return { learned: true, more: messages.length > 1, prompt: true, target };

    if (scroll.blessed && disintegrateCursedArmor(messages))
        return { learned: true, more: messages.length > 1 };

    const legacy = !scroll.blessed;
    const legacyResult = legacy ? legacyDestroyArm(messages) : null;
    const destroyed = legacy ? legacyResult.changed : destroyArm(messages);
    if (!destroyed) {
        messages.push('Your skin itches.');
        exerciseAttribute(A_STR, false);
        exerciseAttribute(A_CON, false);
        return { learned: false, more: messages.length > 1, skipCall: legacy, legacy, uacDelta: legacyResult?.uacDelta || 0 };
    }
    return { learned: !legacy, more: messages.length > 1, skipCall: legacy, legacy, uacDelta: legacyResult?.uacDelta || 0 };
}

async function finishDestroyArmorSelection(selectedArmor = null) {
    const pending = game._destroy_armor_scroll || {};
    const target = selectedArmor || pending.target || null;
    const messages = [];
    game._destroy_armor_scroll = null;
    game._command_mode = null;
    game._overlay_lines = null;
    game._overlay_hide_status = 0;
    game.context.move = 1;
    if (target) disintegrateArm(target, messages);
    if (messages.length) await setMessage(messages.join('  '), messages.length > 1);
    else {
        game._pending_message = '';
        game._message_more = 0;
        game._keep_pending_message = 1;
    }
}

function isSpecialEnchantArmor(item) {
    const kind = armorKind(item);
    return kind.includes('elven') || ((game.urole?.name?.m || game._startup_role) === 'Wizard' && kind === 'cornuthaum');
}

function isEnchantMagicalArmor(item) {
    return !!item.magic || MAGICAL_ARMOR_KINDS.has(armorKind(item));
}

function enchantArmorColorWord(item, cursed, blind) {
    if (blind) return '';
    const kind = armorKind(item);
    if (cursed && (kind === 'black dragon scale mail' || kind === 'black dragon scales')) return '';
    if (!cursed && (kind === 'silver dragon scale mail' || kind === 'silver dragon scales' || kind === 'shield of reflection')) return '';
    return cursed ? ' black' : ' silver';
}

function enchantArmorConfusedEffect(item, armor) {
    const messages = [];
    const oldErodeproof = !!armor.oerodeproof;
    const newErodeproof = !item.cursed;
    armor.oerodeproof = false;
    const subject = armorSubject(armor);
    if (game.u?.blind) {
        armor.rknown = false;
        messages.push(`${subject} ${armorVerb(armor, 'feels', 'feel')} warm for a moment.`);
    } else {
        armor.rknown = true;
        messages.push(`${subject} ${armorVerb(armor, 'is', 'are')} covered by a ${item.cursed ? 'mottled black glow' : `shimmering golden ${armorSlot(armor) === 'shield' ? 'layer' : 'shield'}`}!`);
    }
    const oldAc = wornArmorAcValue(armor);
    if (newErodeproof && ((armor.oeroded || 0) || (armor.oeroded2 || 0))) {
        armor.oeroded = 0;
        armor.oeroded2 = 0;
        if (game.u) game.u.uac = (game.u.uac ?? 10) + oldAc - wornArmorAcValue(armor);
        messages.push(`${subject} ${armorVerb(armor, game.u?.blind ? 'feels' : 'looks', game.u?.blind ? 'feel' : 'look')} as good as new!`);
    }
    finishConfusedProofMutation(armor, oldErodeproof, newErodeproof, messages);
    if (oldErodeproof && !newErodeproof) armor.rknown = true;
    updateArmorLine(armor);
    return { messages, known: false };
}

function transformDragonScales(armor, blessed) {
    const oldAc = wornArmorAcValue(armor);
    const oldName = armorMessageName(armor);
    const mail = DRAGON_SCALE_MAIL_BY_SCALES.get(armorKind(armor));
    const spec = DRAGON_ARMOR_BY_COLOR.get(mail.replace(/ dragon scale mail$/, ''));
    armor.kind = mail;
    armor.actualKind = mail;
    if (spec) {
        armor.otyp = spec.mailOtyp;
        armor.color = spec.color;
        armor._display_color = spec.color;
    }
    armor.dragonArmor = true;
    armor.dragonArmorKind = 'mail';
    armor.noArticle = false;
    armor.owt = 40;
    if (blessed) {
        armor.spe = capWishSpe((armor.spe ?? 0) + 1);
        armor.blessed = true;
        armor.cursed = false;
    } else if (armor.cursed) {
        armor.cursed = false;
    }
    armor.known = true;
    updateArmorLine(armor);
    if (game.u) game.u.uac = (game.u.uac ?? 10) + oldAc - wornArmorAcValue(armor);
    updateReflectionFromInventory();
    return `Your ${oldName} ${armorVerb({ ...armor, kind: oldName, actualKind: oldName }, 'merges', 'merge')} and ${armorVerb({ ...armor, kind: oldName, actualKind: oldName }, 'hardens', 'harden')}!`;
}

function enchantArmorScrollEffect(item) {
    const armor = someEnchantArmorTarget();
    if (!armor) {
        exerciseAttribute(A_CON, !item.cursed);
        exerciseAttribute(A_STR, !item.cursed);
        return {
            messages: [game.u?.blind ? 'Your skin feels warm for a moment.' : 'Your skin glows then fades.'],
            known: false,
        };
    }
    if (heroIsConfused()) return enchantArmorConfusedEffect(item, armor);

    const specialArmor = isSpecialEnchantArmor(armor);
    let s = item.cursed ? -(armor.spe ?? 0) : (armor.spe ?? 0);
    if (s > (specialArmor ? 5 : 3) && rn2(s)) {
        const subject = armorSubject(armor);
        const color = enchantArmorColorWord(armor, item.cursed, game.u?.blind);
        const messages = [`${subject} violently ${armorVerb(armor, game.u?.blind ? 'vibrates' : 'glows', game.u?.blind ? 'vibrate' : 'glow')}${color} for a while, then ${armorVerb(armor, 'evaporates', 'evaporate')}.`];
        destroyWornArmorItem(armor, messages);
        return {
            messages,
            known: !!armor.known,
        };
    }
    if (s < -100) s = -100;
    s = Math.trunc((4 - s) / 2);
    if (specialArmor) s++;
    if (!isEnchantMagicalArmor(armor)) s++;
    if (item.blessed) s++;
    if (s <= 0) {
        s = 0;
        if ((armor.spe ?? 0) > 0 && !rn2(armor.spe)) s = 1;
    } else {
        s = rnd(s);
    }
    if (s > 11) s = 11;
    if (item.cursed) s = -s;

    if (s >= 0 && DRAGON_SCALE_MAIL_BY_SCALES.has(armorKind(armor))) {
        return { messages: [transformDragonScales(armor, item.blessed)], known: true };
    }

    const messages = [];
    const color = enchantArmorColorWord(armor, item.cursed, game.u?.blind);
    messages.push(`${armorSubject(armor)} ${s === 0 ? 'violently ' : ''}${armorVerb(armor, game.u?.blind ? 'vibrates' : 'glows', game.u?.blind ? 'vibrate' : 'glow')}${color} for a ${s * s > 1 ? 'while' : 'moment'}.`);

    if (s < 0) {
        const payment = costlyAlterationPaymentMessage(armor, 'disenchant');
        if (payment) messages.push(payment);
    }

    if (item.cursed) {
        armor.cursed = true;
        armor.blessed = false;
    } else if (item.blessed) {
        armor.blessed = true;
        armor.cursed = false;
    } else if (armor.cursed) {
        armor.cursed = false;
    }

    if (s) {
        const oldAc = wornArmorAcValue(armor);
        const oldSpe = armor.spe ?? 0;
        armor.spe = capWishSpe(oldSpe + s);
        s = armor.spe - oldSpe;
        if (s && game.u) game.u.uac = (game.u.uac ?? 10) + oldAc - wornArmorAcValue(armor);
        armor.known = true;
    }
    updateArmorLine(armor);
    if ((armor.spe ?? 0) > (specialArmor ? 5 : 3) && (specialArmor || !rn2(7))) {
        messages.push(`${armorSubject(armor)} suddenly ${armorVerb(armor, 'vibrates', 'vibrate')} ${game.u?.blind ? 'again' : 'unexpectedly'}.`);
    }
    return { messages, known: !!armor.known };
}

function loseAmnesiaSpells() {
    const spells = game._known_spells || [];
    const n = spells.length;
    let nzap = rn2(n + 1);
    if (heroIsConfused()) {
        const confusedZap = rn2(n + 1);
        if (confusedZap > nzap) nzap = confusedZap;
    }
    if (nzap > 1 && !rnl(7)) nzap = rnd(nzap);
    if (!nzap) return;

    const kept = [];
    for (let i = 0; i < n; i++) {
        if (nzap > 0 && rn2(n - i) < nzap) {
            exerciseAttribute(A_WIS, false);
            nzap--;
        } else {
            kept.push(spells[i]);
        }
    }
    game._known_spells = kept;
}

function amnesiaScrollEffect(item) {
    if (!item.blessed) loseAmnesiaSpells();
    rnd(item.blessed ? 3 : 5);
    if (game.u && (game.u.upunished || game._punished)) game.u._bcFelt = 0;
    for (const mon of game.level?.monsters || []) {
        if (mon !== game.u?.usteed && mon !== game.u?.ustuck) mon.meverseen = 0;
    }
    if (game.u?.hallucinating) {
        exerciseAttribute(A_WIS, false);
        return 'Your mind releases itself from mundane concerns.';
    }
    if (/^maud/i.test(game.plname || '')) {
        exerciseAttribute(A_WIS, false);
        return 'As your mind turns inward on itself, you forget everything else.';
    }
    const message = rn2(2)
        ? 'Who was that Maud person anyway?'
        : 'Thinking of Maud you forget everything else.';
    exerciseAttribute(A_WIS, false);
    return message;
}

async function createMonsterScrollEffect(item) {
    const confused = heroIsConfused();
    const count = 1 + ((confused || item.cursed) ? 12 : 0)
        + ((item.blessed || rn2(73)) ? 0 : rnd(4));
    const fixedMonster = confused ? monsterByRndName('acid blob') : null;
    let known = false;
    for (let i = 0; i < count; i++) {
        const mon = await makemon(fixedMonster, game.u?.ux || 0, game.u?.uy || 0, 0);
        if (!mon) continue;
        newsym(mon.mx, mon.my);
        if (couldsee(mon.mx, mon.my) && !mon.mundetected) known = true;
    }
    if (known) learnScrollByName('create monster', item, 6);
    return known;
}

function visibleMonsterForScroll(mon) {
    return !!mon && !mon.dead && (mon.mhp ?? 1) > 0
        && !mon.mundetected && (!mon.minvis || game.u?.seeInvisible) && couldsee(mon.mx, mon.my);
}

function ensurePetExtension(mon) {
    mon.mextra ??= {};
    mon.mextra.edog ??= {
        apport: 3,
        hungrytime: Math.max(game.moves || 1, 1) + 1000,
        dropdist: 10000,
        whistletime: 0,
        ogoal: { x: 0, y: 0 },
    };
}

function baseScrollTameness(mon) {
    const name = String(mon.data?.name || mon.name || '').toLowerCase();
    const mlet = mon.data?.mlet || mon.mlet;
    return mlet === 'dog' || mlet === 'feline' || mlet === 'unicorn'
        || ['little dog', 'dog', 'large dog', 'kitten', 'housecat', 'large cat', 'pony', 'horse', 'warhorse'].includes(name)
        ? 10 : 5;
}

function tameMonsterWithScroll(mon, item) {
    const wasTame = mon.mtame || 0;
    const wasPeaceful = !!(mon.mpeaceful || mon.pet);
    if (item.cursed) {
        mon.mpeaceful = 0;
        mon.pet = false;
        mon.mtame = 0;
        set_malign(mon);
        return wasPeaceful ? -1 : 0;
    }

    if (!mon.isshk && monsterResistsEffect(mon, 9)) return 0;
    if (mon.mfrozen) mon.mfrozen = Math.trunc((mon.mfrozen + 1) / 2);
    if (mon.msleeping) mon.msleeping = 0;
    const monsterName = String(mon.data?.name || mon.name || '').toLowerCase();
    if (monsterName === 'wizard of yendor' || monsterName === 'medusa' || mon.data?.wantsArtifact)
        return 0;

    mon.mpeaceful = 1;
    mon.mflee = 0;
    mon.mfleetim = 0;
    clearMonsterTrack(mon);
    set_malign(mon);

    if ((mon.mtame || 0) && mon.mtame < 10) {
        if (mon.mtame < rnd(10)) mon.mtame++;
        if (item.blessed) mon.mtame = Math.min(10, mon.mtame + 2);
        return (mon.mtame || 0) !== wasTame ? 1 : 0;
    }
    if (mon.isshk || mon.isgd || mon.ispriest || mon.isminion
        || mon.data?.isHuman || mon.data?.human || mon.data?.demon || mon.data?.covetous
        || mon.mcanmove === false)
        return !wasPeaceful && mon.mpeaceful ? 1 : 0;

    mon.pet = true;
    mon.mtame = Math.max(mon.mtame || 0, baseScrollTameness(mon));
    mon.mpeaceful = 1;
    ensurePetExtension(mon);
    newsym(mon.mx, mon.my);
    return (!wasPeaceful || wasTame !== mon.mtame) ? 1 : 0;
}

function tamingScrollEffect(item) {
    const confused = heroIsConfused();
    const radius = confused ? 5 : 1;
    let candidates = 0;
    let results = 0;
    let visibleResults = 0;
    const seen = new Set();
    const candidatesList = [];
    for (const mon of game.level?.monsters || []) {
        if (!mon || mon.dead || (mon.mhp ?? 1) <= 0 || mon.mx == null || mon.my == null) continue;
        if (Math.max(Math.abs(mon.mx - (game.u?.ux || 0)), Math.abs(mon.my - (game.u?.uy || 0))) > radius) continue;
        if (seen.has(mon)) continue;
        seen.add(mon);
        candidatesList.push(mon);
    }
    if (game.u?.usteed && !seen.has(game.u.usteed)) {
        seen.add(game.u.usteed);
        candidatesList.push(game.u.usteed);
    }

    for (const mon of candidatesList) {
        candidates++;
        const res = tameMonsterWithScroll(mon, item);
        results += res;
        if (visibleMonsterForScroll(mon)) visibleResults += res;
    }

    if (!results) {
        return { message: `Nothing interesting ${candidates ? 'seems to happen' : 'happens'}.`, known: false };
    }
    if (visibleResults > 0) learnScrollByName('taming', item, 7);
    return {
        message: `The neighborhood ${visibleResults ? 'is' : 'seems'} ${results < 0 ? 'un' : ''}friendlier.`,
        known: visibleResults > 0,
    };
}

function confuseMonsterScrollEffect(item) {
    const confused = heroIsConfused();
    const nonHuman = !!game.u?._polyself_form && game.u._polyself_form.mlet !== 'human';
    if (item.cursed || nonHuman) {
        const wasConfused = confused;
        addHeroConfusion(rnd(100));
        return wasConfused ? '' : 'You feel confused.';
    }
    if (confused) {
        if (item.blessed) {
            clearHeroConfusion();
            return 'A red glow surrounds your head.';
        }
        addHeroConfusion(rnd(100));
        return 'Your hands begin to glow purple.';
    }
    let increment = 3;
    const existing = game.u?.umconf || 0;
    let message;
    if (item.blessed) {
        message = `Your hands glow ${existing ? 'an even more' : 'a'} brilliant red.`;
        increment += rn1(8, 2);
    } else {
        message = existing
            ? 'The red glow of your hands intensifies.'
            : 'Your hands begin to glow red.';
        increment += rnd(2);
    }
    if (existing >= 40) increment = 1;
    if (game.u) {
        game.u.umconf = existing + increment;
        addHeroStatusSuffix('Glow');
    }
    return message;
}

function scareMonsterScrollEffect(item) {
    const confused = heroIsConfused();
    const reverse = confused || item.cursed;
    let visibleUntame = 0;
    for (const mon of game.level?.monsters || []) {
        if (!mon || mon.dead || mon.mhp <= 0 || !couldsee(mon.mx, mon.my)) continue;
        if (reverse) {
            mon.mflee = 0;
            mon.mfrozen = 0;
            mon.msleeping = 0;
            mon.mcanmove = 1;
        } else if (!monsterResistsEffect(mon, 9)) {
            mon.mflee = 1;
            mon.mfleetim = 0;
            clearMonsterTrack(mon);
        }
        if (!mon.mtame && !mon.pet) visibleUntame++;
    }
    return `You hear ${reverse ? 'sad wailing' : 'maniacal laughter'} ${visibleUntame ? 'close by' : 'in the distance'}.`;
}

function applyConfuseMonsterOnHit(mon, messages, targetPhrase) {
    if (!game.u?.umconf || mon?.mconf) return;
    const handsMessage = game.u.umconf === 1
        ? 'Your hands stop glowing red.'
        : 'Your hands no longer glow so brightly red.';
    messages.push(handsMessage);
    game.u.umconf--;
    if (!game.u.umconf) removeHeroStatusSuffix('Glow');
    const attackLevel = game.u?.ulevel || 1;
    if (!monsterResistsEffect(mon, attackLevel)) {
        mon.mconf = 1;
        if (couldsee(mon.mx, mon.my))
            messages.push(`${sentenceCase(targetPhrase)} appears confused.`);
    }
}

function isBoxObject(item) {
    const kind = objectKindKey(item);
    return item?.otyp === LARGE_BOX || item?.otyp === CHEST
        || kind === 'large box' || kind === 'chest';
}

function isWishedContainerObject(item) {
    const kind = objectKindKey(item);
    return isBoxObject(item) || item?.otyp === ICE_BOX || BAG_OBJECT_TYPES.has(item?.otyp)
        || kind === 'ice box' || kind === 'sack' || kind === 'oilskin sack'
        || kind === 'bag of holding';
}

function applyWishedContainerState(item, qualifiers) {
    if (!item) return;
    const box = isBoxObject(item);
    const tin = isTinObject(item);
    if (qualifiers.trappedState && (box || tin))
        item.otrapped = qualifiers.trappedState === 1;
    if (qualifiers.empty && tin && !item._wish_tin_explicit_content)
        setTinEmpty(item);
    if (qualifiers.empty && (objectKindKey(item) === 'bag of tricks' || isHornOfPlentyObject(item)))
        item.spe = 0;
    if (qualifiers.empty && isWishedContainerObject(item))
        item.contents = [];
    if (!box || !qualifiers.lockState) return;
    if (qualifiers.lockState === 'locked') {
        item.olocked = true;
        item.locked = true;
        item.obroken = false;
        item.broken = false;
    } else if (qualifiers.lockState === 'unlocked') {
        item.olocked = false;
        item.locked = false;
        item.obroken = false;
        item.broken = false;
    } else if (qualifiers.lockState === 'broken') {
        item.olocked = false;
        item.locked = false;
        item.obroken = true;
        item.broken = true;
        item.otrapped = false;
    }
}

const FIRE_FLAMMABLE_ARMOR_KINDS = new Set([
    'elven leather helm', 'fedora', 'cornuthaum', 'dunce cap',
    'studded leather armor', 'leather armor', 'leather jacket',
    'hawaiian shirt', 't-shirt',
    'mummy wrapping', 'elven cloak', 'orcish cloak', 'dwarvish cloak', 'oilskin cloak',
    'robe', 'alchemy smock', 'leather cloak', 'cloak of protection',
    'cloak of invisibility', 'cloak of magic resistance', 'cloak of displacement',
    'small shield', 'shield of drain resistance', 'shield of shock resistance', 'elven shield',
    'leather gloves', 'gauntlets of fumbling', 'gauntlets of dexterity',
    'low boots', 'high boots', 'speed boots', 'water walking boots', 'jumping boots',
    'elven boots', 'fumble boots', 'levitation boots',
]);

const FIRE_NONFLAMMABLE_ARMOR_KINDS = new Set([
    'orcish helm', 'dwarvish iron helm', 'dented pot', 'helm of brilliance',
    'helmet', 'helm of caution', 'helm of opposite alignment', 'helm of telepathy',
    'plate mail', 'crystal plate mail', 'bronze plate mail', 'splint mail',
    'banded mail', 'dwarvish mithril-coat', 'elven mithril-coat', 'chain mail',
    'orcish chain mail', 'scale mail', 'ring mail', 'orcish ring mail',
    'uruk-hai shield', 'orcish shield', 'large shield', 'dwarvish roundshield',
    'shield of reflection', 'gauntlets of power', 'iron shoes', 'kicking boots',
]);

const IRON_POLEARM_KINDS = new Set([
    'partisan', 'ranseur', 'spetum', 'glaive', 'halberd', 'bardiche',
    'voulge', 'fauchard', 'guisarme', 'bill-guisarme', 'lucern hammer',
    'bec de corbin',
]);

function wishedDamageProfile(item) {
    const kind = objectKindKey(item);
    const cls = itemClassKey(item);
    const weapon = cls === 'weapon' || item?.glyph === ')';
    const armor = cls === 'armor' || item?.glyph === '[';
    const ballOrChain = item?.otyp === HEAVY_IRON_BALL || item?.otyp === IRON_CHAIN || cls === 'ball' || cls === 'chain';
    const weptool = cls === 'tool' && APPLY_WEAPON_NAME_RE.test(kind);
    const erosionMatters = weapon || armor || ballOrChain || weptool;
    if (!erosionMatters) return { erosionMatters: false };

    const material = String(item?.material || item?.oc_material || '').toLowerCase().replace(/_/g, ' ');
    const hasMaterial = !!material;
    const materialIron = /^(?:iron|steel)$/.test(material);
    const materialCopper = /^(?:copper|bronze)$/.test(material);
    const materialGlass = /^(?:glass|crystal)$/.test(material);
    const materialFlammable = /^(?:wood|leather|cloth|paper|wax|veggy|vegetable|flesh|plastic)$/.test(material);
    const materialExcluded = /^(?:silver|gold|mithril|platinum|gem|stone|mineral|metal)$/.test(material);
    const excludedMetal = materialExcluded || /\b(?:silver|gold|mithril|platinum|gem|stone|crystal ball|shield of reflection)\b/.test(kind);
    const glassArmor = armor && (materialGlass || /\b(?:crystal plate mail|helm of brilliance|crystal helmet)\b/.test(kind));
    const dragonHide = armor && /\bdragon (?:scales|scale mail|hide)\b/.test(kind);
    const flammableArmor = armor && FIRE_FLAMMABLE_ARMOR_KINDS.has(kind);
    const nonflammableArmor = armor && FIRE_NONFLAMMABLE_ARMOR_KINDS.has(kind);
    const copperLike = materialCopper || /\b(?:copper|bronze)\b/.test(kind);
    const rustproneProjectile = /^(?:arrow|orcish arrow|crude arrow|crossbow bolt)$/.test(kind);
    const inferredIronLike = !hasMaterial && !flammableArmor && !excludedMetal && !glassArmor && !copperLike && !dragonHide && (ballOrChain || kind.includes('iron')
        || rustproneProjectile
        || IRON_POLEARM_KINDS.has(kind)
        || /\b(?:plate mail|splint mail|banded mail|ring mail|chain mail|scale mail|large shield|roundshield|gauntlets|helm|helmet|dented pot|shoes|sword|saber|dagger|knife|axe|mace|hammer|flail|morning star|pick-axe|mattock|spear|trident|lance|polearm|dart|shuriken|throwing star)\b/.test(kind));
    const ironLike = materialIron || inferredIronLike;
    const flammableLike = materialFlammable || flammableArmor || (!hasMaterial && !nonflammableArmor && !glassArmor && !ironLike && !copperLike && !excludedMetal
        && /\b(?:leather|cloth|cloak|robe|shirt|boots|gloves|wooden|small shield|bow|crossbow|arrow|club|quarterstaff|aklys|bullwhip|sling)\b/.test(kind));
    const rustprone = ironLike;
    const crackable = glassArmor;
    const corrodeable = ironLike || copperLike;
    const flammable = flammableLike;
    const rottable = flammableLike || dragonHide;
    const damageable = rustprone || crackable || corrodeable || flammable || rottable;

    return {
        erosionMatters,
        primary: rustprone || crackable || flammable,
        secondary: corrodeable || rottable,
        damageable,
        primaryWord: rustprone ? 'rusty' : crackable ? 'cracked' : flammable ? 'burnt' : '',
        secondaryWord: corrodeable ? 'corroded' : rottable ? 'rotted' : '',
        proofWord: rustprone ? 'rustproof' : corrodeable ? 'corrodeproof'
            : flammable ? 'fireproof' : crackable ? 'tempered'
                : rottable ? 'rotproof' : '',
    };
}

function wishedPoisonable(item) {
    const kind = objectKindKey(item);
    return item?.artifact === 'Grimtooth' || POISONABLE_WISH_WEAPONS.has(kind);
}

function applyWishedQualifiers(item, qualifiers) {
    if (!item) return;
    const profile = wishedDamageProfile(item);
    if (profile.erosionMatters) {
        item.oeroded = 0;
        item.oeroded2 = 0;
        if (qualifiers.eroded && profile.primary)
            item.oeroded = Math.min(3, qualifiers.eroded);
        if (qualifiers.eroded2 && profile.secondary)
            item.oeroded2 = Math.min(3, qualifiers.eroded2);
        if (qualifiers.erodeproof && profile.damageable)
            item.oerodeproof = ((game.u?.uluck || 0) + (game.u?.moreluck || 0)) >= 0 || !!game.flags?.debug;
    }
    if (qualifiers.greased) item.greased = true;
    if (qualifiers.diluted && isPotionObject(item) && !isWaterPotion(item))
        item.odiluted = true;
    applyWishedLightState(item, qualifiers.lightState);
    if (qualifiers.halfeaten)
        applyWishedPartlyEaten(item);
    if (qualifiers.poisoned) {
        if (wishedPoisonable(item)) item.opoisoned = ((game.u?.uluck || 0) + (game.u?.moreluck || 0)) >= 0;
        else if (itemClassKey(item) === 'food') item.age = 1;
    }
    if (qualifiers.zombifying && (item.otyp === CORPSE || /\bcorpse$/.test(objectKindKey(item)))) {
        item.zombifying = true;
        if (!item.zombifyTurn) startCorpseTimeout(item, { zombify: true });
    }
    if (qualifiers.wetness && objectKindKey(item) === 'towel') {
        item.wetness = qualifiers.wetness;
        item.spe = qualifiers.wetness;
    }
    applyWishedContainerState(item, qualifiers);
}

function applyWishedQuantity(item, wishedQuan, forceQuantity = false) {
    const quantity = Math.max(1, Math.trunc(Number(wishedQuan || 1)));
    if (item?.globby) {
        applyWishedGlobQuantity(item, quantity);
    } else if (item?.dragonArmor) {
        item.quan = 1;
    } else if (isTinObject(item)) {
        if (game.flags?.debug || quantity < rnd(6))
            item.quan = quantity;
    } else if (wishQuantityMergeable(item)) {
        if (game.flags?.debug || quantity < rnd(6) || wishQuantityAlwaysAllowed(item, quantity))
            item.quan = quantity;
    } else if (forceQuantity) {
        item.quan = 1;
    }
}

function wishQuantityMergeable(item) {
    const metadata = wishObjectMetadataForItem(item);
    if (metadata?.ocMerge != null) return !!metadata.ocMerge;
    const cls = itemClassKey(item);
    if (cls === 'scroll' || cls === 'potion' || cls === 'gem') return true;
    if (cls === 'food' && objectKindKey(item) !== 'meat ring') return true;
    if (cls === 'weapon') return true;
    if (cls === 'venom') return true;
    if (isCandleObject(item)) return true;
    return false;
}

function wishedAmmoOrMissile(item) {
    const kind = objectKindKey(item);
    return item?.otyp === DART
        || /\b(?:arrow|arrows|bolt|bolts|dart|darts|shuriken|throwing star|throwing stars|rock|rocks|flint)\b/.test(kind);
}

function wishQuantityAlwaysAllowed(item, quantity) {
    if (quantity <= 7 && isCandleObject(item)) return true;
    return quantity <= 20 && (wishedAmmoOrMissile(item)
        || item?.otyp === ROCK || item?.otyp === FLINT || ['rock', 'flint'].includes(objectKindKey(item)));
}

function applyWishedTinVariety(item) {
    if (!isTinObject(item) || item._wish_tin_requested_variety == null) return;
    const varietyIndex = item._wish_tin_requested_variety;
    if (game.flags?.debug || rn2(4)) {
        if (item.corpsenm?.name) setTinMonster(item, item.corpsenm, varietyIndex);
        else item.spe = -(varietyIndex + 1);
    }
}

function splitWishedTextClause(text, clause) {
    const match = String(text || '').match(new RegExp(`\\s+${clause}\\s+`, 'i'));
    if (!match) return null;
    return {
        base: String(text).slice(0, match.index).trim(),
        tail: String(text).slice(match.index + match[0].length).trim(),
    };
}

function splitWishedLabelClause(text) {
    const match = String(text || '').match(/\s+labell?ed\s+/i);
    if (!match) return null;
    return {
        base: String(text).slice(0, match.index).trim(),
        tail: String(text).slice(match.index + match[0].length).trim(),
    };
}

function unquoteWishedText(text) {
    const trimmed = String(text || '').trim();
    const quoted = trimmed.match(/^"([^"]*)"$/) || trimmed.match(/^'([^']*)'$/);
    return (quoted ? quoted[1] : trimmed).trim();
}

function wishedLabelKey(text) {
    return unquoteWishedText(text).toLowerCase().replace(/\s+/g, ' ');
}

function calledWishymatch(userText, objectText) {
    return wishedFuzzyObjectKey(userText) === wishedFuzzyObjectKey(objectText);
}

function calledTailMatchesObjectName(called, objectName) {
    if (calledWishymatch(called, objectName)) return true;
    const of = String(objectName || '').toLowerCase().indexOf(' of ');
    return of >= 0 && calledWishymatch(called, String(objectName).slice(of + 4));
}

function calledRangeNamedescName(base, called) {
    const range = WISH_OBJECT_RANGES.get(base);
    if (!range) return '';
    const rangeNames = new Set(range.map(([name]) => name));
    for (const [namedesc, candidates] of WISH_NAMEDESC_RANGES) {
        if (!calledWishymatch(called, namedesc)) continue;
        if (candidates.every(([name]) => rangeNames.has(name))) return namedesc;
    }
    for (const [name] of range) {
        if (calledTailMatchesObjectName(called, name)) return name;
        const baseObject = WISH_BASE_OBJECTS.get(name);
        if (baseObject?.actualKind && calledTailMatchesObjectName(called, baseObject.actualKind))
            return name;
        const armorAppearance = ARMOR_WISH_APPEARANCES[name];
        if (armorAppearance) {
            const [group, index, fallback] = armorAppearance;
            const appearance = group ? game._object_descriptions?.[group]?.[index] || fallback : fallback;
            if (appearance && calledTailMatchesObjectName(called, appearance)) return name;
        }
        const toolAppearance = WISH_TOOL_APPEARANCES.get(name);
        if (toolAppearance && calledTailMatchesObjectName(called, toolAppearance)) return name;
    }
    return '';
}

function calledRangeBaseNamedescName(base) {
    const range = WISH_OBJECT_RANGES.get(base);
    if (!range) return '';
    const matches = [];
    for (const [name, prob] of range) {
        let matched = calledTailMatchesObjectName(base, name);
        const baseObject = WISH_BASE_OBJECTS.get(name);
        if (!matched && baseObject?.actualKind)
            matched = calledTailMatchesObjectName(base, baseObject.actualKind);
        const armorAppearance = ARMOR_WISH_APPEARANCES[name];
        if (!matched && armorAppearance) {
            const [group, index, fallback] = armorAppearance;
            const appearance = group ? game._object_descriptions?.[group]?.[index] || fallback : fallback;
            matched = appearance && calledTailMatchesObjectName(base, appearance);
        }
        const toolAppearance = WISH_TOOL_APPEARANCES.get(name) || WISH_RANGE_BASE_DESCRIPTIONS.get(name);
        if (!matched && toolAppearance)
            matched = calledTailMatchesObjectName(base, toolAppearance);
        if (matched) matches.push([name, prob + 1]);
    }
    const total = matches.reduce((sum, [, prob]) => sum + prob, 0);
    if (total <= 0) return '';
    let roll = rn2(total);
    for (const [name, prob] of matches) {
        roll -= prob;
        if (roll < 0) return name;
    }
    return matches[0]?.[0] || '';
}

function parseWishedScrollLabel(name) {
    const match = String(name || '').trim().match(/^scrolls?\s+labell?ed\s+(.+)$/i);
    return match ? unquoteWishedText(match[1]) : '';
}

function resolveCalledWishName(baseName, calledName) {
    const base = String(baseName || '').trim().toLowerCase();
    const called = wishedLabelKey(calledName);
    const explicit = new Map([
        ['shield:reflection', 'shield of reflection'],
        ['helm:telepathy', 'helm of telepathy'],
        ['amulet:life saving', 'amulet of life saving'],
        ['amulet:esp', 'amulet of esp'],
        ['amulet:guarding', 'amulet of guarding'],
        ['ring:accuracy', 'ring of increase accuracy'],
        ['ring:increase accuracy', 'ring of increase accuracy'],
        ['ring:protection from shape changers', 'ring of protection from shape changers'],
        ['ring:protection from shape shifters', 'ring of protection from shape changers'],
    ]).get(`${base}:${called}`);
    if (explicit) return explicit;
    const rangeCalled = calledRangeNamedescName(base, called);
    if (rangeCalled) return rangeCalled;
    if (base === 'amulet' || base === 'ring') {
        const candidate = `${base} of ${called}`;
        return WISH_BASE_OBJECTS.has(candidate)
            || WISH_NAME_ALIASES.has(candidate)
            || IDENTIFIED_AMULET_NAMES.includes(candidate)
            || IDENTIFIED_RING_NAMES.includes(candidate.replace(/^ring of /, ''))
            || ARMOR_WISH_APPEARANCES[candidate]
            ? candidate : '';
    }
    return '';
}

