const WISH_GEMS = [...WISH_REAL_GEMS, ...WISH_GLASS_GEMS];
const WISH_GEMS_BY_DISPLAY = new Map();
for (const gem of WISH_GEMS) {
    WISH_GEMS_BY_DISPLAY.set(gem.name, gem);
    WISH_GEMS_BY_DISPLAY.set(gem.displayName, gem);
}

function wishedGemObject(spec, { description = spec?.description || '', consumeNamedesc = true } = {}) {
    if (!spec) return null;
    if (consumeNamedesc) rn2(spec.prob + 1);
    const otmp = mksobj(GEM_CLASS, false, false);
    const display = spec.displayName || spec.name;
    const color = WISH_GEM_COLORS.get(spec.description) ?? NO_COLOR;
    return Object.assign(otmp, {
        cls: 'gem',
        glyph: '*',
        kind: display,
        actualKind: display,
        gemDescription: description ? `${description} gem` : display,
        color,
        _display_color: color,
        wishedfor: true,
    });
}

function weightedWishedGem(candidates) {
    const total = candidates.reduce((sum, gem) => sum + gem.prob + 1, 0);
    let roll = rn2(total);
    for (const gem of candidates) {
        roll -= gem.prob + 1;
        if (roll < 0) return gem;
    }
    return candidates[0] || null;
}

function canonicalWishedGlassName(lowerName) {
    if (lowerName === 'looking glass') return '';
    let name = String(lowerName || '').trim();
    if (name === 'glass') {
        const gem = WISH_GLASS_GEMS[rn2(WISH_GLASS_GEMS.length)];
        return gem?.name || '';
    }
    if (!name.endsWith(' glass')) return '';
    name = name.replace(/^worthless\s+/, '');
    name = name.replace(/^pieces?\s+of\s+/, '');
    name = name.replace(/^colou?red\s+/, '');
    if (name === 'glass') {
        const gem = WISH_GLASS_GEMS[rn2(WISH_GLASS_GEMS.length)];
        return gem?.name || '';
    }
    return `worthless piece of ${name}`;
}

function makeWishedGemObject(lowerName) {
    let name = String(lowerName || '').trim().replace(/^worthless pieces of /, 'worthless piece of ');
    const suffix = name.match(/^(.+?)\s+(?:gems?|stones?)$/);
    if (suffix) {
        const description = suffix[1].trim();
        const candidates = WISH_GEMS.filter(gem => gem.description === description || gem.name === description || gem.displayName === description);
        if (candidates.length) return wishedGemObject(weightedWishedGem(candidates), { description, consumeNamedesc: false });
    }
    const glassName = canonicalWishedGlassName(name);
    if (glassName) name = glassName;
    const exact = WISH_GEMS_BY_DISPLAY.get(name);
    if (exact) return wishedGemObject(exact);
    return null;
}

function normalizeWishedGroupPhrase(name, quantity) {
    const match = String(name || '').match(/^(pair|pairs|set|sets)\s+of\s+/i);
    if (!match) return { name, quantity, matched: false };
    const objectName = String(name).slice(match[0].length);
    const nonStackingPairObject = /\b(?:boots|shoes|gloves|gauntlets|lenses)\b/i.test(objectName);
    let wishedQuantity = quantity;
    const group = match[1].toLowerCase();
    if (nonStackingPairObject) wishedQuantity = 1;
    else if (group === 'pair') wishedQuantity *= 2;
    else if (!nonStackingPairObject && group === 'pairs' && quantity > 1) wishedQuantity *= 2;
    return {
        name: objectName,
        quantity: wishedQuantity,
        matched: true,
    };
}

function applyWishedPluralQuantity(name, quantity) {
    if (quantity !== 1) return quantity;
    const rawLowerName = String(name || '').trim().toLowerCase();
    if (rawLowerName === 'venoms' || rawLowerName === 'splashes of venom'
        || rawLowerName === 'splashes of blinding venom' || rawLowerName === 'splashes of acid venom')
        return 2;
    const rawFruit = fruitWishMatch(rawLowerName);
    if (rawFruit?.plural) return 2;
    const rawBaseObject = WISH_BASE_OBJECTS.get(rawLowerName);
    if (rawBaseObject?.plural && rawLowerName === String(rawBaseObject.plural).toLowerCase()) return 2;
    const lowerName = resolveWishedSpellingAlias(rawLowerName).name;
    const fruit = fruitWishMatch(lowerName);
    if (fruit?.plural) return 2;
    const baseObject = WISH_BASE_OBJECTS.get(lowerName);
    if (baseObject?.plural && lowerName === String(baseObject.plural).toLowerCase()) return 2;
    if (/^(?:worthless\s+)?pieces\s+of\s+.+\s+glass$/.test(lowerName)) return 2;
    if (/\bgems$/.test(lowerName) || /\bstones$/.test(lowerName)) return 2;
    if (lowerName === 'fortune cookies') return 2;
    return quantity;
}

function applyWishedInstanceName(item, name) {
    const objectName = String(name || '').trim();
    if (!item || !objectName || item.artifact) return;
    item.oname = objectName;
    item._wish_object_name = objectName;
}

function makeWishedBaseObject(baseObject, metadata) {
    const forceBagOfTricksTool = !!metadata?.forceBagOfTricksTool;
    if (forceBagOfTricksTool) game._mkobj_force_bag_of_tricks = true;
    try {
        return mksobj(baseObject.otyp, true, false);
    } finally {
        if (forceBagOfTricksTool) game._mkobj_force_bag_of_tricks = false;
    }
}

function wishedObjectRangeName(lowerName) {
    const range = WISH_OBJECT_RANGES.get(lowerName);
    if (!range) return '';
    const total = range.reduce((sum, [, prob]) => sum + prob, 0);
    if (total <= 0) return range[rn2(range.length)]?.[0] || '';
    let roll = rnd(total);
    for (const [name, prob] of range) {
        roll -= prob;
        if (roll <= 0) return name;
    }
    return range[0]?.[0] || '';
}

function makeWishedObjectRangeObject(lowerName) {
    const rangeName = wishedObjectRangeName(lowerName);
    if (!rangeName) return null;
    return makeWishedRangeObjectByName(rangeName);
}

function makeWishedRangeObjectByName(rangeName) {
    if (rangeName === 'magic lamp' && !game.flags?.debug)
        return makeOilLampFromMagicLampWishObject();
    const baseObject = WISH_BASE_OBJECTS.get(rangeName);
    if (!baseObject) return null;
    const baseFields = { ...baseObject };
    delete baseFields.wishSpeRn1;
    const metadata = wishObjectMetadataForName(rangeName) ?? wishObjectMetadataForItem(baseFields);
    const otmp = makeWishedBaseObject(baseObject, metadata);
    return Object.assign(otmp, baseFields, { wishedfor: true });
}

function makeWishedObjectClassObject(oclass) {
    if (!oclass) return null;
    const otmp = mkobj(oclass, false);
    const classFields = {};
    if (oclass === SCROLL_CLASS) classFields.cls = 'scroll';
    else if (oclass === SPBOOK_CLASS) classFields.cls = 'spellbook';
    return Object.assign(otmp, object_display(otmp), classFields, { wishedfor: true });
}

function makeWishedFruitObject(lowerName) {
    const fruit = fruitWishMatch(lowerName);
    if (!fruit) return null;
    const otmp = mksobj(SLIME_MOLD, true, false);
    applySlimeMoldFruitFields(otmp, fruit.fid);
    return Object.assign(otmp, { wishedfor: true });
}

function wishedObjectFromName(name, qualifiers = {}) {
    const wishName = String(name || '').trim();
    const lowerWishName = wishName.toLowerCase();
    const artifact = makeArtifactWishObject(lowerWishName, { wizardMode: !!game.flags?.debug });
    if (artifact) return artifact;

    const named = splitWishedTextClause(wishName, 'named');
    let baseText = named?.base || wishName;
    const called = splitWishedTextClause(baseText, 'called');
    if (called) {
        baseText = called.base;
        qualifiers = { ...qualifiers, wishCalledName: unquoteWishedText(called.tail) };
    }
    const labeled = splitWishedLabelClause(baseText);
    if (labeled) {
        baseText = labeled.base;
        qualifiers = { ...qualifiers, wishLabelName: unquoteWishedText(labeled.tail) };
    }
    const baseName = normalizeWishedSpelling(baseText);
    const item = wishedBaseObjectFromName(baseName.toLowerCase(), qualifiers, baseName);
    if (named?.tail) applyWishedInstanceName(item, named.tail);
    return item;
}

function wishedBaseObjectFromName(lowerName, qualifiers = {}, originalName = lowerName) {
    const spellingAlias = resolveWishedSpellingAlias(lowerName);
    lowerName = spellingAlias.name;
    if (qualifiers.wishCalledName) {
        const calledWish = resolveCalledWishName(lowerName, qualifiers.wishCalledName);
        if (calledWish)
            return wishedBaseObjectFromName(calledWish, { ...qualifiers, wishCalledName: '' }, calledWish);
        const rangeBaseWish = calledRangeBaseNamedescName(lowerName);
        if (rangeBaseWish) return makeWishedRangeObjectByName(rangeBaseWish);
        const rangeClass = WISH_OBJECT_RANGE_CLASSES.get(lowerName);
        if (rangeClass) return makeWishedObjectClassObject(rangeClass);
    }
    if (lowerName === 'spell') return noFittingWishObject();
    if (lowerName === 'paperback' || lowerName === 'paperback book') return makeNovelWishObject();
    if (lowerName === 'paperback spellbook') return noFittingWishObject();

    const tinWish = parseWishedTinName(lowerName);
    if (tinWish) return makeWishedTinObject(tinWish);

    const yendorAmulet = makeAmuletOfYendorWishObject(lowerName, qualifiers);
    if (yendorAmulet) return yendorAmulet;

    const statueWish = parseWishedStatueName(lowerName, qualifiers);
    if (statueWish) {
        const statue = makeWishedStatueObject(statueWish, qualifiers);
        if (statue) return statue;
    }

    const figurineWish = parseWishedFigurineName(lowerName, qualifiers);
    if (figurineWish) return makeWishedFigurineObject(figurineWish, qualifiers);

    const corpseWish = parseWishedCorpseName(lowerName, qualifiers);
    if (corpseWish) return makeWishedCorpseObject(corpseWish, qualifiers);

    const globWish = parseWishedGlobName(lowerName, qualifiers);
    if (globWish) return makeWishedGlobObject(globWish);

    const eggWish = parseWishedEggName(lowerName, qualifiers);
    if (eggWish) return makeWishedEggObject(eggWish, qualifiers);

    const venomWish = makeWishedVenomObject(lowerName);
    if (venomWish) return venomWish;

    const wizardSpecial = makeWizardSpecialWishObject(lowerName);
    if (wizardSpecial) return wizardSpecial;

    const specialSubstitution = substituteNonWizardSpecialWish(lowerName);
    if (specialSubstitution) return specialSubstitution;
    const localWishMetadata = wishObjectMetadataForName(lowerName);
    if (localWishMetadata?.ocNowish && !game.flags?.debug) return noFittingWishObject();

    const rangeWish = makeWishedObjectRangeObject(lowerName);
    if (rangeWish) return rangeWish;

    const namedescRangeWish = makeWishedNamedescRangeObject(lowerName);
    if (namedescRangeWish) return namedescRangeWish;

    const dragonArmorWish = parseWishedDragonArmorName(lowerName);
    if (dragonArmorWish) return makeWishedDragonArmorObject(dragonArmorWish);

    const grayStoneWish = makeWishedGrayStoneObject(lowerName);
    if (grayStoneWish) return grayStoneWish;

    const gemWish = makeWishedGemObject(lowerName);
    if (gemWish) return gemWish;

    const fruitWish = makeWishedFruitObject(lowerName);
    if (fruitWish) return fruitWish;

    const baseObject = WISH_BASE_OBJECTS.get(lowerName);
    if (baseObject) {
        const namedescBound = WISH_BASE_NAMEDESC_BOUNDS.get(lowerName);
        if (namedescBound && !spellingAlias.skipNamedesc) rn2(namedescBound);
        const baseFields = { ...baseObject };
        delete baseFields.wishSpeRn1;
        const metadata = localWishMetadata ?? wishObjectMetadataForItem(baseFields);
        const otmp = makeWishedBaseObject(baseObject, metadata);
        return Object.assign(otmp, baseFields, { wishedfor: true });
    }

    const wandWish = lowerName.match(/^wand of ([a-z ]+?)$/);
    if (wandWish && WAND_NAME_TO_INDEX.has(wandWish[1])) {
        const wand = wandWish[1];
        const wandIndex = WAND_NAME_TO_INDEX.get(wand);
        rn2(WAND_WISH_NAMEDESC_BOUNDS.get(wand));
        game._mkobj_wand_index = wandIndex;
        const otmp = mksobj(WAND_CLASS, true, false);
        const chargeSuffix = !!qualifiers.wishChargeSuffix;
        let spe = chargeSuffix ? capWishSpe(Number(qualifiers.wishChargeSpe || 0)) : otmp.spe;
        let recharged = chargeSuffix ? Math.min(Math.max(0, Math.trunc(Number(qualifiers.wishRecharged || 0))), 7) : 0;
        let ignoreRequestedSpe = false;
        if (wand === 'wishing' && !game.flags?.debug) {
            spe = rn2(10) ? -1 : 0;
            recharged = 1;
            ignoreRequestedSpe = true;
        } else if (!game.flags?.debug) {
            spe = wishedSpeForItem(otmp, spe);
        }
        return Object.assign(otmp, {
            cls: 'wand',
            glyph: '/',
            kind: wand,
            wand,
            wandIndex,
            spe,
            recharged,
            known: false,
            wishedfor: true,
            _wish_ignore_requested_spe: ignoreRequestedSpe,
            _wish_spe_from_suffix: chargeSuffix,
        });
    }

    if (lowerName.includes('ring')) {
        const ringName = lowerName.replace(/^ring of /, '');
        const ringIndex = IDENTIFIED_RING_NAMES.indexOf(ringName);
        if (ringIndex >= 0) {
            if (!spellingAlias.skipNamedesc) rn2(2);
            game._mkobj_ring_roll = ringIndex + 1;
        }
        const otmp = mksobj(RING_CLASS, true, false);
        const appearance = game._object_descriptions?.rings?.[ringIndex];
        return Object.assign(otmp, {
            cls: 'ring',
            glyph: '=',
            kind: ringIndex >= 0 ? (appearance ? `${appearance} ring` : lowerName) : lowerName,
            actualKind: ringIndex >= 0 ? `ring of ${ringName}` : lowerName,
            ringRoll: ringIndex + 1,
            known: false,
            wishedfor: true,
        });
    }

    if (lowerName.includes('amulet')) {
        const amuletIndex = IDENTIFIED_AMULET_NAMES.indexOf(lowerName);
        const namedescBound = WISH_AMULET_NAMEDESC_BOUNDS.get(lowerName);
        if (namedescBound && !spellingAlias.skipNamedesc) rn2(namedescBound);
        game._mkobj_bad_amulet = BAD_AMULET_NAMES.has(lowerName);
        const otmp = mksobj(AMULET_CLASS, true, false);
        const appearance = amuletIndex >= 0 ? game._object_descriptions?.amulets?.[amuletIndex] : '';
        return Object.assign(otmp, {
            cls: 'amulet',
            glyph: '"',
            kind: lowerName,
            actualKind: lowerName,
            amuletIndex,
            appearance,
            known: false,
            wishedfor: true,
        });
    }

    if (qualifiers.unlabeled && lowerName === 'paper')
        return makeAmbiguousBlankPaperWishObject();

    if (lowerName === 'wall of water') return noFittingWishObject();
    if (/potion|juice|water/.test(lowerName)) {
        let potionName = lowerName.replace(/^potion(?: of)?\s+/, '');
        const appearanceWish = lowerName.match(/^(.+?) potions?$/);
        let appearanceIndex = -1;
        if (appearanceWish && !lowerName.startsWith('potion')) {
            const appearanceKey = wishedLabelKey(appearanceWish[1]);
            appearanceIndex = (game._object_descriptions?.potions || [])
                .findIndex(potion => wishedLabelKey(potion.description || '') === appearanceKey);
            if (appearanceIndex >= 0) potionName = IDENTIFIED_POTION_NAMES[appearanceIndex] || potionName;
        }
        const holyWater = potionName === 'holy water' || lowerName === 'holy water';
        const unholyWater = potionName === 'unholy water' || lowerName === 'unholy water';
        const waterPotion = lowerName === 'water' || potionName === 'water' || holyWater || unholyWater;
        const oilPotion = potionName === 'oil';
        const potionIndex = appearanceIndex >= 0 ? appearanceIndex : IDENTIFIED_POTION_NAMES.indexOf(potionName);
        if (potionIndex >= 0 && !spellingAlias.skipNamedesc) rn2(POTION_WISH_PROBS[potionIndex] + 1);
        const otmp = mksobj(waterPotion ? POT_WATER : oilPotion ? POT_OIL : potionIndex >= 0 ? POTION_WISH_BASE + potionIndex : POTION_CLASS, true, false);
        if (oilPotion && otmp.age == null) otmp.age = 400;
        const appearance = potionIndex >= 0 ? game._object_descriptions?.potions?.[potionIndex]?.description : '';
        if (holyWater) {
            otmp.blessed = true;
            otmp.cursed = false;
        } else if (unholyWater) {
            otmp.blessed = false;
            otmp.cursed = true;
        }
        return Object.assign(otmp, {
            cls: 'potion',
            glyph: '!',
            kind: waterPotion ? 'water' : appearance ? `${appearance} potion` : lowerName,
            actualKind: waterPotion ? 'potion of water' : potionIndex >= 0 ? `potion of ${potionName}` : lowerName,
            potionIndex: waterPotion ? null : potionIndex,
            known: false,
            wishedfor: true,
        });
    }

    if (lowerName.includes('scroll')) {
        const wishedLabel = qualifiers.wishLabelName || parseWishedScrollLabel(originalName);
        if (wishedLabel) {
            const labelKey = wishedLabelKey(wishedLabel);
            const scrollIndex = (game._object_descriptions?.scrolls || [])
                .findIndex(label => wishedLabelKey(label) === labelKey);
            if (scrollIndex >= 0 && scrollIndex < IDENTIFIED_SCROLL_NAMES.length) {
                rn2(SCROLL_WISH_PROBS[scrollIndex] + 1);
                return makeWishedKnownScrollObject(scrollIndex, wishedLabel);
            }
            if (scrollIndex >= IDENTIFIED_SCROLL_NAMES.length) {
                return makeWishedObjectClassObject(SCROLL_CLASS);
            }
            if (/^scrolls?$/.test(lowerName)) return makeWishedObjectClassObject(SCROLL_CLASS);
        }
        const scrollName = lowerName.replace(/^scrolls?(?: of)?\s+/, '');
        if ((qualifiers.unlabeled && /^scrolls?$/.test(lowerName)) || scrollName === 'blank paper')
            return makeBlankScrollWishObject();
        const scrollIndex = IDENTIFIED_SCROLL_NAMES.indexOf(scrollName);
        const mailScroll = scrollName === 'mail';
        if (mailScroll) rn2(1);
        else if (scrollIndex >= 0 && !spellingAlias.skipNamedesc) rn2(SCROLL_WISH_PROBS[scrollIndex] + 1);
        if (scrollIndex >= 0) return makeWishedKnownScrollObject(scrollIndex);
        const otmp = mksobj(SCROLL_CLASS, !mailScroll, false);
        const label = game._object_descriptions?.scrolls?.[scrollIndex] || 'ZELGO MER';
        return Object.assign(otmp, {
            cls: 'scroll',
            glyph: '?',
            kind: scrollName === 'mail' ? 'stamped scroll' : lowerName,
            actualKind: lowerName,
            scrollIndex,
            known: false,
            wishedfor: true,
        });
    }

    if (/spellbook|book/.test(lowerName)) {
        const spellName = lowerName.replace(/^spellbook(?: of)?\s+/, '');
        if ((qualifiers.unlabeled && lowerName === 'spellbook') || spellName === 'blank paper')
            return makeBlankSpellbookWishObject();
        const spellbookNames = Object.keys(SPELLBOOK_LEVELS);
        if (qualifiers.wishLabelName) {
            const labelKey = wishedLabelKey(qualifiers.wishLabelName);
            const spellbookIndex = (game._object_descriptions?.spellbooks || [])
                .findIndex(label => wishedLabelKey(label) === labelKey);
            if (spellbookIndex >= 0 && spellbookIndex < spellbookNames.length) {
                const labeledSpellName = spellbookNames[spellbookIndex];
                const namedescBound = WISH_SPELLBOOK_NAMEDESC_BOUNDS.get(labeledSpellName);
                if (namedescBound) rn2(namedescBound);
                const otmp = mksobj(SPBOOK_NO_NOVEL, true, false);
                return Object.assign(otmp, {
                    cls: 'spellbook',
                    glyph: '+',
                    kind: `spellbook of ${labeledSpellName}`,
                    spellName: labeledSpellName,
                    spellbookIndex,
                    appearance: game._object_descriptions?.spellbooks?.[spellbookIndex] || qualifiers.wishLabelName,
                    known: spellbookDiscoveryKnown(labeledSpellName),
                    wishedfor: true,
                });
            }
            if (/^spell\s*books?$/.test(lowerName)) return makeWishedObjectClassObject(SPBOOK_CLASS);
        }
        const spellbookIndex = spellbookNames.indexOf(spellName);
        const namedescBound = WISH_SPELLBOOK_NAMEDESC_BOUNDS.get(spellName);
        if (namedescBound) rn2(namedescBound);
        const otmp = mksobj(SPBOOK_NO_NOVEL, true, false);
        return Object.assign(otmp, {
            cls: 'spellbook',
            glyph: '+',
            kind: spellbookIndex >= 0 ? `spellbook of ${spellName}` : lowerName,
            spellName: spellbookIndex >= 0 ? spellName : '',
            spellbookIndex,
            appearance: spellbookIndex >= 0 ? game._object_descriptions?.spellbooks?.[spellbookIndex] : '',
            known: spellbookIndex >= 0 && spellbookDiscoveryKnown(spellName),
            wishedfor: true,
        });
    }

    if (/armor|mail|helm|gauntlets?|gloves|boots|cloak|shirt|robe|shield/.test(lowerName)) {
        const namedescBound = WISH_BASE_NAMEDESC_BOUNDS.get(lowerName);
        if (namedescBound && !spellingAlias.skipNamedesc) rn2(namedescBound);
        const otmp = mksobj(ARMOR_CLASS, true, false);
        const armorAppearance = ARMOR_WISH_APPEARANCES[lowerName];
        const [group, index, fallback] = armorAppearance || [];
        return Object.assign(otmp, {
            cls: 'armor',
            glyph: '[',
            kind: lowerName,
            actualKind: lowerName,
            appearance: armorAppearance ? game._object_descriptions?.[group]?.[index] || fallback : '',
            known: false,
            wishedfor: true,
        });
    }

    if (isWishedFoodName(lowerName)) {
        const namedescBound = WISH_FOOD_NAMEDESC_BOUNDS.get(lowerName);
        if (namedescBound) rn2(namedescBound);
        const otmp = mksobj(FOOD_CLASS, true, false);
        return Object.assign(otmp, { cls: 'food', glyph: '%', kind: lowerName, wishedfor: true });
    }
    if (lowerName === 'wall' || lowerName.endsWith(' wall')) return noFittingWishObject();
    if (/gem|stone|rock/.test(lowerName)) {
        const otmp = mksobj(GEM_CLASS, false, false);
        return Object.assign(otmp, { cls: 'gem', glyph: '*', gemDescription: lowerName, actualKind: lowerName, wishedfor: true });
    }
    if (/lamp|chest|camera|bag|sack|tool|marker|card|bell|harp|leash|blindfold|towel|lenses|flute|horn|whistle|drum|saddle|grease|figurine|tin opener|crystal ball/.test(lowerName)) {
        const namedescBound = WISH_TOOL_NAMEDESC_BOUNDS.get(lowerName);
        if (namedescBound) rn2(namedescBound);
        const toolRoll = WISH_TOOL_ROLLS.get(lowerName);
        if (toolRoll) game._mkobj_tool_roll = toolRoll;
        const otmp = mksobj(TOOL_CLASS, true, false);
        const appearance = WISH_TOOL_APPEARANCES.get(lowerName);
        const explicitOtyp = WISH_TOOL_OTYPES.get(lowerName);
        if (explicitOtyp != null) otmp.otyp = explicitOtyp;
        return Object.assign(otmp, {
            cls: 'tool',
            glyph: '(',
            kind: appearance || lowerName,
            actualKind: lowerName,
            known: !appearance,
            wishedfor: true,
        });
    }
    return noFittingWishObject();
}

function setOverlay(lines, clearRows = 24, hideStatus = false, clearCol = null) {
    game._overlay_lines = lines;
    game._overlay_clear_rows = clearRows;
    game._overlay_hide_status = hideStatus;
    game._overlay_hide_status_only = 0;
    game._overlay_clear_col = clearCol;
    game._overlay_cursor = null;
    game._pending_message = '';
    game._message_more = 0;
}

const DATA_FILE_CACHE = {};

function dataFileLines(name) {
    if (name === 'generated-options') {
        return GENERATED_OPTIONS_HELP_LINES;
    }
    if (name === 'full-key-bindings') return FULL_KEY_BINDINGS_LINES;
    if (name === 'menu-control-help') return MENU_CONTROL_HELP_LINES;
    if (name === 'support-info') return SUPPORT_INFO_LINES;
    if (!DATA_FILE_CACHE[name]) DATA_FILE_CACHE[name] = bundledDatFileLines(name);
    return DATA_FILE_CACHE[name];
}

function dataPagerLines(name, page) {
    const lines = dataFileLines(name);
    const start = page * 23;
    const rows = lines.slice(start, start + 23).map((line, row) => [row, 0, line]);
    rows.push([23, 0, '--More--']);
    return rows;
}

function maybeWishedInstanceName(obj, baseName) {
    const objectName = String(obj?._wish_object_name || obj?.oname || '').trim();
    const name = String(baseName || '');
    if (!objectName || obj?.artifact || / named .+$/i.test(name)) return name;
    return `${name} named ${objectName}`;
}

function isSlimeMoldObject(obj) {
    return obj?.otyp === SLIME_MOLD || String(obj?.actualKind || '').toLowerCase() === 'slime mold';
}

export function pickupObjectName(obj) {
    const named = name => maybeWishedInstanceName(obj, name);
    const archeologist = (game.urole?.name?.m || game._startup_role) === 'Archeologist';
    if (obj.otyp === GOLD_PIECE || obj.cls === 'coin' || obj.glyph === '$')
        return (obj.quan || 1) > 1 ? 'gold pieces' : 'gold piece';
    if (isBoulderObject(obj)) return named((obj.quan || 1) > 1 ? 'boulders' : 'boulder');
    if (obj.artifact) return artifactObjectName(obj) || obj.kind;
    if (obj.otyp === 'corpse' || obj.otyp === CORPSE) return corpseObjectName(obj);
    if (isEggItem(obj)) return named(eggObjectName(obj));
    if (obj.globby) return named(globObjectName(obj));
    if (isSlimeMoldObject(obj))
        return named(slimeMoldNameForObject(obj, (obj.quan || 1) > 1));
    if ((obj.kind === 'statue' || obj.otyp === STATUE) && obj.corpsenm?.name) {
        const historic = archeologist && (((obj.spe || 0) & CORPSTAT_HISTORIC) || obj.historic);
        return named(`${historic ? 'historic ' : ''}statue of ${corpstatMonsterIndefiniteName(obj)}`);
    }
    if ((obj.kind === 'figurine' || obj.actualKind === 'figurine') && obj.corpsenm?.name)
        return named(`figurine of ${corpstatMonsterIndefiniteName(obj)}`);
    if (isTinObject(obj)) return named(tinObjectName(obj));
    if (obj.otyp === LARGE_BOX) return named('large box');
    if (obj.otyp === CHEST) return named('chest');
    if (obj.otyp === ICE_BOX) return named('ice box');
    if (BAG_OBJECT_TYPES.has(obj.otyp)) return named(obj.contents?.length || !obj.cknown ? 'bag' : 'empty bag');
    if (obj.otyp === OIL_LAMP || obj.otyp === MAGIC_LAMP) return named(maybeLitObjectName(obj, 'lamp'));
    if (obj.otyp === BRASS_LANTERN) return named(maybeLitObjectName(obj, 'brass lantern'));
    if (obj.otyp === TALLOW_CANDLE || obj.otyp === WAX_CANDLE) {
        const name = obj.kind || (obj.otyp === WAX_CANDLE ? 'wax candle' : 'tallow candle');
        return named(maybeLitObjectName(obj, (obj.quan || 1) > 1 ? obj.plural || `${name}s` : name));
    }
    if (obj.otyp === SCROLL_CLASS || obj.cls === 'scroll' || obj.otyp === SCR_SCARE_MONSTER) {
        if ((obj.quan || 1) > 1 && obj.plural) return named(obj.plural);
        const scrollIndex = obj.scrollIndex ?? (obj.otyp === SCR_SCARE_MONSTER ? 3 : undefined);
        const blankScroll = obj.otyp === SCR_BLANK_PAPER || scrollIndex === 21
            || obj.kind === 'blank paper' || (scrollIndex == null && !obj.kind);
        if (blankScroll) {
            if (obj.known === true || obj.actualKind === 'scroll of blank paper')
                return named((obj.quan || 1) > 1 ? 'scrolls of blank paper' : 'scroll of blank paper');
            return named((obj.quan || 1) > 1 ? 'unlabeled scrolls' : 'unlabeled scroll');
        }
        if (obj.kind?.startsWith?.('scroll:')) {
            const name = obj.kind.slice(7);
            return named((obj.quan || 1) > 1 ? `scrolls of ${name}` : obj.singular || `scroll of ${name}`);
        }
        if (obj.kind?.startsWith?.('scroll labeled ')) {
            const label = obj.kind.slice('scroll labeled '.length);
            return named((obj.quan || 1) > 1 ? `scrolls labeled ${label}` : obj.kind);
        }
        if (obj.kind === 'stamped scroll') return named((obj.quan || 1) > 1 ? 'stamped scrolls' : obj.kind);
        if (obj.kind) {
            const name = obj.kind.replace(/^scroll of /, '');
            return named((obj.quan || 1) > 1 ? `scrolls of ${name}` : `scroll of ${name}`);
        }
        const label = game._object_descriptions?.scrolls?.[scrollIndex] || 'ZELGO MER';
        return named((obj.quan || 1) > 1 ? `scrolls labeled ${label}` : `scroll labeled ${label}`);
    }
    if (obj.otyp === POTION_CLASS || obj.cls === 'potion') {
        if ((obj.quan || 1) > 1 && obj.plural) return named(obj.plural);
        if (obj.kind?.startsWith?.('potion:')) return named(maybeLitObjectName(obj, maybeDilutedPotionName(obj, obj.singular || `potion of ${obj.kind.slice(7)}`)));
        const rawKind = String(obj.kind || '').replace(/^potion of /, '');
        if (rawKind === 'water' && (obj.blessed || obj.cursed)) {
            const kind = obj.blessed ? 'holy water' : 'unholy water';
            return named((obj.quan || 1) > 1 ? `potions of ${kind}` : `potion of ${kind}`);
        }
        if (obj.kind === 'holy water' || obj.kind === 'unholy water')
            return named((obj.quan || 1) > 1 ? `potions of ${obj.kind}` : `potion of ${obj.kind}`);
        if (obj.kind?.endsWith?.(' potion')) return named(maybeLitObjectName(obj, maybeDilutedPotionName(obj, obj.kind)));
        if (obj.kind) {
            const name = obj.kind.replace(/^potion of /, '');
            return named(maybeLitObjectName(obj, maybeDilutedPotionName(obj, (obj.quan || 1) > 1 ? `potions of ${name}` : `potion of ${name}`)));
        }
        const appearance = game._object_descriptions?.potions?.[obj.potionIndex]?.description || 'clear';
        return named(maybeLitObjectName(obj, maybeDilutedPotionName(obj, `${appearance} potion`)));
    }
    if (obj.otyp === WAND_CLASS || obj.cls === 'wand') {
        if (obj.known === false) {
            const appearance = obj.appearance || game._object_descriptions?.wands?.[obj.wandIndex]?.description;
            return named(appearance ? `${appearance} wand` : 'wand');
        }
        if (obj.wand === 'sleep' || obj.wandIndex === 22) return named('wand of sleep');
        if (obj.kind && obj.kind !== 'sleep') return named(obj.kind.startsWith('wand') ? obj.kind : `wand of ${obj.kind}`);
        const appearance = game._object_descriptions?.wands?.[obj.wandIndex]?.description;
        return named(appearance ? `${appearance} wand` : 'wand');
    }
    if (obj.cls === 'spellbook' || obj.otyp === SPBOOK_NO_NOVEL || obj.otyp === SPE_HEALING || obj.otyp === BOOK_OF_THE_DEAD) {
        if (isBookOfTheDeadItem(obj)) return named('Book of the Dead');
        if ((obj.quan || 1) > 1 && obj.plural) return named(obj.plural);
        const name = obj.spellName || obj.spell?.name || String(obj.kind || '').replace(/^spellbook(?: of)? /, '');
        const typeKnown = obj.known === true || spellbookDiscoveryKnown(name);
        if (!typeKnown || (obj.otyp === SPE_HEALING && !obj.cls) || (obj.otyp === SPBOOK_NO_NOVEL && !name)) {
            const appearance = obj.appearance || game._object_descriptions?.spellbooks?.[
                obj.spellbookIndex ?? HEALING_SPELLBOOK_APPEARANCE_INDEX
            ];
            if (appearance) return named(`${appearance} spellbook`);
        }
        if (!name) return named('spellbook');
        return named((obj.quan || 1) > 1 ? `spellbooks of ${name}` : `spellbook of ${name}`);
    }
    if (obj.glyph === '=' || obj.cls === 'ring') {
        if (typeof obj.kind !== 'string')
            return named(`${game._object_descriptions?.rings?.[(obj.ringRoll || 1) - 1] || 'ruby'} ring`);
        return named(obj.kind);
    }
    if (obj.fakeAmuletOfYendor) return obj.known ? obj.actualKind : 'Amulet of Yendor';
    if (obj.realAmuletOfYendor) return 'Amulet of Yendor';
    if (obj.otyp === AMULET_CLASS || obj.cls === 'amulet') {
        if (obj.known === false || !obj.kind) {
            const appearance = obj.appearance || game._object_descriptions?.amulets?.[obj.amuletIndex] || 'amulet';
            return named(`${appearance} amulet`);
        }
        return named(obj.kind || 'amulet');
    }
    if (obj.cls === 'armor') {
        const kind = String(obj.actualKind || obj.kind || '').toLowerCase();
        const armorAppearance = ARMOR_WISH_APPEARANCES[kind];
        const typeKnown = obj.known === true
            || !armorAppearance
            || (game._discoveries || []).some(entry => {
                if (entry.section !== 'Armor') return false;
                const discoveredName = entry.name.toLowerCase().replace(/^pair of /, '');
                return discoveredName === kind && (entry.starred || discoveredName === 'leather gloves');
            });
        if (!typeKnown && (obj.appearance || armorAppearance)) {
            const [group, index, fallback] = armorAppearance || [];
            return named(obj.appearance || game._object_descriptions?.[group]?.[index] || fallback);
        }
        return named(obj.kind || 'armor');
    }
    if (obj.otyp === MIRROR) return named('looking glass');
    if (obj.otyp === DART || obj.kind === 'dart') {
        const poisoned = obj.opoisoned ? 'poisoned ' : '';
        return named((obj.quan || 1) > 1 ? `${poisoned}darts` : `${poisoned}dart`);
    }
    if (obj.cls === 'weapon' || obj.otyp === WEAPON_CLASS || obj.glyph === ')') {
        const actualKind = String(obj.actualKind || '').toLowerCase();
        const rawKind = String(obj.kind || '').toLowerCase();
        const kind = actualKind || rawKind;
        const displayKind = obj.known === false && rawKind && rawKind !== actualKind ? rawKind : kind;
        const poisoned = obj.opoisoned && isPoisonableWeaponObject(obj) ? 'poisoned ' : '';
        if (kind === 'orcish dagger' || obj.otyp === ORCISH_DAGGER) {
            const known = obj.known === true || (game._discoveries || [])
                .some(entry => entry.section === 'Weapons' && entry.name === 'orcish dagger' && entry.starred);
            if (known) return named((obj.quan || 1) > 1 ? `${poisoned}orcish daggers` : `${poisoned}orcish dagger`);
            return named((obj.quan || 1) > 1 ? `${poisoned}crude daggers` : `${poisoned}crude dagger`);
        }
        if ((obj.quan || 1) > 1 && displayKind) {
            const plural = {
                knife: 'knives',
                stiletto: 'stilettos',
                ya: 'ya',
                'crossbow bolt': 'crossbow bolts',
                shuriken: 'shuriken',
            }[displayKind] || (displayKind.endsWith('s') ? displayKind : `${displayKind}s`);
            return named(`${poisoned}${plural}`);
        }
        if (displayKind) return named(`${poisoned}${displayKind}`);
    }
    if (obj.otyp === FOOD_CLASS || obj.cls === 'food') {
        const buc = foodBucPrefix(obj);
        if ((obj.quan || 1) > 1 && obj.plural) return named(`${buc}${maybePartlyEatenFoodName(obj, obj.plural)}`);
        if ((obj.quan || 1) > 1 && obj.kind === 'food ration') return named(`${buc}${maybePartlyEatenFoodName(obj, 'food rations')}`);
        if ((obj.quan || 1) > 1 && obj.kind === 'cram ration') return named(`${buc}${maybePartlyEatenFoodName(obj, 'cram rations')}`);
        if (obj.kind === 'tripe') return named(`${buc}${maybePartlyEatenFoodName(obj, (obj.quan || 1) > 1 ? 'tripe rations' : 'tripe ration')}`);
        if (obj.kind?.startsWith?.('tin:')) return named(`${buc}${maybePartlyEatenFoodName(obj, obj.singular || 'tin')}`);
        if (obj.kind) return named(`${buc}${maybePartlyEatenFoodName(obj, obj.kind)}`);
        if ((obj.foodRoll || 1000) <= 140) return named(`${buc}${maybePartlyEatenFoodName(obj, 'tripe ration')}`);
        return named(`${buc}${maybePartlyEatenFoodName(obj, 'food ration')}`);
    }
    if (obj.otyp === GEM_CLASS) {
        const name = obj.gemDescription || 'white gem';
        return named((obj.quan || 1) > 1 ? `${name}s` : name);
    }
    if ((obj.quan || 1) > 1 && obj.plural) return named(obj.plural);
    return named(obj.kind || (obj.otyp != null ? String(obj.otyp) : 'object'));
}

function containerSortRank(item) {
    if (item.otyp === GOLD_PIECE || item.cls === 'coin' || item.glyph === '$') return 0;
    if (item.otyp === SCROLL_CLASS || item.cls === 'scroll' || item.glyph === '?') return 1;
    if (item.cls === 'spellbook' || item.glyph === '+') return 2;
    if (item.otyp === GEM_CLASS || item.cls === 'gem' || item.glyph === '*') return 3;
    return 4;
}

function containerLootSortKey(item) {
    return pickupObjectName({ ...item, quan: 1 }).toLowerCase();
}

function compareContainerLootItems(a, b) {
    return containerSortRank(a) - containerSortRank(b)
        || containerLootSortKey(a).localeCompare(containerLootSortKey(b));
}

function isIceBoxObject(obj) {
    return !!obj && (obj.otyp === ICE_BOX || obj.kind === 'ice box' || objectKindKey(obj) === 'ice box');
}

function iceBoxPutClassTypes() {
    return [...BAG_PUT_CLASS_TYPES, { key: 'other', label: 'Other Items', symbol: '*' }];
}

function iceBoxPutCategory(item) {
    if (item.otyp === GOLD_PIECE || item.cls === 'coin' || item.glyph === '$') return 'coin';
    if (item.cls === 'amulet' || item.otyp === AMULET_CLASS || item.glyph === '"') return 'amulet';
    if (item.cls === 'weapon' || item.otyp === WEAPON_CLASS || item.glyph === ')') return 'weapon';
    if (item.cls === 'armor' || item.otyp === ARMOR_CLASS || item.glyph === '[') return 'armor';
    if (item.otyp === 'corpse' || item.otyp === CORPSE || item.otyp === FOOD_CLASS || item.cls === 'food' || item.glyph === '%') return 'food';
    if (item.otyp === SCROLL_CLASS || item.cls === 'scroll' || item.glyph === '?') return 'scroll';
    if (item.otyp === SPBOOK_NO_NOVEL || item.cls === 'spellbook' || item.glyph === '+') return 'spellbook';
    if (item.otyp === POTION_CLASS || item.cls === 'potion' || item.glyph === '!') return 'potion';
    if (item.otyp === RING_CLASS || item.cls === 'ring' || item.glyph === '=') return 'ring';
    if (item.otyp === WAND_CLASS || item.cls === 'wand' || item.glyph === '/') return 'wand';
    if (item.otyp === GEM_CLASS || item.cls === 'gem' || item.glyph === '*') return 'gem';
    if (item.otyp === BOULDER || item.otyp === STATUE || item.cls === 'rock' || item.glyph === '`') return 'rock';
    if (item === game.u?.uball || item.cls === 'ball' || item.glyph === '0') return 'ball';
    if (item === game.u?.uchain || item.cls === 'chain' || item.glyph === '_') return 'chain';
    if (BAG_OBJECT_TYPES.has(item.otyp) || item.otyp === ICE_BOX || item.otyp === OIL_LAMP || item.otyp === MAGIC_LAMP
        || item.otyp === MIRROR || item.otyp === EXPENSIVE_CAMERA || item.otyp === STETHOSCOPE
        || item.otyp === MAGIC_MARKER || item.cls === 'tool' || item.glyph === '(') return 'tool';
    return 'other';
}

function buildIceBoxPutItems(iceBox = null) {
    const putItems = [];
    if (game._goldCount) {
        putItems.push({
            item: { letter: '$', cls: 'coin', otyp: GOLD_PIECE, glyph: '$', quan: game._goldCount },
            category: 'coin',
        });
    }
    for (const item of game.inventory || []) {
        if (item.letter === '$' || item.cls === 'coin' || item.glyph === '$') continue;
        if (item === iceBox) continue;
        putItems.push({ item, category: iceBoxPutCategory(item) });
    }
    return putItems;
}

function iceBoxPutLetters(iceBox = null) {
    const letters = [];
    if (game._goldCount) letters.push('$');
    for (const item of game.inventory || []) {
        if (item.letter === '$' || item.cls === 'coin' || item.glyph === '$') continue;
        if (item === iceBox) continue;
        if (item.letter) letters.push(item.letter);
    }
    return letters.join('');
}

function buildContainerPutItems(container = null) {
    const putItems = [];
    if (game._goldCount) {
        putItems.push({
            item: { letter: '$', cls: 'coin', otyp: GOLD_PIECE, glyph: '$', quan: game._goldCount },
            category: 'coin',
        });
    }
    for (const item of game.inventory || []) {
        if (item.letter === '$' || item.cls === 'coin' || item.glyph === '$') continue;
        if (item === container) continue;
        putItems.push({ item, category: iceBoxPutCategory(item) });
    }
    return putItems;
}

function containerPutLetters(container = null) {
    const letters = [];
    if (game._goldCount) letters.push('$');
    for (const { item } of buildContainerPutItems(container)) {
        if (item.letter && item.letter !== '$') letters.push(item.letter);
    }
    return letters.join('');
}

function clearIceBoxPutState() {
    game._icebox_put_container = null;
    game._icebox_put_type_choices = null;
    game._icebox_put_type_selected = null;
    game._icebox_put_items = null;
    game._icebox_put_entries = null;
    game._icebox_put_selected = null;
    game._icebox_stash_letters = null;
    game._overlay_lines = null;
    game._overlay_hide_status = 0;
}

function clearContainerPutState() {
    game._container_put_container = null;
    game._container_put_type_choices = null;
    game._container_put_type_selected = null;
    game._container_put_items = null;
    game._container_put_entries = null;
    game._container_put_selected = null;
    game._container_stash_letters = null;
    game._overlay_lines = null;
    game._overlay_hide_status = 0;
}

function clearContainerTakeoutState() {
    game._loot_takeout_container = null;
    game._loot_takeout_entries = null;
    game._loot_takeout_selected = null;
    game._loot_takeout_clear_col = null;
    game._loot_takeout_type_entries = null;
    game._loot_takeout_types_selected = null;
}

function clearIceBoxSequenceState() {
    game._icebox_sequence_after_takeout = null;
    game._icebox_sequence_after_putin = null;
    game._icebox_sequence_used = 0;
    game._icebox_sequence_messages = null;
}

function clearContainerSequenceState() {
    game._container_sequence_after_takeout = null;
    game._container_sequence_after_putin = null;
    game._container_sequence_used = 0;
    game._container_sequence_messages = null;
}

function lootTrapContainerCandidate(container) {
    return !!(container?.otrapped
        && (container.kind === 'chest' || container.otyp === CHEST
            || container.kind === 'large box' || container.otyp === LARGE_BOX));
}

async function triggerLootChestTrap(container) {
    if (!lootTrapContainerCandidate(container)) return false;
    container.lknown = true;
    const result = applyChestTrapPayload(container, { disarm: false });
    game._floor_container_object = null;
    clearContainerTakeoutState();
    clearContainerPutState();
    clearContainerSequenceState();
    game._overlay_lines = null;
    game._overlay_hide_status = 0;
    game._command_mode = null;
    const objectResult = result && typeof result === 'object';
    await setMessage(objectResult ? result.message : result, !!(objectResult && result.more));
    if (objectResult && applyLifeSavingOrFatalCommandMode(result)) return true;
    game.context ??= {};
    game.context.move = 1;
    return true;
}

function startIceBoxSequence(nextAction) {
    clearIceBoxSequenceState();
    if (nextAction === 'putin') game._icebox_sequence_after_takeout = 'putin';
    else if (nextAction === 'takeout') game._icebox_sequence_after_putin = 'takeout';
    game._icebox_sequence_messages = [];
}

function startContainerSequence(nextAction) {
    clearContainerSequenceState();
    if (nextAction === 'putin') game._container_sequence_after_takeout = 'putin';
    else if (nextAction === 'takeout') game._container_sequence_after_putin = 'takeout';
    game._container_sequence_messages = [];
}

function iceBoxSequenceActive() {
    return !!(game._icebox_sequence_after_takeout || game._icebox_sequence_after_putin);
}

function containerSequenceActive() {
    return !!(game._container_sequence_after_takeout || game._container_sequence_after_putin);
}

function markIceBoxSequenceUsed(used = true) {
    if (used) game._icebox_sequence_used = 1;
}

function markContainerSequenceUsed(used = true) {
    if (used) game._container_sequence_used = 1;
}

function addIceBoxSequenceMessages(messages) {
    const list = Array.isArray(messages) ? messages : [messages];
    game._icebox_sequence_messages ??= [];
    for (const message of list) {
        if (message) game._icebox_sequence_messages.push(message);
    }
}

function addContainerSequenceMessages(messages) {
    const list = Array.isArray(messages) ? messages : [messages];
    game._container_sequence_messages ??= [];
    for (const message of list) {
        if (message) game._container_sequence_messages.push(message);
    }
}

function iceBoxEmptyMessage() {
    return 'The ice box is empty.';
}

function iceBoxIsOnHeroFloor(iceBox) {
    return !!(iceBox && (game.level?.objects || []).includes(iceBox)
        && iceBox.ox === game.u?.ux && iceBox.oy === game.u?.uy);
}

function iceBoxIsCarried(iceBox) {
    return !!(iceBox && (game.inventory || []).includes(iceBox));
}

function iceBoxContainerAvailable(iceBox) {
    return iceBoxIsOnHeroFloor(iceBox) || iceBoxIsCarried(iceBox);
}

function setIceBoxActionMenu(iceBox, done = false) {
    game._icebox_action_container = iceBox || null;
    setOverlay(done ? LOOT_ICE_MENU_DONE_LINES : LOOT_ICE_MENU_LINES, 11);
    game._command_mode = 'iceBoxAction';
}

function clearIceBoxActionState() {
    game._icebox_action_container = null;
}

function iceBoxPutTypeChoices(putItems) {
    const classTypes = iceBoxPutClassTypes();
    const presentTypes = classTypes.filter(type => putItems.some(entry => entry.category === type.key));
    const choices = [{ key: 'auto', letter: 'A', label: 'Auto-select every relevant item' }];
    if (presentTypes.length > 1) choices.push({ key: 'all', letter: 'a', label: 'All types', row: 5 });
    let row = presentTypes.length > 1 ? 6 : 5;
    let letterIndex = presentTypes.length > 1 ? 1 : 0;
    for (const type of presentTypes) {
        const letter = 'abcdefghijklmnopqrstuvwxyz'[letterIndex++];
        choices.push({ ...type, letter, row: row++ });
    }
    const extraChoices = [];
    if (putItems.some(({ item }) => objectBucCategory(item) === 'blessed'))
        extraChoices.push({ key: 'blessed', letter: 'B', label: 'Items known to be Blessed' });
    if (putItems.some(({ item }) => objectBucCategory(item) === 'cursed'))
        extraChoices.push({ key: 'cursed', letter: 'C', label: 'Items known to be Cursed' });
    if (putItems.some(({ item }) => objectBucCategory(item) === 'uncursed'))
        extraChoices.push({ key: 'uncursed', letter: 'U', label: 'Items known to be Uncursed' });
    if (putItems.some(({ item }) => objectBucCategory(item) === 'unknown'))
        extraChoices.push({ key: 'unknown', letter: 'X', label: 'Items of unknown Bless/Curse status' });
    if (game._just_picked_gold && game._goldCount)
        extraChoices.push({
            key: 'justpicked',
            letter: 'P',
            label: `Just picked up: ${game._goldCount} gold piece${game._goldCount === 1 ? '' : 's'}`,
        });
    if (extraChoices.length) row++;
    for (const choice of extraChoices) choices.push({ ...choice, row: row++ });
    return choices;
}

function containerPutTypeChoices(putItems) {
    return iceBoxPutTypeChoices(putItems);
}

function drawIceBoxPutTypeMenu() {
    const choices = game._icebox_put_type_choices || [];
    const selected = new Set(game._icebox_put_type_selected || []);
    const rows = [
        [0, 23, 'Put in what type of objects?', 1],
        [2, 23, `A ${selected.has('auto') ? '+' : '-'} Auto-select every relevant item`],
        [3, 27, '(ignored unless some other choices are also picked)'],
    ];
    for (const choice of choices) {
        if (!choice.row) continue;
        rows.push([choice.row, 23, `${choice.letter} ${selected.has(choice.key) ? '+' : '-'} ${choice.label}`]);
    }
    const endRow = Math.max(4, ...choices.map(choice => choice.row || 0)) + 1;
    rows.push([endRow, 23, '(end)']);
    setOverlay(rows, endRow + 1, false, 23);
}

function drawContainerPutTypeMenu() {
    const choices = game._container_put_type_choices || [];
    const selected = new Set(game._container_put_type_selected || []);
    const rows = [
        [0, 23, 'Put in what type of objects?', 1],
        [2, 23, `A ${selected.has('auto') ? '+' : '-'} Auto-select every relevant item`],
        [3, 27, '(ignored unless some other choices are also picked)'],
    ];
    for (const choice of choices) {
        if (!choice.row) continue;
        rows.push([choice.row, 23, `${choice.letter} ${selected.has(choice.key) ? '+' : '-'} ${choice.label}`]);
    }
    const endRow = Math.max(4, ...choices.map(choice => choice.row || 0)) + 1;
    rows.push([endRow, 23, '(end)']);
    setOverlay(rows, endRow + 1, false, 23);
}

function beginIceBoxPutIn(iceBox) {
    const putItems = buildIceBoxPutItems(iceBox);
    if (!putItems.length) return false;
    game._icebox_put_container = iceBox;
    game._icebox_put_items = putItems;
    game._icebox_put_type_choices = iceBoxPutTypeChoices(putItems);
    game._icebox_put_type_selected = [];
    drawIceBoxPutTypeMenu();
    game._command_mode = 'iceBoxPutTypes';
    return true;
}

function beginContainerPutIn(container) {
    const putItems = buildContainerPutItems(container);
    if (!putItems.length) return false;
    game._container_put_container = container;
    game._container_put_items = putItems;
    game._container_put_type_choices = containerPutTypeChoices(putItems);
    game._container_put_type_selected = [];
    drawContainerPutTypeMenu();
    game._command_mode = 'containerPutTypes';
    return true;
}

function drawIceBoxPutObjectMenu() {
    const entries = game._icebox_put_entries || [];
    const selected = new Set(game._icebox_put_selected || []);
    const rows = [[0, 41, 'Put in what?', 1]];
    let row = 2;
    let lastCategory = '';
    for (const entry of entries) {
        if (entry.category !== lastCategory) {
            const type = iceBoxPutClassTypes().find(type => type.key === entry.category);
            rows.push([row, 34, '┌─────']);
            rows.push([row, 40, ' '.repeat(40)]);
            rows.push([row++, 41, type?.label || 'Other Items', 1]);
            lastCategory = entry.category;
        }
        entry.row = row;
        const label = entry.letter === '$'
            ? `${entry.amount} gold piece${entry.amount === 1 ? '' : 's'}`
            : inventoryItemName(entry.item);
        rows.push([row, 34, '│']);
        rows.push([row++, 40, ` ${entry.letter} ${selected.has(entry.letter) ? '+' : '-'} ${label}`.padEnd(40, ' ')]);
    }
    rows.push([row, 34, '│']);
    rows.push([row, 40, ' (end)'.padEnd(40, ' ')]);
    setOverlay(rows, 2, false, 0);
}

function drawContainerPutObjectMenu() {
    const entries = game._container_put_entries || [];
    const selected = new Set(game._container_put_selected || []);
    const rows = [[0, 41, 'Put in what?', 1]];
    let row = 2;
    let lastCategory = '';
    for (const entry of entries) {
        if (entry.category !== lastCategory) {
            const type = iceBoxPutClassTypes().find(type => type.key === entry.category);
            rows.push([row, 34, '┌─────']);
            rows.push([row, 40, ' '.repeat(40)]);
            rows.push([row++, 41, type?.label || 'Other Items', 1]);
            lastCategory = entry.category;
        }
        entry.row = row;
        const label = entry.letter === '$'
            ? `${entry.amount} gold piece${entry.amount === 1 ? '' : 's'}`
            : inventoryItemName(entry.item);
        rows.push([row, 34, '│']);
        rows.push([row++, 40, ` ${entry.letter} ${selected.has(entry.letter) ? '+' : '-'} ${label}`.padEnd(40, ' ')]);
    }
    rows.push([row, 34, '│']);
    rows.push([row, 40, ' (end)'.padEnd(40, ' ')]);
    setOverlay(rows, 2, false, 0);
}

function articlelessObjectName(item) {
    return pickupObjectName(item).replace(/^(?:an? |the )/i, '');
}

function iceBoxPutRejectMessage(iceBox, item) {
    if (!item) return "You don't have that object.";
    if (item === game.u?.uball || item === game.u?.uchain) return 'You must be kidding.';
    if (item === iceBox) return 'That would be an interesting topological exercise.';
    if (isWornInventoryItem(item)) return 'You cannot refrigerate something you are wearing.';
    const kind = objectKindKey(item);
    if ((item.otyp === LOADSTONE || kind === 'loadstone') && item.cursed) {
        item.bknown = true;
        return `The stone${(item.quan || 1) === 1 ? '' : 's'} won't leave your person.`;
    }
    const actual = String(item.actualKind || '').toLowerCase();
    if (item.realAmuletOfYendor || actual === 'amulet of yendor' || (!actual && kind === 'amulet of yendor')
        || isBookOfTheDeadItem(item) || isBellOfOpeningItem(item) || isCandelabrumOfInvocationItem(item))
        return `The ${articlelessObjectName(item)} cannot be confined in such trappings.`;
    if (kind === 'leash' && item.leashmon) return 'The leash is attached to your pet.';
    const boxLike = isIceBoxObject(item) || item.otyp === CHEST || item.otyp === LARGE_BOX
        || kind === 'chest' || kind === 'large box';
    const bigStatue = item.otyp === STATUE
        && (item.big || item.bigStatue || item.large || item.corpsenm?.msize === 'large' || item.corpsenm?.size === 'large');
    if (boxLike || item.otyp === BOULDER || kind === 'boulder' || bigStatue)
        return `You cannot fit the ${articlelessObjectName(item)} into the ice box.`;
    return '';
}

function containerPutRejectMessage(container, item) {
    if (!item) return "You don't have that object.";
    if (isIceBoxObject(container)) return iceBoxPutRejectMessage(container, item);
    if (item === game.u?.uball || item === game.u?.uchain) return 'You must be kidding.';
    if (item === container) return 'That would be an interesting topological exercise.';
    if (isWornInventoryItem(item)) return 'You cannot stash something you are wearing.';
    const kind = objectKindKey(item);
    if ((item.otyp === LOADSTONE || kind === 'loadstone') && item.cursed) {
        item.bknown = true;
        return `The stone${(item.quan || 1) === 1 ? '' : 's'} won't leave your person.`;
    }
    const actual = String(item.actualKind || '').toLowerCase();
    if (item.realAmuletOfYendor || actual === 'amulet of yendor' || (!actual && kind === 'amulet of yendor')
        || isBookOfTheDeadItem(item) || isBellOfOpeningItem(item) || isCandelabrumOfInvocationItem(item))
        return `The ${articlelessObjectName(item)} cannot be confined in such trappings.`;
    if (kind === 'leash' && item.leashmon) return 'The leash is attached to your pet.';
    const boxLike = isIceBoxObject(item) || item.otyp === CHEST || item.otyp === LARGE_BOX
        || kind === 'chest' || kind === 'large box';
    const bigStatue = item.otyp === STATUE
        && (item.big || item.bigStatue || item.large || item.corpsenm?.msize === 'large' || item.corpsenm?.size === 'large');
    if (boxLike || item.otyp === BOULDER || kind === 'boulder' || bigStatue)
        return `You cannot fit the ${articlelessObjectName(item)} into the ${tipContainerSimpleName(container)}.`;
    return '';
}

function clearContainerPutEquipmentState(item, name) {
    const line = String(item.line || '');
    if (item.wielded || /(?:weapon|wielded) in/.test(line) || line.includes('(wielded)')) {
        item.wielded = false;
        if (item.artifact === 'Mjollnir' || item.kind === 'mjollnir') game._wielded_mjollnir = false;
    }
    if (item.alternate || line.includes('alternate weapon')) item.alternate = false;
    if (item.quivered || /at the ready|in quiver/.test(line)) item.quivered = false;
    if (item.line) item.line = `${item.letter || '?'} - ${name}`;
}

function putInventoryObjectIntoIceBox(iceBox, item, amount = item?.quan || 1, options = {}) {
    if (!iceBoxContainerAvailable(iceBox)) return { moved: false, message: '' };
    iceBox.contents ??= [];
    iceBox.cknown = true;
    if (item?.letter === '$' || item?.otyp === GOLD_PIECE || item?.cls === 'coin' || item?.glyph === '$') {
        const gold = Math.min(Math.max(0, amount || 0), game._goldCount || 0);
        if (!gold) return { moved: false, message: 'You have no gold to put in.' };
        const shopGold = donateShopGoldAt(iceBox, gold);
        add_to_container(iceBox, { letter: '$', cls: 'coin', otyp: GOLD_PIECE, glyph: '$', quan: gold });
        game._goldCount = Math.max(0, (game._goldCount || 0) - gold);
        game._just_picked_gold = Math.max(0, (game._just_picked_gold || 0) - gold);
        const money = (game.inventory || []).find(invItem => invItem.letter === '$' || invItem.cls === 'coin');
        if (money && game._goldCount) {
            money.quan = game._goldCount;
            updateMoneyLine(money);
        } else {
            game.inventory = (game.inventory || []).filter(invItem => invItem.letter !== '$' && invItem.cls !== 'coin');
        }
        game._pet_food_scan_inventory = game.inventory;
        const messages = [`You put ${gold} gold piece${gold === 1 ? '' : 's'} into the ice box.`, ...(shopGold.messages || [])];
        return { moved: true, message: messages.join('  '), messages };
    }

    const reject = iceBoxPutRejectMessage(iceBox, item);
    if (reject) return { moved: false, message: reject };

    const name = inventoryItemName(item);
    const count = Math.min(Math.max(1, amount || 1), item.quan || 1);
    const putItem = (item.quan || 1) > count ? { ...item, quan: count } : item;
    clearContainerPutEquipmentState(putItem, name);
    let sellobjResult = null;
    if (!options.skipSalePrompt) {
        const pendingSale = beginShopFloorContainerPutSale(iceBox, item, count);
        if (pendingSale?.prompt)
            return { moved: false, pendingSale, message: pendingSale.promptMessage };
        if (pendingSale?.handled) sellobjResult = pendingSale;
    }
    curseLoadstoneLeavingInventory(putItem);
    const billing = billShopFloorContainerPutObject(iceBox, putItem, {
        acceptedSale: !!options.acceptedSale,
        shkp: options.salePending?.shkp,
        sellobjResult,
    });
    removeInventoryItem(item, count);
    freezeObjectInIcebox(putItem);
    const contained = add_to_container(iceBox, putItem);
    if (options.acceptedSale && contained) markAcceptedShopContainerSaleState(contained, options.salePending?.shkp || billing.shkp);
    if (billing.noCharge && contained && contained !== putItem) markNoChargeRecursively(contained);
    game._pet_food_scan_inventory = game.inventory;
    const messages = [sellobjResult?.message, `You put ${name} into the ice box.`].filter(Boolean);
    return { moved: true, message: messages.join('  '), messages };
}

function putInventoryObjectIntoBag(bag, item, amount = item?.quan || 1) {
    if (!bag || !(game.inventory || []).includes(bag)) return { moved: false, message: '' };
    bag.contents ??= [];
    bag.cknown = true;
    if (item?.letter === '$' || item?.otyp === GOLD_PIECE || item?.cls === 'coin' || item?.glyph === '$') {
        const gold = Math.min(Math.max(0, amount || 0), game._goldCount || 0);
        if (!gold) return { moved: false, message: 'You have no gold to put in.' };
        add_to_container(bag, { letter: '$', cls: 'coin', otyp: GOLD_PIECE, glyph: '$', quan: gold });
        game._goldCount = Math.max(0, (game._goldCount || 0) - gold);
        game._just_picked_gold = Math.max(0, (game._just_picked_gold || 0) - gold);
        const money = (game.inventory || []).find(invItem => invItem.letter === '$' || invItem.cls === 'coin');
        if (money && game._goldCount) {
            money.quan = game._goldCount;
            updateMoneyLine(money);
        } else {
            game.inventory = (game.inventory || []).filter(invItem => invItem.letter !== '$' && invItem.cls !== 'coin');
        }
        game._pet_food_scan_inventory = game.inventory;
        return { moved: true, message: `You put ${gold} gold piece${gold === 1 ? '' : 's'} into the bag.` };
    }

    const reject = containerPutRejectMessage(bag, item);
    if (reject) return { moved: false, message: reject };

    const name = inventoryItemName(item);
    const count = Math.min(Math.max(1, amount || 1), item.quan || 1);
    const putItem = splitInventoryObjectForContainerPut(item, count);
    clearContainerPutEquipmentState(putItem, name);
    curseLoadstoneLeavingInventory(putItem);
    if (isMagicBagObject(bag) && magicBagExplodesWithObject(putItem)) {
        removeInventoryItem(item, count);
        return explodeMagicBagTransfer(bag, putItem, [], { triggerHeld: true });
    }
    removeInventoryItem(item, count);
    add_to_container(bag, putItem);
    game._pet_food_scan_inventory = game.inventory;
    return { moved: true, message: `You put ${name} into the bag.` };
}

function splitInventoryObjectForContainerPut(item, count) {
    if (!item || (item.quan || 1) <= count) return item;
    const putItem = { ...item, quan: count, id: next_ident() };
    delete putItem.o_id;
    delete putItem._shopBillObjectId;
    if (item.unpaid && !splitCarriedObjectShopBill(item, putItem, count))
        clearObjectShopBillState(putItem);
    return putItem;
}

function billShopFloorContainerPutObject(container, putItem, options = {}) {
    const x = container?.ox ?? game.u?.ux;
    const y = container?.oy ?? game.u?.uy;
    if (!container || !putItem || (game.inventory || []).includes(container) || x == null || y == null)
        return { shkp: null, returned: false, noCharge: false };
    const shkp = shopFloorContainerShopkeeper(container);
    if (!shkp) return { shkp: null, returned: false, noCharge: false };
    if (shopBillableGold(putItem)) return { shkp, returned: false, noCharge: false };
    const sellobjResult = options.sellobjResult;
    if (sellobjResult?.angry || sellobjResult?.robbed)
        return { shkp, returned: false, noCharge: false, sellobjResult };
    const gold = containedShopGold(putItem);
    if (gold > 0) donateShopGoldAt(container, gold);
    if (returnUnpaidObjectToShopBillOwnerAt(putItem, x, y))
        return { shkp, returned: true, noCharge: false };
    if (!putItem.unpaid) {
        const hadContainedUnpaid = globContents(putItem).length && shopObjectOrContentsUnpaid(putItem);
        if (options.acceptedSale) {
            markAcceptedShopContainerSaleState(putItem, options.shkp || shkp);
            if (hadContainedUnpaid) subFromShopBill(putItem, options.shkp || shkp);
            return { shkp, returned: false, noCharge: false, acceptedSale: true };
        }
        markNoChargeRecursively(putItem);
        if (hadContainedUnpaid) subFromShopBill(putItem, options.shkp || shkp);
        return { shkp, returned: false, noCharge: true };
    }
    return { shkp, returned: false, noCharge: false };
}

function preserveExplodedShopFloorPutTriggerBill(putItem, owner, fallbackShkp, price) {
    if (!putItem || shopBillableGold(putItem)) return false;
    if (!owner?.entry) return false;
    const shkp = owner?.shkp || fallbackShkp || heroShopkeeper();
    if (!shkp) return false;
    if (!shopBillEntryForObject(shkp, putItem) && price > 0)
        addObjectToShopBill(shkp, putItem, price, { useup: true });
    return markObjectShopBillUsedUp(putItem, shkp);
}

function putInventoryObjectIntoContainer(container, item, amount = item?.quan || 1, options = {}) {
    if (!container) return { moved: false, message: '' };
    if (isIceBoxObject(container)) return putInventoryObjectIntoIceBox(container, item, amount, options);
    container.contents ??= [];
    container.cknown = true;
    const containerName = tipContainerSimpleName(container);
    if (item?.letter === '$' || item?.otyp === GOLD_PIECE || item?.cls === 'coin' || item?.glyph === '$') {
        const gold = Math.min(Math.max(0, amount || 0), game._goldCount || 0);
        if (!gold) return { moved: false, message: 'You have no gold to put in.' };
        const shopGold = donateShopGoldAt(container, gold);
        add_to_container(container, { letter: '$', cls: 'coin', otyp: GOLD_PIECE, glyph: '$', quan: gold });
        game._goldCount = Math.max(0, (game._goldCount || 0) - gold);
        game._just_picked_gold = Math.max(0, (game._just_picked_gold || 0) - gold);
        const money = (game.inventory || []).find(invItem => invItem.letter === '$' || invItem.cls === 'coin');
        if (money && game._goldCount) {
            money.quan = game._goldCount;
            updateMoneyLine(money);
        } else {
            game.inventory = (game.inventory || []).filter(invItem => invItem.letter !== '$' && invItem.cls !== 'coin');
        }
        refreshTipContainerWeight(container);
        game._pet_food_scan_inventory = game.inventory;
        const messages = [`You put ${gold} gold piece${gold === 1 ? '' : 's'} into the ${containerName}.`, ...(shopGold.messages || [])];
        return { moved: true, message: messages.join('  '), messages };
    }

    const reject = containerPutRejectMessage(container, item);
    if (reject) return { moved: false, message: reject };

    const name = inventoryItemName(item);
    const count = Math.min(Math.max(1, amount || 1), item.quan || 1);
    const putItem = splitInventoryObjectForContainerPut(item, count);
    clearContainerPutEquipmentState(putItem, name);
    let sellobjResult = null;
    if (!options.skipSalePrompt) {
        const pendingSale = beginShopFloorContainerPutSale(container, item, count);
        if (pendingSale?.prompt)
            return { moved: false, pendingSale, message: pendingSale.promptMessage };
        if (pendingSale?.handled) sellobjResult = pendingSale;
    }
    curseLoadstoneLeavingInventory(putItem);
    if (isMagicBagObject(container) && magicBagExplodesWithObject(putItem)) {
        const triggerOwner = shopkeeperOwningBillEntry(putItem);
        const triggerPrice = triggerOwner.entry ? shopBillEntryTotal(triggerOwner.entry) : 0;
        const wasUnpaid = !!triggerOwner.entry;
        const billing = billShopFloorContainerPutObject(container, putItem, {
            acceptedSale: !!options.acceptedSale,
            shkp: options.salePending?.shkp,
            sellobjResult,
        });
        if (wasUnpaid)
            preserveExplodedShopFloorPutTriggerBill(putItem, triggerOwner, billing.shkp, triggerPrice);
        billShopFloorMagicBagExplosionTarget(container);
        removeInventoryItem(item, count);
        const messages = sellobjResult?.message ? [sellobjResult.message] : [];
        return explodeMagicBagTransfer(container, putItem, messages, { triggerHeld: true });
    }
    const billing = billShopFloorContainerPutObject(container, putItem, {
        acceptedSale: !!options.acceptedSale,
        shkp: options.salePending?.shkp,
        sellobjResult,
    });
    removeInventoryItem(item, count);
    const contained = add_to_container(container, putItem);
    if (options.acceptedSale && contained) markAcceptedShopContainerSaleState(contained, options.salePending?.shkp || billing.shkp);
    if (billing.noCharge && contained && contained !== putItem) markNoChargeRecursively(contained);
    refreshTipContainerWeight(container);
    game._pet_food_scan_inventory = game.inventory;
    const messages = [sellobjResult?.message, `You put ${name} into the ${containerName}.`].filter(Boolean);
    return { moved: true, message: messages.join('  '), messages };
}

function finishShopFloorContainerPutSale(pending, accept) {
    if (!pending?.container || !pending.item || !pending.putItem || !pending.shkp)
        return { moved: false, message: '' };
    const result = putInventoryObjectIntoContainer(
        pending.container,
        pending.item,
        pending.amount || pending.item?.quan || 1,
        { skipSalePrompt: true, acceptedSale: !!accept, salePending: pending },
    );
    if (!result.moved || !accept) return result;
    const saleMessage = shopSalePaymentMessage({ ...pending, obj: pending.putItem }, 'sell');
    const messages = [saleMessage, ...(result.messages || (result.message ? [result.message] : []))].filter(Boolean);
    return { ...result, saleMessage, messages, message: messages.join('  ') };
}

async function showIceBoxMessageList(messages) {
    messages = (messages || []).filter(Boolean);
    if (!messages.length) return;
    const message = messages.join('  ');
    if (message.length <= 79) {
        await setMessage(message);
    } else {
        const first = messages.slice(0, 2).join('  ');
        const rest = messages.slice(2).join('  ');
        game._queued_message_after_more = rest || null;
        game._queued_message_process_time_after_more = 1;
        await setMessage(first, true);
    }
}

function iceBoxPutResultMessages(results) {
    return (results || []).map(result => result.message).filter(Boolean);
}

async function showIceBoxPutMessages(results) {
    await showIceBoxMessageList(iceBoxPutResultMessages(results));
}

async function finishIceBoxSequence(messages = [], moved = false) {
    const allMessages = [...(game._icebox_sequence_messages || []), ...(messages || [])];
    const used = moved || !!game._icebox_sequence_used;
    clearIceBoxSequenceState();
    clearIceBoxActionState();
    game._command_mode = null;
    game._overlay_lines = null;
    game._overlay_hide_status = 0;
    if (used) game.context.move = 1;
    await showIceBoxMessageList(allMessages);
}

async function finishContainerSequence(messages = [], moved = false) {
    const allMessages = [...(game._container_sequence_messages || []), ...(messages || [])];
    const used = moved || !!game._container_sequence_used;
    clearContainerSequenceState();
    game._floor_container_object = null;
    game._command_mode = null;
    game._overlay_lines = null;
    game._overlay_hide_status = 0;
    if (used) game.context.move = 1;
    await showIceBoxMessageList(allMessages);
}

async function continueIceBoxSequenceToPutIn(iceBox, messages = []) {
    addIceBoxSequenceMessages(messages);
    if (iceBoxContainerAvailable(iceBox) && beginIceBoxPutIn(iceBox)) return true;
    clearIceBoxPutState();
    game._command_mode = null;
    await finishIceBoxSequence(["You don't have anything to put in."]);
    return true;
}

async function continueContainerSequenceToPutIn(container, messages = []) {
    addContainerSequenceMessages(messages);
    if (beginContainerPutIn(container)) return true;
    clearContainerPutState();
    game._command_mode = null;
    await finishContainerSequence(["You don't have anything to put in."]);
    return true;
}

async function continueIceBoxSequenceToTakeout(iceBox, messages = []) {
    addIceBoxSequenceMessages(messages);
    if (!iceBoxContainerAvailable(iceBox)) {
        clearContainerTakeoutState();
        clearIceBoxPutState();
        game._command_mode = null;
        await finishIceBoxSequence();
        return true;
    }
    const learnedEmpty = !(iceBox.contents || []).length && !iceBox.cknown;
    iceBox.cknown = true;
    if (beginIceBoxTakeout(iceBox)) return true;
    if (learnedEmpty) markIceBoxSequenceUsed();
    clearContainerTakeoutState();
    game._command_mode = null;
    await finishIceBoxSequence([iceBoxEmptyMessage()]);
    return true;
}

async function continueContainerSequenceToTakeout(container, messages = []) {
    addContainerSequenceMessages(messages);
    if (!container) {
        clearContainerTakeoutState();
        clearContainerPutState();
        game._command_mode = null;
        await finishContainerSequence();
        return true;
    }
    const learnedEmpty = !(container.contents || []).length && !container.cknown;
    container.cknown = true;
    if (beginIceBoxTakeout(container)) return true;
    if (learnedEmpty) markContainerSequenceUsed();
    clearContainerTakeoutState();
    game._command_mode = null;
    await finishContainerSequence([tipContainerEmptyMessage(container)]);
    return true;
}

async function beginIceBoxStash(iceBox) {
    const letters = iceBoxPutLetters(iceBox);
    if (!letters) return false;
    game._icebox_put_container = iceBox;
    game._icebox_stash_letters = letters;
    await setMessage(`What do you want to stash? [${getobjPromptLetters(letters)} or ?*]`);
    game._command_mode = 'iceBoxStashObject';
    return true;
}

async function beginContainerStash(container) {
    const letters = containerPutLetters(container);
    if (!letters) return false;
    game._container_put_container = container;
    game._container_stash_letters = letters;
    await setMessage(`What do you want to stash? [${getobjPromptLetters(letters)} or ?*]`);
    game._command_mode = 'containerStashObject';
    return true;
}

function containerLootCategory(item) {
    if (item.otyp === GOLD_PIECE || item.cls === 'coin' || item.glyph === '$') return 'Coins';
    if (item.otyp === FOOD_CLASS || item.cls === 'food' || item.glyph === '%') return 'Comestibles';
    if (item.otyp === SCROLL_CLASS || item.cls === 'scroll' || item.glyph === '?') return 'Scrolls';
    if (item.cls === 'spellbook' || item.glyph === '+') return 'Spellbooks';
    if (item.otyp === POTION_CLASS || item.cls === 'potion' || item.glyph === '!') return 'Potions';
    if (item.otyp === RING_CLASS || item.cls === 'ring' || item.glyph === '=') return 'Rings';
    if (item.otyp === GEM_CLASS || item.cls === 'gem' || item.glyph === '*') return 'Gems/Stones';
    if (isBoulderObject(item) || item.otyp === STATUE || item.cls === 'rock' || item.glyph === '`') return 'Boulders/Statues';
    return 'Other Items';
}

function beginIceBoxTakeout(iceBox) {
    const contents = [...(iceBox?.contents || [])].sort(compareContainerLootItems);
    if (!contents.length) return false;
    const seen = new Set(contents.map(containerLootCategory));
    const typeEntries = [...seen]
        .sort((a, b) => PICKUP_SECTION_ORDER.indexOf(a) - PICKUP_SECTION_ORDER.indexOf(b))
        .map((label, i) => ({ letter: String.fromCharCode('b'.charCodeAt(0) + i), label }));
    if (typeEntries.length === 1) {
        const entries = contents.map((item, i) => ({
            item,
            label: typeEntries[0].label,
            letter: String.fromCharCode('a'.charCodeAt(0) + i),
        }));
        const rows = [[0, 41, 'Take out what?', 1], [2, 41, typeEntries[0].label, 1]];
        let row = 3;
        for (const entry of entries)
            rows.push([row++, 41, `${entry.letter} - ${pickupObjectPhrase(entry.item)}`]);
        rows.push([row, 41, '(end)']);
        game._loot_takeout_container = iceBox;
        game._loot_takeout_entries = entries;
        game._loot_takeout_selected = [];
        game._loot_takeout_clear_col = 40;
        setOverlay(rows, row + 1, false, game._loot_takeout_clear_col);
        game._command_mode = 'lootTakeoutObjects';
        return true;
    }

    const typeRows = [
        [0, 23, 'Take out what type of objects?', 1],
        [2, 23, 'A - Auto-select every relevant item'],
        [3, 27, '(ignored unless some other choices are also picked)'],
        [5, 23, 'a - All types'],
    ];
    for (let i = 0; i < typeEntries.length; i++)
        typeRows.push([6 + i, 23, `${typeEntries[i].letter} - ${typeEntries[i].label}`]);
    let filterRow = 7 + typeEntries.length;
    if (contents.some(item => objectBucCategory(item) === 'blessed'))
        typeRows.push([filterRow++, 23, 'B - Items known to be Blessed']);
    if (contents.some(item => objectBucCategory(item) === 'cursed'))
        typeRows.push([filterRow++, 23, 'C - Items known to be Cursed']);
    if (contents.some(item => objectBucCategory(item) === 'uncursed'))
        typeRows.push([filterRow++, 23, 'U - Items known to be Uncursed']);
    if (contents.some(item => objectBucCategory(item) === 'unknown'))
        typeRows.push([filterRow++, 23, 'X - Items of unknown Bless/Curse status']);
    typeRows.push([filterRow, 23, '(end)']);
    game._loot_takeout_container = iceBox;
    game._loot_takeout_type_entries = typeEntries;
    game._loot_takeout_types_selected = [];
    setOverlay(typeRows, filterRow + 1, false, 22);
    game._command_mode = 'lootTakeoutMenu';
    return true;
}

function prepareContainerTakeoutObject(container, obj) {
    if (isIceBoxObject(container)) removedFromIcebox(obj);
    obj.contained = false;
    obj.container = null;
    delete obj.nobj;
    delete obj.nexthere;
    return obj;
}

function addContainerTakeoutObjectToInventory(container, obj, options = {}) {
    const billingSource = options.sourceObj || obj;
    if (shopBillableGold(obj)) {
        prepareContainerTakeoutObject(container, obj);
        const amount = Math.max(1, Math.trunc(Number(obj.quan || 1)));
        addContainerTakeoutObjectToShopBill(container, billingSource, obj);
        addGoldToHero(amount);
        return `$ - ${amount} gold piece${amount === 1 ? '' : 's'}`;
    }
    if (isBoulderObject(obj)) normalizeBoulderObject(obj);
    const mergeInfo = findContainerTakeoutInventoryMergeTarget(container, obj);
    if (mergeInfo) {
        const line = mergeContainerTakeoutObjectIntoInventory(container, obj, mergeInfo);
        game._pet_food_scan_inventory = game.inventory;
        return line;
    }
    prepareContainerTakeoutObject(container, obj);
    const letter = options.inventoryLetter || nextInventoryLetter();
    Object.assign(obj, {
        cls: obj.cls || (obj.otyp === GEM_CLASS ? 'gem'
            : obj.otyp === SCROLL_CLASS ? 'scroll'
                : obj.glyph === '+' ? 'spellbook' : obj.cls),
        letter,
        kind: obj.kind || pickupObjectName({ ...obj, quan: 1 }),
    });
    obj.line = normalInventoryLine({ ...obj, line: '' });
    const billing = addContainerTakeoutObjectToShopBill(container, billingSource, obj);
    game.inventory = [...(game.inventory || []), obj];
    maybeAttachCarriedFigurineTimeout(obj);
    game._pet_food_scan_inventory = game.inventory;
    const line = obj.line || `${letter} - ${pickupObjectPhrase(obj)}`;
    return billing.messages?.length ? `${billing.messages.join('  ')}  ${line}` : line;
}

function splitContainerTakeoutObjectForLift(obj, count) {
    const quantity = Math.max(1, Math.trunc(Number(obj?.quan || 1)));
    const takeCount = Math.max(1, Math.min(quantity, Math.trunc(Number(count || quantity))));
    if (isLoadstoneObject(obj)) return obj;
    if (!obj || takeCount >= quantity) return obj;
    const lifted = { ...obj, id: next_ident(), quan: takeCount };
    delete lifted.o_id;
    delete lifted._shopBillObjectId;
    delete lifted.letter;
    delete lifted.line;
    obj.quan = quantity - takeCount;
    return lifted;
}

async function finishContainerTakeoutSelection(container, picked, preflightMessages = []) {
    const messages = [...(preflightMessages || [])];
    if (!(picked || []).length) {
        clearContainerTakeoutState();
        game._floor_container_object = null;
        game._overlay_lines = null;
        game._overlay_hide_status = 0;
        clearIceBoxSequenceState();
        clearContainerSequenceState();
        game._command_mode = null;
        game.context.move = 0;
        await showIceBoxMessageList(messages);
        return;
    }
    const moved = [];
    for (const pickedEntry of picked || []) {
        const source = pickedEntry.item;
        const obj = splitContainerTakeoutObjectForLift(source, pickedEntry.takeCount || source?.quan || 1);
        const line = addContainerTakeoutObjectToInventory(container, obj, { inventoryLetter: pickedEntry.inventoryLetter, sourceObj: source });
        moved.push(obj);
        messages.push(/[.!?]$/.test(line) ? line : `${line}.`);
    }
    for (const obj of moved) removeContainedObject(container, obj);
    game._pet_food_scan_inventory = game.inventory;
    const followupPutIn = game._icebox_sequence_after_takeout === 'putin' && isIceBoxObject(container);
    const finishSequence = !followupPutIn && iceBoxSequenceActive() && isIceBoxObject(container);
    const followupContainerPutIn = game._container_sequence_after_takeout === 'putin' && !isIceBoxObject(container);
    const finishContainerSeq = !followupContainerPutIn && containerSequenceActive() && !isIceBoxObject(container);
    clearContainerTakeoutState();
    game._floor_container_object = null;
    game._overlay_lines = null;
    game._overlay_hide_status = 0;
    if (followupPutIn) {
        markIceBoxSequenceUsed(true);
        await continueIceBoxSequenceToPutIn(container, messages);
        return;
    }
    if (finishSequence) {
        await finishIceBoxSequence(messages, true);
        return;
    }
    if (followupContainerPutIn) {
        markContainerSequenceUsed(true);
        await continueContainerSequenceToPutIn(container, messages);
        return;
    }
    if (finishContainerSeq) {
        await finishContainerSequence(messages, true);
        return;
    }
    clearIceBoxSequenceState();
    clearContainerSequenceState();
    game._command_mode = null;
    game.context.move = 1;
    await showIceBoxMessageList(messages);
}

function placeObjectOnFloorWithEffects(obj, x, y, messages, verb = 'drop', {
    stack = false,
    usedUpShopBillOnDestroy = false,
} = {}) {
    obj.contained = false;
    obj.container = null;
    obj.ox = x;
    obj.oy = y;
    obj.hidden = false;
    obj.buried = false;
    obj.transientProjectile = false;
    delete obj.line;
    delete obj.nobj;
    delete obj.nexthere;
    const display = object_display(obj);
    if (display.glyph === '?' && OBJECT_CLASS_GLYPHS[obj.cls]) {
        display.glyph = OBJECT_CLASS_GLYPHS[obj.cls];
        if (obj.cls === 'armor') display.color = carriedDropDisplayColor(obj);
    }
    Object.assign(obj, display);
    if (!earthFloorEffects(obj, x, y, messages, verb, { usedUpShopBillOnDestroy })) {
        game.level.objects ??= [];
        const stacked = stack ? stackMonsterThrownObject(obj) : obj;
        if (stacked === obj) game.level.objects.push(obj);
        objectIceEffect(obj, x, y);
        newsym(x, y);
        return true;
    }
    newsym(x, y);
    return false;
}

function placeTippedObjectOnFloor(obj, x, y, messages) {
    return placeObjectOnFloorWithEffects(obj, x, y, messages, 'drop', {
        usedUpShopBillOnDestroy: true,
    });
}

function tipContainerSimpleName(source) {
    const display = BAG_OBJECT_TYPES.has(source?.otyp) ? { ...source, cknown: false } : source;
    const name = articlelessObjectName(display);
    if ((source?.broken || source?.obroken) && /^(?:large box|chest)$/.test(name))
        return `broken ${name}`;
    return name;
}

function tipContainerEmptyMessage(source) {
    return `The ${tipContainerSimpleName(source)} is empty.`;
}

function thawObjectTippedFromSource(source, obj) {
    if (isIceBoxObject(source)) removedFromIcebox(obj);
}

function returnTippedObjectToShopFloor(source, obj) {
    const shkp = shopFloorContainerShopkeeper(source);
    if (!shkp || !obj || shopBillableGold(obj)) return false;
    if (globContents(obj).length) return subFromShopBill(obj, shkp);
    return sellobjReturnUnpaidToShop(obj, obj.ox, obj.oy);
}

function tipContainerToFloor(source) {
    const contents = [...liquidFlowContainerContents(source)];
    source.cknown = true;
    if (!contents.length) return [tipContainerEmptyMessage(source)];
    const x = game.u?.ux ?? source.ox ?? 0;
    const y = game.u?.uy ?? source.oy ?? 0;
    const cursedMagicBag = isMagicBagObject(source) && source.cursed;
    let lostMerchandise = 0;
    const names = contents.map(containerObjectPhrase).join(', ');
    const messages = [cursedMagicBag
        ? (contents.length === 1 ? 'An object spills out.' : 'Objects spill out.')
        : contents.length === 1
            ? `An object spills out: ${names}.`
            : `Objects spill out: ${names}.`];
    for (const obj of contents) {
        removeContainedObject(source, obj);
        thawObjectTippedFromSource(source, obj);
        if (cursedMagicBag && !rn2(13)) {
            lostMerchandise += billMagicBagLostItem(source, obj);
            destroyMagicBagItem(obj, messages);
            continue;
        }
        addTippedContainerObjectToShopBill(source, obj);
        const placed = placeTippedObjectOnFloor(obj, x, y, messages);
        if (placed) {
            const gold = shopBillableGold(obj)
                ? Math.max(1, Math.trunc(Number(obj.quan || 1)))
                : containedShopGold(obj);
            if (gold > 0) donateShopGoldAt(source, gold);
            returnTippedObjectToShopFloor(source, obj);
        }
    }
    if (Array.isArray(source.contents)) source.contents.length = 0;
    if (Array.isArray(source.cobj)) source.cobj.length = 0;
    refreshTipContainerWeight(source);
    const lostMessage = lostShopMerchandiseMessage(lostMerchandise);
    if (lostMessage) messages.push(lostMessage);
    return messages;
}

function isTipContainerObject(obj) {
    if (!obj) return false;
    if (isIceBoxObject(obj) || isBoxObject(obj) || BAG_OBJECT_TYPES.has(obj.otyp)) return true;
    return /^(?:large box|chest|ice box|sack|oilskin sack|bag of holding|bag)$/.test(objectKindKey(obj));
}

function isBagOfTricksObject(obj) {
    return !!obj && (obj.otyp === BAG_OF_TRICKS || objectKindKey(obj) === 'bag of tricks'
        || pickupObjectName({ ...obj, quan: 1 }).toLowerCase() === 'bag of tricks');
}

function isKnownBagOfTricksObject(obj) {
    return isBagOfTricksObject(obj) && obj.dknown === true
        && (obj.known === true || toolDiscoveryKnown('bag of tricks'));
}

function isUnknownBagOfTricksObject(obj) {
    return isBagOfTricksObject(obj) && !isKnownBagOfTricksObject(obj);
}

function isHornOfPlentyObject(obj) {
    return !!obj && (obj.otyp === HORN_OF_PLENTY || objectKindKey(obj) === 'horn of plenty'
        || pickupObjectName({ ...obj, quan: 1 }).toLowerCase() === 'horn of plenty');
}

function isKnownHornOfPlentyObject(obj) {
    return isHornOfPlentyObject(obj) && obj.dknown === true
        && (obj.known === true || toolDiscoveryKnown('horn of plenty'));
}

function isTipSourceObject(obj) {
    return isTipContainerObject(obj) || isBagOfTricksObject(obj) || isHornOfPlentyObject(obj);
}

function isFloorTipSourceObject(obj) {
    return isTipContainerObject(obj) || isBagOfTricksObject(obj);
}

function tipSpillageKind(obj) {
    const kind = objectKindKey(obj);
    if (isCandleObject(obj) && obj.lamplit) return 'wax';
    if ((isPotionOfOil(obj) && obj.lamplit)
        || ((obj?.otyp === OIL_LAMP || kind === 'oil lamp') && (obj.age ?? 0) !== 0)
        || ((obj?.otyp === MAGIC_LAMP || kind === 'magic lamp') && (obj.spe ?? 0) !== 0))
        return 'oil';
    if ((toolChargeKind(obj) === 'can of grease' || kind === 'can of grease') && (obj?.spe ?? 0) > 0)
        return 'grease';
    if (obj?.otyp === FOOD_RATION || obj?.otyp === LEMBAS_WAFER
        || kind === 'food ration' || kind === 'cram ration' || kind === 'lembas wafer')
        return 'crumbs';
    if (obj?.cls === 'venom') return 'venom';
    return '';
}

function isTipSpillageObject(obj) {
    return !!tipSpillageKind(obj);
}

function isTipCommandObject(obj) {
    return isTipSourceObject(obj) || isTipSpillageObject(obj);
}

function isTipCoinObject(obj) {
    return !!obj && (obj.otyp === GOLD_PIECE || obj.cls === 'coin' || obj.glyph === '$');
}

function tipSelectionKind(obj) {
    if (!obj || isTipCoinObject(obj)) return 'exclude';
    if (isTipContainerObject(obj) || isBagOfTricksObject(obj)) return 'suggest';
    if (isKnownHornOfPlentyObject(obj)) return 'suggest';
    return 'downplay';
}

function tipInventoryItemsBySelectionKind(kind) {
    return (game.inventory || []).filter(item => tipSelectionKind(item) === kind && item.letter);
}

function tipSelectableInventoryItems() {
    return (game.inventory || []).filter(item => tipSelectionKind(item) !== 'exclude' && item.letter);
}

function tipSuggestedLetters() {
    return tipInventoryItemsBySelectionKind('suggest').map(item => item.letter).join('');
}

function tipPromptMessage() {
    const suggested = tipSuggestedLetters();
    if (suggested) return `What do you want to tip? [${getobjPromptLetters(suggested)} or ?*]`;
    if (tipInventoryItemsBySelectionKind('downplay').length) return 'What do you want to tip? [*]';
    return "You don't have anything to tip.";
}

function tipMenuItems(ch) {
    if (ch === '*') return tipSelectableInventoryItems();
    const suggested = tipInventoryItemsBySelectionKind('suggest');
    return suggested.length ? suggested : tipInventoryItemsBySelectionKind('downplay');
}

function tipSpillageSurfacePhrase(spillage) {
    const plural = spillage === 'crumbs';
    const loc = game.level?.at?.(game.u?.ux, game.u?.uy);
    if (loc?.typ === LAVAPOOL || loc?.typ === LAVAWALL)
        return { surface: 'lava', suffix: ` and immediately ${plural ? 'burn' : 'burns'} away` };
    if (loc && (IS_POOL(loc.typ) || loc.typ === WATER || loc.typ === MOAT))
        return { surface: 'water', suffix: ` and gradually ${plural ? 'dissipate' : 'dissipates'}` };
    return { surface: 'floor', suffix: '' };
}

function tipSpillageObject(obj) {
    const spillage = tipSpillageKind(obj);
    if (!spillage) return ['Nothing happens.'];
    const plural = spillage === 'crumbs';
    const { surface, suffix } = tipSpillageSurfacePhrase(spillage);
    const messages = [`Some ${spillage} ${plural ? 'spill' : 'spills'} onto the ${surface}${suffix}.`];
    if ((toolChargeKind(obj) === 'can of grease' || objectKindKey(obj) === 'can of grease') && (obj?.spe ?? 0) > 0)
        spendChargedToolUse(obj, messages);
    return messages;
}

function tipOrdinaryObjectMessages(obj) {
    if (obj?.cls === 'potion' || obj?.glyph === '!') {
        const name = pickupObjectName(obj);
        const plural = Math.max(1, Math.trunc(Number(obj?.quan || 1))) > 1;
        return [`The ${name} ${plural ? 'are' : 'is'} securely sealed.`];
    }
    if (obj?.otyp === STATUE || objectKindKey(obj) === 'statue') return ['Nothing interesting happens.'];
    return ['Nothing happens.'];
}

function tipWornHelmet() {
    return wornArmorInSlot('helm');
}

function isTipWornHelmet(obj) {
    return !!obj && obj === tipWornHelmet();
}

function tipHatSimpleName(helmet) {
    return hardEarthHelmet(helmet) ? 'helm' : 'hat';
}

function tipHatDirectionPrompt() {
    return 'At whom? (in what direction)';
}

async function beginTipHat(helmet) {
    const cancelMove = helmet?.bknown ? 0 : 1;
    if (helmet?.cursed) {
        helmet.bknown = true;
        refreshInventoryObjectLine(helmet);
        await setMessage("You can't.  It is cursed.");
        game.context.move = cancelMove;
        game._command_mode = null;
        return;
    }
    game._tip_hat_letter = helmet?.letter || '';
    game._tip_hat_cancel_move = cancelMove;
    await setMessage(tipHatDirectionPrompt());
    game._command_mode = 'tipHatDirection';
}

function tipHatDirectionFromKey(ch) {
    return commandDirection(ch);
}

function tipHatMonsterCanBeSeen(mon) {
    return !!mon && !game.u?.blind && !mon.minvis && !mon.mundetected && couldsee(mon.mx, mon.my);
}

function tipHatApparentObjectOrFurniture(mon) {
    const appearance = M_AP_TYPE(mon);
    return !!mon && (appearance === M_AP_FURNITURE || appearance === M_AP_OBJECT
        || mon.appearObj != null || !!mon.appearGlyph);
}

function tipHatMonsterAppearsAsStatueGlyph(mon) {
    if (!mon) return false;
    const kind = String(mon.appearKind ?? mon.appearanceKind ?? mon.mappearanceKind ?? '').toLowerCase();
    return mon.appearObj === STATUE || mon.mappearance === STATUE
        || mon.appearStatueGlyph === true || mon.statueGlyph === true
        || kind === 'statue' || kind.endsWith(' statue');
}

function tipHatLocationHasStatueGlyph(loc) {
    return !!(loc?.displayed_statue_glyph
        || loc?.remembered_glyph?.statueGlyph
        || loc?.statueGlyph
        || loc?.glyph_is_statue);
}

function tipHatMonsterVisible(mon) {
    return tipHatMonsterCanBeSeen(mon) && !tipHatApparentObjectOrFurniture(mon);
}

function tipHatMonsterResponsive(mon) {
    if (!mon || mon.dead) return false;
    if (tipHatMonsterHelpless(mon) || mon.mcansee === false || mon.blind) return false;
    return true;
}

function tipHatMonsterIsNymph(mon, monName = '', mlet = '') {
    const data = mon?.data || {};
    const name = String(monName || data.name || mon?.name || '').toLowerCase();
    const letter = String(mlet || data.mlet || mon?.mlet || '').toLowerCase();
    return !!(mon?.nymph || data.nymph || letter === 'n' || letter === 'nymph' || /\bnymph\b/.test(name));
}

function tipHatMonsterHumanoid(mon) {
    const data = mon?.data || {};
    const mlet = data.mlet || mon?.mlet || '';
    const name = String(data.name || mon?.name || '').toLowerCase();
    return !!(data.humanoid || data.human || mlet === 'humanoid' || mlet === 'human' || mlet === '@'
        || data.name === 'human' || /^(gremlin|leprechaun|skeleton|death|pestilence|famine)$/.test(name)
        || tipHatMonsterIsNymph(mon, name, mlet)
        || tipHatMonsterIsVampireInOwnForm(name)
        || /\bzombie$/.test(name));
}

function tipHatMonsterPossessive(mon) {
    const data = mon?.data || {};
    if (mon?.female || data.female) return 'her';
    if (mon?.male || data.male) return 'his';
    return 'its';
}

function tipHatMonsterFemale(mon) {
    const data = mon?.data || {};
    if (mon?.female != null) return !!mon.female;
    if (data.female != null) return !!data.female;
    return false;
}

function chatHeroHumanoidForDeafResponse() {
    const form = polyselfForm();
    if (!form) return true;
    if (form.humanoid != null) return !!form.humanoid;
    const mlet = String(form.mlet || '').toLowerCase();
    const name = String(form.name || '').toLowerCase();
    return !!(form.human || mlet === '@' || mlet === 'human' || mlet === 'humanoid' || name === 'human');
}

function chatClearTargetWaitStrategy(mon) {
    if (Number.isInteger(mon?.mstrategy)) mon.mstrategy &= ~STRAT_WAITMASK;
    else if (mon?.mstrategy === 'waitforu') mon.mstrategy = 0;
}

function chatMonsterNameForDeafResponse(mon, visible) {
    return visible ? ` from ${fireScrollMonsterName(mon).replace(/^The /, 'the ')}` : '';
}

function chatDeafResponseMessage(mon, visible) {
    const response = chatHeroHumanoidForDeafResponse() ? 'falls on deaf ears' : 'is inaudible';
    return `Any response${chatMonsterNameForDeafResponse(mon, visible)} ${response}.`;
}

function chatMapUnseenMonster(mon) {
    const unseenLoc = game.level?.at?.(mon.mx, mon.my);
    if (unseenLoc) unseenLoc.map_invisible = true;
    newsym(mon.mx, mon.my);
}

function chatMonsterIsEating(mon) {
    return Number(mon?.mtame || 0) > 0 && !!mon?.meating;
}

function chatMonsterName(mon, visible) {
    if (!visible) return 'It';
    const name = fireScrollMonsterName(mon);
    if (mon?.saddled && !mon?.givenName && !(mon?.isshk && mon?.shknam))
        return name.replace(/^The /, 'The saddled ');
    return name;
}

function chatClearNoTarget() {
    game._pending_message = '';
    game._message_more = 0;
    game._command_mode = null;
}

function chatTargetIsWall(loc) {
    return !!loc && (IS_WALL(loc.typ) || loc.typ === SDOOR);
}

function chatVisibleStatueAt(x, y) {
    const obj = topFloorObjectAt(x, y);
    return obj && (obj.kind === 'statue' || obj.otyp === STATUE) ? obj : null;
}

function chatBlindHasMappedWall(loc) {
    return IS_WALL(loc?.lastseentyp ?? 0);
}

function chatStatueTargetName() {
    return heroIsHallucinating()
        ? (rndmonnum()?.name || randomHallucinatedMonsterName())
        : 'statue';
}

const CHAT_HALLUCINATED_WALL_TALK = [
    'gripes about its job.',
    'tells you a funny joke!',
    'insults your heritage!',
    'chuckles.',
    'guffaws merrily!',
    'deprecates your exploration efforts.',
    'suggests a stint of rehab...',
    "doesn't seem to be interested.",
];

function chatWallTargetMessage() {
    if (!heroIsHallucinating()) return "It's like talking to a wall.";
    let idx = rn2(10);
    if (idx >= CHAT_HALLUCINATED_WALL_TALK.length)
        idx = CHAT_HALLUCINATED_WALL_TALK.length - 1;
    return `The wall ${CHAT_HALLUCINATED_WALL_TALK[idx]}`;
}

const CHAT_SILENT_POLYFORM_NAMES = new Set([
    'acid blob', 'quivering blob', 'gelatinous cube',
    'blue jelly', 'spotted jelly', 'ochre jelly',
    'small mimic', 'large mimic', 'giant mimic',
    'giant ant', 'soldier ant', 'fire ant', 'giant beetle',
]);

function chatHeroPolyform() {
    return polyselfForm() || game.u?._polyself_form || game.u?.data || {};
}

function chatHeroIsSilent() {
    const form = chatHeroPolyform();
    const explicit = form?.msound ?? form?.sound;
    const soundName = String(explicit ?? '').toLowerCase();
    const name = String(form?.name || '').toLowerCase();
    if (form?.silent || form?.msilent || explicit === 0
        || soundName === 'silent' || soundName === 'ms_silent'
        || CHAT_SILENT_POLYFORM_NAMES.has(name))
        return true;
    if (explicit != null) return false;
    return tipHatGeneratedMonsterSound(name) === 'silent';
}

function chatHeroPolyformArticleName() {
    return articleFor(String(chatHeroPolyform()?.name || 'creature').toLowerCase());
}

function chatPreDirectionMessage() {
    if (chatHeroIsSilent())
        return `As ${chatHeroPolyformArticleName()}, you cannot speak.`;
    if (heroIsStrangledForChoke()) return "You can't speak.  You're choking!";
    if (game.u?.uswallow) return "They won't hear you out there.";
    if (game.u?.uinwater || game.u?.underwater || game.u?.uunderwater)
        return 'Your speech is unintelligible underwater.';
    return '';
}

function chatShopFloorObjects() {
    const x = game.u?.ux;
    const y = game.u?.uy;
    return (game.level?.objects || [])
        .filter(obj => obj && !obj.hidden && !obj.transientProjectile
            && obj.ox === x && obj.oy === y
            && !(obj.otyp === GOLD_PIECE || obj.cls === 'coin' || obj.glyph === '$'));
}

function chatShopkeeperCanQuoteFloor(shkp) {
    return !!shkp && shopkeeperInHisShop(shkp)
        && !shopkeeperAngryForSellobj(shkp)
        && !shopkeeperMuteForSpeech(shkp)
        && !tipHatMonsterHelpless(shkp);
}

function chatShopQuoteWearingSurcharge() {
    const worn = (game.inventory || []).filter(isWornInventoryItem);
    if (worn.some(item => objectKindKey(item) === 'dunce cap')) return true;
    const role = game._startup_role || game.urole?.name?.m || '';
    if (role === 'Tourist' && (game.u?.ulevel || 1) < 15) return true;
    const wornArmor = worn.filter(item =>
        item.cls === 'armor' || item.glyph === '[' || item.otyp === ARMOR_CLASS);
    const visibleShirt = wornArmor.some(item => ['hawaiian shirt', 't-shirt'].includes(objectKindKey(item)))
        && !wornArmor.some(item => ['body', 'cloak'].includes(armorSlot(item)));
    return visibleShirt;
}

function chatShopQuoteUnitCost(obj, shkp) {
    let price = shopBaseCost(obj);
    if ((obj?.cls === 'food' || obj?.otyp === FOOD_CLASS || obj?.otyp === CORPSE || obj?.otyp === 'corpse')
        && (game.u?.uhs || 0) >= 2)
        price *= game.u.uhs;
    if ((obj?.cls === 'food' || obj?.otyp === FOOD_CLASS || obj?.otyp === CORPSE || obj?.otyp === 'corpse')
        && obj?.oeaten)
        price = 0;
    if ((obj?.cls === 'armor' || obj?.cls === 'weapon' || obj?.glyph === '[' || obj?.glyph === ')')
        && (obj?.spe || 0) > 0)
        price += 10 * obj.spe;
    if (isCandleObject(obj) && obj?.age < 20 * price) price = Math.trunc(price / 2);
    if (!price) price = 5;

    let multiplier = 1;
    let divisor = 1;
    if ((obj?.dknown !== true || !shopObjectNameKnown(obj))
        && ((obj?.id ?? obj?.o_id ?? 0) % 4) === 0) {
        multiplier *= 4;
        divisor *= 3;
    }
    if (chatShopQuoteWearingSurcharge()) {
        multiplier *= 4;
        divisor *= 3;
    }
    const cha = game.u?.acurr?.a?.[A_CHA] ?? 10;
    if (cha > 18) divisor *= 2;
    else if (cha === 18) { multiplier *= 2; divisor *= 3; }
    else if (cha >= 16) { multiplier *= 3; divisor *= 4; }
    else if (cha <= 5) multiplier *= 2;
    else if (cha <= 7) { multiplier *= 3; divisor *= 2; }
    else if (cha <= 10) { multiplier *= 4; divisor *= 3; }

    price *= multiplier;
    if (divisor > 1) price = Math.trunc((Math.trunc(price * 10 / divisor) + 5) / 10);
    price = Math.max(1, Math.trunc(price));
    if (obj?.artifact || obj?.oartifact) price *= 4;
    if (shkp?.surcharge) price += Math.trunc((price + 2) / 3);
    return price;
}

function chatShopQuoteTopCost(obj, shkp) {
    if (!obj || obj.no_charge || obj === game.u?.uball || obj === game.u?.uchain) return 0;
    let price = chatShopQuoteUnitCost(obj, shkp);
    if (isGlobbyObject(obj)) price *= shopPricingUnits(obj);
    return Math.max(0, Math.trunc(Number(price || 0)));
}

function chatShopQuoteContainedCost(obj, shkp, seen = new Set()) {
    if (!obj || seen.has(obj)) return 0;
    seen.add(obj);
    let price = 0;
    for (const child of globContents(obj)) {
        if (!child || seen.has(child)) continue;
        if (!shopBillableGold(child) && !child.no_charge)
            price += chatShopQuoteUnitCost(child, shkp) * shopPricingUnits(child);
        price += chatShopQuoteContainedCost(child, shkp, seen);
    }
    return Math.max(0, Math.trunc(price));
}

function chatShopQuoteMagicObject(obj, oclass) {
    if (shopObjectNameKnown(obj))
        return !!(obj?.oc_magic || obj?.magic || obj?.magicStone);
    return [AMULET_CLASS, RING_CLASS, WAND_CLASS, POTION_CLASS, SCROLL_CLASS, SPBOOK_CLASS]
        .includes(oclass);
}

function chatShopQuoteEmbellishment(obj, cost) {
    if (!rn2(3)) {
        let choice = rn2(5);
        if (choice === 0) choice = cost < 100 ? 1 : cost < 500 ? 2 : 3;
        switch (choice) {
        case 4: {
            if (cost < 10) break;
            const oclass = shopObjectClassCode(obj);
            if (oclass === FOOD_CLASS) return ", gourmets' delight!";
            if (chatShopQuoteMagicObject(obj, oclass)) return ', painstakingly developed!';
            return ', superb craftsmanship!';
        }
        case 3:
            return ', finest quality.';
        case 2:
            return ', an excellent choice.';
        case 1:
            return ', a real bargain.';
        default:
            break;
        }
    } else if (obj?.artifact) {
        return ', one of a kind!';
    }
    return '.';
}

function chatShopQuoteEntry(obj, shkp) {
    const topCost = chatShopQuoteTopCost(obj, shkp);
    let cost = topCost + (globContents(obj).length
        ? chatShopQuoteContainedCost(obj, shkp)
        : 0);
    cost = Math.max(0, Math.trunc(Number(cost || 0)));
    const contentsOnly = cost > 0 && topCost === 0;
    const name = `${contentsOnly ? 'the contents of ' : ''}${pickupObjectPhrase(obj)}`;
    const price = cost > 0
        ? `${cost} ${shopCurrency(cost)}${(obj?.quan || 1) > 1 ? ' each' : ''}`
        : 'no charge';
    return { obj, cost, contentsOnly, line: `${name}, ${price}` };
}

function chatShopFloorQuote() {
    if (heroIsDeaf() || heroIsBlind()) return null;
    const x = game.u?.ux;
    const y = game.u?.uy;
    const shkp = shopkeeperForCostlySpot(x, y);
    if (!chatShopkeeperCanQuoteFloor(shkp)) return null;
    const objects = chatShopFloorObjects();
    if (!objects.length) return null;
    return { shkp, entries: objects.map(obj => chatShopQuoteEntry(obj, shkp)) };
}

async function finishChatShopFloorQuote(quote) {
    const entries = quote?.entries || [];
    if (!entries.length) return false;
    if (entries.length > 1) {
        const rows = [[0, 0, 'Fine goods for sale:'], [1, 0, '']];
        for (let i = 0; i < entries.length; i++)
            rows.push([i + 2, 0, entries[i].line]);
        setOverlay(rows, rows.length);
        game._command_mode = 'chatPriceQuoteMenu';
        game._pending_message = '';
        game._message_more = 0;
        game._keep_pending_message = 0;
        game._pending_time_passed = Math.max(game._pending_time_passed || 0, 1);
        game.context.move = 0;
        return true;
    }

    const entry = entries[0];
    let message = `${upstartText(entry.line)}!`;
    if (entry.cost > 0) {
        const name = upstartText(entry.contentsOnly
            ? entry.line.replace(/, \d+ .*/, '')
            : pickupObjectPhrase(entry.obj));
        const stackEach = (entry.obj?.quan || 1) > 1 ? ' each' : '';
        const suffix = entry.contentsOnly ? '.' : chatShopQuoteEmbellishment(entry.obj, entry.cost);
        message = `${name}, price ${entry.cost} ${shopCurrency(entry.cost)}${stackEach}${suffix}`;
    }
    await setMessage(message, message.includes('  '));
    game._command_mode = null;
    chatConsumeTurn();
    return true;
}

async function beginChatCommand() {
    const preDirectionMessage = chatPreDirectionMessage();
    if (preDirectionMessage) {
        await setMessage(preDirectionMessage);
        game._command_mode = null;
        return;
    }
    if (await finishChatShopFloorQuote(chatShopFloorQuote())) return;
    await setMessage('Talk to whom? (in what direction)');
    game._command_mode = 'chatDirection';
}

function chatConsumeTurn() {
    game._process_command_time_now = 1;
    game.context ??= {};
    game.context.move = 1;
}

async function finishChatSteedTarget(steed) {
    if (tipHatMonsterHelpless(steed)) {
        await setMessage(`${chatMonsterName(steed, true)} seems not to notice you.`);
        game._command_mode = null;
        chatConsumeTurn();
        return;
    }

    const noise = tipHatMonsterNoise(steed, {
        visible: true,
        nameOverride: chatMonsterName(steed, true),
    });
    if (noise.handled) {
        await setMessage(noise.message, noise.message.includes('  '));
        game._command_mode = null;
        chatConsumeTurn();
        return;
    }
    if (noise.message) {
        await setMessage(noise.message, noise.message.includes('  '));
        game._command_mode = null;
        return;
    }
    game._pending_message = '';
    game._message_more = 0;
    game._command_mode = null;
}

async function finishChatMonsterTarget(mon, sound) {
    const visible = tipHatMonsterVisible(mon);
    if (tipHatMonsterHelpless(mon) && sound !== 'priest') {
        await setMessage(visible ? `${fireScrollMonsterName(mon)} seems not to notice you.` : '');
        game._command_mode = null;
        return;
    }

    chatClearTargetWaitStrategy(mon);
    if (!heroIsDeaf() && chatMonsterIsEating(mon)) {
        if (!visible) chatMapUnseenMonster(mon);
        await setMessage(`${chatMonsterName(mon, visible)} is eating noisily.`);
        game._command_mode = null;
        return;
    }
    if (heroIsDeaf()) {
        await setMessage(chatDeafResponseMessage(mon, visible));
        game._command_mode = null;
        return;
    }

    const noise = tipHatMonsterNoise(mon, { visible, offerCommandMode: true });
    if (!visible && !tipHatMonsterVisible(mon) && (noise.handled || noise.message || noise.mapInvisible))
        chatMapUnseenMonster(mon);

    if (noise.handled) {
        await setMessage(noise.message, noise.message.includes('  '));
        if (noise.commandMode) {
            game._command_mode = noise.commandMode;
            if (noise.demonBribe) {
                game._demon_bribe_mon = noise.demonBribe.mon;
                game._demon_bribe_demand = noise.demonBribe.demand;
                game._demon_bribe_prompt = noise.demonBribe.mon?._last_demon_bribe_prompt || 'How much will you offer?';
                game._demon_bribe_text = '';
            }
        } else {
            game._command_mode = null;
            chatConsumeTurn();
        }
        return;
    }
    if (noise.message) {
        await setMessage(noise.message, noise.message.includes('  '));
        game._command_mode = null;
        return;
    }
    game._pending_message = '';
    game._message_more = 0;
    game._command_mode = null;
}

function heroHasConflict() {
    const u = game.u || {};
    if (u.conflict || u.HConflict || u.EConflict || u._intrinsicConflict || u._extrinsicConflict)
        return true;
    const intrinsics = u.intrinsics || {};
    const extrinsics = u.extrinsics || {};
    const uprops = u.uprops || {};
    if (intrinsics.conflict || intrinsics.Conflict || extrinsics.conflict || extrinsics.Conflict)
        return true;
    if (uprops.conflict?.intrinsic || uprops.conflict?.extrinsic
        || uprops.CONFLICT?.intrinsic || uprops.CONFLICT?.extrinsic)
        return true;
    return (game.inventory || []).some(item => wornRingItem(item)
        && (Number(item.ringRoll ?? item.roll ?? 0) === 14
            || /\bring of conflict\b/i.test(String(item.actualKind || item.kind || item.line || ''))));
}

function tipHatMonsterHelpless(mon) {
    return !!(mon?.helpless || mon?.msleeping || mon?.mcanmove === false);
}

function tipHatMonsterSilent(mon) {
    const data = mon?.data || {};
    const explicit = mon?.msound ?? mon?.sound ?? data.msound ?? data.sound;
    const msound = String(explicit ?? '').toLowerCase();
    if (mon?.silent || data.silent || explicit === 0 || msound === 'silent' || msound === 'ms_silent')
        return true;
    if (explicit != null) return false;
    const name = String(data.name || mon?.name || '').toLowerCase();
    return tipHatGeneratedMonsterSound(name) === 'silent';
}

function tipHatHeroHasTopLevelGold() {
    if ((game._goldCount || 0) > 0) return true;
    return (game.inventory || []).some(item => item?.letter === '$'
        || item?.cls === 'coin' || item?.otyp === GOLD_PIECE || item?.glyph === '$');
}

function tipHatGoldStack(items = []) {
    return items.find(item => item?.letter === '$'
        || item?.cls === 'coin' || item?.otyp === GOLD_PIECE || item?.glyph === '$') || null;
}

function tipHatGoldCount(items = []) {
    const stack = tipHatGoldStack(items);
    return Math.max(0, Math.trunc(Number(stack?.quan || 0)));
}

function tipHatHeroGoldCount() {
    return Math.max(0, Math.trunc(Number(game._goldCount || 0))) || tipHatGoldCount(game.inventory || []);
}

function tipHatAddHeroGold(amount) {
    const gold = Math.max(0, Math.trunc(Number(amount || 0)));
    if (!gold) return;
    game._goldCount = Math.max(0, Math.trunc(Number(game._goldCount || 0))) + gold;
    const stack = tipHatGoldStack(game.inventory || []);
    if (stack) stack.quan = (stack.quan || 0) + gold;
    else game.inventory = [...(game.inventory || []), { letter: '$', cls: 'coin', otyp: GOLD_PIECE, glyph: '$', quan: gold }];
}

function tipHatHeroIsHealer() {
    return game._startup_role === 'Healer'
        || game.urole?.name?.m === 'Healer' || game.urole?.name?.f === 'Healer';
}

function tipHatInventoryKind(item) {
    return String(item?.actualKind || item?.kind || item?.line || '').toLowerCase();
}

function tipHatHeroWieldsNurseWeapon() {
    return (game.inventory || []).some(item => {
        if (!itemIsWielded(item)) return false;
        if (item.cls === 'weapon' || item.glyph === ')' || item.otyp === WEAPON_CLASS) return true;
        return item.cls === 'tool' && (isWeaponTool(item) || APPLY_WEAPON_NAME_RE.test(tipHatInventoryKind(item)));
    });
}

function tipHatIsShirtArmor(item) {
    return (item?.cls === 'armor' || item?.glyph === '[' || item?.otyp === ARMOR_CLASS)
        && /\b(?:shirt|t-shirt)\b/.test(tipHatInventoryKind(item));
}

function tipHatHeroWearsNurseArmor() {
    return (game.inventory || []).some(item => isWornArmorItem(item) && !tipHatIsShirtArmor(item));
}

function tipHatHeroWearsShirt() {
    return (game.inventory || []).some(item => isWornArmorItem(item) && tipHatIsShirtArmor(item));
}

function tipHatMonsterAdjacent(mon) {
    if (!mon) return false;
    return Math.max(Math.abs((mon.mx || 0) - (game.u?.ux || 0)),
        Math.abs((mon.my || 0) - (game.u?.uy || 0))) <= 1;
}

function tipHatMonsterIsMplayer(mon) {
    const data = mon?.data || {};
    return !!(mon?.mplayer || mon?.is_mplayer || mon?.isMplayer
        || data.mplayer || data.is_mplayer || data.isMplayer);
}

function tipHatNameTokens(value) {
    const name = String(value || '').toLowerCase();
    return name.replace(/[^a-z]+/g, ' ').trim();
}

function tipHatRaceFamiliesFrom(value, meta = {}) {
    const families = new Set();
    const name = tipHatNameTokens(value || meta.name || meta.data?.name);
    const rawMlet = String(meta.mlet || meta.data?.mlet || '');
    const rawGlyph = String(meta.glyph || meta.data?.glyph || '');
    const mlet = rawMlet.toLowerCase();
    if (meta.orc || meta.isOrc || meta.data?.orc || name === 'orcish'
        || /\b(?:orc|goblin|hobgoblin|uruk hai)\b/.test(name)
        || mlet === 'orc' || rawMlet === 'o' || rawGlyph === 'o')
        families.add('orc');
    if (meta.gnome || meta.isGnome || meta.data?.gnome
        || /\b(?:gnome|gnomish)\b/.test(name)
        || mlet === 'gnome' || rawMlet === 'G' || rawGlyph === 'G')
        families.add('gnome');
    if (meta.kobold || meta.isKobold || meta.data?.kobold || /\bkobold\b/.test(name)
        || mlet === 'kobold' || rawMlet === 'k' || rawGlyph === 'k')
        families.add('kobold');
    if (meta.demon || meta.isDemon || meta.data?.demon
        || /\b(?:yeenoghu|orcus|demon)\b/.test(name)
        || mlet === 'demon' || rawMlet === '&' || rawGlyph === '&')
        families.add('demon');
    return families;
}

function tipHatHeroRaceFamilies() {
    const form = polyselfForm() || game.u?._polyself_form || {};
    const families = tipHatRaceFamiliesFrom(form.name || form.race || form.roleName, form);
    for (const family of tipHatRaceFamiliesFrom(game.urace?.noun || game.urace?.adj || game._startup_race))
        families.add(family);
    return families;
}

function tipHatMonsterSharesHeroRace(mon, monName) {
    const heroFamilies = tipHatHeroRaceFamilies();
    if (!heroFamilies.size) return false;
    for (const family of tipHatRaceFamiliesFrom(monName, mon || {})) {
        if (heroFamilies.has(family)) return true;
    }
    return false;
}

const TIPHAT_MPLAYER_SAME_CLASS_MESSAGES = [
    "I can't win, and neither will you!",
    "You don't deserve to win!",
    "Mine should be the honor, not yours!",
];

const TIPHAT_MPLAYER_OTHER_CLASS_MESSAGES = [
    'The low-life wants to talk, eh?',
    'Fight, scum!',
    'Here is what I have to say!',
];

const TIPHAT_MPLAYER_ROLE_NAMES = [
    'archeologist', 'barbarian', 'caveman', 'healer', 'knight', 'monk', 'priest',
    'ranger', 'rogue', 'samurai', 'tourist', 'valkyrie', 'wizard',
];

function tipHatCanonicalRoleName(value) {
    const role = String(value || '').toLowerCase().replace(/[^a-z]/g, '');
    if (!role) return '';
    if (role === 'cavewoman') return 'caveman';
    if (role === 'priestess') return 'priest';
    return TIPHAT_MPLAYER_ROLE_NAMES.find(name => name.replace(/[^a-z]/g, '') === role) || '';
}

function tipHatMplayerRoleFromIndex(index) {
    if (!Number.isInteger(index)) return '';
    if (index >= 305 && index <= 317) return TIPHAT_MPLAYER_ROLE_NAMES[index - 305] || '';
    if (index >= 0 && index < TIPHAT_MPLAYER_ROLE_NAMES.length)
        return TIPHAT_MPLAYER_ROLE_NAMES[index] || '';
    return '';
}

function tipHatHeroRoleName() {
    const numeric = game.player?.roleMnum ?? game.u?.roleMnum ?? game.urole?.mnum;
    return tipHatMplayerRoleFromIndex(numeric)
        || tipHatCanonicalRoleName(game.urole?.name?.m || game._startup_role || game.urole?.name?.f);
}

function tipHatMonsterMplayerRole(mon, monName) {
    const data = mon?.data || {};
    const numeric = mon?.roleMnum ?? mon?.mnum ?? data.roleMnum ?? data.mnum ?? data.monsndx;
    return tipHatMplayerRoleFromIndex(numeric)
        || tipHatCanonicalRoleName(mon?.role || mon?.roleName || data.role || data.roleName || monName);
}

function tipHatMplayerTalk(mon, monName) {
    const monsterRole = tipHatMonsterMplayerRole(mon, monName);
    const heroRole = tipHatHeroRoleName();
    const sameClass = monsterRole && heroRole && monsterRole === heroRole;
    const messages = sameClass ? TIPHAT_MPLAYER_SAME_CLASS_MESSAGES : TIPHAT_MPLAYER_OTHER_CLASS_MESSAGES;
    return { handled: true, message: `"Talk? -- ${messages[rn2(3)]}"` };
}

function tipHatMonsterMlet(mon) {
    return String(mon?.data?.mlet ?? mon?.mlet ?? '').toLowerCase();
}

function tipHatMonsterHp(mon) {
    const hp = Number(mon?.mhp ?? mon?.hp ?? mon?.data?.mhp ?? mon?.data?.hp ?? NaN);
    const hpmax = Number(mon?.mhpmax ?? mon?.mhpMax ?? mon?.hpmax ?? mon?.hpMax
        ?? mon?.data?.mhpmax ?? mon?.data?.hpmax ?? NaN);
    return { hp, hpmax };
}

function tipHatMonsterTrapAt(mon) {
    return (game.level?.traps || []).find(trap => trap.tx === mon?.mx && trap.ty === mon?.my) || null;
}

function tipHatMonsterIsElf(mon, name) {
    const data = mon?.data || {};
    return !!(mon?.elf || data.elf || data.isElf || /\belf\b|(?:^|-| )elf$|elven/.test(name));
}

function tipHatMonsterIsDwarf(mon, name) {
    const data = mon?.data || {};
    return !!(mon?.dwarf || data.dwarf || data.isDwarf || /\bdwarf\b/.test(name));
}

function tipHatMonsterIsGnome(mon, name) {
    const data = mon?.data || {};
    const mlet = tipHatMonsterMlet(mon);
    return !!(mon?.gnome || data.gnome || data.isGnome || mlet === 'g' || /\b(?:gnome|gnomish)\b/.test(name));
}

const TIPHAT_MAGIC_MONSTER_NAMES = new Set(['kobold shaman', 'orc shaman', 'gnomish wizard']);

function tipHatMonsterLikesMagic(mon) {
    const data = mon?.data || {};
    const name = String(data.name || mon?.name || '').toLowerCase();
    return !!(mon?.likesMagic || mon?.magic || mon?.spellcaster
        || data.likesMagic || data.magic || data.spellcaster
        || TIPHAT_MAGIC_MONSTER_NAMES.has(name));
}

function tipHatMonsterIsMinion(mon) {
    return monsterIsMinion(mon);
}

function tipHatPeacefulHumanoidNoise(mon, name, monName, moves, hungryTime) {
    const { hp, hpmax } = tipHatMonsterHp(mon);
    const action = text => ({ handled: true, message: `${name} ${text}` });
    const verbal = text => ({ handled: true, message: `"${text}"` });
    if (mon.mflee) return action('wants nothing to do with you.');
    if (Number.isFinite(hp) && Number.isFinite(hpmax) && hp < hpmax / 4)
        return action('moans.');
    if (mon.mconf || mon.mstun) {
        if (!rn2(3)) return verbal('Huh?');
        return verbal(rn2(2) ? 'What?' : 'Eh?');
    }
    if (mon.mcansee === false) return verbal("I can't see!");
    if (mon.mtrapped) {
        const trap = tipHatMonsterTrapAt(mon);
        if (trap) trap.tseen = true;
        return verbal("I'm trapped!");
    }
    if (Number.isFinite(hp) && Number.isFinite(hpmax) && hp < hpmax / 2)
        return action('asks for a potion of healing.');
    if (Number(mon.mtame || 0) && !tipHatMonsterIsMinion(mon)
        && Number.isFinite(hungryTime) && moves > hungryTime)
        return verbal("I'm hungry.");
    if (tipHatMonsterIsElf(mon, monName)) return action('curses orcs.');
    if (tipHatMonsterIsDwarf(mon, monName)) return action('talks about mining.');
    if (tipHatMonsterLikesMagic(mon)) return action('talks about spellcraft.');
    if (tipHatMonsterMlet(mon) === 'centaur' || tipHatMonsterMlet(mon) === 'c')
        return action('discusses hunting.');
    if (tipHatMonsterIsGnome(mon, monName)) {
        if (heroIsHallucinating()) {
            const gnomeplan = rn2(4);
            if (gnomeplan % 2)
                return verbal(gnomeplan === 1
                    ? 'Phase one, collect underpants.'
                    : 'Phase three, profit!');
        }
        return verbal('Many enter the dungeon, and few return to the sunlit lands.');
    }
    if (monName === 'hobbit') {
        return (Number.isFinite(hp) && Number.isFinite(hpmax) && hp < hpmax
            && (hpmax <= 10 || hp <= hpmax - 10))
            ? action('complains about unpleasant dungeon conditions.')
            : action('asks you about the One Ring.');
    }
    if (monName === 'archeologist')
        return action('describes a recent article in "Spelunker Today" magazine.');
    if (monName === 'tourist') return verbal('Aloha.');
    return action('discusses dungeon exploration.');
}

