const TIPHAT_HALLUCINATED_MONSTER_PRONOUNS = [
    { subject: 'he', object: 'him' },
    { subject: 'she', object: 'her' },
    { subject: 'it', object: 'it' },
    { subject: 'they', object: 'them' },
];

function tipHatHallucinatedMonsterPronoun(key) {
    const pronouns = TIPHAT_HALLUCINATED_MONSTER_PRONOUNS[rn2(TIPHAT_HALLUCINATED_MONSTER_PRONOUNS.length)];
    return pronouns[key];
}

function tipHatShopkeeperSellSubjectPronoun(mon) {
    return heroIsHallucinating() ? tipHatHallucinatedMonsterPronoun('subject') : shopkeeperSubjectPronoun(mon);
}

function tipHatShopkeeperSellObjectivePronoun(mon) {
    return heroIsHallucinating() ? tipHatHallucinatedMonsterPronoun('object') : shopkeeperObjectivePronoun(mon);
}

function tipHatLawfulDeityName() {
    const roleName = game.urole?.name?.m || game._startup_role || 'Archeologist';
    const pantheonRole = roleName === 'Priest' ? game._pantheon_role || roleName : roleName;
    return (GODS_BY_ROLE[pantheonRole] || GODS_BY_ROLE.Archeologist)[0] || 'Marduk';
}

function tipHatCommonPagerLine(messages) {
    const line = messages[rn2(messages.length)] || '';
    return line
        .split('%D').join(tipHatLawfulDeityName())
        .split('%p').join(game.plname || 'Hero');
}

function tipHatMonsterIsLawfulMinion(mon) {
    const data = mon?.data || {};
    const renegade = !!(mon?.renegade || mon?.mextra?.emin?.renegade || mon?.emin?.renegade
        || data.renegade || data.mextra?.emin?.renegade || data.emin?.renegade);
    if (mon?.lminion || mon?.is_lminion || mon?.isLminion
        || data.lminion || data.is_lminion || data.isLminion)
        return !renegade;
    const minion = tipHatMonsterIsMinion(mon);
    const align = Number(mon?.min_align ?? mon?.align ?? mon?.alignment
        ?? data.min_align ?? data.align ?? data.alignment ?? data.maligntyp ?? 0);
    return minion && align > A_NEUTRAL && !renegade;
}

function tipHatMonsterIsWizardCuss(mon, monName) {
    const data = mon?.data || {};
    return !!(mon?.iswiz || mon?.isWizard || data.iswiz || data.isWizard
        || monName === 'wizard of yendor');
}

function tipHatHostileCussNoise(mon, name, monName) {
    const monHp = Number(mon?.mhp ?? mon?.hp ?? mon?.data?.mhp ?? NaN);
    let message = '';
    if (tipHatMonsterIsWizardCuss(mon, monName)) {
        if (!rn2(5)) {
            message = `${name} laughs fiendishly.`;
        } else if (game.u?.uhave?.amulet && !rn2(TIPHAT_CUSS_RANDOM_INSULTS.length)) {
            message = `"Relinquish the amulet, ${TIPHAT_CUSS_RANDOM_INSULTS[rn2(TIPHAT_CUSS_RANDOM_INSULTS.length)]}!"`;
        } else if ((game.u?.uhp || 0) < 5 && !rn2(2)) {
            message = rn2(2)
                ? `"Even now thy life force ebbs, ${TIPHAT_CUSS_RANDOM_INSULTS[rn2(TIPHAT_CUSS_RANDOM_INSULTS.length)]}!"`
                : `"Savor thy breath, ${TIPHAT_CUSS_RANDOM_INSULTS[rn2(TIPHAT_CUSS_RANDOM_INSULTS.length)]}, it be thy last!"`;
        } else if (Number.isFinite(monHp) && monHp < 5 && !rn2(2)) {
            message = rn2(2) ? '"I shall return."' : '"I\'ll be back."';
        } else {
            message = `"${TIPHAT_CUSS_RANDOM_MALEDICTIONS[rn2(TIPHAT_CUSS_RANDOM_MALEDICTIONS.length)]} ${TIPHAT_CUSS_RANDOM_INSULTS[rn2(TIPHAT_CUSS_RANDOM_INSULTS.length)]}!"`;
        }
    } else if (tipHatMonsterIsLawfulMinion(mon)) {
        message = tipHatCommonPagerLine(TIPHAT_ANGEL_CUSS_MESSAGES);
    } else if (!rn2(tipHatMonsterIsMinion(mon) ? 100 : 5)) {
        message = `${name} casts aspersions on your ancestry.`;
    } else {
        message = tipHatCommonPagerLine(TIPHAT_DEMON_CUSS_MESSAGES);
    }
    const wakeMessages = tipHatWakeNearby(mon, 5 * 5);
    return { handled: true, message: [message, ...wakeMessages].filter(Boolean).join('  ') };
}

export function monsterHostileCussNoise(mon, name = null) {
    const monName = String(mon?.data?.name || mon?.name || '').toLowerCase();
    return tipHatHostileCussNoise(mon, name || fireScrollMonsterName(mon), monName);
}

function tipHatPeacefulCussNoise(mon) {
    return {
        handled: true,
        message: tipHatMonsterIsLawfulMinion(mon) ? `"It's not too late."` : `"We're all doomed."`,
    };
}

function tipHatHeroWieldsDemonBribeArtifact() {
    return (game.inventory || []).some(item => {
        if (!itemIsWielded(item)) return false;
        const name = String(item.artifact || item.oartifact || artifactObjectName(item)
            || item.actualKind || item.kind || item.line || '').toLowerCase();
        return /\b(?:excalibur|demonbane)\b/.test(name);
    });
}

function tipHatHeroIsDemonPolyself() {
    const form = polyselfForm();
    if (!form) return false;
    return tipHatRaceFamiliesFrom(form.name || form.race || form.roleName, form).has('demon');
}

function tipHatDemonBribeSetHostile(mon) {
    if (!mon) return;
    mon.mpeaceful = 0;
    mon.peaceful = false;
    mon.mtame = 0;
    mon.tame = 0;
    mon.hostile = true;
    set_malign(mon);
    newsym(mon.mx, mon.my);
}

function tipHatDemonBribeAtHome(mon) {
    const inHell = !!game.inhell
        || game.dungeons?.[game.u?.uz?.dnum]?.name === 'Gehennom'
        || !!game.level?.flags?.gehennom;
    return inHell && !(mon?.cham || mon?.mcham || mon?.data?.cham);
}

function tipHatDemonBribeAlignmentFactor(mon) {
    const heroSign = Math.sign(Number(game.u?.ualign?.type ?? A_NEUTRAL));
    const monSign = Math.sign(Number(mon?.data?.maligntyp ?? mon?.maligntyp ?? 0));
    return 1 + (heroSign === monSign ? 1 : 0);
}

function tipHatMonsterHasAmulet(mon) {
    return (mon?.minvent || []).some(item => {
        const name = String(item.actualKind || item.kind || item.artifact || item.line || '').toLowerCase();
        if (/\bcheap plastic imitation\b/.test(name)) return false;
        return item.realAmuletOfYendor || name === 'amulet of yendor' || /\bamulet of yendor\b/.test(name);
    });
}

function tipHatDemonBribeDemand(mon, cash) {
    const homeBonus = tipHatDemonBribeAtHome(mon) ? 20 : 0;
    let demand = Math.trunc((cash * (rnd(80) + homeBonus))
        / (100 * tipHatDemonBribeAlignmentFactor(mon)));
    if (demand > 0 && (tipHatMonsterHasAmulet(mon) || heroIsDeaf())) demand = cash + rn1(1000, 125);
    return demand;
}

export function monsterTurnDemonBribeNoGold(mon) {
    if (!mon || tipHatHeroWieldsDemonBribeArtifact() || tipHatHeroIsDemonPolyself())
        return false;
    const cash = tipHatHeroGoldCount();
    if (cash > 0) return false;
    const revealMessage = tipHatDemonBribeReveal(mon);
    const demand = tipHatDemonBribeDemand(mon, cash);
    mon._last_demon_bribe_demand = demand;
    if (demand) return false;
    tipHatDemonBribeSetHostile(mon);
    return { handled: true, message: revealMessage };
}

export function monsterTurnDemonBribeArtifact(mon) {
    if (!mon || !tipHatHeroWieldsDemonBribeArtifact()) return false;
    const message = tipHatMonsterVisible(mon)
        ? `${fireScrollMonsterName(mon)} looks very angry.`
        : 'You feel tension building.';
    tipHatDemonBribeSetHostile(mon);
    return { handled: true, message };
}

export function monsterTurnDemonBribeDemand(mon) {
    if (!mon || tipHatHeroWieldsDemonBribeArtifact() || tipHatHeroIsDemonPolyself())
        return false;
    const cash = tipHatHeroGoldCount();
    if (cash <= 0) return false;
    const revealMessage = tipHatDemonBribeReveal(mon);
    const demand = tipHatDemonBribeDemand(mon, cash);
    mon._last_demon_bribe_demand = demand;
    if (!demand || (game._helpless_time || 0) > 0) {
        tipHatDemonBribeSetHostile(mon);
        return { handled: true, message: revealMessage, continueTurn: true };
    }

    const speakerName = fireScrollMonsterName(mon);
    if (heroIsDeaf()) {
        const messages = [revealMessage];
        if (tipHatMonsterVisible(mon))
            messages.push(`${speakerName} seems to be demanding something.`);
        messages.push(`${speakerName} gets angry...`);
        tipHatDemonBribeSetHostile(mon);
        return { handled: true, message: messages.filter(Boolean).join('  '), continueTurn: true };
    }

    const prompt = 'How much will you offer?';
    mon._last_demon_bribe_prompt = prompt;
    const demandMessage = `${speakerName} demands ${demand} ${shopCurrency(demand)} for safe passage.  ${prompt}`;
    return {
        handled: true,
        message: [revealMessage, demandMessage].filter(Boolean).join('  '),
        commandMode: 'demonBribeOffer',
        demonBribe: { mon, demand },
    };
}

function tipHatDemonBribeIsPrince(mon) {
    const data = mon?.data || {};
    return !!(mon?.demonPrince || mon?.isDemonPrince || data.demonPrince || data.isDemonPrince);
}

function tipHatDemonBribeReveal(mon) {
    if (!tipHatDemonBribeIsPrince(mon) || !mon?.minvis) return '';
    const wasUnseen = !tipHatMonsterVisible(mon);
    mon.minvis = 0;
    mon.perminvis = 0;
    mon.invisible = 0;
    if (Number.isInteger(mon.mstrategy)) mon.mstrategy &= ~STRAT_APPEARMSG;
    newsym(mon.mx, mon.my);
    if (wasUnseen && tipHatMonsterVisible(mon)) return `${fireScrollMonsterName(mon)} appears before you.`;
    return '';
}

function tipHatDemonRelocationSuffix(x, y, oldX, oldY) {
    const heroX = game.u?.ux ?? 0;
    const heroY = game.u?.uy ?? 0;
    const du = (x - heroX) * (x - heroX) + (y - heroY) * (y - heroY);
    if (du <= 2) return ' next to you';
    if (du <= BOLT_LIM * BOLT_LIM) return ' close by';
    const oldDu = (oldX - heroX) * (oldX - heroX) + (oldY - heroY) * (oldY - heroY);
    if (oldDu === du) return '';
    return du < oldDu ? ' closer to you' : ' farther away';
}

function tipHatDemonBribeRelocate(mon) {
    if (!mon) return '';
    const name = fireScrollMonsterName(mon);
    const wasVisible = tipHatMonsterVisible(mon);
    if (noteleportLevelForMonster(mon))
        return wasVisible ? `A mysterious force prevents ${demonBribeObjectName(mon)} from teleporting!` : '';

    const oldX = mon.mx;
    const oldY = mon.my;
    if (!rlocNoMsg(mon)) return '';
    newsym(oldX, oldY);
    newsym(mon.mx, mon.my);

    const nowVisible = tipHatMonsterVisible(mon);
    if (wasVisible && nowVisible)
        return `${name} vanishes and reappears${tipHatDemonRelocationSuffix(mon.mx, mon.my, oldX, oldY)}.`;
    if (wasVisible) return `${name} vanishes!`;
    if (nowVisible) return `${name} appears${tipHatDemonRelocationSuffix(mon.mx, mon.my, oldX, oldY)}!`;
    return '';
}

function demonBribeOfferValue(text) {
    const match = String(text || '').match(/^\s*([+-]?\d+)/);
    return match ? Math.trunc(Number(match[1])) : 0;
}

function demonBribeObjectName(mon) {
    return fireScrollMonsterName(mon).replace(/^The /, '');
}

function demonBribeGiveGold(mon, amount) {
    const paid = removeGoldFromHero(amount);
    if (paid > 0)
        add_to_minv(mon, { cls: 'coin', otyp: GOLD_PIECE, glyph: '$', quan: paid });
    return paid;
}

function demonBribeVanish(mon) {
    removeMonsterFromLevel(mon);
    mon.dead = true;
    mon.minvent = [];
}

function clearDemonBribeOfferState() {
    game._demon_bribe_mon = null;
    game._demon_bribe_demand = 0;
    game._demon_bribe_prompt = '';
    game._demon_bribe_text = '';
    game._demon_bribe_monster_turn = null;
    game._demon_bribe_offer_after_more = 0;
}

async function finishDemonBribeOffer() {
    const mon = game._demon_bribe_mon;
    const demand = Math.max(0, Math.trunc(Number(game._demon_bribe_demand || mon?._last_demon_bribe_demand || 0)));
    let offer = demonBribeOfferValue(game._demon_bribe_text);
    const monsterTurn = game._demon_bribe_monster_turn || null;
    clearDemonBribeOfferState();
    game._command_mode = null;
    if (!mon || !demand) {
        await setMessage('');
        if (!monsterTurn) chatConsumeTurn();
        return;
    }

    const objectName = demonBribeObjectName(mon);
    const sentenceName = fireScrollMonsterName(mon);
    const messages = [];
    let paidOff = false;
    if (offer < 0) {
        messages.push(`You try to shortchange ${objectName}, but fumble.`);
        offer = 0;
    } else if (offer === 0) {
        messages.push('You refuse.');
    } else {
        const available = tipHatHeroGoldCount();
        if (offer >= available) {
            messages.push(`You give ${objectName} all your gold.`);
            offer = available;
        } else {
            messages.push(`You give ${objectName} ${offer} ${shopCurrency(offer)}.`);
        }
        offer = demonBribeGiveGold(mon, offer);
    }
    mon._last_demon_bribe_offer = offer;

    if (offer >= demand) {
        messages.push(`${sentenceName} vanishes, laughing about cowardly mortals.`);
        if (monsterTurn) {
            game._monster_resume_index = adjustedMonsterResumeIndexForRemoval(mon, monsterTurn.nextIndex ?? 0);
            game._monster_resume_somebody_can_move = !!monsterTurn.somebodyCanMove;
        }
        demonBribeVanish(mon);
        paidOff = true;
    } else if (offer > 0 && rnd(5 * (game.u?.acurr?.a?.[A_CHA] ?? 10)) > demand - offer) {
        messages.push(`${sentenceName} scowls at you menacingly, then vanishes.`);
        if (monsterTurn) {
            game._monster_resume_index = adjustedMonsterResumeIndexForRemoval(mon, monsterTurn.nextIndex ?? 0);
            game._monster_resume_somebody_can_move = !!monsterTurn.somebodyCanMove;
        }
        demonBribeVanish(mon);
        paidOff = true;
    } else {
        messages.push(`${sentenceName} gets angry...`);
        tipHatDemonBribeSetHostile(mon);
        if (monsterTurn) {
            game._monster_resume_index = monsterTurn.resumeIndex ?? 0;
            game._monster_resume_somebody_can_move = !!monsterTurn.somebodyCanMove;
            game._monster_resume_same_index = 1;
            game._monster_resume_after_preturn = 1;
        }
    }

    await setMessage(messages.join('  '), messages.length > 1);
    if (monsterTurn) {
        game._pending_time_passed = Math.max(game._pending_time_passed || 0, 1);
        game.context ??= {};
        game.context.move = 0;
        game._process_command_time_now = 1;
        if (paidOff && !game._monster_resume_index)
            game._monster_resume_somebody_can_move = !!monsterTurn.somebodyCanMove;
    } else {
        chatConsumeTurn();
    }
}

function tipHatDemonBribeNoise(mon, name, visible, offerCommandMode = false) {
    if (tipHatHeroWieldsDemonBribeArtifact()) {
        tipHatDemonBribeSetHostile(mon);
        return {
            handled: true,
            message: visible ? `${name} looks very angry.` : 'You feel tension building.',
        };
    }

    const revealMessage = tipHatDemonBribeReveal(mon);
    const speakerName = revealMessage ? fireScrollMonsterName(mon) : name;

    if (tipHatHeroIsDemonPolyself()) {
        const relocationMessage = tipHatDemonBribeRelocate(mon);
        return {
            handled: true,
            message: [
                revealMessage,
                `${speakerName} says, "Good hunting, ${game.flags?.female ? 'Sister' : 'Brother'}."`,
                relocationMessage,
            ].filter(Boolean).join('  '),
        };
    }

    const cash = tipHatHeroGoldCount();
    const demand = tipHatDemonBribeDemand(mon, cash);
    mon._last_demon_bribe_demand = demand;
    if (!demand) {
        tipHatDemonBribeSetHostile(mon);
        return { handled: true, message: revealMessage };
    }

    if (offerCommandMode) mon._last_demon_bribe_prompt = 'How much will you offer?';
    const demandMessage = `${speakerName} demands ${demand} ${shopCurrency(demand)} for safe passage.${offerCommandMode ? '  How much will you offer?' : ''}`;
    return {
        handled: true,
        ...(offerCommandMode ? {
            commandMode: 'demonBribeOffer',
            demonBribe: { mon, demand },
        } : {}),
        message: [revealMessage, demandMessage].filter(Boolean).join('  '),
    };
}

function tipHatMonsterIsShopkeeperType(mon, monName = '') {
    const data = mon?.data || {};
    const name = String(monName || data.name || mon?.name || '').toLowerCase();
    return !!(data.shopkeeper || mon?.shopkeeper || name === 'shopkeeper');
}

function tipHatMonsterIsPriestType(mon, monName = '') {
    const data = mon?.data || {};
    const name = String(monName || data.name || mon?.name || '').toLowerCase();
    return !!(mon?.ispriest || mon?.priest || data.priest
        || /^(?:aligned cleric|high cleric|high priest|high priestess)$/.test(name));
}

function tipHatShopkeeperIsAngry(mon) {
    return !!(mon?.hostile || mon?.mpeaceful === 0 || mon?.mpeaceful === false || mon?.angry);
}

function tipHatResidentShopkeeperSellNoise(mon) {
    const canSpeak = shopkeeperCanSpeakToHero(mon);
    if (tipHatShopkeeperIsAngry(mon)) {
        const customerType = shopkeeperRobbedAmount(mon) > 0 ? 'non-paying' : 'rude';
        return { handled: true, message: `${shopkeeperSentenceName(mon)} ${canSpeak ? 'mentions' : 'indicates'} how much ${tipHatShopkeeperSellSubjectPronoun(mon)} dislikes ${customerType} customers.` };
    }
    if (mon?.following) {
        const player = String(game.plname || 'Hero');
        const customer = String(mon?.customer || '');
        if (customer !== player) {
            mon.following = 0;
            if (!canSpeak) return { handled: true, message: '' };
            return { handled: true, message: `"${shopkeeperHello(mon)} ${player}!  I was looking for ${customer}."` };
        }
        if (!canSpeak) return { handled: true, message: `${shopkeeperSentenceName(mon)} taps you on the arm.` };
        return { handled: true, message: `"${shopkeeperHello(mon)} ${player}!  Didn't you forget to pay?"` };
    }
    const debit = Math.trunc(Number(mon?.debit || 0));
    if (shopBillEntryCount(mon) > 0) {
        const total = shopBillTotal(mon) + debit;
        return { handled: true, message: `${shopkeeperSentenceName(mon)} ${canSpeak ? 'says' : 'indicates'} that your bill comes to ${total} ${shopCurrency(total)}.` };
    }
    if (debit > 0)
        return { handled: true, message: `${shopkeeperSentenceName(mon)} ${canSpeak ? 'reminds you' : 'indicates'} that you owe ${tipHatShopkeeperSellObjectivePronoun(mon)} ${debit} ${shopCurrency(debit)}.` };
    const credit = Math.trunc(Number(mon?.credit || 0));
    if (credit > 0)
        return { handled: true, message: `${shopkeeperSentenceName(mon)} encourages you to use your ${credit} ${shopCurrency(credit)} of credit.` };
    const shkmoney = shopkeeperCash(mon);
    if (Math.trunc(Number(mon?.robbed || 0)) > 0)
        return { handled: true, message: `${shopkeeperSentenceName(mon)} ${canSpeak ? 'complains' : 'indicates concern'} about a recent robbery.` };
    if (Math.trunc(Number(mon?.surcharge || 0)) > 0)
        return { handled: true, message: `${shopkeeperSentenceName(mon)} ${canSpeak ? 'warns you' : 'indicates'} that ${tipHatShopkeeperSellSubjectPronoun(mon)} is watching you carefully.` };
    if (shkmoney < 50)
        return { handled: true, message: `${shopkeeperSentenceName(mon)} ${canSpeak ? 'complains' : 'indicates'} that business is bad.` };
    if (shkmoney > 4000)
        return { handled: true, message: `${shopkeeperSentenceName(mon)} ${canSpeak ? 'says' : 'indicates'} that business is good.` };
    if (!heroIsHallucinating() && shopkeeperIsIzchak(mon) && shopkeeperInTown(mon)) {
        if (!canSpeak) return { handled: true, message: '' };
        const name = shopkeeperDisplayName(mon);
        const message = TIPHAT_IZCHAK_SELL_MESSAGES[rn2(TIPHAT_IZCHAK_SELL_MESSAGES.length)](name);
        return { handled: true, message };
    }
    if (!canSpeak) return { handled: true, message: '' };
    return { handled: true, message: `${shopkeeperSentenceName(mon)} talks about the problem of shoplifters.` };
}

function tipHatShopkeeperSellNoise(mon, name) {
    if (!mon?.isshk && tipHatMonsterIsShopkeeperType(mon))
        return { handled: true, message: `${name} asks whether you've seen any untended shops recently.` };
    if (mon?.isshk)
        return tipHatResidentShopkeeperSellNoise(mon);
    return { handled: false, message: '' };
}

const TIPHAT_PRIEST_CRANKY_MESSAGES = [
    "Thou wouldst have words, eh?  I'll give thee a word or two!",
    'Talk?  Here is what I have to say!',
    'Pilgrim, I would speak no longer with thee.',
];

function tipHatPriestAlign(mon) {
    const data = mon?.data || {};
    const value = mon?.shrine?.align ?? mon?.min_align ?? mon?.align ?? mon?.alignment
        ?? data.min_align ?? data.align ?? data.alignment ?? data.maligntyp;
    const align = Number(value);
    return Number.isFinite(align) ? align : A_NEUTRAL;
}

function tipHatPriestCoaligned(mon) {
    return Number(game.u?.ualign?.type ?? A_NEUTRAL) === tipHatPriestAlign(mon);
}

function tipHatPriestHasShrine(priest) {
    const shrine = priest?.shrine;
    const loc = shrine ? game.level?.at?.(shrine.x, shrine.y) : null;
    if (!priest?.ispriest || !shrine || loc?.typ !== ALTAR) return false;
    const mask = loc.flags ?? loc.altarmask ?? 0;
    if (!(mask & AM_SHRINE)) return false;
    return shrine.align === Amask2align(mask & ~AM_SHRINE);
}

function tipHatPriestInTempleRoom(priest) {
    const shrine = priest?.shrine;
    if (!priest?.ispriest || !shrine) return false;
    return game.level?.at?.(priest.mx, priest.my)?.roomno === shrine.room;
}

function tipHatPriestInHisTemple(priest) {
    return tipHatPriestInTempleRoom(priest) && tipHatPriestHasShrine(priest);
}

function tipHatTransferPriestAleMoney(priest) {
    const goldStack = tipHatGoldStack(priest?.minvent || []);
    const pmoney = Math.max(0, Math.trunc(Number(goldStack?.quan || 0)));
    if (!pmoney) return 0;
    const amount = pmoney > 1 ? 2 : 1;
    goldStack.quan = Math.max(0, pmoney - amount);
    if (!goldStack.quan)
        priest.minvent = (priest.minvent || []).filter(item => item !== goldStack);
    tipHatAddHeroGold(amount);
    return pmoney;
}

function tipHatRejectAtheismByPriestConsult() {
    game.u ??= {};
    game.u.uconduct ??= {};
    game.u.uconduct.gnostic = Math.max(0, Math.trunc(Number(game.u.uconduct.gnostic || 0))) + 1;
}

function tipHatPriestNoise(priest, name) {
    tipHatRejectAtheismByPriestConsult();
    const coaligned = tipHatPriestCoaligned(priest);
    const strayed = Number(game.u?.ualign?.record ?? 0) < 0;
    if (priest.mflee || (!priest.ispriest && coaligned && strayed)) {
        priest.mpeaceful = 0;
        return { handled: true, message: `${name} doesn't want anything to do with you!` };
    }

    const helpless = tipHatMonsterHelpless(priest);
    if (!tipHatPriestInHisTemple(priest) || !priest.mpeaceful || helpless) {
        const messages = [];
        if (helpless) {
            messages.push(`${name} breaks out of ${tipHatMonsterPossessive(priest)} reverie!`);
            priest.mfrozen = 0;
            priest.msleeping = 0;
            priest.mcanmove = true;
        }
        priest.mpeaceful = 0;
        messages.push(`"${TIPHAT_PRIEST_CRANKY_MESSAGES[rn2(3)]}"`);
        return { handled: true, message: messages.join('  ') };
    }

    if (priest.mpeaceful && tipHatPriestInTempleRoom(priest) && !tipHatPriestHasShrine(priest)) {
        priest.mpeaceful = 0;
        return {
            handled: true,
            message: '"Begone!  Thou desecratest this holy place with thy presence."',
        };
    }

    if (!tipHatHeroGoldCount()) {
        if (coaligned && !strayed) {
            const pmoney = tipHatTransferPriestAleMoney(priest);
            if (pmoney > 0) {
                const bits = heroIsHallucinating()
                    ? shopCurrency(pmoney)
                    : pmoney === 1 ? 'bit' : 'bits';
                return { handled: true, message: `${name} gives you ${pmoney === 1 ? 'one ' : 'two '}${bits} for an ale.` };
            }
            return { handled: true, message: `${name} preaches the virtues of poverty.` };
        }
        return { handled: true, message: `${name} is not interested.` };
    }

    const cheapskate = Math.max(0, Math.trunc(Number(priest.cheapskate_count ?? priest.cheapskateCount ?? 0)));
    const peak = Math.max(1, Math.trunc(Number(game.u?.ulevelpeak || game.u?.ulevel || 1)));
    const suggested = peak * rn1(101, 150 + cheapskate * 40);
    const quan = Math.max(1, Math.trunc(tipHatHeroGoldCount() / (suggested * 3)));
    priest._last_priest_suggested = suggested;
    priest._last_priest_offer_prompt = `How much will you offer (suggested: ${suggested * quan} or ${suggested * quan * 2})?`;
    return { handled: true, message: `${name} asks you for a contribution for the temple.` };
}

function tipHatMonsterIsHumanWereForm(mon, monName, mlet) {
    const data = mon?.data || {};
    if (!/^(?:were(?:rat|jackal|wolf))$/.test(monName)) return false;
    if (mon?.wereBeast || data.wereBeast) return false;
    return !!(mon?.wereHuman || data.wereHuman || data.humanoid || data.human
        || mlet === '@' || mlet === 'human' || mlet === 'humanoid');
}

function tipHatMonsterIsVampireInOwnForm(monName) {
    return /^vampire(?: (?:lord|lady|leader|mage))?$/.test(monName) || monName === 'vlad the impaler';
}

const TIPHAT_MUMBLE_MONSTER_NAMES = new Set([
    'lich', 'demilich', 'master lich', 'arch-lich', 'salamander',
]);

function tipHatMonsterHasOrcSound(mon, name) {
    if (PROPER_NAME_MS_ORC_MONSTER_NAMES.has(name)) return true;
    const families = tipHatRaceFamiliesFrom(name, mon || {});
    return families.has('orc') || families.has('gnome') || families.has('kobold');
}

function tipHatMonsterSound(mon) {
    const data = mon?.data || {};
    const name = String(data.name || mon?.name || '').toLowerCase();
    const mlet = String(data.mlet || mon?.mlet || '').toLowerCase();
    if (mon?.isshk) return 'sell';
    const explicit = mon?.msound ?? mon?.sound ?? data.msound ?? data.sound;
    if (explicit != null) return String(explicit).toLowerCase().replace(/^ms_/, '');
    if (mon?.nemesis || data.nemesis) return 'nemesis';
    if (tipHatMonsterIsShopkeeperType(mon, name)) return 'sell';
    if (tipHatMonsterIsPriestType(mon, name)) return 'priest';
    {
        const generatedSound = tipHatGeneratedMonsterSound(name);
        if (generatedSound) return generatedSound;
    }
    if (name === 'skeleton') return 'bones';
    if (/^(death|pestilence|famine)$/.test(name)) return 'rider';
    if (tipHatMonsterIsWizardCuss(mon, name)) return 'cuss';
    if (/\bzombie$/.test(name) || (mlet === 'zombie' && name !== 'ghoul')) return 'groan';
    if (tipHatMonsterHasOrcSound(mon, name)) return 'orc';
    if (/^(gremlin|leprechaun)$/.test(name)) return 'laugh';
    if (name === 'shrieker') return 'shriek';
    if (/^(mumak|mastodon)$/.test(name)) return 'trumpet';
    if (/^(rothe|minotaur)$/.test(name)) return 'moo';
    if (/^(raven|tengu)$/.test(name)) return 'sqawk';
    if (/^(leocrotta|aleax|doppelganger)$/.test(name)) return 'imitate';
    if (TIPHAT_MUMBLE_MONSTER_NAMES.has(name) || /\bnaga\b/.test(name)) return 'mumble';
    if (name === 'ki-rin') return 'spell';
    if (name === 'oracle') return 'oracle';
    if (name === 'imp') return 'cuss';
    if (name === 'amorous demon') return 'seduce';
    if (tipHatMonsterIsNymph(mon, name, mlet)) return 'seduce';
    if (tipHatMonsterIsHumanWereForm(mon, name, mlet)) return 'were';
    if (tipHatMonsterIsVampireInOwnForm(name)) return 'vampire';
    if (TIPHAT_BOAST_MONSTER_NAMES.has(name)) return 'boast';
    if (/^(pony|horse|warhorse|white unicorn|gray unicorn|black unicorn)$/.test(name)
        || mlet === 'quadruped' || mlet === 'unicorn')
        return 'neigh';
    if (/^(jackal|fox|coyote|little dog|dog|large dog|dingo|wolf|werejackal|werewolf|winter wolf cub|winter wolf|warg)$/.test(name)
        || mlet === 'dog')
        return 'bark';
    if (/^(kitten|housecat|large cat|jaguar|lynx|panther)$/.test(name)
        || mlet === 'f' || mlet === 'feline')
        return 'mew';
    if (name === 'gecko') return 'sqeek';
    if (mlet === 'rodent' || /rat|mouse/.test(name)) return 'sqeek';
    if (mlet === 'snake' || /snake|viper|cobra/.test(name)) return 'hiss';
    return '';
}

function tipHatMonsterAppearsAsGecko(mon) {
    if (!mon) return false;
    const name = String(mon.data?.name || mon.name || '').toLowerCase();
    if (name === 'gecko') return true;
    const loc = game.level?.at?.(mon.mx, mon.my);
    const index = loc?.hallucinated_monster_index;
    return Number.isInteger(index) && DISPLAY_MONSTER_HALLU_NAMES[index] === 'gecko';
}

function tipHatIsNight() {
    if (game.flags?.night || game.flags?.isnight) return true;
    const hourValue = game.flags?.hour ?? game.hour ?? game.context?.hour;
    const datetime = String(game._datetime || '');
    const hour = hourValue == null
        ? (/^\d{10}/.test(datetime) ? Number(datetime.slice(8, 10)) : NaN)
        : Number(hourValue);
    return Number.isFinite(hour) && (hour < 6 || hour > 21);
}

function tipHatIsMidnight() {
    const hourValue = game.flags?.hour ?? game.hour ?? game.context?.hour;
    const datetime = String(game._datetime || '');
    const hour = hourValue == null
        ? (/^\d{10}/.test(datetime) ? Number(datetime.slice(8, 10)) : NaN)
        : Number(hourValue);
    return hour === 0;
}

function tipHatHeroVampireKindred() {
    return /^(?:vampire|vampire lord|vampire leader|vampire lady)$/.test(polyselfFormName());
}

function tipHatHeroNightChild() {
    return /^(?:wolf|winter wolf|winter wolf cub)$/.test(polyselfFormName());
}

function tipHatHeroRaceNoun() {
    const race = game.urace || {};
    const individual = race.individual || {};
    if (game.flags?.female && individual.f) return individual.f;
    return individual.m || race.noun || game._startup_race || 'human';
}

function tipHatHeroBloodPart() {
    const form = polyselfForm() || {};
    const name = polyselfFormName();
    const mlet = String(form.mlet || form.glyph || '').toLowerCase();
    if (form.light || mlet === 'light' || /^(?:yellow|black) light$/.test(name)) return 'beam';
    if (form.spider || mlet === 'spider' || /spider/.test(name)) return 'hemolymph';
    if (form.vortex || form.elemental || form.sphere || mlet === 'vortex'
        || mlet === 'elemental' || mlet === 'eye' || /(?:vortex|elemental|sphere|eye)$/.test(name))
        return 'life force';
    if (form.fungus || mlet === 'fungus' || /(?:mold|lichen|fungus|toadstool)$/.test(name))
        return 'juices';
    if (form.jelly || form.pudding || form.blob || mlet === 'jelly'
        || mlet === 'pudding' || mlet === 'blob' || /(?:jelly|pudding|blob|ooze)$/.test(name))
        return 'juices';
    return 'blood';
}

function tipHatMonsterHungryTime(mon) {
    return Number(mon?.hungrytime ?? mon?.hungryTime ?? mon?.edog?.hungrytime
        ?? mon?.mextra?.edog?.hungrytime ?? NaN);
}

function tipHatMonsterPlineName(mon, visible, fallbackName) {
    if (!visible) return 'It';
    if (heroIsHallucinating()) return `The ${randomHallucinatedMonsterName()}`;
    return fallbackName || fireScrollMonsterName(mon);
}

function tipHatLivingMonster(mon) {
    return !!mon && !mon.dead && (mon.mhp == null || mon.mhp > 0);
}

function tipHatClearWakeWait(mon) {
    if (Number.isInteger(mon.mstrategy)) mon.mstrategy &= ~STRAT_WAITMASK;
    else if (mon.mstrategy === 'waitforu') mon.mstrategy = 0;
    mon.waiting = false;
}

function tipHatWakeNearby(mon, distance) {
    const messages = [];
    for (const sleeper of game.level?.monsters || []) {
        if (!tipHatLivingMonster(sleeper)) continue;
        const dx = (sleeper.mx || 0) - (mon?.mx || 0);
        const dy = (sleeper.my || 0) - (mon?.my || 0);
        if (distance !== 0 && dx * dx + dy * dy >= distance) continue;
        if (sleeper.msleeping && tipHatMonsterVisible(sleeper)) {
            const alive = String(sleeper.data?.name || sleeper.name || '').toLowerCase() === 'flesh golem'
                ? " It's alive!" : '';
            messages.push(`${fireScrollMonsterName(sleeper)} wakes up.${alive}`);
        }
        sleeper.msleeping = 0;
        if (!(sleeper.unique || sleeper.data?.unique || sleeper.data?.uniq))
            tipHatClearWakeWait(sleeper);
    }
    disturbBuriedZombieCorpseTimersAt(mon?.mx || 0, mon?.my || 0);
    return messages;
}

const TIPHAT_DEATH_QUOTE_OID = 1;
const TIPHAT_MAX_TRIBUTE_PASSAGES = 30;

function tipHatTributeContext() {
    game.context ??= {};
    game.context.tribute ??= {};
    return game.context.tribute;
}

function tipHatNovelTrackingContext() {
    game.context ??= {};
    game.context.novel ??= {};
    return game.context.novel;
}

function tipHatNovelTitleIndex(value) {
    if (value == null) return -1;
    const raw = String(value).trim().replace(/^the\s+/i, 'The ');
    const lower = raw.toLowerCase();
    const aliases = new Map([
        ['the color of magic', 'The Colour of Magic'],
        ['sorcery', 'Sourcery'],
        ['masquerade', 'Maskerade'],
        ['the amazing maurice', 'The Amazing Maurice and His Educated Rodents'],
        ['thud', 'Thud!'],
    ]);
    const canonical = aliases.get(lower) || raw;
    const wanted = canonical.toLowerCase();
    return TRIBUTE_NOVEL_TITLES.findIndex(title =>
        title.toLowerCase() === wanted
        || title.toLowerCase().replace(/^the\s+/i, '') === wanted
        || title.toLowerCase() === `the ${wanted}`);
}

function tipHatNovelTitle(item) {
    const roll = rn2(TRIBUTE_NOVEL_TITLES.length);
    let index = Number.isInteger(item?.novelidx) ? item.novelidx
        : Number.isInteger(item?.novelIndex) ? item.novelIndex
            : tipHatNovelTitleIndex(item?.novelTitle ?? item?.title ?? item?.oname);
    if (index < 0 || index >= TRIBUTE_NOVEL_TITLES.length) {
        index = roll;
        if (item) item.novelidx = index;
    }
    return TRIBUTE_NOVEL_TITLES[index] || '';
}

function tipHatHeroCarriedNovel() {
    return (game.inventory || []).find(item => {
        const kind = String(item?.actualKind || item?.kind || item?.name || '').toLowerCase();
        return item?.novel || (item?.cls === 'spellbook' && kind === 'novel');
    }) || null;
}

function tipHatChooseTributePassage(passageCount, oid) {
    if (passageCount < 1) return 0;
    const tracking = tipHatNovelTrackingContext();
    if (tracking.id !== oid || !tracking.count) {
        tracking.id = oid;
        const passages = [];
        if (passageCount <= TIPHAT_MAX_TRIBUTE_PASSAGES) {
            for (let idx = 0; idx < passageCount; idx++) passages.push(idx + 1);
        } else {
            let range = passageCount;
            let limit = TIPHAT_MAX_TRIBUTE_PASSAGES;
            for (let idx = 0; idx < passageCount; idx++, range--) {
                if (range > 0 && rn2(range) < limit) {
                    passages.push(idx + 1);
                    limit--;
                }
            }
        }
        tracking.count = passages.length;
        tracking.pasg = passages;
    }
    const idx = rn2(tracking.count);
    const passage = tracking.pasg[idx];
    tracking.count--;
    tracking.pasg[idx] = tracking.pasg[tracking.count];
    return passage;
}

function tipHatDeathQuote() {
    const passage = tipHatChooseTributePassage(TRIBUTE_DEATH_QUOTES.length, TIPHAT_DEATH_QUOTE_OID);
    return TRIBUTE_DEATH_QUOTES[passage - 1] || '';
}

function tipHatDeathSpeech(message) {
    return String(message || '').toUpperCase();
}

function tipHatDeathRiderNoise(name) {
    const tribute = tipHatTributeContext();
    const book = !tribute.Deathnotice ? tipHatHeroCarriedNovel() : null;
    if (book) {
        const title = tipHatNovelTitle(book);
        tribute.Deathnotice = 1;
        if (title) {
            let message = `Ah, so you have a copy of /${title}/.`;
            if (title !== 'Snuff' && title !== 'The Wee Free Men')
                message += '  I may have been misquoted there.';
            return { handled: true, message: tipHatDeathSpeech(message) };
        }
    }
    if (rn2(3)) {
        const quote = tipHatDeathQuote();
        if (quote) return { handled: true, message: tipHatDeathSpeech(quote) };
    }
    if (!rn2(10))
        return { handled: true, message: `${name} is busy reading a copy of Sandman #8.` };
    return { handled: true, message: tipHatDeathSpeech('Who do you think you are, War?') };
}

function tipHatAggravateMonsters() {
    for (const mon of game.level?.monsters || []) {
        if (!tipHatLivingMonster(mon)) continue;
        mon.msleeping = 0;
        if (Number.isInteger(mon.mstrategy))
            mon.mstrategy &= ~(STRAT_WAITFORU | STRAT_APPEARMSG);
        else if (mon.mstrategy === 'waitforu') mon.mstrategy = 0;
        mon.waiting = false;
        if (mon.mcanmove === false && !rn2(5)) {
            mon.mfrozen = 0;
            mon.mcanmove = true;
        }
    }
}

function tipHatQuestRoleInfo() {
    const roleName = game.urole?.name?.m || game._startup_role || '';
    return QUEST_ROLE_DATA[roleName] || null;
}

function tipHatMonsterIsRoleQuestGuardian(mon, monName) {
    const info = tipHatQuestRoleInfo();
    if (!info?.guardian) return false;
    const guardian = String(info.guardian).toLowerCase();
    const data = mon?.data || {};
    return monName === guardian
        || String(mon?.questGuardian || mon?.guardianName || data.questGuardian || data.guardianName || '').toLowerCase() === guardian;
}

function tipHatQuestGuardianNoise() {
    const after = game.u?.uhave?.questart && game.quest_status?.killed_nemesis;
    const message = questPagerText(after ? 'guardtalk_after' : 'guardtalk_before', { initCore: false });
    return message ? { handled: true, message } : { handled: false, message: '' };
}

function tipHatQuestNemesisNoise() {
    game.quest_status ??= {};
    const message = questPagerText('discourage', { initCore: false });
    if (!game.quest_status.met_nemesis) game.quest_status.met_nemesis = true;
    return message ? { handled: true, message } : { handled: false, message: '' };
}

function tipHatMonsterNoise(mon, { visible = tipHatMonsterVisible(mon), nameOverride = null, offerCommandMode = false } = {}) {
    const silent = tipHatMonsterSilent(mon);
    if (!mon || heroIsDeaf() || (silent && !mon?.isshk)) return { handled: false, message: '' };
    const name = nameOverride ?? (visible ? fireScrollMonsterName(mon) : 'It');
    const monName = String(mon?.data?.name || mon?.name || '').toLowerCase();
    let sound = tipHatMonsterSound(mon);
    const peaceful = !!mon.mpeaceful;
    const tame = Number(mon.mtame || 0);
    const moves = Number(game.moves ?? game.context?.moves ?? 0);
    const hungryTime = tipHatMonsterHungryTime(mon);
    if (sound === 'orc' && (tipHatMonsterSharesHeroRace(mon, monName) || heroIsHallucinating())) sound = 'humanoid';
    else if (sound === 'moo' && !tame) sound = 'bellow';
    else if (sound === 'guardian' && !tipHatMonsterIsRoleQuestGuardian(mon, monName)) sound = 'humanoid';
    else if (heroIsHallucinating() && tipHatMonsterAppearsAsGecko(mon)) sound = 'sell';
    switch (sound) {
    case 'sell':
        if (heroIsHallucinating()) {
            if (mon?.isshk && (silent || !rn2(2))) return tipHatShopkeeperSellNoise(mon, name);
            return { handled: true, message: `"15 minutes could save you 15 ${shopCurrency(15)}."` };
        }
        return tipHatShopkeeperSellNoise(mon, name);
    case 'bark': {
        if (game.flags?.moonphase === 4 && tipHatIsNight())
            return { handled: true, message: `${name} howls.` };
        if (peaceful) {
            if (monName === 'dingo') return { handled: true, message: '' };
            if (tame && (mon.mconf || mon.mflee || mon.mtrapped
                || (Number.isFinite(hungryTime) && moves > hungryTime) || tame < 5))
                return { handled: true, message: `${name} whines.` };
            if (tame && Number.isFinite(hungryTime) && hungryTime > moves + 1000)
                return { handled: true, message: `${name} yips.` };
            return { handled: true, message: `${name} barks.` };
        }
        return { handled: true, message: `${name} growls.` };
    }
    case 'mew':
        if (tame) {
            if (mon.mconf || mon.mflee || mon.mtrapped || tame < 5)
                return { handled: true, message: `${name} yowls.` };
            if (Number.isFinite(hungryTime) && moves > hungryTime)
                return { handled: true, message: `${name} meows.` };
            if (Number.isFinite(hungryTime) && hungryTime > moves + 1000)
                return { handled: true, message: `${name} purrs.` };
            return { handled: true, message: `${name} mews.` };
        }
        return { handled: true, message: `${name} ${peaceful ? 'snarls.' : 'growls!'}` };
    case 'growl':
        return { handled: true, message: `${name} ${peaceful ? 'snarls.' : 'growls!'}` };
    case 'roar':
        return { handled: true, message: `${name} ${peaceful ? 'snarls.' : 'roars!'}` };
    case 'sqeek':
    case 'squeak':
        return { handled: true, message: `${name} squeaks.` };
    case 'sqawk':
    case 'squawk':
        if (monName === 'raven' && !peaceful) return { handled: true, message: '"Nevermore!"' };
        return { handled: true, message: `${name} squawks.` };
    case 'hiss':
        return peaceful
            ? { handled: false, message: '', mapInvisible: !visible }
            : { handled: true, message: `${name} hisses!` };
    case 'buzz':
        return { handled: true, message: `${name} ${peaceful ? 'drones.' : 'buzzes angrily.'}` };
    case 'orc':
    case 'grunt':
        return { handled: true, message: `${name} grunts.` };
    case 'neigh': {
        if (tame < 5) return { handled: true, message: `${name} neighs.` };
        if (Number.isFinite(hungryTime) && moves > hungryTime)
            return { handled: true, message: `${name} whinnies.` };
        return { handled: true, message: `${name} whickers.` };
    }
    case 'moo':
        return { handled: true, message: `${name} moos.` };
    case 'bellow':
        return { handled: true, message: `${name} bellows!` };
    case 'chirp':
        return { handled: true, message: `${name} chirps.` };
    case 'wail':
        return { handled: true, message: `${name} wails mournfully.` };
    case 'groan':
        return { handled: true, message: rn2(3) ? '' : `${name} groans.` };
    case 'gurgle':
        return { handled: true, message: `${name} gurgles.` };
    case 'djinni':
        if (tame) return { handled: true, message: `"Sorry, I'm all out of wishes."` };
        if (peaceful)
            return monName === 'water demon'
                ? { handled: true, message: `${name} gurgles.` }
                : { handled: true, message: `"I'm free!"` };
        return monName === 'prisoner'
            ? { handled: true, message: `"Get me out of here."` }
            : { handled: true, message: `"This will teach you not to disturb me!"` };
    case 'humanoid':
        if (!peaceful) {
            if (tipHatMonsterIsMplayer(mon) && In_endgame(game.u?.uz))
                return tipHatMplayerTalk(mon, monName);
            return { handled: true, message: `${tipHatMonsterPlineName(mon, visible, name)} threatens you.` };
        }
        return tipHatPeacefulHumanoidNoise(mon, name, monName, moves, hungryTime);
    case 'boast':
        if (peaceful) return tipHatPeacefulHumanoidNoise(mon, name, monName, moves, hungryTime);
        switch (rn2(4)) {
        case 0:
            return {
                handled: true,
                message: `${name} boasts about ${tipHatMonsterPossessive(mon)} gem collection.`,
            };
        case 1:
            return { handled: true, message: `${name} complains about a diet of mutton.` };
        default: {
            const wakeMessages = tipHatWakeNearby(mon, 7 * 7);
            return {
                handled: true,
                message: [...wakeMessages, `${name} shouts "Fee Fie Foe Foo!" and guffaws.`].join('  '),
            };
        }
        }
    case 'burble':
        return { handled: true, message: `${name} burbles.` };
    case 'trumpet': {
        const wakeMessages = tipHatWakeNearby(mon, 11 * 11);
        return { handled: true, message: [...wakeMessages, `${name} trumpets!`].join('  ') };
    }
    case 'shriek':
        tipHatAggravateMonsters();
        return { handled: true, message: `${name} shrieks.` };
    case 'laugh': {
        const laughMessages = ['giggles.', 'chuckles.', 'snickers.', 'laughs.'];
        return { handled: true, message: `${name} ${laughMessages[rn2(4)]}` };
    }
    case 'imitate':
        return { handled: true, message: `${name} imitates you.` };
    case 'bones':
        game._helpless_time = Math.max(game._helpless_time || 0, 2);
        game._wake_message = 'You can move again.';
        return { handled: true, message: `${name} rattles noisily.  You freeze for a moment.` };
    case 'mumble':
        return { handled: true, message: `${name} mumbles incomprehensibly.` };
    case 'spell':
        return { handled: true, message: `${name} seems to mutter a cantrip.` };
    case 'oracle':
        if (!peaceful)
            return { handled: false, message: `${name} is in no mood for consultations.`, mapInvisible: !visible };
        if (!tipHatHeroHasTopLevelGold())
            return { handled: false, message: 'You have no gold.', mapInvisible: !visible };
        return { handled: false, message: '', mapInvisible: !visible };
    case 'priest':
        return tipHatPriestNoise(mon, name);
    case 'seduce': {
        const sameGender = !!game.flags?.female === tipHatMonsterFemale(mon);
        if (!tipHatMonsterIsNymph(mon, monName) && !sameGender)
            return { handled: false, message: '' };
        if (!sameGender) {
            const swval = rn2(3);
            if (swval === 2) return { handled: true, message: '"Hello, sailor."' };
            if (swval === 1) return { handled: true, message: `${name} comes on to you.` };
        }
        return { handled: true, message: `${name} cajoles you.` };
    }
    case 'were': {
        const fullMoon = game.flags?.moonphase === 4;
        const isNight = tipHatIsNight();
        const bloodcurdling = fullMoon && (isNight ? rn2(13) !== 0 : !rn2(13));
        if (!bloodcurdling)
            return { handled: true, message: `${name} whispers inaudibly.  All you can make out is "moon".` };
        const cry = monName === 'wererat' ? 'shriek' : 'howl';
        const howlMessage = `${name} throws back ${tipHatMonsterPossessive(mon)} head and lets out a blood curdling ${cry}!`;
        const wakeMessages = tipHatWakeNearby(mon, 11 * 11);
        return { handled: true, message: [howlMessage, ...wakeMessages].filter(Boolean).join('  ') };
    }
    case 'vampire': {
        const isNight = tipHatIsNight();
        const kindred = tipHatHeroVampireKindred();
        const nightchild = tipHatHeroNightChild();
        if (tame) {
            if (kindred) {
                const ending = isNight ? '!' : '.  Why do we not rest?';
                return { handled: true, message: `"Good ${isNight ? 'evening' : 'day'} to you Master${ending}"` };
            }
            const prefix = nightchild ? 'Child of the night, ' : '';
            if (tipHatIsMidnight())
                return { handled: true, message: `"${prefix}I can stand this craving no longer!"` };
            if (isNight)
                return { handled: true, message: `"${prefix}I beg you, help me satisfy this growing craving!"` };
            return { handled: true, message: `"${prefix}I find myself growing a little weary."` };
        }
        if (peaceful) {
            if (kindred && isNight)
                return { handled: true, message: `"Good feeding ${game.flags?.female ? 'sister' : 'brother'}!"` };
            if (nightchild && isNight)
                return { handled: true, message: '"How nice to hear you, child of the night!"' };
            return { handled: true, message: '"I only drink... potions."' };
        }
        if (kindred)
            return { handled: true, message: '"This is my hunting ground that you dare to prowl!"' };
        const formName = polyselfFormName();
        if (formName === 'silver dragon' || formName === 'baby silver dragon') {
            const address = formName === 'silver dragon' ? 'Fool' : 'Young Fool';
            return { handled: true, message: `"${address}!  Your silver sheen does not frighten me!"` };
        }
        if (rn2(2) === 0)
            return { handled: true, message: `"I vant to suck your ${tipHatHeroBloodPart()}!"` };
        const prey = polyselfForm() ? articleFor(polyselfFormName()) : articleFor(tipHatHeroRaceNoun());
        return { handled: true, message: `"I vill come after ${prey} without regret!"` };
    }
    case 'rider':
        if (monName === 'death') return tipHatDeathRiderNoise(name);
        return { handled: true, message: '"Who do you think you are, War?"' };
    case 'guardian':
        return tipHatQuestGuardianNoise();
    case 'nemesis':
        return tipHatQuestNemesisNoise();
    case 'bribe':
        if (peaceful && !tame) return tipHatDemonBribeNoise(mon, name, visible, offerCommandMode);
        if (peaceful) return tipHatPeacefulCussNoise(mon);
        return tipHatHostileCussNoise(mon, name, monName);
    case 'cuss':
        if (peaceful) return tipHatPeacefulCussNoise(mon);
        return tipHatHostileCussNoise(mon, name, monName);
    case 'arrest': {
        if (peaceful)
            return { handled: true, message: `"Just the facts, ${game.flags?.female ? "Ma'am" : 'Sir'}."` };
        const arrestMessages = [
            'Anything you say can be used against you.',
            "You're under arrest!",
            'Stop in the name of the Law!',
        ];
        return { handled: true, message: `"${arrestMessages[rn2(3)]}"` };
    }
    case 'guard':
        return tipHatHeroHasTopLevelGold()
            ? { handled: true, message: `"Please drop that gold and follow me."` }
            : { handled: true, message: `"Please follow me."` };
    case 'nurse':
        if (mon.mcan) return { handled: true, message: `"I hate this job!"` };
        if (tipHatHeroWieldsNurseWeapon())
            return { handled: true, message: `"Put that weapon away before you hurt someone!"` };
        if (tipHatHeroWearsNurseArmor()) {
            return tipHatHeroIsHealer()
                ? { handled: true, message: `"Doc, I can't help you unless you cooperate."` }
                : { handled: true, message: `"Please undress so I can examine you."` };
        }
        if (tipHatHeroWearsShirt()) return { handled: true, message: `"Take off your shirt, please."` };
        return { handled: true, message: `"Relax, this won't hurt a bit."` };
    case 'soldier': {
        const soldierMessages = peaceful
            ? [
                "What lousy pay we're getting here!",
                "The food's not fit for Orcs!",
                "My feet hurt, I've been on them all day!",
            ]
            : [
                'Resistance is useless!',
                "You're dog meat!",
                'Surrender!',
            ];
        return { handled: true, message: `"${soldierMessages[rn2(3)]}"` };
    }
    default:
        return { handled: false, message: '' };
    }
}

function tipHatRudeHumanoidResponse(name) {
    const reaction = ['curses', 'gestures rudely', 'gestures offensively'];
    const deaf = heroIsDeaf();
    const which = deaf ? rn1(2, 1) : rn2(3);
    let twice = 0;
    if (!deaf && which === 0 && !rn2(3))
        twice = rn1(2, 1);
    return `${name} ${reaction[which]}${twice ? ` and ${reaction[twice]}` : ''} at you...`;
}

function tipHatDirectedResponse(dir) {
    if (!dir.dx && !dir.dy) {
        if (game.u?.usteed && dir.dz > 0) {
            if (tipHatMonsterHelpless(game.u.usteed))
                return `${fireScrollMonsterName(game.u.usteed)} doesn't notice.`;
            return tipHatMonsterNoise(game.u.usteed, { visible: true }).message;
        }
        if (dir.dz) return `There's no one ${dir.dz < 0 ? 'up' : 'down'} there.`;
        return "The lout here doesn't acknowledge you...";
    }

    let x = game.u?.ux || 0;
    let y = game.u?.uy || 0;
    let target = null;
    let unseen = false;
    let statue = false;
    for (let range = 1; range <= BOLT_LIM + 1; range++) {
        x += dir.dx;
        y += dir.dy;
        statue = false;
        if (!isok(x, y) || (range > 1 && !couldsee(x, y))) break;
        let monHere = (game.level?.monsters || []).find(mon => mon.mx === x && mon.my === y && !mon.dead);
        const rawVisibleMonster = tipHatMonsterCanBeSeen(monHere);
        const apparentStatue = rawVisibleMonster && tipHatMonsterAppearsAsStatueGlyph(monHere);
        const apparent = rawVisibleMonster && tipHatApparentObjectOrFurniture(monHere);
        if (apparent) monHere = null;
        const loc = game.level?.at?.(x, y);
        unseen = !!loc?.map_invisible;
        statue = tipHatLocationHasStatueGlyph(loc)
            || apparentStatue
            || (!rawVisibleMonster && !unseen && !!floorStatueAt(x, y));
        const visibleTarget = tipHatMonsterVisible(monHere);
        const adjacentResponder = range === 1 && monHere && tipHatMonsterResponsive(monHere)
            && !tipHatMonsterSilent(monHere);
        if (visibleTarget || unseen || (statue && heroIsHallucinating()) || adjacentResponder
            || !loc || (!(ACCESSIBLE(loc.typ) || loc.typ === IRONBARS))) {
            if (visibleTarget || adjacentResponder) target = monHere;
            break;
        }
    }
    if (unseen || (statue && heroIsHallucinating()))
        return `That ${unseen ? 'unseen ' : ''}creature is ignoring you!`;
    const visible = tipHatMonsterVisible(target);
    const name = fireScrollMonsterName(target);
    if (!target || !tipHatMonsterResponsive(target)) {
        if (target && visible) return `${name} seems not to notice you.`;
        return 'Nothing happens.';
    }

    if (Number.isInteger(target.mstrategy)) target.mstrategy &= ~STRAT_WAITMASK;
    else if (target.mstrategy === 'waitforu') target.mstrategy = 0;
    if (visible && tipHatMonsterHumanoid(target) && target.mpeaceful && !heroHasConflict()) {
        const helmet = monsterEarthHelmet(target);
        if (!helmet) return `${name} waves.`;
        const simple = tipHatSimpleName(helmet);
        const poss = tipHatMonsterPossessive(target);
        if (helmet.cursed) {
            helmet.bknown = true;
            return `${name} grasps ${poss} ${simple} but can't remove it.`;
        }
        return `${name} tips ${poss} ${simple} in response.`;
    }
    if (visible && tipHatMonsterHumanoid(target))
        return tipHatRudeHumanoidResponse(name);
    if (tipHatMonsterAdjacent(target)) {
        const noise = tipHatMonsterNoise(target, { visible });
        if (!visible && !tipHatMonsterVisible(target) && noise.mapInvisible) {
            const loc = game.level?.at?.(target.mx, target.my);
            if (loc) loc.map_invisible = true;
            newsym(target.mx, target.my);
        }
        if (noise.handled) {
            if (!visible && !tipHatMonsterVisible(target)) {
                const loc = game.level?.at?.(target.mx, target.my);
                if (loc) loc.map_invisible = true;
                newsym(target.mx, target.my);
            }
            return noise.message;
        }
        if (noise.message)
            return [noise.message, visible ? `${name} doesn't respond.` : 'Nothing happens.'].join('  ');
    }
    if (visible) return `${name} doesn't respond.`;
    return 'Nothing happens.';
}

async function finishTipHatDirection(ch) {
    const helmet = (game.inventory || []).find(item => item.letter === game._tip_hat_letter);
    const cancelMove = game._tip_hat_cancel_move || 0;
    if (ch === '\x1b' || ch === ' ' || ch === '\r' || ch === '\n' || ch === 'q') {
        game._tip_hat_letter = '';
        game._tip_hat_cancel_move = 0;
        game._command_mode = null;
        game.context.move = cancelMove;
        await setMessage('Never mind.');
        return;
    }
    const dir = tipHatDirectionFromKey(ch);
    if (!dir) {
        await setMessage(tipHatDirectionPrompt());
        return;
    }
    game._tip_hat_letter = '';
    game._tip_hat_cancel_move = 0;
    game._command_mode = null;
    if (!helmet || !isTipWornHelmet(helmet)) {
        await setMessage('Nothing happens.');
        return;
    }
    const messages = [
        `You briefly doff your ${tipHatSimpleName(helmet)}.`,
        tipHatDirectedResponse(dir),
    ].filter(Boolean);
    await setMessage(messages.join('  '), messages.length > 1);
    game.context.move = 1;
}

function isTipTargetContainer(obj) {
    return isTipContainerObject(obj) || isUnknownBagOfTricksObject(obj);
}

function carriedTipTargetContainers(source) {
    if (polyselfNoHands()) return [];
    return (game.inventory || [])
        .filter(obj => obj !== source && isTipTargetContainer(obj)
            && !(obj.lknown && (obj.locked || obj.olocked)));
}

function tipTargetPhrase(targetBox) {
    const name = articlelessObjectName(targetBox);
    return `the ${name}`;
}

function tipTrapMessages(result) {
    const objectResult = result && typeof result === 'object';
    const messages = [objectResult ? result.message : result].filter(Boolean);
    if (objectResult) {
        Object.defineProperty(messages, '_trapResult', {
            value: result,
            enumerable: false,
        });
    }
    return messages;
}

function tipContainerCheckMessages(container, { allowEmpty = false } = {}) {
    if (!container) return ["You don't have that object."];
    container.lknown = true;
    if (container.locked || container.olocked) return [`The ${tipContainerSimpleName(container)} is locked.`];
    if (container.otrapped)
        return tipTrapMessages(applyChestTrapPayload(container, { disarm: false }));
    if (!allowEmpty && !liquidFlowContainerContents(container).length) {
        container.cknown = true;
        return [tipContainerEmptyMessage(container)];
    }
    return null;
}

function tipChargeCount(item) {
    return Math.max(0, item?.spe ?? 0);
}

function consumeTipCharge(item) {
    item.spe = Math.max(0, (item.spe ?? 0) - 1);
    updateChargedItemLine(item);
}

function identifyChargedToolKind(item, knownKind) {
    if (!item || !knownKind) return;
    item.known = true;
    item.actualKind = knownKind;
    item.kind = knownKind;
    recordKnownToolDiscovery(knownKind);
    updateChargedItemLine(item);
}

function clearTipState() {
    game._tip_container_object = null;
    game._tip_target_entries = null;
    game._overlay_lines = null;
    game._overlay_hide_status = 0;
}

function drawTipDestinationMenu(source, targets) {
    const sourceName = (game.inventory || []).includes(source)
        ? inventoryItemName(source)
        : `the ${tipContainerSimpleName(source)}`;
    const rows = [
        [0, 32, `Where to tip the contents of ${sourceName}?`, 1],
        [2, 32, '- - on the floor'],
    ];
    let row = 4;
    for (const target of targets) {
        rows.push([row++, 32, `${target.letter || '?'} - ${normalInventoryLine(target).replace(/^[a-zA-Z] - /, '')}`]);
        if (row >= 23) break;
    }
    rows.push([row, 32, '(end)']);
    setOverlay(rows, Math.max(5, row + 1), false, 31);
}

function beginTipDestinationSelection(source) {
    const targets = carriedTipTargetContainers(source);
    if (!targets.length) return false;
    game._tip_container_object = source;
    game._tip_target_entries = targets.map(target => ({ target, letter: target.letter }));
    drawTipDestinationMenu(source, targets);
    game._command_mode = 'tipDestination';
    return true;
}

function prepareTippedObjectForContainer(obj) {
    obj.contained = false;
    obj.container = null;
    delete obj.ox;
    delete obj.oy;
    delete obj.hidden;
    delete obj.buried;
    delete obj.transientProjectile;
    delete obj.nobj;
    delete obj.nexthere;
}

function refreshTipContainerWeight(container) {
    if (isGlobWeightContainerObject(container)) container.owt = globObjectWeight(container);
}

function isBagOfHoldingObject(obj) {
    return !!obj && (obj.otyp === BAG_OF_HOLDING || objectKindKey(obj) === 'bag of holding');
}

function isMagicBagObject(obj) {
    return isBagOfHoldingObject(obj) || isBagOfTricksObject(obj);
}

function isWandOfCancellationObject(obj) {
    return !!obj && (obj.wandIndex === WAND_NAME_TO_INDEX.get('cancellation')
        || wandTypeName(obj) === 'cancellation'
        || objectKindKey(obj) === 'wand of cancellation'
        || objectKindKey(obj) === 'cancellation');
}

function magicBagExplodesWithObject(obj, depth = 0) {
    if ((isWandOfCancellationObject(obj) || isBagOfTricksObject(obj)) && (obj.spe ?? 0) <= 0)
        return false;
    if ((isMagicBagObject(obj) || isWandOfCancellationObject(obj))
        && rn2(1 << Math.min(depth, 7)) <= depth)
        return true;
    for (const content of liquidFlowContainerContents(obj))
        if (magicBagExplodesWithObject(content, depth + 1)) return true;
    return false;
}

function magicBagItemGoneMessage(item) {
    if (item?.dknown !== false) {
        const subject = upstartText(containerObjectPhrase(item));
        const verb = (item.quan || 1) > 1 ? 'have' : 'has';
        return `${subject} ${verb} vanished!`;
    }
    return `You ${game.u?.blind ? 'notice' : 'see'} ${containerObjectPhrase(item)} disappear!`;
}

function removeObjectFromWorld(obj) {
    if (!obj) return;
    if ((game.inventory || []).includes(obj))
        game.inventory = (game.inventory || []).filter(item => item !== obj);
    if ((game.level?.objects || []).includes(obj)) {
        const x = obj.ox;
        const y = obj.oy;
        removeFloorObject(obj);
        if (x != null && y != null) newsym(x, y);
    }
    stopCarriedFigurineTimerOnLeave(obj);
    game._pet_food_scan_inventory = game.inventory || [];
}

function destroyMagicBagItem(item, messages, { silent = false, usedUpShopBill = false } = {}) {
    if (!item) return;
    if (usedUpShopBill) markObjectTreeShopBillsUsedUp(item);
    if (!silent) messages.push(magicBagItemGoneMessage(item));
    removeObjectFromWorld(item);
}

function magicBagContentsLoss(container, messages, { silent = false, details = null } = {}) {
    if (!isMagicBagObject(container) || !container.cursed) return 0;
    let lost = 0;
    let lostMerchandise = 0;
    for (const obj of [...liquidFlowContainerContents(container)]) {
        if (rn2(13)) continue;
        lostMerchandise += billMagicBagLostItem(container, obj);
        removeContainedObject(container, obj);
        destroyMagicBagItem(obj, messages, { silent });
        lost++;
    }
    refreshTipContainerWeight(container);
    const lostMessage = !silent ? lostShopMerchandiseMessage(lostMerchandise) : '';
    if (lostMessage) messages.push(lostMessage);
    if (details) {
        details.lost = lost;
        details.lostMerchandise = lostMerchandise;
    }
    return lost;
}

function magicBagScatterBreakMessage(obj, breakKind, messages) {
    if (!breakKind) return;
    if (breakKind === 'splat') {
        messages.push('Splat!');
        return;
    }
    if (breakKind === 'splash') {
        messages.push('Splash!');
        return;
    }
    if (breakKind === 'mess') {
        messages.push('What a mess!');
        return;
    }
    if (game.u?.blind) {
        messages.push('You hear something shatter!');
        return;
    }
    const name = pickupObjectName({ ...obj, quan: obj.quan || 1 });
    const many = (obj.quan || 1) > 1;
    const subject = many ? `The ${name}` : (/^[aeiou]/i.test(name) ? `An ${name}` : `A ${name}`);
    const verb = many ? 'shatter' : 'shatters';
    messages.push(`${subject} ${verb}${breakKind === 'pieces' ? ' into a thousand pieces' : ''}!`);
}

function magicBagScatterBreaks(obj, sx, sy, messages) {
    const randomBreak = !rn2(10);
    const material = String(obj?.material || obj?.oc_material || '').toLowerCase();
    const forcedBreak = obj?.otyp === EGG || objectKindKey(obj) === 'egg' || material === 'glass';
    if (!randomBreak && !forcedBreak) return false;
    const breakKind = impactDropBreakKind(obj);
    if (!breakKind && !forcedBreak) return false;
    if (floorObjectVisible(sx, sy)) magicBagScatterBreakMessage(obj, breakKind || 'shatter', messages);
    destroyMagicBagItem(obj, messages, { silent: true, usedUpShopBill: true });
    return true;
}

function splitMagicBagScatterStack(obj) {
    if ((obj?.quan || 1) <= 1) return obj;
    const splitCount = rnd(Math.min(obj.quan - 1, Number.MAX_SAFE_INTEGER));
    obj.quan -= splitCount;
    const splitObj = {
        ...obj,
        id: next_ident(),
        quan: splitCount,
        contents: Array.isArray(obj.contents) ? [...obj.contents] : obj.contents,
        cobj: Array.isArray(obj.cobj) ? [...obj.cobj] : obj.cobj,
    };
    delete splitObj.o_id;
    delete splitObj._shopBillObjectId;
    if (obj.unpaid && !splitCarriedObjectShopBill(obj, splitObj, splitCount))
        clearObjectShopBillState(splitObj);
    return splitObj;
}

function magicBagScatterClosedDoor(x, y) {
    const loc = game.level?.at(x, y);
    return !!(loc?.typ === DOOR && (loc.doormask & (D_CLOSED | D_LOCKED)));
}

function magicBagScatterWeight(obj) {
    return Math.max(0, globObjectWeight(obj) || obj?.owt || obj?.weight || floorEffectsObjectWeight(obj));
}

function magicBagScatterMonsterAt(x, y) {
    return (game.level?.monsters || []).find(mon =>
        mon.mx === x && mon.my === y && !mon.dead && (mon.mhp == null || mon.mhp > 0));
}

function magicBagScatterObjectName(obj) {
    return pickupObjectName({ ...obj, quan: Math.max(1, obj?.quan || 1) });
}

function magicBagScatterMissileName(obj) {
    return pickupObjectName({ ...obj, quan: 1 });
}

function magicBagScatterObjectArticle(obj) {
    const name = magicBagScatterObjectName(obj);
    return (obj?.quan || 1) > 1 ? name : articleFor(name);
}

function magicBagScatterMonsterHitBonus(mon) {
    const data = mon?.data || {};
    let bonus = data.verysmall || data.tiny ? -2 : data.small ? -1 : 0;
    if (data.big || data.bigmonst || data.large || data.strong) bonus += 2;
    if (mon?.msleeping) bonus += 2;
    if (mon?.mcanmove === 0 || data.mmove === 0) bonus += 4;
    return bonus;
}

function magicBagScatterObjectHitBonus(obj) {
    if (obj?.otyp === HEAVY_IRON_BALL) return 2;
    if (obj?.otyp === BOULDER) return 6;
    const cls = obj?.cls || (obj?.otyp === GEM_CLASS ? 'gem' : obj?.otyp === WEAPON_CLASS ? 'weapon' : '');
    return (cls === 'weapon' || cls === 'gem' || obj?.glyph === ')') ? (obj?.spe || 0) : 0;
}

function magicBagScatterHitConsumesObject(obj) {
    const kind = objectKindKey(obj);
    return isPotionObject(obj)
        || obj?.otyp === CREAM_PIE || kind === 'cream pie'
        || obj?.otyp === EGG || kind === 'egg'
        || obj?.cls === 'venom';
}

function magicBagScatterKillVerb(mon) {
    const data = mon?.data || {};
    return data.nonliving || data.mlet === 'Z' || data.mlet === 'zombie'
        || data.glyph === 'Z' || data.name?.includes('zombie') || data.name?.endsWith(' golem')
        ? 'destroyed'
        : 'killed';
}

function magicBagScatterCorpseData(mon) {
    const data = mon?.data || {};
    return data.corpse
        || (data.name?.endsWith(' zombie') ? monsterByRndName(data.name.replace(/ zombie$/, '')) : null)
        || data;
}

function magicBagScatterRemoveKilledMonster(mon, messages) {
    const data = mon?.data || {};
    const corpseData = magicBagScatterCorpseData(mon);
    const dropCorpse = monsterLeavesCorpseLikeDrop(corpseData)
        && monsterCorpseDropSucceeds(mon, data);
    dropMonsterInventory(mon, messages);
    if (dropCorpse) createMonsterCorpseOrGlob(mon, corpseData, mon.mx, mon.my, { messages });
    recordVanquished(mon, !game._monster_moving);
    const loc = game.level?.at(mon.mx, mon.my);
    if (loc?.map_invisible) {
        loc.map_invisible = false;
        loc.remembered_glyph = null;
    }
    game.level.monsters = (game.level?.monsters || []).filter(other => other !== mon);
    mon.mhp = 0;
    mon.dead = true;
    mon.movement = 0;
    newsym(mon.mx, mon.my);
}

function magicBagScatterHitMonster(mon, obj, x, y, messages) {
    const visible = floorObjectVisible(x, y);
    const monsterName = fireScrollMonsterName(mon).replace(/^The /, 'the ');
    const toHit = 5 + (mon?.data?.mac ?? 10)
        + magicBagScatterMonsterHitBonus(mon)
        + magicBagScatterObjectHitBonus(obj);
    if (toHit < rnd(20)) {
        if (visible)
            messages.push(`${sentenceCase(articleFor(magicBagScatterMissileName(obj)))} misses ${monsterName}.`);
        return { stopped: false, consumed: false };
    }

    const consumedOnHit = magicBagScatterHitConsumesObject(obj);
    const damage = consumedOnHit ? 0 : earthObjectDamage(obj, mon);
    mon.msleeping = 0;
    if (visible) {
        const punct = damage > 4 ? '!' : '.';
        messages.push(`${sentenceCase(articleFor(magicBagScatterMissileName(obj)))} hits ${monsterName}${punct}`);
    }
    if (damage > 0) mon.mhp = (mon.mhp || 1) - damage;
    if ((mon.mhp || 0) <= 0) {
        if (visible)
            messages.push(`${fireScrollMonsterName(mon)} is ${magicBagScatterKillVerb(mon)}!`);
        magicBagScatterRemoveKilledMonster(mon, messages);
    } else if (!game._monster_moving) {
        mon.mpeaceful = false;
    }

    if (consumedOnHit) {
        destroyMagicBagItem(obj, messages, { silent: true, usedUpShopBill: true });
        newsym(x, y);
        return { stopped: true, consumed: true };
    }
    placeObjectOnFloorWithEffects(obj, x, y, messages, 'land', { stack: true });
    return { stopped: true, consumed: false };
}

function magicBagScatterHitHero(obj, messages) {
    if (!game.u) return { hit: false, consumed: false };
    const form = polyselfForm() || {};
    const damage = earthObjectDamage(obj, { data: form });
    const hitValue = 8 + (obj?.spe || 0) + (form.big || form.bigmonst ? 1 : 0);
    const roll = rnd(20);
    const objectName = magicBagScatterObjectArticle(obj);
    if ((game.u.uac ?? 10) + hitValue <= roll) {
        if (game.u.blind || game.flags?.verbose === false) messages.push('It misses.');
        else if ((game.u.uac ?? 10) + hitValue <= roll - 2)
            messages.push(`${sentenceCase(objectName)} misses you.`);
        else
            messages.push(`You are almost hit by ${objectName}.`);
        return { hit: false, consumed: false };
    }

    if (game.u.blind || game.flags?.verbose === false) messages.push(`You are hit${damage > 4 ? '!' : '.'}`);
    else messages.push(`You are hit by ${objectName}${damage > 4 ? '!' : '.'}`);
    if (magicBagScatterHitConsumesObject(obj)) {
        destroyMagicBagItem(obj, messages, { silent: true, usedUpShopBill: true });
        return { hit: true, consumed: true };
    }
    if (damage > 0) {
        game.u.uhp = Math.max(0, (game.u.uhp || 1) - damage);
        if ((game.u.uhp || 0) <= 0) {
            game._death_cause = `killed by ${magicBagScatterObjectName(obj)}`;
            messages.push('You die...');
        }
    }
    return { hit: true, consumed: false };
}

function magicBagScatterShopContext(sx, sy) {
    const originRoomno = game.level?.at?.(sx, sy)?.roomno || 0;
    const shkp = shopkeeperForCostlySpot(sx, sy);
    return shkp ? {
        shkp,
        originRoomno,
        beforeCredit: Math.max(0, Math.trunc(Number(shkp.credit || 0))),
        beforeDebit: Math.max(0, Math.trunc(Number(shkp.debit || 0))),
        beforeLoan: Math.max(0, Math.trunc(Number(shkp.loan || 0))),
    } : null;
}

function magicBagScatterGoldValue(obj) {
    if (!(obj?.otyp === GOLD_PIECE || obj?.cls === 'coin' || obj?.glyph === '$')) return 0;
    return Math.max(1, obj.quan || 1);
}

function magicBagScatterHeroInOriginShop(shopContext) {
    const roomno = game.level?.at?.(game.u?.ux, game.u?.uy)?.roomno || 0;
    return roomno >= ROOMOFFSET && roomno === shopContext?.originRoomno;
}

function chargeShopGold(shkp, amount) {
    if (!shkp || !(amount > 0)) return;
    const credit = Math.max(0, Math.trunc(Number(shkp.credit || 0)));
    if (credit >= amount) {
        shkp.credit = credit - amount;
        return;
    }
    const delta = amount - credit;
    shkp.credit = 0;
    shkp.debit = Math.max(0, Math.trunc(Number(shkp.debit || 0))) + delta;
    shkp.loan = Math.max(0, Math.trunc(Number(shkp.loan || 0))) + delta;
}

function maybeBillMagicBagScatterGold(obj, sx, sy, x, y, shopContext) {
    if (!shopContext?.shkp || (x === sx && y === sy)) return;
    if (shopkeeperForCostlySpot(x, y) || !magicBagScatterHeroInOriginShop(shopContext)) return;
    chargeShopGold(shopContext.shkp, magicBagScatterGoldValue(obj));
}

function finishMagicBagScatterShopBilling(shopContext, messages) {
    if (!shopContext?.shkp) return;
    const nowCredit = Math.max(0, Math.trunc(Number(shopContext.shkp.credit || 0)));
    const nowDebit = Math.max(0, Math.trunc(Number(shopContext.shkp.debit || 0)));
    const nowLoan = Math.max(0, Math.trunc(Number(shopContext.shkp.loan || 0)));
    let amount = 0;
    let kind = 'debt has increased';
    if (nowCredit < shopContext.beforeCredit) {
        amount = shopContext.beforeCredit - nowCredit;
        kind = 'credit has been reduced';
    } else if (nowDebit > shopContext.beforeDebit) {
        amount = nowDebit - shopContext.beforeDebit;
    } else if (nowLoan > shopContext.beforeLoan) {
        amount = nowLoan - shopContext.beforeLoan;
    }
    if (amount)
        messages.push(`Your ${kind} by ${amount} zorkmid${amount === 1 ? '' : 's'}.`);
}

function scatterMagicBagObject(container, obj, sx, sy, messages, shopContext = null) {
    let remaining = obj;
    while (remaining) {
        const scatterObj = splitMagicBagScatterStack(remaining);
        if (scatterObj !== remaining) {
            scatterObj.container = null;
            scatterObj.contained = false;
        } else {
            removeContainedObject(container, remaining);
            remaining = null;
        }
        scatterOneMagicBagObject(scatterObj, sx, sy, messages, shopContext);
    }
}

function scatterOneMagicBagObject(scatterObj, sx, sy, messages, shopContext = null) {
    if (magicBagScatterBreaks(scatterObj, sx, sy, messages)) return;

    const dir = rn2(N_DIRS);
    const dx = xdir[dir];
    const dy = ydir[dir];
    const force = Math.max(1, 4 - Math.trunc(magicBagScatterWeight(scatterObj) / 40));
    let range = rnd(force);
    let x = sx;
    let y = sy;
    while (range-- > 0) {
        const nx = x + dx;
        const ny = y + dy;
        const loc = game.level?.at(nx, ny);
        if (!isok(nx, ny) || !loc || !ZAP_POS(loc.typ) || magicBagScatterClosedDoor(nx, ny))
            break;
        x = nx;
        y = ny;
        if (loc.typ === SINK) break;
        const mon = magicBagScatterMonsterAt(x, y);
        if (mon) {
            range--;
            const hit = magicBagScatterHitMonster(mon, scatterObj, x, y, messages);
            if (hit.stopped) return;
            continue;
        }
        if (game.u?.ux === x && game.u?.uy === y) {
            const hit = magicBagScatterHitHero(scatterObj, messages);
            if (hit.consumed) return;
            if (hit.hit) range -= 3;
        }
    }
    if (placeObjectOnFloorWithEffects(scatterObj, x, y, messages, 'land', {
        stack: true,
        usedUpShopBillOnDestroy: true,
    }))
        maybeBillMagicBagScatterGold(scatterObj, sx, sy, x, y, shopContext);
}

function scatterMagicBagContents(container, messages, { lostContext = null } = {}) {
    const x = game.u?.ux ?? container?.ox ?? 0;
    const y = game.u?.uy ?? container?.oy ?? 0;
    const shopContext = magicBagScatterShopContext(x, y);
    for (const obj of [...liquidFlowContainerContents(container)]) {
        if (!rn2(13)) {
            billMagicBagLostItemWithContext(container, obj, lostContext);
            removeContainedObject(container, obj);
            destroyMagicBagItem(obj, messages, { silent: true });
            continue;
        }
        obj.ox = x;
        obj.oy = y;
        scatterMagicBagObject(container, obj, x, y, messages, shopContext);
    }
    finishMagicBagScatterShopBilling(shopContext, messages);
    clearLiquidFlowContainerContents(container);
}

function magicBagExplosionMessage(obj, tumble = false) {
    if (tumble) {
        const subject = containerObjectPhrase(obj);
        const verb = (obj.quan || 1) > 1 ? 'tumble' : 'tumbles';
        return `As ${subject} ${verb} inside, you are blasted by a magical explosion!`;
    }
    return `As you put ${inventoryItemName(obj)} inside, you are blasted by a magical explosion!`;
}

function damageHeroWithMagicBagExplosion(messages) {
    if (!game.u) return;
    game.u.uhp = Math.max(0, (game.u.uhp || 0) - d(6, 6));
    if ((game.u.uhp || 0) <= 0) {
        game._death_cause = 'killed by a magical explosion';
        messages.push('You die...');
    }
}

function explodeMagicBagTransfer(targetBag, triggerObj, messages, { tumble = false, triggerHeld = null } = {}) {
    messages.push(magicBagExplosionMessage(triggerObj, tumble));
    if (isBagOfHoldingObject(triggerObj)) {
        const lostContext = triggerHeld == null ? null : { held: !!triggerHeld };
        scatterMagicBagContents(triggerObj, messages, { lostContext });
    }
    destroyMagicBagItem(triggerObj, messages, { silent: true, usedUpShopBill: true });
    scatterMagicBagContents(targetBag, messages);
    destroyMagicBagItem(targetBag, messages, { silent: true, usedUpShopBill: true });
    damageHeroWithMagicBagExplosion(messages);
    return { bagGone: true, moved: true, message: '', messages };
}

function visibleCreatedMonster(mon) {
    if (!mon || game.u?.blind) return false;
    return cansee(mon.mx, mon.my) || !!(game.viz_array?.[mon.my]?.[mon.mx] & IN_SIGHT);
}

function chargedToolUsageBasePrice(obj) {
    return shopItemPrice(obj, game.u?.ux, game.u?.uy) || shopBaseCost(obj) || 0;
}

function chargedUsageChargeCount(obj, override = null) {
    if (override != null) return Math.max(0, Math.trunc(Number(override || 0)));
    if (isWandItem(obj)) return Math.max(0, wandCharges(obj));
    const kind = toolChargeKind(obj);
    if ((kind === 'oil lamp' || kind === 'brass lantern' || kind === 'magic lamp')
        && obj?.spe == null && obj?.charges == null)
        return 1;
    return Math.max(0, Math.trunc(Number(obj?.spe ?? obj?.charges ?? 0)));
}

function chargedUsageIsChargeBased(obj) {
    if (isWandItem(obj)) return true;
    const kind = toolChargeKind(obj);
    return CHARGED_TOOL_KINDS.has(kind)
        || kind === 'oil lamp' || kind === 'brass lantern' || kind === 'magic lamp';
}

function chargedToolUsageFee(obj, altusage = false, chargeCount = chargedUsageChargeCount(obj)) {
    let fee = chargedToolUsageBasePrice(obj);
    if (!(fee > 0)) return 0;
    const kind = toolChargeKind(obj);
    if (kind === 'magic lamp') {
        if (!altusage) return shopBaseCost({ cls: 'tool', kind: 'oil lamp', actualKind: 'oil lamp' }) || 0;
        fee += Math.trunc(fee / 3);
    } else if (kind === 'magic marker') {
        fee = Math.trunc(fee / 2);
    } else if (!altusage && (isBagOfTricksObject(obj) || isHornOfPlentyObject(obj))) {
        fee = Math.trunc(fee / 5);
    } else if (isWandItem(obj) || kind === 'crystal ball' || kind === 'oil lamp'
        || kind === 'brass lantern' || kind === 'magic flute' || kind === 'magic harp'
        || kind === 'frost horn' || kind === 'fire horn' || kind === 'drum of earthquake') {
        if (chargeCount > 1) fee = Math.trunc(fee / 4);
    } else if (obj?.cls === 'spellbook' || obj?.glyph === '+') {
        fee -= Math.trunc(fee / 5);
    } else if (kind === 'can of grease' || kind === 'tinning kit' || kind === 'expensive camera') {
        fee = Math.trunc(fee / 10);
    } else if (obj?.cls === 'potion' && /(?:^| )oil$|potion of oil/.test(objectKindKey(obj))) {
        fee = Math.trunc(fee / 5);
    }
    return Math.max(0, fee);
}

function chargedToolUsageFeeMessage(obj, fee, altusage = false, shkp = null) {
    let arg1 = '';
    let arg2 = '';
    if (obj?.cls === 'spellbook' || obj?.glyph === '+') {
        const additional = (shkp?.debit || 0) > 0 ? ' an additional' : '';
        return `"This is no free library!  You owe${additional} ${fee} zorkmid${fee === 1 ? '' : 's'}."`;
    }
    if (obj?.cls === 'potion' && /(?:^| )oil$|potion of oil/.test(objectKindKey(obj)))
        return `"That will cost you ${fee} zorkmid${fee === 1 ? '' : 's'} (Yendorian Fuel Tax)."`;
    if (altusage && (isBagOfTricksObject(obj) || isHornOfPlentyObject(obj))) {
        if (!rn2(3)) arg1 = 'Whoa!  ';
        if (!rn2(3)) arg1 = 'Watch it!  ';
        return `"${arg1}Emptying that will cost you ${fee} zorkmid${fee === 1 ? '' : 's'}."`;
    }
    if (!rn2(3)) arg1 = 'Hey!  ';
    if (!rn2(3)) arg2 = 'Ahem.  ';
    return `"${arg1}${arg2}Usage fee, ${fee} zorkmid${fee === 1 ? '' : 's'}."`;
}

function checkUnpaidUsage(obj, messages, { altusage = false, chargeCount = null } = {}) {
    const shkp = heroShopkeeper();
    if (!shkp) return 0;
    const billEntry = shopBillEntryForObject(shkp, obj);
    if (!billEntry || billEntry.useup) return 0;
    const currentCharges = chargedUsageChargeCount(obj, chargeCount);
    if (chargedUsageIsChargeBased(obj) && currentCharges <= 0) return 0;
    const fee = chargedToolUsageFee(obj, altusage, currentCharges);
    if (!(fee > 0)) return 0;
    const message = chargedToolUsageFeeMessage(obj, fee, altusage, shkp);
    shkp.debit = Math.max(0, Math.trunc(Number(shkp.debit || 0))) + fee;
    if (shopkeeperCanSpeakToHero(shkp)) messages?.push(message);
    return fee;
}

function billChargedToolUsage(obj, messages, { altusage = false, chargeCount = tipChargeCount(obj) } = {}) {
    return checkUnpaidUsage(obj, messages, { altusage, chargeCount });
}

function floorSpecialSourceUsageBill(source) {
    if (!source || (game.inventory || []).includes(source) || source.no_charge) return null;
    const x = source.ox ?? game.u?.ux;
    const y = source.oy ?? game.u?.uy;
    if (x == null || y == null || x !== game.u?.ux || y !== game.u?.uy) return null;
    const shkp = shopkeeperForCostlySpot(x, y);
    if (!shopkeeperInHisShop(shkp)) return null;
    const price = shopItemPrice(source, x, y);
    if (!(price > 0)) return null;
    return {
        shkp,
        unpaid: source.unpaid,
        unpaidPrice: source.unpaidPrice,
        line: source.line,
        price,
    };
}

function beginFloorSpecialSourceUsageBill(source) {
    const saved = floorSpecialSourceUsageBill(source);
    if (!saved) return null;
    const existingEntry = shopBillEntryForObject(saved.shkp, source);
    const savedEntry = existingEntry ? { ...existingEntry } : null;
    const billEntry = existingEntry || addObjectToShopBill(saved.shkp, source, saved.price);
    if (!billEntry) return null;
    return () => {
        if (savedEntry) Object.assign(existingEntry, savedEntry);
        else removeObjectFromShopBillById(saved.shkp, shopBillObjectId(source));
        saved.shkp.billct = Array.isArray(saved.shkp.bill) ? saved.shkp.bill.length : Math.max(0, saved.shkp.billct || 0);
        source.unpaid = saved.unpaid;
        source.unpaidPrice = saved.unpaidPrice;
        source.line = saved.line;
    };
}

async function applyBagOfTricksOnce(bag, { tipping = false } = {}) {
    if (tipChargeCount(bag) < 1) {
        if (tipping && bag.cknown) return ["It's empty."];
        if (isKnownBagOfTricksObject(bag)) bag.cknown = true;
        return ['Nothing happens.'];
    }

    const messages = [];
    if (!tipping) billChargedToolUsage(bag, messages);
    consumeTipCharge(bag);
    let creatcnt = 1;
    if (!rn2(23)) creatcnt += rnd(7);
    let moncount = 0;
    let seecount = 0;
    for (let i = 0; i < creatcnt; i++) {
        const mon = await makemon(null, game.u?.ux || 0, game.u?.uy || 0, 0);
        if (!mon) continue;
        moncount++;
        if (visibleCreatedMonster(mon)) seecount++;
    }
    if (seecount && bag.dknown) identifyChargedToolKind(bag, 'bag of tricks');
    if (!tipping && !seecount) messages.push(moncount ? 'Nothing seems to happen.' : 'Nothing happens.');
    return messages;
}

async function lootFloorBagOfTricks(bag) {
    bag.lknown = true;
    const bagName = articlelessObjectName(bag);
    const damage = rnd(10);
    if (game.u) {
        game.u.uhp = Math.max(0, (game.u.uhp || 0) - damage);
        if ((game.u.uhp || 0) <= 0) game._death_cause = 'killed by a carnivorous bag';
    }
    identifyChargedToolKind(bag, 'bag of tricks');
    const messages = [
        `You carefully open the ${bagName}...`,
        'It develops a huge set of teeth and bites you!',
    ];
    if ((game.u?.uhp || 0) <= 0) messages.push('You die...');
    await setMessage(messages.join('  '), messages.length > 1);
    game.context.move = 1;
}

async function tipBagOfTricks(bag) {
    if (tipChargeCount(bag) < 1) return applyBagOfTricksOnce(bag, { tipping: true });
    const oldSpe = tipChargeCount(bag);
    let seen = false;
    while (tipChargeCount(bag) > 0) {
        const beforeMonsters = (game.level?.monsters || []).length;
        const messages = await applyBagOfTricksOnce(bag, { tipping: true });
        if (messages.length) return messages;
        const created = (game.level?.monsters || []).slice(beforeMonsters);
        if (created.some(visibleCreatedMonster)) seen = true;
    }
    if (tipChargeCount(bag) < oldSpe) {
        bag.spe = 0;
        bag.cknown = true;
        updateChargedItemLine(bag);
        const messages = seen ? [] : ['Nothing seems to happen.'];
        billChargedToolUsage(bag, messages, { altusage: true, chargeCount: oldSpe });
        return messages;
    }
    return [];
}

function hornCreatedObjectDescription(obj, potion) {
    if (potion) return (obj.quan || 1) > 1 ? 'Some potions' : 'A potion';
    return 'Some food';
}

function hornSpillMessage(obj, potion) {
    const what = hornCreatedObjectDescription(obj, potion);
    const spills = !potion || what === 'A potion';
    return `${what} ${spills ? 'spills' : 'spill'} out.`;
}

function createHornOfPlentyObject(horn) {
    const potion = !rn2(13);
    const obj = mkobj(potion ? POTION_CLASS : FOOD_CLASS, false);
    if (!potion && objectKindKey(obj) === 'food ration' && !rn2(7)) {
        Object.assign(obj, {
            otyp: LUMP_OF_ROYAL_JELLY,
            kind: 'lump of royal jelly',
            singular: 'lump of royal jelly',
            plural: 'lumps of royal jelly',
        });
    }
    obj.blessed = !!horn.blessed;
    obj.cursed = !!horn.cursed;
    Object.assign(obj, object_display(obj));
    return { obj, potion };
}

function hornCreatedObjectBillMessage(obj, price) {
    const name = pickupObjectName(obj);
    const subject = (obj.quan || 1) > 1 ? upstartText(name) : `The ${name}`;
    const each = (obj.quan || 1) > 1 ? ' each' : '';
    return `${subject} will cost you ${price} zorkmid${price === 1 ? '' : 's'}${each}.`;
}

function billHornCreatedObject(horn, obj, messages, { silent = false } = {}) {
    if (!horn?.unpaid || !obj) return 0;
    const shkp = heroShopkeeper();
    if (!shkp) return 0;
    const price = shopItemPrice(obj, game.u?.ux, game.u?.uy);
    if (!(price > 0)) return 0;
    if (!addObjectToShopBill(shkp, obj, price)) return 0;
    if (!silent && !heroIsDeaf()) messages?.push(hornCreatedObjectBillMessage(obj, price));
    return price;
}

function mergeStackedUnpaidBill(stacked, obj) {
    if (!stacked || stacked === obj || !obj?.unpaid) return;
    const price = unpaidBillPrice(stacked) + unpaidBillPrice(obj);
    if (!(price > 0)) return;
    stacked.unpaid = true;
    stacked.unpaidPrice = price;
    syncUnpaidBillLine(stacked);
}

function placeHornObjectOnFloor(obj, messages) {
    const x = game.u?.ux ?? 0;
    const y = game.u?.uy ?? 0;
    placeTippedObjectOnFloor(obj, x, y, messages);
    messages.push(`${upstartText(containerObjectPhrase(obj))} drops to the floor.`);
}

function hornApplyFloorMessage(obj) {
    const quan = obj.quan || 1;
    const name = pickupObjectName({ ...obj, quan: 1 });
    const subject = quan > 1 ? upstartText(containerObjectPhrase(obj)) : `The ${name}`;
    return `Oops! ${subject} slip${quan > 1 ? '' : 's'} to the floor!`;
}

function placeAppliedHornObjectOnFloor(obj, messages) {
    const x = game.u?.ux ?? 0;
    const y = game.u?.uy ?? 0;
    placeTippedObjectOnFloor(obj, x, y, messages);
    messages.push(hornApplyFloorMessage(obj));
}

function addAppliedHornObjectToInventory(obj, messages) {
    game.inventory ??= [];
    const used = new Set(game.inventory.map(item => item.letter).filter(Boolean));
    const letter = nextInventoryLetter();
    if (!letter || used.has(letter)) {
        placeAppliedHornObjectOnFloor(obj, messages);
        return;
    }
    prepareTippedObjectForContainer(obj);
    obj.letter = letter;
    const displayLine = normalInventoryLine({ ...obj, line: '' });
    obj.line = displayLine;
    if (obj.unpaid) syncUnpaidBillLine(obj);
    game.inventory.push(obj);
    maybeAttachCarriedFigurineTimeout(obj);
    game._pet_food_scan_inventory = game.inventory;
    messages.push(`${displayLine}.`);
}

function applyHornOfPlentyOnce(horn) {
    if (tipChargeCount(horn) < 1) {
        horn.cknown = true;
        updateChargedItemLine(horn);
        return ['Nothing happens.'];
    }

    const messages = [];
    billChargedToolUsage(horn, messages);
    consumeTipCharge(horn);
    const { obj, potion } = createHornOfPlentyObject(horn);
    messages.push(hornSpillMessage(obj, potion));
    billHornCreatedObject(horn, obj, messages);
    if (horn.dknown) identifyChargedToolKind(horn, 'horn of plenty');
    updateChargedItemLine(horn);
    addAppliedHornObjectToInventory(obj, messages);
    return messages;
}

async function tipHornOfPlenty(horn, targetBox = null) {
    if (tipChargeCount(horn) < 1) {
        horn.cknown = true;
        updateChargedItemLine(horn);
        return ['Nothing happens.'];
    }

    const messages = [];
    const oldSpe = tipChargeCount(horn);
    while (tipChargeCount(horn) > 0) {
        consumeTipCharge(horn);
        const { obj, potion } = createHornOfPlentyObject(horn);
        messages.push(hornSpillMessage(obj, potion));
        billHornCreatedObject(horn, obj, messages, { silent: true });
        if (targetBox) {
            prepareTippedObjectForContainer(obj);
            const stacked = add_to_container(targetBox, obj);
            mergeStackedUnpaidBill(stacked, obj);
            refreshTipContainerWeight(targetBox);
        } else {
            placeHornObjectOnFloor(obj, messages);
        }
    }
    if (tipChargeCount(horn) < oldSpe) {
        horn.spe = 0;
        horn.cknown = true;
        if (horn.dknown) identifyChargedToolKind(horn, 'horn of plenty');
        updateChargedItemLine(horn);
        billChargedToolUsage(horn, messages, { altusage: true, chargeCount: oldSpe });
    }
    return messages;
}

async function tipSpecialSourceContents(source, targetBox = null) {
    if (targetBox) {
        const targetError = tipContainerCheckMessages(targetBox, { allowEmpty: true });
        if (targetError) return targetError;
    }
    const restoreFloorBill = beginFloorSpecialSourceUsageBill(source);
    try {
        if (isBagOfTricksObject(source)) return await tipBagOfTricks(source);
        if (isHornOfPlentyObject(source)) return await tipHornOfPlenty(source, targetBox);
        return null;
    } finally {
        if (restoreFloorBill) restoreFloorBill();
    }
}

function tipContainerIntoContainer(source, targetBox) {
    const contents = [...liquidFlowContainerContents(source)];
    source.cknown = true;
    if (!contents.length) return [tipContainerEmptyMessage(source)];
    targetBox.contents ??= [];
    const cursedMagicBag = isMagicBagObject(source) && source.cursed;
    const sourceHeld = objectCarriedByHero(source);
    let lostMerchandise = 0;
    const messages = [contents.length === 1
        ? `An object tumbles into ${tipTargetPhrase(targetBox)}.`
        : `Objects tumble into ${tipTargetPhrase(targetBox)}.`];
    let targetGone = false;
    for (const obj of contents) {
        removeContainedObject(source, obj);
        thawObjectTippedFromSource(source, obj);
        if (cursedMagicBag && !rn2(13)) {
            lostMerchandise += billMagicBagLostItem(source, obj);
            destroyMagicBagItem(obj, messages);
            continue;
        }
        addTippedContainerObjectToShopBill(source, obj);
        prepareTippedObjectForContainer(obj);
        if (isMagicBagObject(targetBox) && magicBagExplodesWithObject(obj)) {
            explodeMagicBagTransfer(targetBox, obj, messages, { tumble: true, triggerHeld: sourceHeld });
            targetGone = true;
            break;
        }
        add_to_container(targetBox, obj);
    }
    refreshTipContainerWeight(source);
    if (!targetGone) refreshTipContainerWeight(targetBox);
    const lostMessage = lostShopMerchandiseMessage(lostMerchandise);
    if (lostMessage) messages.push(lostMessage);
    return messages;
}

async function tipContainerContents(source, targetBox = null) {
    const special = isBagOfTricksObject(source) || isHornOfPlentyObject(source);
    if (targetBox && isBagOfTricksObject(targetBox))
        return applyBagOfTricksOnce(targetBox, { tipping: false });
    const sourceError = tipContainerCheckMessages(source, { allowEmpty: special });
    if (sourceError) return sourceError;
    if (special) return tipSpecialSourceContents(source, targetBox);
    if (targetBox) {
        const targetError = tipContainerCheckMessages(targetBox, { allowEmpty: true });
        if (targetError) return targetError;
    }
    return targetBox ? tipContainerIntoContainer(source, targetBox) : tipContainerToFloor(source);
}

async function finishTipContainerCommandMessages(messages) {
    const trapResult = messages?._trapResult;
    await setMessage((messages || []).join('  '), (messages || []).length > 1 || !!trapResult?.more);
    if (trapResult && applyLifeSavingOrFatalCommandMode(trapResult)) return true;
    game.context ??= {};
    game.context.move = 1;
    game._command_mode = null;
    return false;
}

async function finishCarriedTipSelection(tipTarget) {
    game._overlay_lines = null;
    game._overlay_hide_status = 0;
    if (isTipWornHelmet(tipTarget)) {
        await beginTipHat(tipTarget);
        return;
    }
    if (isTipSourceObject(tipTarget)) {
        game._tip_container_object = tipTarget;
        if (beginTipDestinationSelection(tipTarget)) return;
        game._tip_container_object = null;
        const messages = await tipContainerContents(tipTarget);
        await finishTipContainerCommandMessages(messages);
        return;
    }
    game._tip_container_object = null;
    const messages = isTipSpillageObject(tipTarget)
        ? tipSpillageObject(tipTarget)
        : tipOrdinaryObjectMessages(tipTarget);
    await setMessage(messages.join('  '), messages.length > 1);
    if (isTipSpillageObject(tipTarget)) game.context.move = 1;
    game._command_mode = null;
}

function tipContainerObjectPhrase(obj) {
    const phrase = containerObjectPhrase(obj);
    if (!(obj?.broken || obj?.obroken)) return phrase;
    if (!/^(?:an? |the )?(?:large box|chest)$/i.test(phrase)) return phrase;
    return phrase.replace(/^(an? |the )/i, '$1broken ');
}

function containerObjectPhrase(obj) {
    const count = obj.quan || 1;
    const name = pickupObjectName(obj);
    if (count > 1) return `${count} ${name}`;
    if (obj.unique) return `the ${name}`;
    if (obj.noArticle) return name;
    if (pairArticleObjectName(name))
        return `a pair of ${name}`;
    const article = /^[aeiou]/i.test(name) || name === 'orcish helm' ? 'an' : 'a';
    return `${article} ${name}`;
}

function objectBucCategory(item) {
    if (item.otyp === GOLD_PIECE || item.cls === 'coin' || item.glyph === '$')
        return game.flags?.goldX ? 'unknown' : 'uncursed';
    if (item.bknown !== true && game._startup_role !== 'Priest') return 'unknown';
    if (item.blessed) return 'blessed';
    if (item.cursed) return 'cursed';
    return 'uncursed';
}

function pickupObjectPhrase(obj) {
    recordObservedObjectDiscovery(obj);
    const count = obj.quan || 1;
    const name = pickupObjectName(obj);
    if (obj === game.u?.uchain) return 'an iron chain (attached to you)';
    if (obj === game.u?.uball) {
        const weight = (obj.owt || 0) > 480 ? 'very heavy' : 'heavy';
        return `a ${weight} iron ball (chained to you)`;
    }
    if (obj.otyp === SCROLL_CLASS || obj.cls === 'scroll') {
        const rawScrollName = String(obj.actualKind || obj.kind || '')
            .replace(/^scroll(?::| of | labeled )/, '');
        const scrollIndex = obj.scrollIndex ?? IDENTIFIED_SCROLL_NAMES.indexOf(rawScrollName);
        const scrollName = IDENTIFIED_SCROLL_NAMES[scrollIndex];
        if (scrollName) {
            const label = String(obj.kind || '').startsWith('scroll labeled ')
                ? String(obj.kind).slice(15)
                : game._object_descriptions?.scrolls?.[scrollIndex];
            const discoveryName = `scroll of ${scrollName}`;
            game._discoveries ??= [];
            if (!game._discoveries.some(entry => entry.section === 'Scrolls' && entry.name === discoveryName)) {
                game._discoveries.push({
                    section: 'Scrolls',
                    name: discoveryName,
                    text: label ? `${discoveryName} (${label})` : discoveryName,
                    starred: false,
                    known: false,
                });
            }
        }
    }
    const lineShowsSpe = /(?:^| )[-+]\d+ /.test(String(obj.line || ''));
    const showSpe = obj.known === true || lineShowsSpe;
    if (count === 1 && (obj.cls === 'weapon' || obj.glyph === ')') && obj.spe != null && showSpe) {
        const spe = `${obj.spe >= 0 ? '+' : ''}${obj.spe} `;
        const article = /^[aeiou]/i.test(`${spe}${name}`) ? 'an' : 'a';
        return `${article} ${spe}${name}`;
    }
    if (count > 1) return `${count} ${name}`;
    if (obj.unique) return `the ${name}`;
    if (obj.noArticle) return name;
    if (pairArticleObjectName(name))
        return `a pair of ${name}`;
    const article = /^[aeiou]/i.test(name) || name === 'orcish helm' ? 'an' : 'a';
    return `${article} ${name}`;
}

function shopBaseCost(obj) {
    const cls = obj.cls || '';
    let kind = String(obj.actualKind || obj.kind || '').toLowerCase();
    kind = kind.replace(/^(?:blessed|uncursed|cursed) /, '');
    if (isGlobbyObject(obj)) return 6;
    if (isBellOfOpeningItem(obj)) return SHOP_OBJECT_COSTS['bell of opening'];

    if (obj.otyp === SCROLL_CLASS || cls === 'scroll' || obj.otyp === SCR_SCARE_MONSTER) {
        const scrollIndex = obj.scrollIndex ?? (obj.otyp === SCR_SCARE_MONSTER ? 3 : undefined);
        if (scrollIndex != null) return SCROLL_SHOP_COSTS[scrollIndex] || 0;
        kind = kind.replace(/^scroll(?::| of | labeled )/, '');
        return SHOP_OBJECT_COSTS[kind] || (kind === 'blank paper' ? 60 : 0);
    }
    if (obj.otyp === POTION_CLASS || cls === 'potion') {
        if (obj.potionIndex != null) return POTION_SHOP_COSTS[obj.potionIndex] || 0;
        kind = kind.replace(/^potion(?::| of )/, '');
        if (kind === 'holy water' || kind === 'unholy water') return 100;
        if (kind === 'water') return obj.blessed || obj.cursed ? 100 : 0;
        return SHOP_OBJECT_COSTS[kind] || 0;
    }
    if (obj.otyp === WAND_CLASS || cls === 'wand') {
        if (obj.spe === -1) return 0;
        if (obj.wandIndex != null) return WAND_SHOP_COSTS[obj.wandIndex] || 0;
        kind = kind.replace(/^wand of /, '');
        return SHOP_OBJECT_COSTS[kind] || 0;
    }
    if (obj.otyp === RING_CLASS || cls === 'ring' || obj.glyph === '=') {
        if (obj.ringRoll) return RING_SHOP_COSTS[obj.ringRoll - 1] || 0;
        kind = kind.replace(/^ring of /, '');
        const ringIndex = IDENTIFIED_RING_NAMES.indexOf(kind);
        return ringIndex >= 0 ? RING_SHOP_COSTS[ringIndex] : 0;
    }
    if (obj.otyp === AMULET_CLASS || cls === 'amulet') {
        if (obj.amuletIndex != null) return 150;
        if (kind === 'amulet of yendor') return 30000;
        if (kind === 'cheap plastic imitation of the amulet of yendor') return 0;
        return kind.startsWith('amulet ') ? 150 : 0;
    }
    if (cls === 'spellbook' || obj.otyp === SPBOOK_NO_NOVEL || obj.otyp === SPE_HEALING) {
        const name = String(obj.spellName || obj.spell?.name || kind)
            .replace(/^spellbook(?: of)? /, '');
        if (name === 'novel') return 20;
        if (name === 'blank paper') return 0;
        return (SPELLBOOK_LEVELS[name] || 0) * 100;
    }

    if (!kind && obj.otyp === CHEST) kind = 'chest';
    else if (!kind && obj.otyp === LARGE_BOX) kind = 'large box';
    else if (!kind && obj.otyp === ICE_BOX) kind = 'ice box';
    else if (!kind && obj.otyp === OIL_LAMP) kind = 'oil lamp';
    else if (!kind && obj.otyp === MAGIC_LAMP) kind = 'magic lamp';
    else if (!kind && obj.otyp === DART) kind = 'dart';
    else if (!kind && obj.otyp === MIRROR) kind = 'mirror';
    else if (!kind && obj.otyp === CREAM_PIE) kind = 'cream pie';
    else if (!kind && obj.otyp === EXPENSIVE_CAMERA) kind = 'expensive camera';
    else if (!kind && obj.otyp === TINNING_KIT) kind = 'tinning kit';
    else if (!kind && obj.otyp === CAN_OF_GREASE) kind = 'can of grease';
    else if (!kind && obj.otyp === MAGIC_FLUTE) kind = 'magic flute';
    else if (!kind && obj.otyp === FROST_HORN) kind = 'frost horn';
    else if (!kind && obj.otyp === FIRE_HORN) kind = 'fire horn';
    else if (!kind && obj.otyp === HORN_OF_PLENTY) kind = 'horn of plenty';
    else if (!kind && obj.otyp === MAGIC_HARP) kind = 'magic harp';
    else if (!kind && obj.otyp === DRUM_OF_EARTHQUAKE) kind = 'drum of earthquake';
    else if (!kind && obj.otyp === STETHOSCOPE) kind = 'stethoscope';
    else if (!kind && obj.otyp === MAGIC_MARKER) kind = 'magic marker';
    if ((obj.foodRoll || 1000) <= 140 || kind === 'tripe') kind = 'tripe ration';
    const metadata = wishObjectMetadataForItem(obj);
    if (metadata?.unitCost != null) return metadata.unitCost;
    return SHOP_OBJECT_COSTS[kind] || 0;
}

function shopPricingUnits(obj) {
    if (isGlobbyObject(obj))
        return Math.max(1, Math.trunc(((obj.owt ?? 20) + 19) / 20));
    return obj?.quan || 1;
}

function shopObjectNameKnown(obj) {
    if (obj.known === true) return true;
    if (obj.known === false) return false;
    let kind = String(obj.actualKind || obj.kind || '').toLowerCase();
    kind = kind.replace(/^(?:blessed|uncursed|cursed) /, '');
    if (!kind) return false;
    if (obj.cls === 'armor' || obj.glyph === '[')
        return !ARMOR_WISH_APPEARANCES[kind]
            || (game._discoveries || []).some(entry => entry.section === 'Armor' && entry.name === kind && entry.starred);
    return true;
}

function levelRoomByRoomno(roomno) {
    if (roomno < ROOMOFFSET) return null;
    const idx = roomno - ROOMOFFSET;
    return game.level?.rooms?.[idx]
        || (game.level?.subrooms || []).find(room => room?.roomnoidx === idx)
        || null;
}

function queueMessageAfterMore(text, more = false, { blockTimeUntilClear = false } = {}) {
    if (!text) return;
    game._queued_message_after_more = game._queued_message_after_more
        ? `${game._queued_message_after_more}  ${text}`
        : text;
    if (more) game._queued_message_more_after_more = 1;
    if (blockTimeUntilClear) game._queued_message_blocks_time_after_more = 1;
}

function specialRoomEntryText(roomno) {
    const room = levelRoomByRoomno(roomno);
    if (!room) return '';
    if (room.rtype === MORGUE) return 'You have an uncanny feeling...';
    return '';
}

function tendedTemplePriest(roomno) {
    return (game.level?.monsters || []).find(mon =>
        mon.ispriest && mon.shrine?.room === roomno
        && game.level?.at(mon.mx, mon.my)?.roomno === roomno);
}

function tendedTemplePriestIntone(roomno) {
    const priest = tendedTemplePriest(roomno);
    if (!priest || game.u?.deaf) return '';
    const moves = game.moves || 0;
    if (moves < (priest._intone_time || 0)) return '';
    priest._intone_time = moves + d(10, 500);
    priest._enter_time = 0;
    const visible = !game.u?.blind && !priest.minvis && !priest.mundetected && couldsee(priest.mx, priest.my);
    return `${visible ? `The ${priest.data?.name || 'priest'}` : 'A nearby voice'} intones:`;
}

function tendedTemplePriestHasShrine(priest) {
    const shrine = priest?.shrine;
    const loc = shrine ? game.level?.at(shrine.x, shrine.y) : null;
    if (!priest?.ispriest || !shrine || loc?.typ !== ALTAR) return false;
    const altarMask = (loc.flags ?? loc.altarmask ?? 0) & ~AM_SHRINE;
    return priest.shrine.align === Amask2align(altarMask);
}

function tendedTemplePriestEntryText(roomno) {
    const priest = tendedTemplePriest(roomno);
    if (!priest || game.u?.deaf) return '';
    const moves = game.moves || 0;
    const shrined = tendedTemplePriestHasShrine(priest);
    const messages = [];
    if (moves >= (priest._enter_time || 0)) {
        messages.push(`"Pilgrim, you enter a ${shrined ? 'sacred' : 'desecrated'} place!"`);
        priest._enter_time = moves + d(10, 100);
    }

    const coaligned = (game.u?.ualign?.type ?? 0) === priest.shrine?.align;
    const record = game.u?.ualign?.record ?? 0;
    const forbidding = !shrined || !coaligned || record <= -4;
    const timeKey = forbidding ? '_hostile_time' : '_peaceful_time';
    const otherKey = forbidding ? '_peaceful_time' : '_hostile_time';
    if (moves >= (priest[timeKey] || 0) || (priest[otherKey] || 0) >= (priest[timeKey] || 0)) {
        if (forbidding) {
            const strange = shrined && coaligned ? ' strange' : '';
            messages.push(`You have a${strange} forbidding feeling...`);
        } else {
            messages.push(`You experience ${record >= 14 ? 'a' : 'an unusual'} sense of peace.`);
        }
        priest[timeKey] = moves + d(10, 20);
        if (priest[timeKey] <= (priest[otherKey] || 0))
            priest[otherKey] = priest[timeKey] - 1;
    }
    return messages.join('  ');
}

function prepareUntendedTempleEntry(newRoomno, oldRoomno = 0) {
    if (!newRoomno || newRoomno === oldRoomno) return null;
    const room = levelRoomByRoomno(newRoomno);
    if (room?.rtype !== TEMPLE || tendedTemplePriest(newRoomno)) return null;
    const roll = rn2(4);
    const text = roll === 0 ? 'You have an eerie feeling...'
        : roll === 1 ? 'You feel like you are being watched.'
            : roll === 2 ? 'A shiver runs down your spine.'
                : '';
    return { text };
}

async function finishUntendedTempleEntry() {
    if (rn2(5)) return '';
    const ghost = await makemon(monsterByRndName('ghost'), game.u?.ux || 0, game.u?.uy || 0, MM_NOMSG);
    if (!ghost) return '';
    ghost.mpeaceful = 0;
    set_malign(ghost);
    newsym(ghost.mx, ghost.my);
    if (game.u?.blind || !(game.viz_array?.[ghost.my]?.[ghost.mx] & IN_SIGHT))
        return 'You sense a presence close by!';
    return 'A ghost appears next to you!';
}

async function queueUntendedTempleEntryAfterTeleport(oldX, oldY, newX, newY) {
    const oldRoomno = game.level?.at(oldX, oldY)?.roomno || 0;
    const newRoomno = game.level?.at(newX, newY)?.roomno || 0;
    const templeEntry = prepareUntendedTempleEntry(newRoomno, oldRoomno);
    if (!templeEntry) return;
    if (templeEntry.text) {
        queueMessageAfterMore(templeEntry.text);
        game._queued_temple_ghost_roll_after_more = 1;
        return;
    }
    const ghostText = await finishUntendedTempleEntry();
    if (ghostText) queueMessageAfterMore(ghostText);
}

function shopItemPrice(obj, x = game.u?.ux, y = game.u?.uy) {
    if (!obj || obj.otyp === GOLD_PIECE || obj.cls === 'coin' || obj.glyph === '$') return null;
    if ((obj.cls === 'food' || obj.otyp === FOOD_CLASS || obj.otyp === CORPSE || obj.otyp === 'corpse') && obj.oeaten)
        return 0;
    const loc = game.level?.at(x, y);
    const roomno = loc?.roomno || 0;
    const room = levelRoomByRoomno(roomno);
    if (!room || room.rtype < SHOPBASE) return null;
    const shkp = room.resident || (game.level?.monsters || [])
        .find(mon => mon.isshk && mon.shoproom === roomno);
    if (!shkp?.isshk) return null;
    if (shkp.shk && x === shkp.shk.x && y === shkp.shk.y) return 0;
    if (obj.no_charge) return 0;

    let price = shopBaseCost(obj);
    if (!price) return null;
    if ((obj.cls === 'armor' || obj.cls === 'weapon' || obj.glyph === '[' || obj.glyph === ')')
        && (obj.spe || 0) > 0) price += 10 * obj.spe;

    let multiplier = 1;
    let divisor = 1;
    if ((obj.dknown !== true || !shopObjectNameKnown(obj)) && ((obj.id ?? obj.o_id ?? 0) % 4) === 0) {
        multiplier *= 4;
        divisor *= 3;
    }
    const cha = game.u?.acurr?.a?.[A_CHA] ?? 10;
    if (cha > 18) divisor *= 2;
    else if (cha === 18) { multiplier *= 2; divisor *= 3; }
    else if (cha >= 16) { multiplier *= 3; divisor *= 4; }
    else if (cha <= 5) multiplier *= 2;
    else if (cha <= 7) { multiplier *= 3; divisor *= 2; }
    else if (cha <= 10) { multiplier *= 4; divisor *= 3; }
    price *= multiplier;
    if (divisor > 1) price = Math.trunc((Math.trunc(price * 10 / divisor) + 5) / 10);
    price = Math.max(1, price) * shopPricingUnits(obj);
    return price;
}

function containedShopNonGoldPrice(obj, x = game.u?.ux, y = game.u?.uy, seen = new Set()) {
    if (!obj || seen.has(obj)) return 0;
    seen.add(obj);
    let price = 0;
    for (const child of globContents(obj)) {
        if (!child || seen.has(child)) continue;
        if (!shopBillableGold(child) && !child.no_charge) {
            const childPrice = shopItemPrice(child, x, y);
            if (childPrice > 0) price += childPrice;
        }
        price += containedShopNonGoldPrice(child, x, y, seen);
    }
    return price;
}

function shopFloorItemPriceInfo(obj, x = game.u?.ux, y = game.u?.uy) {
    const top = shopItemPrice(obj, x, y);
    if (top == null) return null;
    const topPrice = top > 0 ? top : 0;
    const contentsPrice = globContents(obj).length
        ? containedShopNonGoldPrice(obj, x, y)
        : 0;
    const itemPrice = topPrice + contentsPrice;
    return {
        topPrice,
        contentsPrice,
        itemPrice,
        price: itemPrice,
        contentsOnly: contentsPrice > 0 && topPrice === 0,
        contentsIncluded: contentsPrice > 0 && topPrice > 0,
        noCharge: top === 0 && contentsPrice === 0,
    };
}

function shopItemPriceSuffix(obj, x = game.u?.ux, y = game.u?.uy) {
    const info = shopFloorItemPriceInfo(obj, x, y);
    if (!info) return '';
    if (info.itemPrice > 0) {
        const label = info.contentsOnly ? 'contents' : 'for sale';
        return ` (${label}, ${info.itemPrice} zorkmid${info.itemPrice === 1 ? '' : 's'})`;
    }
    if (info.noCharge) return ' (no charge)';
    return '';
}

function shopPickupQuoteMessage(obj, shopPrice, priceInfo = null) {
    const honorifics = ['good', 'honored', 'most gracious', 'esteemed'];
    const honorific = honorifics[rn2(4) || 1];
    const title = game.flags?.female ? 'lady' : 'sir';
    const pricingUnits = Math.max(1, Math.trunc(Number(shopPricingUnits(obj) || 1)));
    const stackQuote = (obj?.quan || 1) > 1;
    const quotePrice = stackQuote && pricingUnits > 1
        ? Math.max(1, Math.trunc(shopPrice / pricingUnits))
        : shopPrice;
    const relation = stackQuote
        ? 'per'
        : priceInfo?.contentsOnly
            ? 'for the contents of this'
            : 'for this';
    const name = pickupObjectName({ ...(obj || {}), quan: 1 });
    const contentsSuffix = !stackQuote && priceInfo?.contentsIncluded ? ' and its contents' : '';
    return `"For you, ${honorific} ${title}; only ${quotePrice} zorkmid${quotePrice === 1 ? '' : 's'} ${relation} ${name}${contentsSuffix}."`;
}

function shopPickupLinePriceSuffix(priceInfo, itemPrice) {
    const price = Math.max(0, Math.trunc(Number(itemPrice || 0)));
    if (!price) return '';
    const label = priceInfo?.contentsOnly ? 'contents' : 'unpaid';
    return ` (${label}, ${price} zorkmid${price === 1 ? '' : 's'})`;
}

function replaceShopPriceLineSuffix(line, suffix) {
    const base = String(line || '').replace(/ \((?:unpaid|contents), \d+ zorkmids?\)/, '');
    return suffix ? `${base}${suffix}` : base;
}

function shopDebtItemName(item) {
    let name = String(item?.line || '')
        .replace(/^[a-zA-Z$] - /, '')
        .replace(/ \(unpaid, \d+ zorkmids?\)/, '');
    if (name) return name;
    const baseName = pickupObjectName({ ...(item || {}), quan: 1 });
    return `${/^[aeiou]/i.test(baseName) ? 'an' : 'a'} ${baseName}`;
}

function findShopBillObjectInList(list, id, seen = new Set()) {
    if (id == null) return null;
    for (const item of list || []) {
        if (!item || seen.has(item)) continue;
        seen.add(item);
        if (String(shopBillObjectId(item)) === String(id)) return item;
        const contents = globContents(item);
        const found = contents.length ? findShopBillObjectInList(contents, id, seen) : null;
        if (found) return found;
    }
    return null;
}

function findShopBillObjectById(id) {
    return findShopBillObjectInList([...(game.inventory || []), ...(game.level?.objects || [])], id);
}

function usedUpShopBillTrackerForId(id, shkp = null) {
    const shkpId = shopkeeperIdentity(shkp);
    return (game._usedUpShopBills || []).find(bill => {
        if (String(bill?.bo_id) !== String(id)) return false;
        return shkpId == null || bill.shopkeeperId == null || String(bill.shopkeeperId) === String(shkpId);
    }) || null;
}

function removeUsedUpShopBillTracker(id, shkp = null) {
    const shkpId = shopkeeperIdentity(shkp);
    const before = (game._usedUpShopBills || []).length;
    game._usedUpShopBills = (game._usedUpShopBills || [])
        .filter(bill => String(bill?.bo_id) !== String(id)
            || (shkpId != null && bill.shopkeeperId != null && String(bill.shopkeeperId) !== String(shkpId)));
    return game._usedUpShopBills.length !== before;
}

function shopBillEntryDisplayName(entry, obj, quantity = null, shkp = null) {
    const tracker = usedUpShopBillTrackerForId(entry?.bo_id, shkp);
    if (tracker?.name) return tracker.name;
    if (entry?.name) return entry.name;
    if (obj) return shopDebtItemName(quantity ? { ...obj, quan: quantity, line: '' } : obj);
    return 'used-up object';
}

function outermostShopBillContainerForObject(obj) {
    let top = obj;
    const seen = new Set();
    while (top?.container && !seen.has(top.container)) {
        seen.add(top);
        top = top.container;
    }
    if (!top || top === obj) return null;
    if ((game.inventory || []).includes(top) || (game.level?.objects || []).includes(top))
        return top;
    return null;
}

function shopContainerPaymentName(container, includesContainer = false) {
    const baseName = pickupObjectName({ ...(container || {}), line: '', quan: 1 })
        .replace(/^empty /, '');
    if (includesContainer)
        return `${articleFor(`unpaid ${baseName}`)} and its contents`;
    if ((game.level?.objects || []).includes(container))
        return `the contents of the ${baseName}`;
    return `the contents of your ${baseName}`;
}

function addContainerPaymentBillItem(groups, container, item, billEntry, price, options = {}) {
    if (!container || !item || !(price > 0)) return;
    const key = shopBillObjectId(container);
    if (key == null) return;
    let group = groups.get(key);
    if (!group) {
        group = { container, billItems: [], price: 0, includesContainer: false, sortBillIndex: options.sortBillIndex };
        groups.set(key, group);
    } else if (group.sortBillIndex == null || options.sortBillIndex === -1
        || (options.sortBillIndex != null && group.sortBillIndex !== -1 && options.sortBillIndex < group.sortBillIndex)) {
        group.sortBillIndex = options.sortBillIndex;
    }
    const billId = billEntry?.bo_id ?? shopBillObjectId(item);
    if (group.billItems.some(entry => String(entry.billId) === String(billId))) return;
    group.billItems.push({ item, billEntry, billId, price, blockedByUsedUp: !!options.blockedByUsedUp });
    group.price += price;
    if (item === container) group.includesContainer = true;
    if (options.blockedByUsedUp) group.blockedByUsedUp = true;
}

function pushShopBillLedgerDebtEntries(shkp, entries, seenBillIds) {
    const ledger = Array.isArray(shkp?.bill) ? shkp.bill : [];
    const usedEntries = [];
    const intactEntries = [];
    const possibleTopContainerEntries = [];
    const containerPaymentGroups = new Map();
    for (let billIndex = 0; billIndex < ledger.length; billIndex++) {
        const billEntry = ledger[billIndex];
        const billId = String(billEntry.bo_id);
        seenBillIds.add(billId);
        const unitPrice = shopBillEntryUnitPrice(billEntry);
        const billedQuantity = shopBillEntryQuantity(billEntry);
        const obj = findShopBillObjectById(billId);
        const liveQuantity = obj ? Math.max(1, Math.trunc(Number(obj.quan || 1))) : 0;
        const tracker = usedUpShopBillTrackerForId(billId, shkp);

        if (billEntry.useup || !obj) {
            const price = shopBillEntryTotal(billEntry) || Number(tracker?.price || 0);
            if (price > 0) usedEntries.push({
                usedUpBill: tracker || { bo_id: billEntry.bo_id, price, name: billEntry.name },
                billEntry,
                billPortion: 'fullyUsedUp',
                quantity: billedQuantity,
                name: shopBillEntryDisplayName(billEntry, obj, billedQuantity, shkp),
                price,
                sortBillIndex: billIndex,
            });
            continue;
        }

        if (liveQuantity < billedQuantity && unitPrice > 0) {
            const usedQuantity = billedQuantity - liveQuantity;
            usedEntries.push({
                item: obj,
                billEntry,
                billPortion: 'partlyUsedUp',
                quantity: usedQuantity,
                name: shopBillEntryDisplayName(billEntry, obj, usedQuantity, shkp),
                price: unitPrice * usedQuantity,
                sortBillIndex: billIndex,
            });
            const intactPrice = unitPrice * liveQuantity;
            const topContainer = outermostShopBillContainerForObject(obj);
            if (topContainer) {
                addContainerPaymentBillItem(containerPaymentGroups, topContainer, obj, billEntry, intactPrice, {
                    blockedByUsedUp: true,
                    sortBillIndex: topContainer.unpaid ? billIndex : -1,
                });
            } else {
                intactEntries.push({
                    item: obj,
                    billEntry,
                    billPortion: 'intact',
                    quantity: liveQuantity,
                    blockedByUsedUp: true,
                    name: shopDebtItemName({ ...obj, quan: liveQuantity, line: '' }),
                    price: intactPrice,
                    sortBillIndex: billIndex,
                });
            }
            continue;
        }

        const price = shopBillEntryTotal(billEntry);
        if (!(price > 0)) continue;
        const intactEntry = {
            item: obj,
            billEntry,
            billPortion: 'intact',
            quantity: liveQuantity || billedQuantity,
            name: shopDebtItemName(obj),
            price,
            sortBillIndex: billIndex,
        };
        const topContainer = outermostShopBillContainerForObject(obj);
        if (topContainer) {
            addContainerPaymentBillItem(containerPaymentGroups, topContainer, obj, billEntry, price, {
                sortBillIndex: topContainer.unpaid ? billIndex : -1,
            });
        } else if (globContents(obj).length) {
            possibleTopContainerEntries.push(intactEntry);
        } else {
            intactEntries.push(intactEntry);
        }
    }
    for (const entry of possibleTopContainerEntries) {
        const group = containerPaymentGroups.get(shopBillObjectId(entry.item));
        if (group) addContainerPaymentBillItem(containerPaymentGroups, entry.item, entry.item, entry.billEntry, entry.price, {
            sortBillIndex: entry.sortBillIndex,
        });
        else intactEntries.push(entry);
    }
    for (const group of containerPaymentGroups.values()) {
        if (!(group.price > 0) || !group.billItems.length) continue;
        intactEntries.push({
            item: group.container,
            containerPayment: true,
            billPortion: 'containerContents',
            billItems: group.billItems,
            quantity: 1,
            name: shopContainerPaymentName(group.container, group.includesContainer),
            price: group.price,
            blockedByUsedUp: !!group.blockedByUsedUp,
            sortBillIndex: group.sortBillIndex,
        });
    }
    entries.push(...usedEntries, ...intactEntries);
}

function collectLegacyUnpaidShopItemsFromList(list, entries, shkp = null, seenBillIds = new Set()) {
    for (const item of list || []) {
        const billEntry = shopBillEntryForObject(shkp, item);
        if (billEntry && seenBillIds.has(String(billEntry.bo_id))) {
            const contents = globContents(item);
            if (contents.length) collectLegacyUnpaidShopItemsFromList(contents, entries, shkp, seenBillIds);
            continue;
        }
        const price = billEntry ? shopBillEntryTotal(billEntry) : unpaidBillPrice(item);
        if ((billEntry || (!shkp && item?.unpaid)) && price) entries.push({ item, billEntry, billPortion: 'legacy', name: shopDebtItemName(item), price });
        const contents = globContents(item);
        if (contents.length) collectLegacyUnpaidShopItemsFromList(contents, entries, shkp, seenBillIds);
    }
}

function collectPayableShopDebts(shkp = null) {
    const entries = [];
    const seenBillIds = new Set();
    if (shkp) pushShopBillLedgerDebtEntries(shkp, entries, seenBillIds);
    collectLegacyUnpaidShopItemsFromList(game.inventory || [], entries, shkp, seenBillIds);
    collectLegacyUnpaidShopItemsFromList(game.level?.objects || [], entries, shkp, seenBillIds);
    for (const bill of game._usedUpShopBills || []) {
        const price = Number(bill?.price || 0);
        if (seenBillIds.has(String(bill?.bo_id))) continue;
        const shkpId = shopkeeperIdentity(shkp);
        if (shkpId != null && bill.shopkeeperId != null && String(bill.shopkeeperId) !== String(shkpId)) continue;
        if (price > 0) entries.push({
            usedUpBill: bill,
            name: bill.name || 'used-up object',
            price,
        });
    }
    return entries
        .map((entry, index) => ({ entry, index }))
        .sort((a, b) => shopPaymentEntryCompare(a.entry, b.entry) || a.index - b.index)
        .map(({ entry }, index) => ({
            ...entry,
            letter: String.fromCharCode(97 + index),
            selected: false,
        }));
}

function shopkeeperDebitPayment(entry) {
    const shkp = entry?.shopkeeperDebit;
    if (!shkp) return { debt: 0, credit: 0, coveredByCredit: 0, cashDue: 0 };
    const debt = Math.max(0, Math.trunc(Number(shkp.debit ?? entry.price ?? 0)));
    const credit = Math.max(0, Math.trunc(Number(shkp.credit || 0)));
    const coveredByCredit = Math.min(credit, debt);
    return { debt, credit, coveredByCredit, cashDue: debt - coveredByCredit };
}

function shopPaymentEntryRank(entry) {
    if (entry?.shopkeeperDebit) return 0;
    if (entry?.billPortion === 'partlyUsedUp' || entry?.billPortion === 'fullyUsedUp' || entry?.usedUpBill) return 1;
    return 2;
}

function shopPaymentEntryIsUsedUp(entry) {
    return entry?.billPortion === 'partlyUsedUp'
        || entry?.billPortion === 'fullyUsedUp'
        || !!entry?.usedUpBill;
}

function shopPaymentEntryCompare(a, b) {
    const rank = shopPaymentEntryRank(a) - shopPaymentEntryRank(b);
    if (rank) return rank;
    const price = shopPaymentEntryValue(b) - shopPaymentEntryValue(a);
    if (price) return price;
    const aSortIndex = Number(a?.sortBillIndex);
    const bSortIndex = Number(b?.sortBillIndex);
    if (Number.isFinite(aSortIndex) && Number.isFinite(bSortIndex) && aSortIndex !== bSortIndex)
        return aSortIndex - bSortIndex;
    return 0;
}

function shopPaymentHasUsedUpSelection(selected, entry) {
    return selected.some(candidate =>
        candidate !== entry && candidate.billEntry === entry.billEntry
        && candidate.billPortion === 'partlyUsedUp');
}

function blockedShopPaymentBillItem(entry, selected) {
    if (entry?.containerPayment || entry?.billPortion === 'containerContents') {
        const billItems = Array.isArray(entry.billItems) ? entry.billItems : [];
        return billItems.find(billItem => {
            if (!billItem?.blockedByUsedUp || !billItem.billEntry || !billItem.item) return false;
            const liveQuantity = Math.max(1, Math.trunc(Number(billItem.item.quan || 1)));
            if (shopBillEntryQuantity(billItem.billEntry) <= liveQuantity) return false;
            return !shopPaymentHasUsedUpSelection(selected, { billEntry: billItem.billEntry });
        }) || null;
    }
    if (!entry?.blockedByUsedUp || !entry.billEntry || !entry.item) return null;
    const liveQuantity = Math.max(1, Math.trunc(Number(entry.item.quan || 1)));
    if (shopBillEntryQuantity(entry.billEntry) <= liveQuantity) return null;
    return !shopPaymentHasUsedUpSelection(selected, entry) ? { item: entry.item, billEntry: entry.billEntry } : null;
}

function shopPaymentEntryBlocked(entry, selected) {
    return !!blockedShopPaymentBillItem(entry, selected);
}

function blockedShopPaymentMessage(entry, selected, shkp = null) {
    const blocker = blockedShopPaymentBillItem(entry, selected);
    if (!blocker?.item || !blocker.billEntry) return "You can't buy that yet.";
    const liveQuantity = Math.max(1, Math.trunc(Number(blocker.item.quan || 1)));
    const usedQuantity = Math.max(1, shopBillEntryQuantity(blocker.billEntry) - liveQuantity);
    const usedName = pickupObjectName({ ...blocker.item, quan: usedQuantity, line: '' });
    if (!shopkeeperCanSpeakToHero(shkp)) {
        const name = shopkeeperDisplayName(shkp);
        const angry = shopkeeperAngryForSellobj(shkp) ? ' angrily' : '';
        const action = shopkeeperNoLimbsForSpeech(shkp) ? 'motions to' : 'points out';
        return `${name}${angry} ${action} your bill for the other ${usedName} first.`;
    }
    const prefix = shopkeeperAngryForSellobj(shkp) ? 'Pay' : 'Please pay';
    const container = entry?.containerPayment || entry?.billPortion === 'containerContents'
        ? entry?.item || blocker.item.container
        : blocker.item.container;
    if (container) {
        const containerName = pickupObjectName({ ...(container || {}), quan: 1, line: '' }).replace(/^empty /, '');
        const liveWord = liveQuantity > 1 ? 'ones' : 'one';
        return `${prefix} for the other ${usedName} before buying the ${liveWord} in the ${containerName}.`;
    }
    const liveWord = liveQuantity > 1 ? 'these' : 'this one';
    return `${prefix} for the other ${usedName} before buying ${liveWord}.`;
}

function payableShopPaymentEntries(selected) {
    return [...(selected || [])]
        .filter(entry => !shopPaymentEntryBlocked(entry, selected || []))
        .sort(shopPaymentEntryCompare);
}

function shopPaymentEntryValue(entry) {
    if (entry?.shopkeeperDebit) return Math.max(0, Math.trunc(Number(entry.shopkeeperDebit.debit ?? entry.price ?? 0)));
    return Math.max(0, Math.trunc(Number(entry?.price || 0)));
}

function shopPaymentCashDue(shkp, selected) {
    let credit = Math.max(0, Math.trunc(Number(shkp?.credit || 0)));
    let cashDue = 0;
    for (const entry of payableShopPaymentEntries(selected)) {
        const value = shopPaymentEntryValue(entry);
        const coveredByCredit = Math.min(credit, value);
        credit -= coveredByCredit;
        cashDue += value - coveredByCredit;
    }
    return cashDue;
}

function shopPaymentPreMenuBlockMessage(shkp, entries, { paidBefore = false } = {}) {
    if (!entries?.length) return '';
    const money = (game.inventory || []).find(item => item.letter === '$' || item.cls === 'coin');
    const availableGold = Math.max(0, Math.trunc(Number(game._goldCount || money?.quan || 0)));
    const credit = Math.max(0, Math.trunc(Number(shkp?.credit || 0)));
    if (availableGold + credit <= 0) return `You have no gold or credit${paidBefore ? ' left' : ''}.`;
    const cheapest = Math.min(...entries.map(entry => shopPaymentEntryValue(entry)).filter(value => value > 0));
    if (Number.isFinite(cheapest) && availableGold + credit < cheapest) {
        const moreThanOne = entries.length > 1;
        return `You don't have enough gold to buy${moreThanOne ? ' any of' : ''} the item${moreThanOne ? 's' : ''} ${moreThanOne ? "you've picked" : 'on your bill'}.`;
    }
    return '';
}

function finishShopDebitPayment(shkp) {
    const debit = Math.max(0, Math.trunc(Number(shkp?.debit || 0)));
    if (!shkp || debit <= 0) return { handled: false, paid: false, blocked: false, cashTotal: 0, message: '' };

    const money = (game.inventory || []).find(item => item.letter === '$' || item.cls === 'coin');
    const availableGold = Math.max(0, Math.trunc(Number(game._goldCount || money?.quan || 0)));
    const credit = Math.max(0, Math.trunc(Number(shkp.credit || 0)));
    const loan = Math.max(0, Math.trunc(Number(shkp.loan || 0)));
    const name = shopkeeperDisplayName(shkp);
    const currency = `zorkmid${debit === 1 ? '' : 's'}`;
    let owed = `You owe ${name} ${debit} ${currency} `;
    if (loan) {
        owed += loan === debit
            ? 'you picked up in the store.'
            : 'for gold picked up and the use of merchandise.';
    } else {
        owed += 'for the use of merchandise.';
    }

    if (availableGold + credit < debit) {
        return {
            handled: true,
            paid: false,
            blocked: true,
            cashTotal: 0,
            message: `${owed}  But you don't have enough gold${credit ? ' or credit' : ''}.`,
        };
    }

    let cashDue = 0;
    let resultMessage = '';
    if (credit >= debit) {
        shkp.credit = credit - debit;
        resultMessage = 'Your debt is covered by your credit.';
    } else if (!credit) {
        cashDue = debit;
        resultMessage = 'You pay that debt.';
    } else {
        cashDue = debit - credit;
        shkp.credit = 0;
        resultMessage = 'That debt is partially offset by your credit.  You pay the remainder.';
    }

    shkp.debit = 0;
    shkp.loan = 0;
    if (cashDue > 0) {
        if (availableGold > cashDue) next_ident();
        game._goldCount = Math.max(0, availableGold - cashDue);
        if (money) {
            money.quan = game._goldCount;
            updateMoneyLine(money);
        }
    }

    return {
        handled: true,
        paid: true,
        blocked: false,
        cashTotal: cashDue,
        message: `${owed}  ${resultMessage}`,
    };
}

function applyShopPaymentValue(shkp, value) {
    const amount = Math.max(0, Math.trunc(Number(value || 0)));
    if (!shkp || !amount) return { coveredByCredit: 0, cashDue: 0 };
    const credit = Math.max(0, Math.trunc(Number(shkp.credit || 0)));
    const coveredByCredit = Math.min(credit, amount);
    shkp.credit = credit - coveredByCredit;
    if (shkp.robbed)
        shkp.robbed = Math.max(0, Math.trunc(Number(shkp.robbed || 0)) - amount);
    return { coveredByCredit, cashDue: amount - coveredByCredit };
}

function payPartlyUsedShopBillEntry(shkp, entry) {
    const billEntry = entry?.billEntry;
    const item = entry?.item;
    if (!billEntry || !item) return { billed: true, removedLedger: false, legacy: true };
    applyShopPaymentValue(shkp, entry.price);
    const liveQuantity = Math.max(1, Math.trunc(Number(item.quan || 1)));
    const unitPrice = shopBillEntryUnitPrice(billEntry);
    billEntry.bquan = liveQuantity;
    billEntry.price = unitPrice;
    billEntry.totalPrice = unitPrice * liveQuantity;
    billEntry.useup = false;
    item.unpaid = true;
    item.unpaidPrice = shopBillEntryTotal(billEntry);
    syncUnpaidBillLine(item);
    removeUsedUpShopBillTracker(billEntry.bo_id, shkp);
    return { billed: true, removedLedger: false, legacy: false };
}

function payFullyUsedShopBillEntry(shkp, entry) {
    const billId = entry?.billEntry?.bo_id ?? entry?.usedUpBill?.bo_id;
    applyShopPaymentValue(shkp, entry.price);
    const removedLedger = removeObjectFromShopBillById(shkp, billId);
    removeUsedUpShopBillTracker(billId, shkp);
    return { billed: true, removedLedger, legacy: !removedLedger };
}

function payIntactShopBillEntry(shkp, entry) {
    applyShopPaymentValue(shkp, entry.price);
    if (!entry?.item) return { billed: false, removedLedger: false, legacy: false };
    const billId = entry.billEntry?.bo_id;
    if (billId != null) {
        const removedLedger = removeObjectFromShopBillById(shkp, billId);
        if (removedLedger) clearObjectShopBillState(entry.item);
        else clearObjectShopBillState(entry.item);
        return { billed: true, removedLedger, legacy: !removedLedger };
    }
    if (removeObjectFromShopBill(shkp, entry.item)) return { billed: true, removedLedger: true, legacy: false };
    clearObjectShopBillState(entry.item);
    return { billed: true, removedLedger: false, legacy: true };
}

function payContainerShopBillEntry(shkp, entry) {
    const billItems = Array.isArray(entry?.billItems) ? entry.billItems : [];
    if (!billItems.length) return { billed: false, removedLedger: false, legacy: false };
    if (shopPaymentEntryBlocked(entry, [entry])) return {
        billed: false,
        removedLedger: false,
        legacy: false,
        blocked: true,
        message: blockedShopPaymentMessage(entry, [entry], shkp),
    };
    applyShopPaymentValue(shkp, entry.price);
    const container = entry.item;
    const ordered = [...billItems].sort((a, b) => (a.item === container) - (b.item === container));
    const seen = new Set();
    let removedLedgerBillCount = 0;
    let legacy = false;
    for (const billItem of ordered) {
        const item = billItem.item;
        const billId = billItem.billEntry?.bo_id ?? shopBillObjectId(item);
        if (billId == null || seen.has(String(billId))) continue;
        seen.add(String(billId));
        const removedLedger = removeObjectFromShopBillById(shkp, billId);
        if (removedLedger) removedLedgerBillCount++;
        else legacy = true;
        clearObjectShopBillState(item);
    }
    return {
        billed: true,
        removedLedger: removedLedgerBillCount > 0,
        removedLedgerBillCount,
        legacy,
    };
}

function applyShopPaymentEntry(shkp, entry) {
    if (entry?.shopkeeperDebit) {
        const debt = Math.max(0, Math.trunc(Number(entry.shopkeeperDebit.debit ?? entry.price ?? 0)));
        applyShopPaymentValue(entry.shopkeeperDebit, debt);
        entry.shopkeeperDebit.debit = 0;
        entry.shopkeeperDebit.loan = 0;
        return { billed: false, removedLedger: false, legacy: false };
    }
    if (entry?.billPortion === 'partlyUsedUp') return payPartlyUsedShopBillEntry(shkp, entry);
    if (entry?.billPortion === 'fullyUsedUp' || entry?.usedUpBill) return payFullyUsedShopBillEntry(shkp, entry);
    if (entry?.billPortion === 'containerContents' || entry?.containerPayment) return payContainerShopBillEntry(shkp, entry);
    return payIntactShopBillEntry(shkp, entry);
}

function shopPaymentInsufficientFundsMessage(entry, shkp) {
    const paymentShopkeeper = entry?.shopkeeperDebit || shkp;
    const credit = Math.max(0, Math.trunc(Number(paymentShopkeeper?.credit || 0)));
    const itemName = entry?.name || 'that item';
    return `You don't have gold${credit ? ' or credit' : ''} enough to pay for ${itemName}.`;
}

function finishShopPaymentSelection(shkp, selected) {
    const payableEntries = payableShopPaymentEntries(selected);
    if (!payableEntries.length) {
        const blockedEntry = (selected || []).find(entry => shopPaymentEntryBlocked(entry, selected || []));
        if (blockedEntry) return {
            paid: false,
            skipped: false,
            blocked: true,
            cashTotal: 0,
            payableEntries,
            message: blockedShopPaymentMessage(blockedEntry, selected || [], shkp),
        };
        return { paid: false, skipped: true, cashTotal: 0, payableEntries, message: '' };
    }
    const money = (game.inventory || []).find(item => item.letter === '$' || item.cls === 'coin');
    const availableGold = game._goldCount || money?.quan || 0;
    let remainingGold = availableGold;
    let cashTotal = 0;
    let removedLedgerBillCount = 0;
    let billedSelections = 0;
    let legacyBillSelections = 0;
    const paidEntries = [];
    let stoppedShort = false;
    let stopMessage = '';
    for (const entry of payableEntries) {
        const paymentShopkeeper = entry?.shopkeeperDebit || shkp;
        const value = shopPaymentEntryValue(entry);
        const credit = Math.max(0, Math.trunc(Number(paymentShopkeeper?.credit || 0)));
        const cashDue = value - Math.min(credit, value);
        if (cashDue > remainingGold) {
            const message = shopPaymentInsufficientFundsMessage(entry, paymentShopkeeper);
            if (paidEntries.length) {
                stoppedShort = true;
                stopMessage = message;
                break;
            }
            return {
                paid: false,
                cashTotal: 0,
                payableEntries,
                message,
            };
        }
        const result = applyShopPaymentEntry(shkp, entry);
        if (result.blocked) {
            if (paidEntries.length) {
                stoppedShort = true;
                stopMessage = result.message || blockedShopPaymentMessage(entry, selected || [], paymentShopkeeper);
                break;
            }
            return {
                paid: false,
                blocked: true,
                cashTotal: 0,
                payableEntries,
                message: result.message || blockedShopPaymentMessage(entry, selected || [], paymentShopkeeper),
            };
        }
        remainingGold -= cashDue;
        cashTotal += cashDue;
        paidEntries.push(entry);
        if (!result.billed) continue;
        billedSelections++;
        if (result.removedLedgerBillCount != null)
            removedLedgerBillCount += result.removedLedgerBillCount;
        else if (result.removedLedger)
            removedLedgerBillCount++;
        if (result.legacy) legacyBillSelections++;
    }
    if (payableEntries.length > paidEntries.length && !stoppedShort) {
        stoppedShort = true;
        stopMessage = shopPaymentInsufficientFundsMessage(payableEntries[paidEntries.length] || payableEntries[0], shkp);
    }
    if (shkp && legacyBillSelections)
        shkp.billct = Math.max(0, (shkp.billct || legacyBillSelections) - legacyBillSelections);
    if (!paidEntries.length) return {
        paid: false,
        cashTotal: 0,
        payableEntries,
        message: shopPaymentInsufficientFundsMessage(payableEntries[0], shkp),
    };

    if (availableGold > cashTotal) next_ident();
    game._goldCount = Math.max(0, remainingGold);
    if (money) {
        money.quan = game._goldCount;
        updateMoneyLine(money);
    }
    return {
        paid: true,
        cashTotal,
        payableEntries: paidEntries,
        billedSelections,
        removedLedgerBillCount,
        legacyBillSelections,
        stoppedShort,
        message: stopMessage,
    };
}

function shopPaymentMenuRows(entries, width) {
    const rows = [[0, 41, 'Pay for which items?', 1]];
    let row = 2;
    const hasUsedUpSection = shopPaymentEntryIsUsedUp(entries[0]);
    if (hasUsedUpSection) {
        const plural = entries[1] && shopPaymentEntryIsUsedUp(entries[1]) ? 's' : '';
        rows.push([row++, 41, `Used up item${plural}:`]);
    }
    for (let i = 0; i < entries.length; i++) {
        const entry = entries[i];
        if (hasUsedUpSection && i > 0 && shopPaymentEntryIsUsedUp(entries[i - 1]) && !shopPaymentEntryIsUsedUp(entry)) {
            const plural = i < entries.length - 1 ? 's' : '';
            rows.push([row++, 41, `Unpaid item${plural}:`]);
        }
        const price = String(entry.price).padStart(width, ' ');
        entry.payMenuRow = row;
        rows.push([row++, 41, `${entry.letter} - ${price} Zm, ${entry.name}`]);
    }
    rows.push([row, 41, '(end)']);
    return rows;
}

function shopPaymentTraditionalStyle() {
    const style = game.flags?.menu_style ?? game.flags?.menustyle ?? game.flags?.menuStyle;
    return style === 0 || String(style || '').toLowerCase() === 'traditional';
}

function shopPaymentMoreThanOne(entries) {
    if ((entries || []).length > 1) return true;
    const entry = entries?.[0];
    return !!(entry?.containerPayment || entry?.billPortion === 'containerContents' || entry?.billPortion === 'partlyUsedUp');
}

function clearShopPaymentPromptState({ clearShopkeeper = true } = {}) {
    game._pay_menu_items = null;
    game._pay_menu_width = 0;
    game._pay_itemized_index = 0;
    game._pay_itemized_paid_entries = null;
    game._pay_itemized_cash_total = 0;
    game._pay_prepaid_message = '';
    game._pay_prepaid_paid = false;
    game._overlay_lines = null;
    if (clearShopkeeper) game._pay_shopkeeper = null;
}

function shopPaymentThankYouMessage(shkp) {
    if (shopkeeperAngryForSellobj(shkp)) return '';
    const shopIndex = (shkp?.shoptype || 0) - SHOPBASE;
    const shopName = SHOP_TYPES[shopIndex]?.name || 'shop';
    const shopkeeperName = shkp?.shknam || 'shopkeeper';
    const possessive = shopkeeperName.endsWith('s') ? `${shopkeeperName}'` : `${shopkeeperName}'s`;
    if (!shopkeeperCanSpeakToHero(shkp))
        return `${shopkeeperDisplayName(shkp)} nods appreciatively at you for shopping in ${possessive} ${shopName}!`;
    return `"Thank you for shopping in ${possessive} ${shopName}!"`;
}

function shopPaymentBoughtMessage(entries, cashTotal) {
    const paidEntries = entries || [];
    if (paidEntries.length === 1) {
        const entry = paidEntries[0];
        return `You bought ${entry.name} for ${entry.price} gold piece${entry.price === 1 ? '' : 's'}.`;
    }
    return `You bought ${paidEntries.length} items for ${cashTotal} gold pieces.`;
}

function shopPaymentItemizedQuestion(entry) {
    const price = Math.max(0, Math.trunc(Number(entry?.price || 0)));
    return `Pay for ${entry?.name || 'that item'} for ${price} zorkmid${price === 1 ? '' : 's'}? [yn]`;
}

function openShopPaymentMenu(shkp, entries, { prepaidMessage = '', prepaidPaid = false } = {}) {
    const width = String(Math.max(...entries.map(entry => entry.price))).length;
    const rows = shopPaymentMenuRows(entries, width);
    game._pay_menu_items = entries;
    game._pay_menu_width = width;
    game._pay_shopkeeper = shkp;
    game._pay_prepaid_message = prepaidMessage || '';
    game._pay_prepaid_paid = !!prepaidPaid;
    setOverlay(rows, Math.max(...rows.map(([row]) => row)) + 1, false, 41);
    game._command_mode = 'payMenu';
}

async function finishShopPaymentCommandResult(shkp, payment, { prepaidMessage = '', prepaidPaid = false } = {}) {
    if (!payment.paid) {
        if (payment.skipped) return false;
        const message = [prepaidMessage, payment.message || "You don't have enough gold."]
            .filter(Boolean).join('  ');
        await setMessage(message);
        if (prepaidPaid) game.context.move = 1;
        return false;
    }
    if (shkp?.shk) {
        const home = shkp.shk;
        const blockingPet = (game.level?.monsters || []).find(mon =>
            mon.pet && Math.max(Math.abs(mon.mx - home.x), Math.abs(mon.my - home.y)) === 1
            && (mon.mx === home.x || mon.my === home.y));
        if (blockingPet) {
            const stepDx = Math.sign((game.u?.ux ?? home.x) - home.x)
                || Math.sign(blockingPet.mx - home.x) || -1;
            const stepDy = Math.sign(blockingPet.my - home.y)
                || Math.sign((game.u?.uy ?? home.y) - home.y) || 1;
            shkp._paid_shopkeeper_step = { x: home.x + stepDx, y: home.y + stepDy };
            blockingPet._paid_shopkeeper_pet_step = {
                x: blockingPet.mx + Math.sign(blockingPet.mx - home.x),
                y: blockingPet.my + Math.sign(blockingPet.my - home.y),
            };
        }
    }
    game._pet_food_scan_inventory = game.inventory;
    game._queued_message_after_more = payment.stoppedShort
        ? payment.message || "You don't have enough gold."
        : shopPaymentThankYouMessage(shkp);
    const message = [prepaidMessage, shopPaymentBoughtMessage(payment.payableEntries, payment.cashTotal)]
        .filter(Boolean).join('  ');
    await setMessage(message, true);
    game.context.move = 1;
    return true;
}

async function startShopPaymentItemizedFlow(shkp, entries, { prepaidMessage = '', prepaidPaid = false } = {}) {
    game._pay_menu_items = entries;
    game._pay_shopkeeper = shkp;
    game._pay_prepaid_message = prepaidMessage || '';
    game._pay_prepaid_paid = !!prepaidPaid;
    game._pay_itemized_index = 0;
    game._pay_itemized_paid_entries = [];
    game._pay_itemized_cash_total = 0;
    game._command_mode = 'payItemized';
    await setMessage(shopPaymentItemizedQuestion(entries[0]));
}

function shopkeeperObjectivePronoun(shkp) {
    if (shkp?.female) return 'her';
    if (shkp?.neuter || shkp?.data?.neuter) return 'it';
    return 'him';
}

function shopkeeperSubjectPronoun(shkp) {
    if (shkp?.female) return 'she';
    if (shkp?.neuter || shkp?.data?.neuter) return 'it';
    return 'he';
}

function shopkeeperRobbedAmount(shkp) {
    return Math.max(0, Math.trunc(Number(shkp?.robbed || 0)));
}

const SHOPKEEPER_APPEASEMENT_GOLD = 1000;

function hasRobbedOnlyShopPayment(shkp, entries = []) {
    if (!shkp || shopkeeperRobbedAmount(shkp) <= 0 || entries.length) return false;
    const ledgerCount = Array.isArray(shkp.bill) ? shkp.bill.length : 0;
    const billCount = Math.max(ledgerCount, Math.max(0, Math.trunc(Number(shkp.billct || 0))));
    const debit = Math.max(0, Math.trunc(Number(shkp.debit || 0)));
    return billCount === 0 && debit === 0;
}

function hasAngryUnrobbedShopPayment(shkp, entries = []) {
    if (!shkp || entries.length || shopkeeperRobbedAmount(shkp) > 0 || !shopkeeperAngryForSellobj(shkp)) return false;
    const ledgerCount = Array.isArray(shkp.bill) ? shkp.bill.length : 0;
    const billCount = Math.max(ledgerCount, Math.max(0, Math.trunc(Number(shkp.billct || 0))));
    const debit = Math.max(0, Math.trunc(Number(shkp.debit || 0)));
    return billCount === 0 && debit === 0;
}

function finishRobbedOnlyShopPayment(shkp, { resident = null } = {}) {
    const robbed = shopkeeperRobbedAmount(shkp);
    if (!robbed) return { handled: false, paid: false, cashTotal: 0, message: '' };

    const money = (game.inventory || []).find(item => item.letter === '$' || item.cls === 'coin');
    const availableGold = Math.max(0, Math.trunc(Number(game._goldCount || money?.quan || 0)));
    const name = shopkeeperDisplayName(shkp);
    const isResident = !!resident && sameShopkeeper(shkp, resident);
    const isAngry = shopkeeperAngryForSellobj(shkp);
    const messages = [];

    if (!isResident && !isAngry) {
        if (!availableGold) {
            return { handled: true, paid: false, cashTotal: 0, message: 'You have no gold.' };
        }
        const nominalPayment = Math.min(availableGold, robbed);
        const payment = applyShopPaymentValue(shkp, nominalPayment);
        const paidCash = payment.cashDue;
        if (availableGold > paidCash) next_ident();
        game._goldCount = Math.max(0, availableGold - paidCash);
        if (money) {
            money.quan = game._goldCount;
            updateMoneyLine(money);
        }
        if (availableGold > robbed)
            messages.push(`You give ${name} the ${robbed} gold piece${robbed === 1 ? '' : 's'} ${shopkeeperSubjectPronoun(shkp)} asked for.`);
        else
            messages.push(`You give ${name} all your gold.`);
        if (availableGold < Math.trunc(robbed / 2)) {
            messages.push(`Unfortunately, ${shopkeeperSubjectPronoun(shkp)} doesn't look satisfied.`);
        } else {
            shkp.robbed = 0;
            shkp.following = 0;
            shkp.angry = false;
            shkp.hostile = false;
            shkp.mpeaceful = 1;
        }
        return {
            handled: true,
            paid: true,
            cashTotal: paidCash,
            compensationValue: nominalPayment,
            robbedOnly: true,
            message: messages.join('  '),
        };
    }

    messages.push(`${name} is after blood, not gold!`);
    if (availableGold < Math.trunc(robbed / 2)) {
        messages.push(availableGold
            ? `Besides, you don't have enough to interest ${shopkeeperObjectivePronoun(shkp)}.`
            : 'Moreover, you have no gold.');
        return {
            handled: true,
            paid: false,
            cashTotal: 0,
            compensationValue: 0,
            robbedOnly: true,
            message: messages.join('  '),
        };
    }

    const possessivePronoun = shopkeeperPossessivePronoun(shkp);
    const nominalPayment = Math.min(availableGold, robbed);
    messages.push(`But since ${possessivePronoun} shop has been robbed recently,`);
    messages.push(`you ${availableGold < robbed ? 'partially ' : ''}compensate ${name} for ${possessivePronoun} losses.`);
    const payment = applyShopPaymentValue(shkp, nominalPayment);
    const paidCash = payment.cashDue;
    if (availableGold > paidCash) next_ident();
    game._goldCount = Math.max(0, availableGold - paidCash);
    if (money) {
        money.quan = game._goldCount;
        updateMoneyLine(money);
    }
    shkp.robbed = 0;
    shkp.following = 0;
    shkp.angry = false;
    shkp.hostile = false;
    shkp.mpeaceful = 1;
    return {
        handled: true,
        paid: true,
        cashTotal: paidCash,
        compensationValue: nominalPayment,
        robbedOnly: true,
        message: messages.join('  '),
    };
}

function finishAngryUnrobbedShopPayment(shkp) {
    if (!shkp) return { handled: false, paid: false, cashTotal: 0, message: '' };

    const money = (game.inventory || []).find(item => item.letter === '$' || item.cls === 'coin');
    const availableGold = Math.max(0, Math.trunc(Number(game._goldCount || money?.quan || 0)));
    const name = shopkeeperDisplayName(shkp);
    const messages = [`${name} is after your hide, not your gold!`];

    if (availableGold < SHOPKEEPER_APPEASEMENT_GOLD) {
        messages.push(availableGold
            ? `Besides, you don't have enough to interest ${shopkeeperObjectivePronoun(shkp)}.`
            : 'Moreover, you have no gold.');
        return { handled: true, paid: false, cashTotal: 0, message: messages.join('  ') };
    }

    const targetName = payCanSpotMonster(shkp) ? `the angry ${name}` : name;
    messages.push(`You try to appease ${targetName} by giving ${shopkeeperObjectivePronoun(shkp)} ${SHOPKEEPER_APPEASEMENT_GOLD} gold pieces.`);
    const payment = applyShopPaymentValue(shkp, SHOPKEEPER_APPEASEMENT_GOLD);
    if (payment.coveredByCredit >= SHOPKEEPER_APPEASEMENT_GOLD) {
        messages.push('The price is deducted from your credit.');
    } else {
        if (payment.coveredByCredit > 0)
            messages.push('The price is partially covered by your credit.');
        if (availableGold > payment.cashDue) next_ident();
        game._goldCount = Math.max(0, availableGold - payment.cashDue);
        if (money) {
            money.quan = game._goldCount;
            updateMoneyLine(money);
        }
    }

    const customer = String(shkp.customer || '');
    const player = String(game.plname || '');
    const stillAngry = !!customer && !!player && customer === player && !rn2(3);
    if (stillAngry) {
        messages.push(`But ${name} is as angry as ever.`);
    } else {
        shkp.robbed = 0;
        shkp.following = 0;
        shkp.angry = false;
        shkp.hostile = false;
        shkp.mpeaceful = 1;
        messages.push(`${name} calms down.`);
    }

    return {
        handled: true,
        paid: true,
        cashTotal: payment.cashDue,
        compensationValue: SHOPKEEPER_APPEASEMENT_GOLD,
        angryUnrobbed: true,
        message: messages.join('  '),
    };
}

async function finishPayCommandForShopkeeper(shkp, resident, { requestMenu = false } = {}) {
    game._pay_prepaid_message = '';
    game._pay_prepaid_paid = false;
    const debitPayment = finishShopDebitPayment(shkp);
    if (debitPayment.blocked) {
        game._command_mode = null;
        await setMessage(debitPayment.message || "You don't have enough gold.");
        game.context.move = 1;
        return;
    }
    const entries = collectPayableShopDebts(shkp);
    if (!debitPayment.paid && hasAngryUnrobbedShopPayment(shkp, entries)) {
        const payment = finishAngryUnrobbedShopPayment(shkp);
        game._command_mode = null;
        await setMessage(payment.message || "You don't have enough gold.");
        game.context.move = 1;
        return;
    }
    if (!debitPayment.paid && hasRobbedOnlyShopPayment(shkp, entries)) {
        const payment = finishRobbedOnlyShopPayment(shkp, { resident });
        game._command_mode = null;
        await setMessage(payment.message || "You don't have enough gold.");
        game.context.move = 1;
        return;
    }
    if (!entries.length) {
        await setMessage(debitPayment.message || `You do not owe ${shkp.shknam || 'the shopkeeper'} anything.`);
        if (debitPayment.paid) game.context.move = 1;
        return;
    }
    const preMenuBlockMessage = shopPaymentPreMenuBlockMessage(shkp, entries, { paidBefore: debitPayment.paid });
    if (preMenuBlockMessage) {
        await setMessage([debitPayment.message, preMenuBlockMessage].filter(Boolean).join('  '));
        if (debitPayment.paid) game.context.move = 1;
        return;
    }
    let viaMenu = !shopPaymentTraditionalStyle();
    if (requestMenu) viaMenu = !viaMenu;
    if (viaMenu) {
        openShopPaymentMenu(shkp, entries, {
            prepaidMessage: debitPayment.message || '',
            prepaidPaid: !!debitPayment.paid,
        });
        return;
    }
    game._pay_menu_items = entries;
    game._pay_shopkeeper = shkp;
    game._pay_prepaid_message = debitPayment.message || '';
    game._pay_prepaid_paid = !!debitPayment.paid;
    if (!shopPaymentMoreThanOne(entries)) {
        await startShopPaymentItemizedFlow(shkp, entries, {
            prepaidMessage: debitPayment.message || '',
            prepaidPaid: !!debitPayment.paid,
        });
        return;
    }
    game._command_mode = 'payItemizedPrompt';
    await setMessage('Itemized billing? [ynq m] (q)');
}

function pickupMenuEntries(objects) {
    return objects.map((obj, index) => {
        let section = 'Other Items';
        if (obj.otyp === GOLD_PIECE || obj.cls === 'coin' || obj.glyph === '$') section = 'Coins';
        else if (obj.cls === 'amulet') section = 'Amulets';
        else if (obj.otyp === DART || obj.cls === 'weapon' || obj.glyph === ')') section = 'Weapons';
        else if (obj.cls === 'armor' || obj.glyph === '[') section = 'Armor';
        else if (obj.otyp === 'corpse' || obj.otyp === CORPSE || obj.otyp === FOOD_CLASS || obj.cls === 'food') section = 'Comestibles';
        else if (obj.otyp === SCROLL_CLASS || obj.cls === 'scroll') section = 'Scrolls';
        else if (obj.cls === 'spellbook') section = 'Spellbooks';
        else if (obj.otyp === POTION_CLASS || obj.cls === 'potion') section = 'Potions';
        else if (obj.otyp === RING_CLASS || obj.cls === 'ring' || obj.glyph === '=') section = 'Rings';
        else if (obj.otyp === WAND_CLASS || obj.cls === 'wand') section = 'Wands';
        else if (BAG_OBJECT_TYPES.has(obj.otyp) || obj.otyp === OIL_LAMP || obj.otyp === MAGIC_LAMP || obj.cls === 'tool' || obj.glyph === '(') section = 'Tools';
        else if (isBoulderObject(obj) || obj.otyp === STATUE || obj.cls === 'rock' || obj.glyph === '`') section = 'Boulders/Statues';
        else if (obj.otyp === GEM_CLASS || obj.cls === 'gem' || obj.glyph === '*') section = 'Gems/Stones';
        if (obj.section) section = obj.section;
        return { obj, index, section };
    }).sort((a, b) => {
        const sectionDiff = PICKUP_SECTION_ORDER.indexOf(a.section) - PICKUP_SECTION_ORDER.indexOf(b.section);
        if (sectionDiff) return sectionDiff;
        if (typeof a.obj.otyp === 'number' && typeof b.obj.otyp === 'number' && a.obj.otyp !== b.obj.otyp)
            return a.obj.otyp - b.obj.otyp;
        if (a.obj.pileIndex != null || b.obj.pileIndex != null) return (a.obj.pileIndex || 0) - (b.obj.pileIndex || 0);
        return a.index - b.index;
    }).map((entry, index, entries) => {
        if (entry.section === 'Coins') return { ...entry, letter: '$' };
        const priorNonCoins = entries.slice(0, index).filter(item => item.section !== 'Coins').length;
        return { ...entry, letter: 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ'[priorNonCoins] };
    });
}

function pickupMenuLines(entries, selected) {
    const selectedLetters = new Set(Array.isArray(selected) ? selected : selected ? [selected] : []);
    const rows = [[0, 41, 'Pick up what?', 1]];
    let row = 2;
    let lastSection = '';
    for (const entry of entries) {
        if (entry.section !== lastSection) {
            rows.push([row++, 41, entry.section, 1]);
            lastSection = entry.section;
        }
        const priceSuffix = shopItemPriceSuffix(entry.obj, entry.obj?.ox, entry.obj?.oy);
        rows.push([row++, 41, `${entry.letter} ${selectedLetters.has(entry.letter) ? '+' : '-'} ${pickupObjectPhrase(entry.obj)}${priceSuffix}`]);
    }
    rows.push([row, 41, '(end)']);
    return rows;
}

function pickupListSelectedObjects(pickup) {
    const selectedLetters = new Set(pickup?.selected || []);
    return (pickup?.entries || [])
        .filter(entry => selectedLetters.has(entry.letter))
        .map(entry => entry.obj);
}

function clearPickupListOverlay() {
    game._overlay_lines = null;
    game._overlay_hide_status = 0;
    game._pickup_list = null;
}

function isFloorGoldObject(obj) {
    return !!obj && (obj.otyp === GOLD_PIECE || obj.cls === 'coin' || obj.glyph === '$');
}

function removePickupListFloorObject(obj) {
    if (!obj) return;
    objectIceEffect(obj, obj.ox, obj.oy, { onLevel: false });
    game.level.objects = (game.level?.objects || []).filter(item => item !== obj);
}

function pickupListPickedClass(obj) {
    return isBoulderObject(obj) ? 'rock' : obj.cls || (obj.otyp === DART ? 'weapon'
        : obj.otyp === GEM_CLASS ? 'gem'
            : obj.otyp === 'corpse' || obj.otyp === CORPSE ? 'food'
                : obj.otyp === RING_CLASS || obj.glyph === '=' ? 'ring'
                    : BAG_OBJECT_TYPES.has(obj.otyp) || obj.otyp === OIL_LAMP || obj.otyp === MAGIC_LAMP
                        || obj.otyp === MIRROR || obj.otyp === EXPENSIVE_CAMERA
                        || obj.otyp === STETHOSCOPE || obj.otyp === MAGIC_MARKER ? 'tool'
                        : undefined);
}

function finishPickupListProcessing(state) {
    game._pet_food_scan_inventory = game.inventory;
    clearPickupListOverlay();
    game._floor_pickup_menu_pending = null;
    game._command_mode = null;
    newsym(game.u?.ux || 0, game.u?.uy || 0);
    return setMessage((state?.messages || []).join('  ')).then(() => {
        game.context.move = 1;
    });
}

function pickupListPromptMessage(state, preflight) {
    return [...(state?.messages || []), floorPickupBurdenPromptMessage(preflight)].join('  ');
}

function pickupListPendingPrompt(state, obj, preflight) {
    state.pendingObject = obj;
    state.pendingPreflight = preflight;
    state.scareResetSpeObj = preflight.scareResetSpeOnDecline ? obj : null;
    game._floor_pickup_menu_pending = state;
    game._command_mode = 'pickupListBurdenConfirm';
    return setMessage(pickupListPromptMessage(state, preflight)).then(() => {
        game.context.move = 0;
    });
}

function pickupListHandleGold(obj, preflight, state) {
    if (preflight?.messages?.length) state.messages.push(...preflight.messages);
    const pickup = pickUpFloorGoldObject(obj, preflight?.takeCount || obj.quan || 1);
    state.messages.push(...(pickup.messages || []));
}

function pickupListHandleObject(obj, preflight, state) {
    if (preflight?.messages?.length) state.messages.push(...preflight.messages);
    const pickupObj = splitFloorPickupObjectForLift(obj, preflight?.takeCount || obj.quan || 1);
    if (preflight.scareRemainderState && pickupObj !== obj)
        Object.assign(obj, preflight.scareRemainderState);
    const letter = pickupObj.wasStolen && pickupObj.letter
        ? pickupObj.letter
        : preflight?.inventoryLetter || nextInventoryLetter();
    const amount = pickupObjectPhrase(pickupObj);
    const priceInfo = shopFloorItemPriceInfo(pickupObj, pickupObj?.ox, pickupObj?.oy);
    const shopPrice = priceInfo?.itemPrice ?? shopItemPrice(pickupObj);
    const mergeTarget = findPickedObjectInventoryMergeTarget(pickupObj, shopPrice);
    if (mergeTarget) {
        objectIceEffect(pickupObj, pickupObj.ox, pickupObj.oy, { onLevel: false });
        if (mergeTarget.billMerge?.price > 0)
            state.messages.push(shopPickupQuoteMessage(pickupObj, mergeTarget.billMerge.price));
        state.messages.push(mergePickedObjectIntoInventory(pickupObj, mergeTarget.target));
        removePickupListFloorObject(pickupObj);
        return;
    }
    const pickedItem = {
        ...pickupObj,
        cls: pickupListPickedClass(pickupObj),
        letter,
        kind: pickupObj.kind || pickupObjectName({ ...pickupObj, quan: 1 }),
        line: `${letter} - ${amount}`,
    };
    const billing = addPickedObjectToShopBill(pickupObj, pickedItem);
    const billedPrice = billing.itemPrice ?? billing.price ?? 0;
    objectIceEffect(pickedItem, pickupObj.ox, pickupObj.oy, { onLevel: false });
    const unpaidSuffix = shopPickupLinePriceSuffix(priceInfo, billedPrice);
    pickedItem.line = replaceShopPriceLineSuffix(pickedItem.line, unpaidSuffix);
    game.inventory = [...(game.inventory || []), pickedItem];
    maybeAttachCarriedFigurineTimeout(pickedItem);
    if (billing.messages?.length) state.messages.push(...billing.messages);
    if (billedPrice > 0) state.messages.push(shopPickupQuoteMessage(pickupObj, billedPrice, priceInfo));
    if (billing.goldMessages?.length) state.messages.push(...billing.goldMessages);
    state.messages.push(`${letter} - ${amount}${unpaidSuffix}.`);
    removePickupListFloorObject(pickupObj);
}

async function continuePickupListProcessing(state, acceptedPreflight = null) {
    state.index ??= 0;
    state.messages ??= [];
    state.selected ??= [];
    while (state.index < state.selected.length) {
        const obj = state.selected[state.index];
        if (!obj || !(game.level?.objects || []).includes(obj)) {
            state.index++;
            continue;
        }
        const preflight = acceptedPreflight || await floorPickupPreflight(obj);
        acceptedPreflight = null;
        if (preflight.prompt)
            return pickupListPendingPrompt(state, obj, preflight);
        if (!preflight.ok) {
            state.messages.push(floorPickupPreflightMessage(preflight));
            if (preflight.scareDust && scheduleScareMonsterDustTryCall(preflight, { moveCost: 1, pickupListState: state })) {
                await setMessage((state.messages || []).join('  '), true);
                game.context.move = 0;
                return;
            }
            if (preflight.scareDust) {
                const billMessage = finalizeScareMonsterDust(preflight);
                if (billMessage) state.messages.push(billMessage);
            }
            state.index++;
            if (preflight.scareDust) continue;
            break;
        }
        if (preflight?.skip) {
            if (preflight?.messages?.length) state.messages.push(...preflight.messages);
            state.index++;
            continue;
        }
        if (isFloorGoldObject(obj)) pickupListHandleGold(obj, preflight, state);
        else pickupListHandleObject(obj, preflight, state);
        state.index++;
    }
    return finishPickupListProcessing(state);
}

function deathSummary() {
    const genderKey = game.flags?.female ? 'f' : 'm';
    const role = game.urole?.name?.[genderKey] || game.urole?.name?.m || game._startup_role || 'Adventurer';
    const rank = game.urole?.rank?.[genderKey] || game.urole?.rank?.m || role;
    const name = game.plname || 'Hero';
    const race = game.urace?.adj || game._startup_race || 'human';
    const gender = game.flags?.female ? 'female' : 'male';
    const align = game.u?.ualign?.type > 0 ? 'lawful' : game.u?.ualign?.type < 0 ? 'chaotic' : 'neutral';
    const stats = game.u?.acurr?.a || [];
    const dungeon = game.level?.flags?.tutorial_level
        ? 'The Tutorial'
        : game.dungeons?.[game.u?.uz?.dnum ?? 0]?.name || 'The Dungeons of Doom';
    const depth = game.u?._displayDepth || depth_of_level(game.u?.uz || { dnum: 0, dlevel: 1 });
    const carriedGold = game._goldCount
        ?? (game.inventory || []).find(item => item.letter === '$' || item.cls === 'coin')?.quan
        ?? 0;
    let hiddenGold = 0;
    const contained = (game.inventory || []).flatMap(item => item.contents || []);
    while (contained.length) {
        const item = contained.pop();
        if (item.otyp === GOLD_PIECE || item.cls === 'coin' || item.glyph === '$') hiddenGold += item.quan || 1;
        contained.push(...(item.contents || []));
    }
    const gold = carriedGold + hiddenGold;
    const cause = game._death_cause || 'died';
    const dnum = game.u?.uz?.dnum ?? 0;
    let deepest = depth;
    for (const key of game._saved_levels?.keys?.() || []) {
        const [savedDnum, savedLevel] = String(key).split(':').map(Number);
        if (savedDnum === dnum) deepest = Math.max(deepest, depth_of_level({ dnum: savedDnum, dlevel: savedLevel }));
    }
    const depthBonus = 50 * (deepest - 1) + (deepest > 30 ? 10000 : deepest > 20 ? 1000 * (deepest - 20) : 0);
    let scoreGold = Math.max(0, gold - (game._initialGoldCount || 0));
    scoreGold -= Math.trunc(scoreGold / 10);
    const score = (game.u?.urexp || 0) + scoreGold + depthBonus;
    return {
        role, rank, name, race, gender, align, stats, dungeon, depth, gold, cause,
        maxlvl: deepest,
        score,
        level: game.u?.ulevel || 1,
        hp: Math.max(0, game.u?.uhp || 0),
        hpmax: game.u?.uhpmax || 1,
        en: game.u?.uen || 0,
        enmax: game.u?.uenmax || 0,
        ac: game.u?.uac ?? 10,
        turns: game._death_moves || game.moves || 1,
        exp: game.u?.uexp || 0,
        outsideDungeon: game._death_outside_dungeon || '',
    };
}

function canMakeBones() {
    if (game._death_no_bones) return false;
    if (game.flags?.bones === false) return false;
    const uz = game.u?.uz;
    const dungeon = game.dungeons?.[uz?.dnum ?? 0];
    if (dungeon && uz?.dlevel === dungeon.num_dunlevs) return false;
    if (uz?.dlevel > 1 && (game.branches || []).some(branch =>
        branch.end1?.dnum === uz.dnum && branch.end1?.dlevel === uz.dlevel)) return false;
    if ((game.level?.traps || []).some(trap => trap.ttyp === MAGIC_PORTAL)) return false;
    const levelDepth = depth_of_level(uz);
    if (levelDepth <= 0) return false;
    if (!rn2(1 + (levelDepth >> 2)) && !game.flags?.debug) return false;
    return !game.flags?.explore;
}

function deathBonesLeavesStatue() {
    return game._death_bones_body === 'statue';
}

function heroDeathStatueMonsterData() {
    if (game.u?._polyself_form) return { ...game.u._polyself_form };
    const roleName = String(game.urole?.name?.m || game._startup_role || 'tourist').toLowerCase();
    return { name: roleName, glyph: '@', mlet: 'human', neuter: false };
}

function createDeathBonesRemains() {
    if (game._death_corpse_created || !game.u) return;
    const leavesStatue = deathBonesLeavesStatue();
    const pm = leavesStatue
        ? heroDeathStatueMonsterData()
        : DEATH_CORPSE_BY_RACE[game._startup_race || game.urace?.adj || 'human'] || DEATH_CORPSE_BY_RACE.human;
    const remains = mkcorpstat(leavesStatue ? STATUE : CORPSE, null, pm, game.u.ux, game.u.uy, leavesStatue ? 0 : 8);
    remains.oname = game.plname || 'wizard';
    remains._death_remains = leavesStatue ? 'statue' : 'corpse';
    if (leavesStatue) {
        remains.kind = 'statue';
        remains.spe = (remains.spe || 0) & ~CORPSTAT_GENDER;
        remains.contents = [];
    }
    game._death_corpse_created = 1;
}

function curseDeathBonesInventory() {
    for (const item of game.inventory || []) {
        if (rn2(5)) {
            item.cursed = true;
            item.blessed = false;
        }
        rn2(8);
    }
}

function createDeathBonesGhost() {
    if (deathBonesLeavesStatue()) {
        delete game._bones_ghost;
        return;
    }
    const ghostId = next_ident();
    const ghostHp = d(9, 8);
    rn2(2);
    rn2(50);
    rn2(100);
    rn2(100);
    game._bones_ghost = {
        id: ghostId,
        mx: game.u?.ux || 0,
        my: game.u?.uy || 0,
        data: {
            name: 'ghost',
            glyph: ' ',
            mlet: 'ghost',
            mlevel: 10,
            mac: -5,
            mmove: 3,
            difficulty: 13,
            maligntyp: -5,
            color: CLR_GRAY,
            passWalls: true,
            noCorpse: true,
            undead: true,
        },
        glyph: ' ',
        color: CLR_GRAY,
        m_lev: game.u?.ulevel || 1,
        mhp: game.u?.uhpmax || ghostHp,
        mhpmax: game.u?.uhpmax || ghostHp,
        msleeping: 1,
        mpeaceful: 0,
        female: !!game.flags?.female,
        givenName: game.plname || 'wizard',
    };
}

function prepareDeathBones() {
    if (game.flags?.debug || game._death_bones_prepared) return;
    game._death_bones_prepared = 1;
    game._bones_ok = canMakeBones();
}

function saveDeathBonesIfNeeded() {
    if (!game._bones_ok || game._death_bones_saved || game.flags?.debug) return;
    game._death_bones_saved = 1;

    const uz = game.u?.uz || { dnum: 0, dlevel: 1 };
    const bonesPath = `/bones/${uz.dnum}:${uz.dlevel}`;
    if (vfsReadFile(bonesPath) !== null) return;

    createDeathBonesRemains();
    curseDeathBonesInventory();
    createDeathBonesGhost();
    vfsWriteFile(bonesPath, encodeBonesLevel());
}

function monsterExperienceValue(mon) {
    const data = mon?.data || {};
    const level = Math.max(0, mon?.m_lev ?? mon?.mlevel ?? data.mlevel ?? 0);
    const speed = data.mmove ?? NORMAL_SPEED;
    const attacks = data.xpAttacks || data.attacks || (data.attack ? [data.attack] : []);
    const hasWeaponAttack = attacks.some(monsterAttack =>
        (monsterAttack.aatyp || (monsterAttack.weapon ? 'weap' : '')) === 'weap');
    let experience = 1 + level * level
        + (speed > NORMAL_SPEED ? speed > (3 * NORMAL_SPEED / 2) ? 5 : 3 : 0)
        + ((data.armed || data.attack?.weapon) && !hasWeaponAttack ? 5 : 0)
        + (data.xpAttackBonus || 0);
    const monsterAc = data.mac ?? 10;
    if (monsterAc < 3) experience += (7 - monsterAc) * (monsterAc < 0 ? 2 : 1);
    for (const monsterAttack of attacks) {
        const attackType = monsterAttack.aatyp || (monsterAttack.weapon ? 'weap' : '');
        if (attackType === 'weap') experience += 5;
        else if (attackType === 'magc') experience += 10;
        else if (XP_SPECIAL_ATTACK_TYPES.has(attackType)) experience += 3;
        const damageType = monsterAttack.adtyp || 'phys';
        if (XP_DOUBLE_DAMAGE_TYPES.has(damageType)) experience += 2 * level;
        else if (XP_FLAT_DAMAGE_TYPES.has(damageType)) experience += 50;
        else if (damageType !== 'phys') experience += level;
        if ((monsterAttack.dice ?? 0) * (monsterAttack.sides ?? 0) > 23) experience += level;
    }
    return experience;
}

export function recordVanquished(mon, awardExperience = true) {
    const name = mon?.data?.name || mon?.name || mon?.corpsenm?.name;
    if (!name) return;
    if (mon._vanquished_recorded) return;
    mon._vanquished_recorded = 1;
    game._vanquished_counts ??= {};
    const previousCount = Math.max(0, Math.trunc(Number(game._vanquished_counts[name]) || 0));
    game._vanquished_counts[name] = Math.min(VANQUISHED_COUNT_LIMIT, previousCount + 1);
    game._vanquished_total = Object.values(game._vanquished_counts).reduce((sum, count) => sum + count, 0);
    game._vanquished = Object.entries(game._vanquished_counts)
        .sort(([nameA], [nameB]) => {
            const monA = VANQUISHED_MONSTER_DATA.get(nameA) || { mlevel: 0, index: 9999 };
            const monB = VANQUISHED_MONSTER_DATA.get(nameB) || { mlevel: 0, index: 9999 };
            return (monB.mlevel - monA.mlevel) || (monA.index - monB.index) || nameA.localeCompare(nameB);
        })
        .map(([monName, count]) => {
            if (count === 1) return `${/^[aeiou]/i.test(monName) ? 'an' : 'a'} ${monName}`;
            const plural = monName.endsWith('s') ? `${monName}es`
                : monName.endsWith('y') ? `${monName.slice(0, -1)}ies`
                : `${monName}s`;
            return `${count} ${plural}`;
        });
    const experience = monsterExperienceValue(mon);
    if (!awardExperience) return;
    game.u.urexp = (game.u.urexp || 0) + 4 * experience;
    if (!game.u?.ualign) return;
    set_malign(mon);
    const conductDelta = mon.mtame ? -15 : mon.mpeaceful ? -5 : 0;
    for (const delta of [conductDelta, mon.malign || 0]) {
        const record = game.u.ualign.record || 0;
        const newRecord = record + delta;
        if (delta < 0) {
            if (newRecord < record) game.u.ualign.record = newRecord;
            game.u.ualign.abuse = (game.u.ualign.abuse || 0) - delta;
        } else if (delta > 0 && newRecord > record) {
            const alignLim = 10 + Math.trunc((game.moves || 1) / 200);
            game.u.ualign.record = Math.min(newRecord, alignLim);
        }
    }
}

function deathAttributesPage1() {
    const dsum = deathSummary();
    const alignIndex = dsum.align === 'lawful' ? 0 : dsum.align === 'neutral' ? 1 : 2;
    const alignNames = ['lawful', 'neutral', 'chaotic'];
    const pantheonRole = dsum.role === 'Priest' ? game._pantheon_role || 'Barbarian' : dsum.role;
    const gods = GODS_BY_ROLE[pantheonRole] || ['Marduk', 'Marduk', 'Marduk'];
    const opposedGods = gods
        .map((god, idx) => ({ god, idx }))
        .filter(({ idx }) => idx !== alignIndex)
        .map(({ god, idx }) => `${god} (${alignNames[idx]})`)
        .join(' and ');
    const raceLimits = DEATH_ATTR_LIMITS_BY_RACE[game._startup_race] || DEATH_ATTR_LIMITS_BY_RACE.human;
    const dungeon = dsum.dungeon === 'The Tutorial' ? 'the Tutorial' : dsum.dungeon.replace(/^The /, 'the ');
    const nextLevelExp = dsum.level === 1 ? 20 : 20 * (2 ** (dsum.level - 1));
    const energy = dsum.en === dsum.enmax
        ? dsum.enmax === 2 ? 'both energy points' : `all ${dsum.enmax} energy points`
        : `${dsum.en} out of ${dsum.enmax} energy points`;
    const pickup = game.flags?.pickup
        ? ` Autopickup was on for '${game.flags.pickup_types || 'all'}' plus thrown.`
        : ' Autopickup was off.';
    const hour = Number(String(game._datetime || '').slice(8, 10));
    const rows = [
        [0, 0, `${dsum.name} the ${dsum.role}'s attributes:`],
        [2, 0, 'Background:'],
        [3, 0, ` You were ${/^[aeiou]/i.test(dsum.rank) ? 'an' : 'a'} ${dsum.rank}, a level ${dsum.level} ${dsum.gender} ${dsum.race} ${dsum.role}.`],
        [4, 0, ` You were ${dsum.align}, on a mission for ${gods[alignIndex]}`],
        [5, 0, ` who was opposed by ${opposedGods}.`],
        [6, 0, ` You were ${game.u?.uhandedness || 'right'}-handed.`],
        [7, 0, ` You were in ${dungeon}, on level ${dsum.depth}.`],
        [8, 0, ` You entered the dungeon ${dsum.turns} turns ago.`],
    ];
    let row = 9;
    if (hour < 6 || hour >= 22) rows.push([row++, 0, ' It was nighttime.']);
    if (game.flags?.moonphase === 4) rows.push([row++, 0, ' There was a full moon in effect when your adventure ended.']);
    if (game.flags?.moonphase === 0) rows.push([row++, 0, ' There was a new moon in effect when your adventure ended.']);
    const needed = nextLevelExp - dsum.exp;
    rows.push(
        [row++, 0, ` You had ${dsum.exp} experience point${dsum.exp === 1 ? '' : 's'}, ${needed}${dsum.exp ? ' more' : ''} ${needed === 1 ? 'was' : 'were'} needed to attain level ${dsum.level + 1}.`],
        [row++, 0, ''],
        [row++, 0, 'Basics:'],
        [row++, 0, ` You had ${dsum.hp} out of ${dsum.hpmax} hit points.`],
        [row++, 0, ` You had ${energy} (spell power).`],
        [row++, 0, ` Your armor class was ${dsum.ac}.`],
        [row++, 0, dsum.gold ? ` Your wallet contained ${dsum.gold} zorkmids.` : ' Your wallet was empty.'],
        [row++, 0, pickup],
        [row++, 0, ''],
        [row++, 0, 'Final Characteristics:'],
        [row++, 0, ` Your strength was ${strengthString(dsum.stats[0] || 10)} (limit:${raceLimits[0]}).`],
        [row++, 0, ` Your dexterity was ${dsum.stats[3] || 10} (limit:${raceLimits[3]}).`],
        [row++, 0, ` Your constitution was ${dsum.stats[4] || 10} (limit:${raceLimits[4]}).`],
        [row++, 0, ` Your intelligence was ${dsum.stats[1] || 10} (limit:${raceLimits[1]}).`],
    );
    game._death_attributes_page2_prefix = rows.filter(([line]) => line >= 23).map(([, col, text]) => [col, text]);
    return [...rows.filter(([line]) => line < 23), [23, 0, ' --More--']];
}

function deathAttributesPage2() {
    const dsum = deathSummary();
    const roleName = game.urole?.name?.m || game._startup_role || dsum.role;
    const raceLimits = DEATH_ATTR_LIMITS_BY_RACE[game._startup_race] || DEATH_ATTR_LIMITS_BY_RACE.human;
    const tutorialDeath = dsum.dungeon === 'The Tutorial';
    const weapon = (game.inventory || []).find(item => item.wielded || item.line?.includes('weapon in') || item.line?.includes('weapon;'));
    let weaponName = tutorialDeath ? null : weapon?.kind || weapon?.name || (typeof weapon?.otyp === 'string' ? weapon.otyp : null);
    if (roleName === 'Samurai') {
        if (weaponName === 'katana') weaponName = 'long sword';
        else if (weaponName === 'wakizashi') weaponName = 'short sword';
    }
    if (/war hammer|mjollnir/i.test(weaponName || '')) weaponName = 'hammer';
    if (weaponName) weaponName = String(weaponName).replace(/^(?:elven|orcish|dwarvish) /, '');
    if (weaponName === 'scalpel') weaponName = 'knife';
    const weaponArticle = weaponName && /^[aeiou]/i.test(weaponName) ? 'an' : 'a';
    const rows = [];
    let row = 0;
    for (const [col, text] of game._death_attributes_page2_prefix || []) rows.push([row++, col, text]);
    rows.push(
        [row++, 0, ` Your wisdom was ${dsum.stats[2] || 10} (limit:${raceLimits[2]}).`],
        [row++, 0, ` Your charisma was ${dsum.stats[5] || 10} (limit:${raceLimits[5]}).`],
        [row++, 0, ''],
        [row++, 0, 'Final Status:'],
    );
    if (game.u?.sleepyTimeout || (game.inventory || []).some(item => item.cls === 'amulet' && item.amuletIndex === 3 && (item.worn || item.line?.includes('being worn'))))
        rows.push([row++, 0, ' You fell asleep uncontrollably.']);
    rows.push(
        [row++, 0, " You weren't hungry."],
        [row++, 0, ' You were unencumbered.'],
        [row++, 0, weaponName ? ` You were wielding ${weaponArticle} ${weaponName}.` : ' You were bare handed.'],
        [row++, 0, weaponName ? ` You had basic skill with ${weaponName}.` : ' You were unskilled in bare handed combat.'],
    );
    if (tutorialDeath || !(game.inventory || []).some(item => item.worn && item.cls === 'armor'))
        rows.push([row++, 0, " You weren't wearing any armor."]);
    rows.push(
        [row++, 0, ''],
        [row++, 0, 'Final Attributes:'],
        [row++, 0, ` You were ${(game.u?.ualign?.record || 0) >= 10 ? 'fervently' : 'nominally'} aligned.`],
    );
    if (game.u?.poisonResistance) rows.push([row++, 0, ' You were poison resistant.']);
    if (roleName === 'Ranger') rows.push([row++, 0, ' You had automatic searching.']);
    if (heroHasAntimagic())
        rows.push([row++, 0, ' You were magic-protected.']);
    if (['elf', 'gnome', 'dwarf', 'orc'].includes(game._startup_race)) rows.push([row++, 0, ' You had infravision.']);
    if (game.u?.stealth) rows.push([row++, 0, ' You were stealthy.']);
    if (heroHasSlowDigestion()) rows.push([row++, 0, ' You had slower digestion.']);
    if (!tutorialDeath && (game.inventory || []).some(item => item.worn && item.cls === 'armor')) rows.push([row++, 0, ' You were warded.']);
    if ((game.u?.uluck || 0) > 0) rows.push([row++, 0, ' You were lucky.']);
    rows.push(
        [row++, 0, ' You are dead.'],
        [row++, 0, ''],
        [row++, 0, 'Miscellaneous:'],
        [row++, 0, " You didn't encounter any bones levels."],
        [row++, 0, ' Total elapsed playing time was none.'],
        [row++, 0, ' --More--'],
    );
    const overflow = rows
        .filter(([line, , text]) => line >= 23 && text !== ' --More--')
        .map(([line, col, text]) => [line - 23, col, text]);
    if (overflow.length) {
        game._death_attributes_page3_lines = [...overflow, [overflow.length, 0, ' --More--']];
        return [...rows.filter(([line]) => line < 23), [23, 0, ' --More--']];
    }
    game._death_attributes_page3_lines = null;
    return rows;
}

function deathConductLines() {
    const rows = [[0, 41, 'Voluntary challenges:']];
    let row = 1;
    const genocideCount = genocidedMonsterNames().length;
    rows.push(
        [row++, 42, 'Character rerolling was not enabled.'],
        [row++, 42, 'You went without food.'],
        [row++, 42, 'You were an atheist.'],
    );
    if (!game._chronicle_first_weapon_hit) rows.push([row++, 42, 'You never hit with a wielded weapon.']);
    if (!game._chronicle_first_kill) rows.push([row++, 42, 'You were a pacifist.']);
    rows.push(
        [row++, 42, 'You were illiterate.'],
        [row++, 42, genocideCount
            ? `You genocided ${genocideCount} type${genocideCount === 1 ? '' : 's'} of monster${genocideCount === 1 ? '' : 's'}.`
            : 'You never genocided any monsters.'],
        [row++, 42, 'You never polymorphed an object.'],
        [row++, 42, 'You never changed form.'],
        [row++, 42, 'You used no wishes.'],
        [row++, 41, '--More--'],
    );
    return rows;
}

function visitedDungeon(name) {
    const current = game.u?.uz;
    if (current && game.dungeons?.[current.dnum]?.name === name) return true;
    for (const key of game._saved_levels?.keys?.() || []) {
        const dnum = Number(String(key).split(':')[0]);
        if (game.dungeons?.[dnum]?.name === name) return true;
    }
    return false;
}

function visitedSpecialLevel(name) {
    const level = game.specialLevels?.find(entry => entry.name === name);
    if (!level) return false;
    const current = game.u?.uz;
    if (current?.dnum === level.dnum && current?.dlevel === level.dlevel) return true;
    return !!game._saved_levels?.has?.(`${level.dnum}:${level.dlevel}`);
}

function conductAchievementRows(startRow, col) {
    const rows = [];
    let row = startRow;
    const role = game._startup_role || game.urole?.name?.m || '';
    const level = game.u?._polyself_base?.ulevel || game.u?.ulevel || 1;
    if (role === 'Knight') {
        for (const [minLevel, rank] of [[2, 'Esquire'], [6, 'Bachelor'], [10, 'Sergeant'], [14, 'Knight']]) {
            if (level >= minLevel) rows.push([row++, col, `You have attained the rank of ${rank}.`]);
        }
    }
    if (visitedDungeon('Gehennom')) rows.push([row++, col, 'You have entered Gehennom.']);
    if (visitedDungeon('The Gnomish Mines')) rows.push([row++, col, 'You have entered the Gnomish Mines.']);
    if (visitedSpecialLevel('minetn')) rows.push([row++, col, 'You have entered Minetown.']);
    return rows;
}

function liveConductLines() {
    const conduct = game.u?.uconduct || {};
    const wizard = !!game.flags?.debug;
    const headerCol = wizard ? 34 : 40;
    const textCol = headerCol + 1;
    const rows = [[0, headerCol, 'Voluntary challenges:']];
    let row = 1;
    const genocideCount = genocidedMonsterNames().length;
    rows.push([row++, textCol, 'Character rerolling was not enabled.']);
    if (conduct.food > 0) {
        if (!conduct.unvegan) rows.push([row++, textCol, 'You have followed a strict vegan diet.']);
        else if (!conduct.unvegetarian) rows.push([row++, textCol, 'You have been vegetarian.']);
    } else {
        rows.push([row++, textCol, 'You have gone without food.']);
    }
    if (!game._chronicle_rejected_atheism) rows.push([row++, textCol, 'You have been an atheist.']);
    if (conduct.weaphit > 0) {
        if (wizard) {
            rows.push([row++, textCol, `You have hit with a wielded weapon ${conduct.weaphit} time${conduct.weaphit === 1 ? '' : 's'}.`]);
        }
    } else rows.push([row++, textCol, 'You have never hit with a wielded weapon.']);
    if (!game._chronicle_first_kill) rows.push([row++, textCol, 'You have been a pacifist.']);
    if (conduct.literate > 0) {
        if (wizard) {
            rows.push([row++, textCol, `You have read items or engraved ${conduct.literate} time${conduct.literate === 1 ? '' : 's'}.`]);
        }
    } else rows.push([row++, textCol, 'You have been illiterate.']);
    if (conduct.pets) {
        if (wizard) rows.push([row++, textCol, `You have had ${conduct.pets} pet${conduct.pets === 1 ? '' : 's'}.`]);
    } else rows.push([row++, textCol, 'You have never had a pet.']);
    rows.push([row++, textCol, genocideCount
        ? `You have genocided ${genocideCount} type${genocideCount === 1 ? '' : 's'} of monster${genocideCount === 1 ? '' : 's'}.`
        : 'You have never genocided any monsters.']);
    if (conduct.polypiles) {
        if (wizard) rows.push([row++, textCol, `You have polymorphed ${conduct.polypiles} item${conduct.polypiles === 1 ? '' : 's'}.`]);
    } else rows.push([row++, textCol, 'You have never polymorphed an object.']);
    if (conduct.polyselfs) {
        if (wizard) rows.push([row++, textCol, `You have changed form ${conduct.polyselfs} time${conduct.polyselfs === 1 ? '' : 's'}.`]);
    } else rows.push([row++, textCol, 'You have never changed form.']);
    if (conduct.wishes) {
        rows.push([row++, textCol, `You have used ${conduct.wishes} wish${conduct.wishes === 1 ? '' : 'es'}.`]);
        if (!conduct.wisharti) rows.push([row++, textCol, "You haven't wished for any artifacts."]);
    } else rows.push([row++, textCol, 'You have used no wishes.']);
    const achievementHeaderRow = row + 1;
    const achievements = conductAchievementRows(achievementHeaderRow + 1, textCol);
    if (achievements.length) {
        row = achievementHeaderRow;
        rows.push([row++, headerCol, 'Achievements:']);
        rows.push(...achievements);
        row = Math.max(...rows.map(([line]) => line)) + 1;
    }
    rows.push([Math.min(row, 20), headerCol, '--More--']);
    return rows.filter(([line]) => line <= 20);
}

