            identifyZapToolOrWand(item, 'fire');
            await setMessage([...preludeMessages, resistsFire ? 'You feel rather warm.' : "You've set yourself afire!"].join('  '), !!followups.length || preludeMessages.length > 0);
            game._command_mode = null;
