            if (['f', 'fo', 'for', 'forc'].includes(command)) command = 'force';
            if (['j', 'ju', 'jum', 'jump'].includes(command)) command = 'jump';
            if (['le', 'lev', 'leve', 'level', 'levelc', 'levelch', 'levelcha', 'levelchan', 'levelchang', 'levelchange'].includes(command)) command = 'levelchange';
            if (command === 'l' && !game.flags?.debug) command = 'loot';
            if (command === 'p' && !game.flags?.debug) command = 'pray';
            if (['tu', 'tur'].includes(command)) command = 'turn';
            if (['d', 'di'].includes(command)) command = 'dip';
            if (command === 's' && !game.flags?.debug) command = 'sit';
            if (command === 'si') command = 'sit';
            if (command === 'cha') command = 'chat';
            if (['hi', 'his', 'hist', 'histo', 'histor'].includes(command)) command = 'history';
            if (game.flags?.debug && command.startsWith('wizw') && 'wizwhere'.startsWith(command))
                command = 'wizwhere';

            game._extended_command = '';
